// Helper para verificar si el usuario puede descargar documentos
// Los usuarios en período de prueba (trial) NO pueden descargar documentos masivos ni exportar datos
// Las descargas se habilitan solo tras el primer pago (status = 'active')
async function canUserDownloadDocuments(req: Express.Request, storageInstance: any): Promise<{ allowed: boolean; message: string }> {
  const user = req.user as any;
  if (!user?.companyId) {
    return { allowed: false, message: "No hay empresa asociada" };
  }
  
  const subscription = await storageInstance.getSubscriptionByCompany(user.companyId);
  const status = subscription?.status || 'trial';
  
  // Solo usuarios con suscripción activa pueden descargar
  if (status === 'active') {
    return { allowed: true, message: "" };
  }
  
  return { 
    allowed: false, 
    message: "Las descargas están disponibles solo para suscriptores activos. Activa tu plan para acceder a esta función." 
  };
}


// Multer configuration for file uploads
const evidenceStorage = multer.diskStorage({
  destination: (req, file, cb) => {
    cb(null, 'uploads/evidences');
  },
  filename: (req, file, cb) => {
    const uniqueSuffix = Date.now() + '-' + Math.round(Math.random() * 1E9);
    cb(null, file.fieldname + '-' + uniqueSuffix + path.extname(file.originalname));
  }
});

const upload = multer({ 
  storage: evidenceStorage,
  limits: {
    fileSize: 10 * 1024 * 1024, // 10MB limit
  },
  fileFilter: (req, file, cb) => {
    // Allow common document and image formats
    const allowedMimeTypes = [
      'image/jpeg',
      'image/jpg',
      'image/png',
      'application/pdf',
      'application/msword', // .doc
      'application/vnd.openxmlformats-officedocument.wordprocessingml.document', // .docx
      'application/vnd.ms-excel', // .xls
      'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet', // .xlsx
    ];
    
    const allowedExtensions = ['.jpg', '.jpeg', '.png', '.pdf', '.doc', '.docx', '.xls', '.xlsx'];
    const extname = path.extname(file.originalname).toLowerCase();
    
    if (allowedMimeTypes.includes(file.mimetype) && allowedExtensions.includes(extname)) {
      return cb(null, true);
    } else {
      cb(new Error('Tipo de archivo no permitido. Solo se permiten: JPG, PNG, PDF, DOC, DOCX, XLS, XLSX'));
    }
  }
});

