// Helper function to calculate days without accidents
function calculateDaysWithoutAccidents(accidents: any[]): number {
  if (!accidents || accidents.length === 0) {
    return 365;
  }
  
  const accidentDates = accidents
    .filter(a => a.incidentType === 'accidente')
    .map(a => new Date(a.date))
    .sort((a, b) => b.getTime() - a.getTime());
  
  if (accidentDates.length === 0) {
    return 365;
  }
  
  const lastAccident = accidentDates[0];
  const today = new Date();
  const diffTime = Math.abs(today.getTime() - lastAccident.getTime());
  const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
  
  return diffDays;
}

// Helper function to load company logo from Object Storage or filesystem
async function loadCompanyLogoBuffer(logoUrl: string | null | undefined): Promise<Buffer | null> {
  if (!logoUrl) {
    console.log("[PDF Logo] No logoUrl provided");
    return null;
  }
  
  console.log("[PDF Logo] Attempting to load logo from:", logoUrl);
  
  try {
    // Check if logo is stored in Object Storage
    if (logoUrl.startsWith("/objects/")) {
      // Normalize the path to handle /objects/uploads/... format correctly
      const normalizedPath = objectStorageService.normalizeObjectEntityPath(logoUrl);
      console.log("[PDF Logo] Normalized path:", normalizedPath);
      const buffer = await objectStorageService.getObjectBuffer(normalizedPath);
      console.log("[PDF Logo] Object Storage result:", buffer ? `Buffer(${buffer.length} bytes)` : "null");
      return buffer;
    }
    
    // Fallback to filesystem for legacy logos
    const logoPath = logoUrl.startsWith("/")
      ? path.join(process.cwd(), "public", logoUrl)
      : path.join(process.cwd(), "public", logoUrl);
    
    if (fs.existsSync(logoPath)) {
      return fs.readFileSync(logoPath);
    }
    
    return null;
  } catch (err) {
    console.warn("Could not load company logo:", err);
    return null;
  }
}

// Helper function to generate standard PDF header with logo, version control, and signatures
interface PdfHeaderOptions {
  doc: typeof PDFDocument.prototype;
  company: {
    name: string;
    nit: string;
    address?: string | null;
    logoUrl?: string | null;
  };
  documentTitle: string;
  documentCode?: string;
  version?: string;
  date?: Date;
  elaboro?: string;
  autorizo?: string;
  aprobo?: string;
  logoBuffer?: Buffer | null;
}

// Setup automatic headers and footers for all pages
function setupPdfHeadersFooters(options: PdfHeaderOptions): number {
  const { doc, company, documentTitle, documentCode, version, date, elaboro, autorizo, aprobo, logoBuffer } = options;
  const pageWidth = doc.page.width;
  const pageHeight = doc.page.height;
  const margin = 35;
  // Flag to prevent infinite recursion
  let isAddingHeaderFooter = false;

  // Function to add header on any page (uses absolute positioning, preserves doc.y)
  const addHeader = (isFirstPage: boolean = false) => {
    // Save current Y position before header rendering
    const savedY = doc.y;
    const headerY = 40;

    // Logo from preloaded buffer or placeholder
    if (logoBuffer) {
      try {
        doc.image(logoBuffer, margin, headerY, { width: 50, height: 50 });
      } catch (err) {
        doc.rect(margin, headerY, 50, 50).stroke('#cccccc');
        doc.fontSize(7).font('Helvetica').fillColor('#000000');
        doc.text('LOGO', margin + 15, headerY + 20, { lineBreak: false });
      }
    } else {
      doc.rect(margin, headerY, 50, 50).stroke('#cccccc');
      doc.fontSize(7).font('Helvetica').fillColor('#000000');
      doc.text('LOGO', margin + 15, headerY + 20, { lineBreak: false });
    }

    // Company name and NIT - use separate calls
    const companyInfoWidth = pageWidth - margin - 350;
    doc.fontSize(9).font('Helvetica-Bold').fillColor('#000000');
    doc.text(company.name, margin + 70, headerY + 5, { width: companyInfoWidth, lineBreak: false });
    doc.fontSize(7).font('Helvetica');
    doc.text(`NIT: ${company.nit}`, margin + 70, headerY + 25, { lineBreak: false });
    if (company.address) {
      doc.fontSize(8);
      doc.text(company.address, margin + 70, headerY + 40, { width: companyInfoWidth, lineBreak: false });
    }

    // Document Code and Version Table
    const tableWidth = 260;
    const tableStartX = pageWidth - margin - tableWidth;
    const rowHeight = 18;
    const labelWidth = 55;
    const valueWidth = tableWidth - labelWidth;

    // Table border
    doc.rect(tableStartX, headerY, tableWidth, rowHeight * 3).stroke('#1e7e34');
    doc.moveTo(tableStartX + labelWidth, headerY)
      .lineTo(tableStartX + labelWidth, headerY + rowHeight * 3)
      .stroke('#1e7e34');

    // Row 1: Código
    doc.fontSize(8).font('Helvetica-Bold').fillColor('#000000');
    doc.text('Código:', tableStartX + 3, headerY + 5, { width: labelWidth - 6, align: 'left', lineBreak: false });
    doc.fontSize(7).font('Helvetica');
    doc.text(documentCode || 'N/A', tableStartX + labelWidth + 3, headerY + 5, { 
      width: valueWidth - 6, 
      align: 'left',
      lineBreak: false 
    });

    // Row 2: Versión
    const row2Y = headerY + rowHeight;
    doc.moveTo(tableStartX, row2Y).lineTo(tableStartX + tableWidth, row2Y).stroke('#1e7e34');
    doc.fontSize(8).font('Helvetica-Bold');
    doc.text('Versión:', tableStartX + 3, row2Y + 5, { width: labelWidth - 6, align: 'left', lineBreak: false });
    doc.fontSize(7).font('Helvetica');
    doc.text(version || '1.0', tableStartX + labelWidth + 3, row2Y + 5, { 
      width: valueWidth - 6, 
      align: 'left',
      lineBreak: false 
    });

    // Row 3: Fecha
    const row3Y = headerY + rowHeight * 2;
    doc.moveTo(tableStartX, row3Y).lineTo(tableStartX + tableWidth, row3Y).stroke('#1e7e34');
    const dateStr = date ? (typeof date === 'string' ? date : new Date(date).toLocaleDateString('es-CO')) : new Date().toLocaleDateString('es-CO');
    doc.fontSize(8).font('Helvetica-Bold');
    doc.text('Fecha:', tableStartX + 3, row3Y + 5, { width: labelWidth - 6, align: 'left', lineBreak: false });
    doc.fontSize(7).font('Helvetica');
    doc.text(dateStr, tableStartX + labelWidth + 3, row3Y + 5, { 
      width: valueWidth - 6, 
      align: 'left',
      lineBreak: false 
    });

    // Document Title (only on first page)
    if (isFirstPage) {
      const titleY = headerY + 95;
      doc.fontSize(9).font('Helvetica-Bold').fillColor('#1e7e34');
      doc.text(documentTitle, margin, titleY, {
        width: pageWidth - 2 * margin,
        align: 'center',
        lineBreak: false
      });
    }
    
    // Restore Y position after header rendering
    doc.y = savedY;
  };

  // Function to add footer on any page (uses absolute positioning, preserves doc.y)
  const addFooter = () => {
    // Save current Y position before footer rendering
    const savedY = doc.y;
    const footerY = pageHeight - 70;
    const headerRowHeight = 16;
    const nameRowHeight = 38;
    const totalFooterHeight = headerRowHeight + nameRowHeight;
    const sigColWidth = (pageWidth - 2 * margin) / 3;

    // Table borders - outer rectangle
    doc.rect(margin, footerY, pageWidth - 2 * margin, totalFooterHeight).stroke('#1e7e34');
    // Vertical dividers
    doc.moveTo(margin + sigColWidth, footerY).lineTo(margin + sigColWidth, footerY + totalFooterHeight).stroke('#1e7e34');
    doc.moveTo(margin + sigColWidth * 2, footerY).lineTo(margin + sigColWidth * 2, footerY + totalFooterHeight).stroke('#1e7e34');
    // Horizontal divider between header and names
    doc.moveTo(margin, footerY + headerRowHeight).lineTo(pageWidth - margin, footerY + headerRowHeight).stroke('#1e7e34');

    // Headers - centered in header row
    doc.fontSize(8).font('Helvetica-Bold').fillColor('#000000');
    doc.text('ELABORÓ', margin + 5, footerY + 4, { width: sigColWidth - 10, align: 'center', lineBreak: false });
    doc.text('AUTORIZÓ', margin + sigColWidth + 5, footerY + 4, { width: sigColWidth - 10, align: 'center', lineBreak: false });
    doc.text('APROBÓ', margin + sigColWidth * 2 + 5, footerY + 4, { width: sigColWidth - 10, align: 'center', lineBreak: false });

    // Names - allow multi-line text with smaller font
    doc.fontSize(6).font('Helvetica');
    const nameY = footerY + headerRowHeight + 4;
    doc.text(elaboro || '', margin + 4, nameY, { width: sigColWidth - 8, align: 'center', height: nameRowHeight - 8 });
    doc.text(autorizo || '', margin + sigColWidth + 4, nameY, { width: sigColWidth - 8, align: 'center', height: nameRowHeight - 8 });
    doc.text(aprobo || '', margin + sigColWidth * 2 + 4, nameY, { width: sigColWidth - 8, align: 'center', height: nameRowHeight - 8 });
    
    // Restore Y position after footer rendering
    doc.y = savedY;
  };
  // Listen for page creation events (for pages 2, 3, 4, etc.)
  doc.on('pageAdded', () => {
    if (isAddingHeaderFooter) return;
    
    isAddingHeaderFooter = true;
    addHeader(false);
    addFooter();
    isAddingHeaderFooter = false;
    
    // Set Y position after header for content to continue properly
    doc.y = 115;
  });

  // Add header and footer to first page
  isAddingHeaderFooter = true;
  addHeader(true);
  addFooter();
  isAddingHeaderFooter = false;

  // Set initial Y position for content on first page
  doc.y = 165;

  // Return Y position where content should start
  return 165;
}

// Legacy function for backward compatibility - now uses the multi-page system
function generateStandardPdfHeader(options: PdfHeaderOptions): number {
  return setupPdfHeadersFooters(options);
}

/**
 * Helper function to check if there is enough space on the current page for content
 * If not, adds a new page and returns the new Y position
 * @param doc - PDFDocument instance
 * @param neededHeight - Height in points needed for the next content block
 * @param footerMargin - Distance from bottom of page to keep clear for footer (default 80)
 * @returns The Y position where content should be placed
 */
function checkPageSpace(doc: any, neededHeight: number, footerMargin: number = 80): number {
  const maxY = doc.page.height - footerMargin;
  if (doc.y + neededHeight > maxY) {
    doc.addPage();
  }
  return doc.y;
}

/**
 * Helper function to check space before adding signature sections
 * Signature sections typically need around 150px of space
 * @param doc - PDFDocument instance
 * @param signatureHeight - Height needed for signatures (default 150)
 * @returns The Y position where signatures should be placed
 */
function checkSignatureSpace(doc: any, signatureHeight: number = 150): number {
  const footerMargin = 80;
  const maxY = doc.page.height - footerMargin;
  if (doc.y + signatureHeight > maxY) {
    doc.addPage();
  }
  return doc.y;
}

