/**
 * Modular FURAT PDF generator
 * Generates official Colombian accident report format complying with Resolution 156/2005
 * @param doc - PDFDocument instance
 * @param accident - Accident data
 * @param worker - Worker data
 * @param company - Company data
 */
function generateFuratPdfContent(
  doc: any,
  accident: any,
  worker: any,
  company: any
): void {
  let currentY = doc.y;

  // Title
  doc.fontSize(9).font('Helvetica-Bold')
    .text('FORMATO ÚNICO DE REPORTE DE ACCIDENTE DE TRABAJO (FURAT)', margin, currentY, {
      align: 'center',
      underline: true
    });
  currentY = doc.y + 4;
  doc.y = currentY;

  // Section 1: Employer Data (using shared helper)
  currentY = renderEmployerSection(doc, company, margin, 1);

  // Section 2: Worker Data (using shared helper)
  currentY = renderWorkerSection(doc, worker, margin, 2);

  // Section 3: Accident Information
  doc.fontSize(9).font('Helvetica-Bold')
    .text('3. INFORMACIÓN DEL ACCIDENTE', margin, currentY);
  currentY = doc.y + 12;

  doc.fontSize(8).font('Helvetica-Bold').text('Fecha del Accidente: ', margin, currentY, { continued: true });
  doc.font('Helvetica').text(new Date(accident.date).toLocaleDateString('es-CO', { 
    year: 'numeric', 
    month: 'long', 
    day: 'numeric' 
  }));
  currentY = doc.y + 12;

  doc.font('Helvetica-Bold').text('Hora: ', margin, currentY, { continued: true });
  doc.font('Helvetica').text(accident.time || 'No especificada');
  currentY = doc.y + 12;

  doc.font('Helvetica-Bold').text('Lugar del Accidente: ', margin, currentY, { continued: true });
  doc.font('Helvetica').text(accident.location || 'No especificado');
  currentY = doc.y + 12;

  doc.font('Helvetica-Bold').text('Tipo de Jornada: ', margin, currentY, { continued: true });
  const journeyTypeMap: Record<string, string> = {
    'ordinaria': 'Jornada Ordinaria',
    'extraordinaria': 'Jornada Extraordinaria (horas extras)'
  };
  doc.font('Helvetica').text(accident.journeyType ? journeyTypeMap[accident.journeyType] : 'No especificada');
  currentY = doc.y + 12;

  doc.font('Helvetica-Bold').text('Clasificación: ', margin, currentY, { continued: true });
  const classificationMap: Record<string, string> = {
    'normal': 'Normal (en instalaciones)',
    'in_itinere': 'In Itinere (trayecto)',
    'en_mision': 'En Misión'
  };
  doc.font('Helvetica').text(accident.accidentClassification ? classificationMap[accident.accidentClassification] : 'No especificada');
  currentY = doc.y + 12;

  doc.font('Helvetica-Bold').text('Descripción Detallada: ');
  currentY = doc.y + 12;
  doc.font('Helvetica').text(accident.description || 'No disponible', margin, currentY, {
    width: pageWidth - 2 * margin,
    align: 'justify'
  });
  currentY = doc.y + 15;

  doc.font('Helvetica-Bold').text('Mecanismo del Accidente: ', margin, currentY, { continued: true });
  doc.font('Helvetica').text(accident.accidentMechanism || 'No especificado');
  currentY = doc.y + 12;

  doc.font('Helvetica-Bold').text('Agente Causante: ', margin, currentY, { continued: true });
  doc.font('Helvetica').text(accident.causativeAgent || 'No especificado');
  currentY = doc.y + 15;

  // Section 4: Injury Details
  doc.fontSize(9).font('Helvetica-Bold')
    .text('4. LESIÓN Y DIAGNÓSTICO', margin, currentY);
  currentY = doc.y + 12;

  doc.fontSize(8).font('Helvetica-Bold').text('Parte del Cuerpo Afectada: ', margin, currentY, { continued: true });
  doc.font('Helvetica').text(accident.bodyPartAffected || 'No especificada');
  currentY = doc.y + 12;

  doc.font('Helvetica-Bold').text('Naturaleza de la Lesión: ', margin, currentY, { continued: true });
  doc.font('Helvetica').text(accident.injuryNature || 'No especificada');
  currentY = doc.y + 12;

  doc.font('Helvetica-Bold').text('Diagnóstico Médico: ', margin, currentY, { continued: true });
  doc.font('Helvetica').text(accident.medicalDiagnosis || 'Pendiente de diagnóstico');
  currentY = doc.y + 12;

  doc.font('Helvetica-Bold').text('IPS de Atención: ', margin, currentY, { continued: true });
  doc.font('Helvetica').text(accident.ipsName || 'No especificada');
  currentY = doc.y + 12;

  doc.font('Helvetica-Bold').text('Gravedad: ', margin, currentY, { continued: true });
  const severityMap: Record<string, string> = {
    'leve': 'Leve',
    'grave': 'Grave',
    'mortal': 'Mortal'
  };
  doc.font('Helvetica').text(severityMap[accident.severity] || accident.severity);
  currentY = doc.y + 15;

  // Section 5: Witnesses
  doc.fontSize(9).font('Helvetica-Bold')
    .text('5. TESTIGOS', margin, currentY);
  currentY = doc.y + 12;

  doc.fontSize(7).font('Helvetica').text(
    accident.witnesses || 'No se registraron testigos', 
    margin, 
    currentY, 
    { width: pageWidth - 2 * margin }
  );
  currentY = doc.y + 25;

  // Section 6: Additional Information
  doc.fontSize(9).font('Helvetica-Bold')
    .text('6. INFORMACIÓN ADICIONAL', margin, currentY);
  currentY = doc.y + 12;

  doc.fontSize(8).font('Helvetica-Bold').text('Hospitalización: ', margin, currentY, { continued: true });
  doc.font('Helvetica').text(accident.wasHospitalized ? 'Sí' : 'No');
  currentY = doc.y + 12;

  doc.font('Helvetica-Bold').text('Remisión a Urgencias: ', margin, currentY, { continued: true });
  doc.font('Helvetica').text(accident.erReferral ? 'Sí' : 'No');
  currentY = doc.y + 12;

  doc.font('Helvetica-Bold').text('Medidas Tomadas Inmediatamente: ');
  currentY = doc.y + 12;
  doc.font('Helvetica').text(
    accident.actionsTaken || 'No se registraron acciones inmediatas', 
    margin, 
    currentY, 
    { width: pageWidth - 2 * margin }
  );
  currentY = doc.y + 30;

  // Legal Note
  doc.fontSize(8).font('Helvetica-Oblique')
    .text(
      'NOTA LEGAL: Este documento fue generado automáticamente por el Sistema de Gestión SST. ' +
      'Debe ser reportado a la ARL dentro de las 48 horas siguientes al accidente (Artículo 62 del Decreto 1295 de 1994). ' +
      'Resolución 156 de 2005 del Ministerio de la Protección Social.',
      margin,
      currentY,
      { width: pageWidth - 2 * margin, align: 'center' }
    );
}

