  app.get("/api/workers", requireAnyPermission(["workers:view", "workers:view_self"]), async (req, res) => {
    // For admin/super_admin: check for X-Company-Id header to filter by specific company
    // For other roles: only get workers from their company
    const userRole = req.user!.role;
    const isAdmin = hasGlobalAccess(userRole);
    const effectiveCompanyId = getEffectiveCompanyId(req);
    
    // Helper function to enrich workers with userId information using batch query
    const enrichWorkersWithUserId = async (workers: any[]) => {
      const workerIds = workers.map(w => w.id);
      const userMap = await storage.getUsersByWorkerIds(workerIds);
      return workers.map(worker => ({
        ...worker,
        userId: userMap.get(worker.id)?.id || null
      }));
    };
    
    // If effectiveCompanyId is set (either from header for superadmin or user's company), filter by it
    if (effectiveCompanyId) {
      const workers = await storage.getWorkers(effectiveCompanyId);
      const enrichedWorkers = await enrichWorkersWithUserId(workers);
      return res.json(enrichedWorkers);
    }
    
    // Admin without specific company: get all workers across all companies
    if (isAdmin) {
      const allWorkers = await storage.getAllWorkers();
      const enrichedWorkers = await enrichWorkersWithUserId(allWorkers);
      return res.json(enrichedWorkers);
    }
    
    // Non-admin without company (shouldn't happen normally)
    return res.status(403).json({ error: "Usuario no asociado a una empresa" });
  });

