  // Configure multer for Excel file uploads
  const excelUpload = multer({
    storage: multer.memoryStorage(),
    limits: {
      fileSize: 10 * 1024 * 1024, // 10MB limit
    },
    fileFilter: (req, file, cb) => {
      const allowedMimeTypes = [
        'application/vnd.ms-excel',
        'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
        'text/csv'
      ];
      const allowedExtensions = ['.xls', '.xlsx', '.csv'];
      const extname = path.extname(file.originalname).toLowerCase();
      
      if (allowedMimeTypes.includes(file.mimetype) && allowedExtensions.includes(extname)) {
        return cb(null, true);
      } else {
        cb(new Error('Tipo de archivo no permitido. Solo se permiten archivos Excel (.xlsx, .xls) o CSV'));
      }
    }
  });

  app.post("/api/workers/import", requirePermission("workers:create"), excelUpload.single('file'), async (req, res) => {
    try {
      const companyId = req.user!.companyId;
      if (!companyId) {
        return res.status(403).send("Usuario no asociado a una empresa");
      }
      
      // Get company info for default affiliations
      const company = await storage.getCompany(companyId);

      if (!req.file) {
        return res.status(400).json({ error: 'No se proporcionó ningún archivo' });
      }

      const XLSX = await import('xlsx');
      const workbook = XLSX.read(req.file.buffer, { type: 'buffer' });
      const sheetName = workbook.SheetNames[0];
      const worksheet = workbook.Sheets[sheetName];
      const data = XLSX.utils.sheet_to_json(worksheet);

      if (data.length === 0) {
        return res.status(400).json({ error: 'El archivo está vacío' });
      }

      // Helper function to convert Excel serial date to JavaScript Date
      const excelDateToJSDate = (excelDate: any): string | undefined => {
        if (!excelDate) return undefined;
        
        // If it's already a string date format, return it
        if (typeof excelDate === 'string') {
          const trimmed = excelDate.trim();
          // Check if it looks like a date string (contains - or /)
          if (trimmed.includes('-') || trimmed.includes('/')) {
            return trimmed;
          }
          // Try to parse as number if it's a numeric string
          const num = parseFloat(trimmed);
          if (!isNaN(num) && num > 25569) { // Excel dates start from 25569 (1970-01-01)
            excelDate = num;
          } else {
            return trimmed;
          }
        }
        
        // If it's a number (Excel serial date), convert it
        if (typeof excelDate === 'number') {
          // Excel's epoch is December 30, 1899
          // JavaScript's epoch is January 1, 1970
          // Excel has a bug where it treats 1900 as a leap year, so we need to account for that
          const excelEpoch = new Date(1899, 11, 30); // Dec 30, 1899
          const millisecondsPerDay = 24 * 60 * 60 * 1000;
          const date = new Date(excelEpoch.getTime() + excelDate * millisecondsPerDay);
          
          // Format as YYYY-MM-DD
          const year = date.getFullYear();
          const month = String(date.getMonth() + 1).padStart(2, '0');
          const day = String(date.getDate()).padStart(2, '0');
          return `${year}-${month}-${day}`;
        }
        
        return undefined;
      };

      // Normalización de sinónimos para campos enum - evita errores de importación por términos coloquiales
      const normalizeEducationLevel = (value: string | undefined): string | undefined => {
        if (!value) return undefined;
        const normalized = value.toLowerCase().trim();
        const synonyms: Record<string, string> = {
          'bachiller': 'secundaria', 'bachillerato': 'secundaria', 'bachiller academico': 'secundaria',
          'bachiller tecnico': 'secundaria', 'media': 'secundaria', 'media vocacional': 'secundaria',
          '11': 'secundaria', 'once': 'secundaria',
          'basica primaria': 'primaria', 'elemental': 'primaria',
          'tecnico laboral': 'tecnico', 'tecnico profesional': 'tecnico',
          'tecnologia': 'tecnologo', 'tecnologico': 'tecnologo',
          'universitario': 'profesional', 'pregrado': 'profesional', 'licenciatura': 'profesional',
          'ingenieria': 'profesional', 'ingeniero': 'profesional',
          'especialista': 'especializacion', 'posgrado': 'especializacion',
          'magister': 'maestria', 'master': 'maestria', 'msc': 'maestria',
          'doctor': 'doctorado', 'phd': 'doctorado',
          'sin estudios': 'ninguno', 'sin educacion': 'ninguno', 'n/a': 'ninguno', 'no aplica': 'ninguno'
        };
        return synonyms[normalized] || normalized;
      };

      const normalizeGender = (value: string | undefined): string | undefined => {
        if (!value) return undefined;
        const normalized = value.toLowerCase().trim();
        const synonyms: Record<string, string> = {
          'hombre': 'masculino', 'mujer': 'femenino', 'm': 'masculino', 'f': 'femenino',
          'male': 'masculino', 'female': 'femenino', 'no especifica': 'prefiero_no_decir', 'no responde': 'prefiero_no_decir'
        };
        return synonyms[normalized] || normalized;
      };

      const normalizeCivilStatus = (value: string | undefined): string | undefined => {
        if (!value) return undefined;
        const normalized = value.toLowerCase().trim();
        const synonyms: Record<string, string> = {
          'soltero/a': 'soltero', 'soltera': 'soltero', 'casado/a': 'casado', 'casada': 'casado',
          'union libre': 'union_libre', 'unión libre': 'union_libre', 'conviviente': 'union_libre',
          'divorciado/a': 'divorciado', 'divorciada': 'divorciado', 'viudo/a': 'viudo', 'viuda': 'viudo',
          'separado/a': 'separado', 'separada': 'separado'
        };
        return synonyms[normalized] || normalized;
      };

      const normalizeContractType = (value: string | undefined): string | undefined => {
        if (!value) return undefined;
        const normalized = value.toLowerCase().trim();
        const synonyms: Record<string, string> = {
          'termino fijo': 'fijo', 'término fijo': 'fijo', 'a término fijo': 'fijo',
          'termino indefinido': 'indefinido', 'término indefinido': 'indefinido', 'a término indefinido': 'indefinido',
          'obra labor': 'obra_labor', 'obra o labor': 'obra_labor', 'por obra o labor': 'obra_labor',
          'prestacion servicios': 'prestacion_servicios', 'prestación de servicios': 'prestacion_servicios',
          'contrato de prestación de servicios': 'prestacion_servicios', 'ops': 'prestacion_servicios',
          'practicas': 'aprendizaje', 'pasante': 'aprendizaje', 'pasantia': 'aprendizaje', 'practicante': 'aprendizaje',
          'ocasional': 'ocasional', 'transitorio': 'ocasional', 'accidental': 'ocasional',
          'servicios': 'servicios', 'civil': 'servicios'
        };
        return synonyms[normalized] || normalized;
      };

      // Helper function to transform Zod validation errors to user-friendly Spanish messages (SST-2026-0017)
      const formatZodErrorForBulkImport = (error: any): string => {
        // Map field names to Spanish labels
        const fieldLabels: Record<string, string> = {
          identificationNumber: 'Cédula/Identificación',
          name: 'Nombre Completo',
          email: 'Email',
          position: 'Cargo',
          department: 'Departamento',
          contractType: 'Tipo de Contrato',
          startDate: 'Fecha de Inicio',
          endDate: 'Fecha de Fin',
          status: 'Estado',
          gender: 'Género',
          birthDate: 'Fecha de Nacimiento',
          educationLevel: 'Nivel Educativo',
          civilStatus: 'Estado Civil',
          epsNombre: 'EPS',
          arlNombre: 'ARL',
          afpNombre: 'AFP',
          ccfNombre: 'Caja de Compensación',
          emergencyContactName: 'Contacto de Emergencia',
          emergencyContactPhone: 'Teléfono de Emergencia'
        };

        // Enum valid options with user-friendly labels
        const enumOptions: Record<string, { values: string[], label: string }> = {
          contractType: {
            values: ['indefinido', 'fijo', 'temporal', 'obra-labor', 'aprendizaje'],
            label: 'Valores permitidos: indefinido, fijo, temporal, obra-labor, aprendizaje'
          },
          status: {
            values: ['activo', 'inactivo', 'retirado'],
            label: 'Valores permitidos: activo, inactivo, retirado'
          },
          gender: {
            values: ['masculino', 'femenino', 'otro', 'prefiero_no_decir'],
            label: 'Valores permitidos: masculino, femenino, otro, prefiero_no_decir'
          },
          educationLevel: {
            values: ['ninguno', 'primaria', 'secundaria', 'tecnico', 'tecnologo', 'profesional', 'especializacion', 'maestria', 'doctorado'],
            label: 'Valores permitidos: ninguno, primaria, secundaria, técnico, tecnólogo, profesional, especialización, maestría, doctorado'
          },
          civilStatus: {
            values: ['soltero', 'casado', 'union_libre', 'divorciado', 'viudo', 'separado'],
            label: 'Valores permitidos: soltero, casado, unión libre (escribir "union libre" o "unión libre"), divorciado, viudo, separado'
          }
        };

        // Check if it's a ZodError
        if (error.name === 'ZodError' && error.issues) {
          const messages: string[] = [];
          
          for (const issue of error.issues) {
            const fieldPath = issue.path.join('.');
            const fieldName = fieldLabels[fieldPath] || fieldPath || 'Campo desconocido';
            const receivedValue = issue.received !== undefined ? ` (valor recibido: "${issue.received}")` : '';
            
            if (issue.code === 'invalid_enum_value') {
              const enumInfo = enumOptions[fieldPath];
              if (enumInfo) {
                messages.push(`El campo '${fieldName}' tiene un valor no válido${receivedValue}. ${enumInfo.label}`);
              } else {
                messages.push(`El campo '${fieldName}' tiene un valor no válido${receivedValue}. Opciones válidas: ${issue.options?.join(', ') || 'no especificadas'}`);
              }
            } else if (issue.code === 'invalid_type') {
              if (issue.expected === 'string' && issue.received === 'undefined') {
                messages.push(`El campo '${fieldName}' es requerido`);
              } else {
                messages.push(`El campo '${fieldName}' tiene un tipo inválido. Se esperaba ${issue.expected}, se recibió ${issue.received}`);
              }
            } else if (issue.code === 'too_small') {
              messages.push(`El campo '${fieldName}' es demasiado corto o está vacío`);
            } else if (issue.code === 'invalid_string') {
              if (issue.validation === 'email') {
                messages.push(`El campo '${fieldName}' debe ser un correo electrónico válido`);
              } else {
                messages.push(`El campo '${fieldName}' tiene un formato inválido`);
              }
            } else {
              messages.push(`Error en '${fieldName}': ${issue.message}`);
            }
          }
          
          return messages.join('; ');
        }
        
        // If not a ZodError, return the original message
        return error.message || 'Error desconocido durante la validación';
      };

      const results = {
        total: data.length,
        successful: 0,
        failed: 0,
        errors: [] as Array<{ row: number; error: string; data: any }>
      };

      // Process each row
      for (let i = 0; i < data.length; i++) {
        const row: any = data[i];
        const rowNumber = i + 2; // +2 because Excel starts at 1 and header is row 1

        try {
          // Get raw date values (may be Excel serial numbers or strings)
          const rawStartDate = row['Fecha de Inicio'] || row['Fecha Inicio'];
          const rawEndDate = row['Fecha de Fin'] || row['Fecha Fin'];
          
          // Get raw date values for sociodemographic data
          const rawBirthDate = row['Fecha de Nacimiento'] || row['Fecha Nacimiento'];
          
          // Map Excel columns to database fields (including Estándar 3.1.1 sociodemographic data)
          const workerData = {
            companyId,
            identificationNumber: row['Cédula']?.toString().trim() || row['Cedula']?.toString().trim() || row['Identificación']?.toString().trim(),
            name: row['Nombre Completo']?.toString().trim() || row['Nombre']?.toString().trim(),
            email: row['Email']?.toString().trim() || row['Correo']?.toString().trim() || undefined,
            position: row['Cargo']?.toString().trim(),
            department: row['Departamento']?.toString().trim() || row['Area']?.toString().trim() || row['Área']?.toString().trim(),
            contractType: normalizeContractType(row['Tipo de Contrato']?.toString() || row['Contrato']?.toString()) || 'indefinido',
            startDate: excelDateToJSDate(rawStartDate),
            endDate: excelDateToJSDate(rawEndDate),
            status: row['Estado']?.toString().toLowerCase().trim() || 'activo',
            // Afiliaciones SSSS
            epsNombre: row['EPS']?.toString().trim() || undefined,
            arlNombre: row['ARL']?.toString().trim() || undefined,
            afpNombre: row['AFP']?.toString().trim() || undefined,
            ccfNombre: row['CCF']?.toString().trim() || undefined,
            // Datos Sociodemográficos - Estándar 3.1.1 Resolución 0312/2019
            gender: normalizeGender(row['Género']?.toString() || row['Genero']?.toString()),
            birthDate: excelDateToJSDate(rawBirthDate) || undefined,
            educationLevel: normalizeEducationLevel(row['Nivel Educativo']?.toString() || row['Educación']?.toString()),
            civilStatus: normalizeCivilStatus(row['Estado Civil']?.toString())
          };

          // Validate required fields
          if (!workerData.identificationNumber) {
            throw new Error('La cédula/identificación es requerida');
          }
          if (!workerData.name || !workerData.position || !workerData.department || 
              !workerData.contractType || !workerData.startDate) {
            throw new Error('Faltan campos requeridos (Nombre, Cargo, Departamento, Tipo de Contrato, Fecha de Inicio)');
          }

          // Validate contract type
          const validContractTypes = ['indefinido', 'fijo', 'temporal', 'obra-labor', 'aprendizaje', 'ocasional', 'servicios', 'prestacion_servicios'];
          if (!validContractTypes.includes(workerData.contractType)) {
            throw new Error(`Tipo de contrato inválido. Debe ser: ${validContractTypes.join(', ')}`);
          }

          // Validate status
          const validStatuses = ['activo', 'inactivo', 'retirado'];
          if (!validStatuses.includes(workerData.status)) {
            throw new Error(`Estado inválido. Debe ser: ${validStatuses.join(', ')}`);
          }

          // Validate and format dates
          const startDate = new Date(workerData.startDate);
          if (isNaN(startDate.getTime())) {
            throw new Error('Fecha de inicio inválida. Use formato AAAA-MM-DD');
          }

          if (workerData.endDate) {
            const endDate = new Date(workerData.endDate);
            if (isNaN(endDate.getTime())) {
              throw new Error('Fecha de fin inválida. Use formato AAAA-MM-DD');
            }
            if (endDate < startDate) {
              throw new Error('La fecha de fin debe ser posterior a la fecha de inicio');
            }
          }

          // Validate using Zod schema
          const validatedData = insertWorkerSchema.parse(workerData);
          
          // Create worker
          const newWorker = await storage.createWorker(validatedData, companyId);
          
          // Auto-create contract for the worker
          try {
            // Map worker contract type to contract table contract type
            const contractTypeMap: Record<string, string> = {
              'indefinido': 'indefinido',
              'fijo': 'fijo',
              'temporal': 'fijo',  // Temporal maps to 'fijo' in contracts v2 enum
              'obra-labor': 'obra_labor',
              'aprendizaje': 'aprendizaje',
              'ocasional': 'ocasional',
              'servicios': 'servicios',
              'prestacion_servicios': 'servicios'
            };
            
            const contractData = {
              workerId: newWorker.id,
              contractType: contractTypeMap[workerData.contractType] || 'indefinido',
              startDate: workerData.startDate,
              endDate: workerData.endDate || null,
              position: workerData.position,
              department: workerData.department,
              status: 'activo' as const
            };
            
            await storage.createContract(contractData, companyId);
          } catch (contractError: any) {
            // Log contract creation error but don't fail the worker import
            console.warn(`[Import] Worker ${newWorker.name} created but contract failed: ${contractError.message}`);
          }
          
          // Auto-create affiliation for the worker using company defaults
          try {
            if (company) {
              // ARL MUST come from company (Decreto 1295/1994 - unique per company in Colombia)
              // EPS/AFP/CCF can use worker values or company defaults
              const afiliacionData = {
                workerId: newWorker.id,
                fecha: workerData.startDate || new Date().toISOString().split('T')[0],
                epsNombre: workerData.epsNombre || company.epsNombreEmpresa || null,
                arlNombre: company.arlNombreEmpresa || null, // STRICTLY from company only
                afpNombre: workerData.afpNombre || company.afpNombreEmpresa || null,
                ccfNombre: workerData.ccfNombre || company.ccfNombreEmpresa || null,
              };
              
              // Create affiliation record (even partial - allows completing later)
              await storage.createAfiliacionSsss(afiliacionData, companyId);
            }
          } catch (afiliacionError: any) {
            console.warn(`[Import] Worker ${newWorker.name} created but affiliation failed: ${afiliacionError.message}`);
          }
          
          results.successful++;

        } catch (error: any) {
          results.failed++;
          results.errors.push({
            row: rowNumber,
            error: formatZodErrorForBulkImport(error),
            data: row
          });
        }
      }

      res.status(200).json(results);
    } catch (error: any) {
      console.error('Error importing workers:', error);
      res.status(500).json({ error: 'Error al importar trabajadores: ' + error.message });
    }
  });


