  // Helper: Calculate SLA status based on due date
  function calculateSlaStatus(dueDateStr: string | null): { slaStatus: string; daysRemaining: number } {
    if (!dueDateStr) return { slaStatus: "sin_fecha", daysRemaining: 0 };
    const now = new Date();
    now.setHours(0, 0, 0, 0);
    const dueDate = new Date(dueDateStr);
    dueDate.setHours(0, 0, 0, 0);
    const diffTime = dueDate.getTime() - now.getTime();
    const daysRemaining = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
    
    let slaStatus = "en_tiempo";
    if (daysRemaining < 0) {
      slaStatus = "vencido";
    } else if (daysRemaining <= 3) {
      slaStatus = "proximo_vencer";
    }
    return { slaStatus, daysRemaining };
  }

