  // POST /api/investigations - Create investigation
  app.post("/api/investigations", requirePermission("accidents:create"), async (req, res) => {
    try {
      const userCompanyId = req.user!.companyId;
      const isAdmin = hasGlobalAccess(req.user!.role);
      
      let companyId: string;
      if (isAdmin) {
        companyId = req.body.companyId;
        if (!companyId) {
          return res.status(400).send("Admin debe especificar companyId");
        }
      } else {
        if (!userCompanyId) {
          return res.status(403).send("Usuario no asociado a una empresa");
        }
        companyId = userCompanyId;
      }
      
      // Inject companyId into body before validation
      const bodyWithCompanyId = { ...req.body, companyId };
      
      // Parse and validate data
      const validatedData = insertAccidentInvestigationSchema.parse(bodyWithCompanyId);
      
      // Auto-calculate dueDate (15 days from event date per Res. 1401/2007)
      const eventDate = new Date(validatedData.eventDate);
      const dueDate = new Date(eventDate);
      dueDate.setDate(dueDate.getDate() + 15);
      const dueDateStr = dueDate.toISOString().split('T')[0];
      
      // Detect severity and set requirements
      const severity = req.body.severity || '';
      const isSevere = severity === 'grave' ? 1 : 0;
      const isFatal = severity === 'mortal' ? 1 : 0;
      const requiresLicensedProfessional = (isSevere || isFatal) ? 1 : 0;
      const requiresMinistryReport = isFatal ? 1 : 0;
      
      // Calculate initial SLA status
      const { slaStatus, daysRemaining } = calculateSlaStatus(dueDateStr);
      
      const [newInvestigation] = await db.insert(schema.accidentInvestigations)
        .values({
          ...validatedData,
          companyId,
          dueDate: dueDateStr,
          isSevere,
          isFatal,
          requiresLicensedProfessional,
          requiresMinistryReport,
          slaStatus,
          daysRemaining,
          createdBy: req.user!.id,
        })
        .returning();
      
      res.status(201).json(newInvestigation);
    } catch (error: any) {
      console.error('Error creating investigation:', error);
      res.status(400).send(error.message);
    }
  });

