      if (!investigation) {
        return res.status(404).send("Investigación no encontrada");
      }
      
      if (!isAdmin && effectiveCompanyId && investigation.companyId !== effectiveCompanyId) {
        return res.status(403).send("No autorizado");
      }
      
      const validatedData = insertInvestigationFindingSchema.parse({
        ...req.body,
        investigationId: id
      });
      
      const [finding] = await db.insert(schema.investigationFindings)
        .values(validatedData)
        .returning();
      
