  // PATCH /api/investigations/:id/findings/:findingId - Update finding status
  app.patch("/api/investigations/:id/findings/:findingId", requirePermission("accidents:edit"), async (req, res) => {
    try {
      const { id, findingId } = req.params;
      const effectiveCompanyId = getEffectiveCompanyId(req);
      const isAdmin = hasGlobalAccess(req.user!.role);
      
      const [investigation] = await db.select()
        .from(schema.accidentInvestigations)
        .where(eq(schema.accidentInvestigations.id, id))
        .limit(1);
      
      if (!investigation) {
        return res.status(404).send("Investigación no encontrada");
      }
      
      if (!isAdmin && effectiveCompanyId && investigation.companyId !== effectiveCompanyId) {
        return res.status(403).send("No autorizado");
      }
      
      const updateData = { ...req.body, updatedAt: new Date() };
      
      // If status changed to verified, record verification
      if (req.body.status === 'verificada') {
        updateData.verifiedBy = req.user!.id;
        updateData.verificationDate = new Date().toISOString().split('T')[0];
      }
      
      // If status changed to completed, record completion
      if (req.body.status === 'completada' && !updateData.completionDate) {
        updateData.completionDate = new Date().toISOString().split('T')[0];
      }
      
      const [updated] = await db.update(schema.investigationFindings)
        .set(updateData)
        .where(eq(schema.investigationFindings.id, findingId))
        .returning();
      
      // Update actions count in investigation
      const allFindings = await db.select()
        .from(schema.investigationFindings)
        .where(eq(schema.investigationFindings.investigationId, id));
      
      const completedActions = allFindings.filter(f => f.status === 'completada' || f.status === 'verificada').length;
      
      await db.update(schema.accidentInvestigations)
        .set({ 
          actionsImplemented: completedActions,
          updatedAt: new Date()
        })
        .where(eq(schema.accidentInvestigations.id, id));
      
      res.json(updated);
    } catch (error: any) {
      console.error('Error updating finding:', error);
      res.status(400).send(error.message);
    }
  });

  // GET /api/investigations/:id/pdf - Generate investigation PDF report
  app.get("/api/investigations/:id/pdf", requirePermission("accidents:view"), async (req, res) => {
    try {
      const { id } = req.params;
      const effectiveCompanyId = getEffectiveCompanyId(req);
      const isAdmin = hasGlobalAccess(req.user!.role);
      
      // Fetch investigation
      const [investigation] = await db.select()
        .from(schema.accidentInvestigations)
        .where(eq(schema.accidentInvestigations.id, id))
        .limit(1);
      
      if (!investigation) {
        return res.status(404).send("Investigación no encontrada");
      }
      
      if (!isAdmin && effectiveCompanyId && investigation.companyId !== effectiveCompanyId) {
        return res.status(403).send("No autorizado");
      }
      
      // Fetch related data
      const participants = await db.select()
        .from(schema.investigationParticipants)
        .where(eq(schema.investigationParticipants.investigationId, id));
      
      const findings = await db.select()
        .from(schema.investigationFindings)
        .where(eq(schema.investigationFindings.investigationId, id));
      
      const [company] = await db.select()
        .from(schema.companies)
        .where(eq(schema.companies.id, investigation.companyId))
        .limit(1);
      
      // Get subscription for watermark
      const subscription = await storage.getSubscriptionByCompany(investigation.companyId);
      const trialStatus = getTrialStatus(subscription?.status || 'trial', subscription?.trialEnd || null, true, true);
      
      // Create PDF
      const doc = new PDFDocument({ size: 'LETTER', margin: 40 });
      setupTrialWatermarkOnAllPages(doc, trialStatus.requiresWatermark);
      
      res.setHeader('Content-Type', 'application/pdf');
      res.setHeader('Content-Disposition', `attachment; filename="Investigacion-${id.substring(0, 8)}.pdf"`);
      doc.pipe(res);
      
      const GREEN_HEADER = '#1e7e34';
      const pageWidth = doc.page.width - 80;
      
      // Header
      doc.fillColor(GREEN_HEADER).fontSize(18).font('Helvetica-Bold')
        .text('INFORME DE INVESTIGACIÓN DE ACCIDENTE', { align: 'center' });
      doc.moveDown(0.5);
      
      if (company) {
        doc.fillColor('#333').fontSize(12).font('Helvetica')
          .text(company.name, { align: 'center' });
        doc.fontSize(10).text(`NIT: ${company.nit}`, { align: 'center' });
      }
      doc.moveDown(1);
      
      // Event Information Section
      doc.fillColor(GREEN_HEADER).fontSize(14).font('Helvetica-Bold')
        .text('1. INFORMACIÓN DEL EVENTO');
      doc.moveDown(0.3);
      doc.fillColor('#333').fontSize(10).font('Helvetica');
      
      const eventInfo = [
        ['Tipo de Evento:', investigation.eventType || '-'],
        ['Fecha del Evento:', investigation.eventDate || '-'],
        ['Fecha Inicio Investigación:', investigation.investigationStartDate || '-'],
        ['Fecha Límite (SLA 15 días):', investigation.dueDate || '-'],
        ['Estado:', investigation.status || '-'],
        ['Metodología de Análisis:', investigation.analysisMethodology || '-'],
      ];
      
      eventInfo.forEach(([label, value]) => {
        doc.font('Helvetica-Bold').text(label, { continued: true });
        doc.font('Helvetica').text(` ${value}`);
      });
      
      if (investigation.isSevere || investigation.isFatal) {
        doc.moveDown(0.3);
        doc.fillColor('#dc3545').font('Helvetica-Bold')
          .text(`⚠ CASO ${investigation.isFatal ? 'MORTAL' : 'GRAVE'} - Requiere profesional SST con licencia`);
        doc.fillColor('#333');
      }
      
      doc.moveDown(0.5);
      doc.font('Helvetica-Bold').text('Descripción del Evento:');
      doc.font('Helvetica').text(investigation.eventDescription || 'Sin descripción', { align: 'justify' });
      doc.moveDown(1);
      
      // Participants Section
      doc.fillColor(GREEN_HEADER).fontSize(14).font('Helvetica-Bold')
        .text('2. EQUIPO INVESTIGADOR');
      doc.moveDown(0.3);
      doc.fillColor('#333').fontSize(10);
      
      if (participants.length === 0) {
        doc.font('Helvetica').text('No se han registrado participantes.');
      } else {
        participants.forEach((p, idx) => {
          doc.font('Helvetica-Bold').text(`${idx + 1}. ${p.participantName}`);
          doc.font('Helvetica')
            .text(`   Rol: ${p.participantRole} | Cargo: ${p.participantPosition || '-'} | Área: ${p.participantArea || '-'}`);
          if (p.hasLicense) {
            doc.text(`   Licencia SST: ${p.licenseNumber || '-'} (Vence: ${p.licenseExpiry || '-'})`);
          }
        });
      }
      doc.moveDown(1);
      
      // Causes Analysis Section
      doc.fillColor(GREEN_HEADER).fontSize(14).font('Helvetica-Bold')
        .text('3. ANÁLISIS DE CAUSAS');
      doc.moveDown(0.3);
      doc.fillColor('#333').fontSize(10);
      
      if (investigation.immediateActCauses && investigation.immediateActCauses.length > 0) {
        doc.font('Helvetica-Bold').text('Causas Inmediatas - Actos Inseguros:');
        investigation.immediateActCauses.forEach(c => doc.font('Helvetica').text(`  • ${c}`));
        doc.moveDown(0.3);
      }
      
      if (investigation.immediateConditionCauses && investigation.immediateConditionCauses.length > 0) {
        doc.font('Helvetica-Bold').text('Causas Inmediatas - Condiciones Inseguras:');
        investigation.immediateConditionCauses.forEach(c => doc.font('Helvetica').text(`  • ${c}`));
        doc.moveDown(0.3);
      }
      
      if (investigation.basicPersonalCauses && investigation.basicPersonalCauses.length > 0) {
        doc.font('Helvetica-Bold').text('Causas Básicas - Factores Personales:');
        investigation.basicPersonalCauses.forEach(c => doc.font('Helvetica').text(`  • ${c}`));
        doc.moveDown(0.3);
      }
      
      if (investigation.basicWorkCauses && investigation.basicWorkCauses.length > 0) {
        doc.font('Helvetica-Bold').text('Causas Básicas - Factores del Trabajo:');
        investigation.basicWorkCauses.forEach(c => doc.font('Helvetica').text(`  • ${c}`));
        doc.moveDown(0.3);
      }
      
      if (investigation.rootCause) {
        doc.font('Helvetica-Bold').text('Causa Raíz Identificada:');
        doc.font('Helvetica').text(`  ${investigation.rootCause}`);
      }
      doc.moveDown(1);
      
      // Corrective Actions Section
      doc.fillColor(GREEN_HEADER).fontSize(14).font('Helvetica-Bold')
        .text('4. ACCIONES CORRECTIVAS Y PREVENTIVAS');
      doc.moveDown(0.3);
      doc.fillColor('#333').fontSize(10);
      
      if (findings.length === 0) {
        doc.font('Helvetica').text('No se han registrado hallazgos/acciones.');
      } else {
        findings.forEach((f, idx) => {
          doc.font('Helvetica-Bold').text(`${idx + 1}. ${f.findingType.toUpperCase()}: ${f.description}`);
          doc.font('Helvetica')
            .text(`   Acción: ${f.correctiveAction}`)
            .text(`   Responsable: ${f.responsibleName} | Área: ${f.responsibleArea || '-'}`)
            .text(`   Fecha Límite: ${f.dueDate} | Estado: ${f.status}`);
          if (f.completionDate) {
            doc.text(`   Fecha Cierre: ${f.completionDate}`);
          }
          doc.moveDown(0.3);
        });
      }
      doc.moveDown(1);
      
      // Conclusions Section
      doc.fillColor(GREEN_HEADER).fontSize(14).font('Helvetica-Bold')
        .text('5. CONCLUSIONES');
      doc.moveDown(0.3);
      doc.fillColor('#333').fontSize(10).font('Helvetica');
      doc.text(investigation.conclusions || 'Sin conclusiones registradas.', { align: 'justify' });
      
      if (investigation.lessonLearned) {
        doc.moveDown(0.5);
        doc.font('Helvetica-Bold').text('Lección Aprendida:');
        doc.font('Helvetica').text(investigation.lessonLearned, { align: 'justify' });
      }
      
      // Footer
      doc.moveDown(2);
      doc.fontSize(8).fillColor('#666')
        .text(`Documento generado el ${new Date().toLocaleDateString('es-CO')} - Sistema SG-SST`, { align: 'center' });
      doc.text('Resolución 1401/2007 - Investigación de incidentes y accidentes de trabajo', { align: 'center' });
      
      doc.end();
    } catch (error: any) {
      console.error('Error generating investigation PDF:', error);
      res.status(500).send(error.message);
    }
  });


