  // GET /api/absences/statistics - Get absence statistics (must be before :id route)
  app.get("/api/absences/statistics", requireAnyPermission(["accidents:view", "accidents:view_self"]), async (req, res) => {
    try {
      const effectiveCompanyId = getEffectiveCompanyId(req);
      const isAdmin = hasGlobalAccess(req.user!.role);
      const { year, month } = req.query;
      
      if (!effectiveCompanyId && !isAdmin) {
        return res.status(403).send("No autorizado");
      }
      
      // Get absences for aggregation
      let baseQuery = db.select().from(schema.workerAbsences);
      const conditions = [];
      
      if (effectiveCompanyId) {
        conditions.push(eq(schema.workerAbsences.companyId, effectiveCompanyId));
      }
      
      const absences = await (conditions.length > 0 
        ? baseQuery.where(and(...conditions))
        : baseQuery);
      
      // Filter by year/month if provided
      let filteredAbsences = absences;
      if (year) {
        filteredAbsences = filteredAbsences.filter(a => {
          const absenceYear = new Date(a.startDate).getFullYear();
          return absenceYear === parseInt(year as string);
        });
      }
      if (month) {
        filteredAbsences = filteredAbsences.filter(a => {
          const absenceMonth = new Date(a.startDate).getMonth() + 1;
          return absenceMonth === parseInt(month as string);
        });
      }
      
      // Calculate statistics
      const totalCases = filteredAbsences.length;
      const totalDaysLost = filteredAbsences.reduce((sum, a) => sum + (a.daysLost || 0), 0);
      
      // Get company worker count for rate calculations
      let totalWorkers = 0;
      if (effectiveCompanyId) {
        const company = await storage.getCompany(effectiveCompanyId);
        totalWorkers = company?.numberOfWorkers || 0;
      }
      
      // Breakdown by type
      const byType: Record<string, { cases: number; daysLost: number }> = {};
      filteredAbsences.forEach(a => {
        const type = a.absenceType || 'other';
        if (!byType[type]) {
          byType[type] = { cases: 0, daysLost: 0 };
        }
        byType[type].cases++;
        byType[type].daysLost += a.daysLost || 0;
      });
      
      // Calculate rates
      const scheduledDays = totalWorkers * 30; // Approximate monthly scheduled days
      const absenteeismRate = scheduledDays > 0 ? (totalDaysLost / scheduledDays) * 100 : 0;
      const frequencyRate = totalWorkers > 0 ? (totalCases / totalWorkers) * 100 : 0;
      const averageDuration = totalCases > 0 ? totalDaysLost / totalCases : 0;
      
      res.json({
        period: { year: year ? parseInt(year as string) : null, month: month ? parseInt(month as string) : null },
        totalWorkers,
        totalCases,
        totalDaysLost,
        absenteeismRate: parseFloat(absenteeismRate.toFixed(4)),
        frequencyRate: parseFloat(frequencyRate.toFixed(4)),
        averageDuration: parseFloat(averageDuration.toFixed(2)),
        byType,
        absences: filteredAbsences
      });
    } catch (error: any) {
      console.error("Error calculating absence statistics:", error);
      res.status(500).send(error.message);
    }
  });
  
