  // POST /api/absences - Create absence (auto-link to accident if accidentId provided)
  app.post("/api/absences", requireAuth, async (req, res) => {
    try {
      const userCompanyId = req.user!.companyId;
      const isAdmin = hasGlobalAccess(req.user!.role);
      
      let companyId: string;
      if (isAdmin) {
        companyId = req.body.companyId;
        if (!companyId) {
          return res.status(400).send("Admin debe especificar companyId");
        }
      } else {
        if (!userCompanyId) {
          return res.status(403).send("Usuario no asociado a una empresa");
        }
        companyId = userCompanyId;
      }
      
      // Validate input
      const validatedData = insertWorkerAbsenceSchema.parse({
        ...req.body,
        companyId
      });
      
      // Auto-calculate daysLost from startDate and endDate
      if (validatedData.startDate && validatedData.endDate) {
        const start = new Date(validatedData.startDate);
        const end = new Date(validatedData.endDate);
        const diffTime = Math.abs(end.getTime() - start.getTime());
        const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24)) + 1;
        validatedData.daysLost = diffDays;
      }
      
      // Insert the absence
      const [newAbsence] = await db.insert(schema.workerAbsences)
        .values(validatedData)
        .returning();
      
      res.status(201).json(newAbsence);
    } catch (error: any) {
      console.error("Error creating absence:", error);
      if (error.name === 'ZodError') {
        return res.status(400).json({ errors: error.errors });
      }
      res.status(500).send(error.message);
    }
  });
  
  // PATCH /api/absences/:id - Update absence
  app.patch("/api/absences/:id", requireAuth, async (req, res) => {
    try {
      const effectiveCompanyId = getEffectiveCompanyId(req);
      const isAdmin = hasGlobalAccess(req.user!.role);
      
      // Get existing absence
      const [existingAbsence] = await db.select().from(schema.workerAbsences)
        .where(eq(schema.workerAbsences.id, req.params.id));
      
      if (!existingAbsence) {
        return res.status(404).send("Ausencia no encontrada");
      }
      
      // Tenant isolation check
      if (!isAdmin && existingAbsence.companyId !== effectiveCompanyId) {
        return res.status(403).send("No autorizado para modificar esta ausencia");
      }
      
      // Prepare update data
      const updateData = { ...req.body };
      delete updateData.id;
      delete updateData.companyId;
      delete updateData.createdAt;
      
      // Recalculate daysLost if dates changed
      const startDate = updateData.startDate || existingAbsence.startDate;
      const endDate = updateData.endDate || existingAbsence.endDate;
      if (startDate && endDate) {
        const start = new Date(startDate);
        const end = new Date(endDate);
        const diffTime = Math.abs(end.getTime() - start.getTime());
        const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24)) + 1;
        updateData.daysLost = diffDays;
      }
      
      updateData.updatedAt = new Date();
      
      const [updatedAbsence] = await db.update(schema.workerAbsences)
        .set(updateData)
        .where(eq(schema.workerAbsences.id, req.params.id))
        .returning();
      
      res.json(updatedAbsence);
    } catch (error: any) {
      console.error("Error updating absence:", error);
      res.status(500).send(error.message);
    }
  });
  
