  app.post("/api/trainings/:trainingId/attendees", requirePermission("trainings:edit"), async (req, res) => {
    try {
      const userCompanyId = req.user!.companyId;
      const isAdmin = hasGlobalAccess(req.user!.role);
      const { trainingId } = req.params;
      const { workerId } = req.body;
      
      if (!workerId) {
        return res.status(400).send("workerId es requerido");
      }
      
      // Verify training exists and user has access
      const training = await storage.getTrainingById(trainingId);
      if (!training) {
        return res.status(404).send("Capacitación no encontrada");
      }
      
      const effectiveCompanyId = isAdmin ? training.companyId : userCompanyId;
      
      if (!isAdmin && training.companyId !== userCompanyId) {
        return res.status(403).send("No tiene permisos para editar esta capacitación");
      }
      
      // Verify worker exists and belongs to the same company
      const worker = await storage.getWorkerById(workerId);
      if (!worker || worker.companyId !== training.companyId) {
        return res.status(400).send("Trabajador no encontrado o no pertenece a la misma empresa");
      }
      
      // Check if already added
      const existingAttendees = await storage.getTrainingAttendees(trainingId, effectiveCompanyId!);
      if (existingAttendees.some(a => a.workerId === workerId)) {
        return res.status(400).send("El trabajador ya está inscrito en esta capacitación");
      }
      
      const attendee = await storage.addTrainingAttendee({
        trainingId,
        workerId,
        attended: 0,
      }, effectiveCompanyId!);
      
      res.json(attendee);
    } catch (error: any) {
      console.error('Error adding training attendee:', error);
      res.status(500).send(error.message);
    }
  });

