  app.patch('/api/inspecciones-peligros/:id', requireAuth, requirePermission('sst_management:edit'), async (req, res) => {
    try {
      const isAdmin = hasGlobalAccess(req.user!.role);
      let companyId: string;

      if (isAdmin) {
        // Admin: fetch specific record to get companyId (targeted lookup, no cross-tenant data loading)
        const existing = await storage.getInspeccionPeligroVinculadoById(req.params.id);
        if (!existing) {
          return res.status(404).send('Vínculo no encontrado');
        }
        companyId = existing.companyId;
      } else {
        companyId = req.user!.companyId!;
        // Verify linkage exists in user's company before update
        const existing = await storage.getInspeccionPeligroVinculado(req.params.id, companyId);
        if (!existing) {
          return res.status(404).send('Vínculo no encontrado');
        }
      }

      // Custom update schema without refine() for partial updates
      const updateSchema = z.object({
        peligroId: z.string().optional(),
        estadoControl: z.enum(['conforme', 'no-conforme', 'observacion']).optional(),
        hallazgos: z.string().optional().nullable(),
        evidenciaFotografica: z.string().optional().nullable(),
        verificadoPor: z.string().optional().nullable(),
        fechaVerificacion: z.coerce.date().optional(),
      }).partial();

      const validatedData = updateSchema.parse(req.body);
      const updated = await storage.updateInspeccionPeligroVinculado(req.params.id, validatedData, companyId);
      
      if (!updated) {
        return res.status(404).send('Vínculo no encontrado');
      }
      res.json(updated);
    } catch (error: any) {
      console.error('Error updating inspeccion-peligro linkage:', error);
      res.status(500).send(error.message);
    }
  });

