  // GET /api/occupational-diseases/:id/furel-pdf - Generate FUREL PDF (Resolution 156/2005)
  app.get("/api/occupational-diseases/:id/furel-pdf", requireAuth, async (req, res) => {
    try {
      const companyId = req.user!.companyId;
      if (!companyId) {
        return res.status(403).send("Usuario no asociado a una empresa");
      }
      
      // Get occupational disease
      const disease = await storage.getOccupationalDisease(req.params.id, companyId);
      if (!disease) {
        return res.status(404).send("Enfermedad ocupacional no encontrada");
      }
      
      // Get related data
      const worker = await storage.getWorker(disease.workerId, disease.companyId);
      const company = await storage.getCompany(disease.companyId);
      
      if (!worker || !company) {
        return res.status(404).send("Datos relacionados no encontrados");
      }
      
      // Create PDF
      const { default: PDFDocument } = await import('pdfkit');
      const doc = new PDFDocument({ margin: 35, size: 'LETTER' });
      // Obtener estado de suscripción para marca de agua
      const furel_subscription = await storage.getSubscriptionByCompany(companyId);
      const furel_trialStatus = getTrialStatus(furel_subscription?.status || 'trial', furel_subscription?.trialEnd || null, true, true);
      setupTrialWatermarkOnAllPages(doc, furel_trialStatus.requiresWatermark);
      const margin = 35;
      const pageWidth = doc.page.width;
      
      // Set response headers
      res.setHeader('Content-Type', 'application/pdf');
      res.setHeader('Content-Disposition', `attachment; filename="FUREL-${disease.id.substring(0, 8)}.pdf"`);
      
      // Pipe PDF to response
      doc.pipe(res);
      
      // Generate content using modular function
      generateFurelPdfContent(doc, disease, worker, company);
      
      // Finalize PDF
      doc.end();
    } catch (error: any) {
      console.error('Error generating FUREL PDF:', error);
      res.status(500).send(error.message);
    }
  });

  // Admin-only: Create admin user
  app.post("/api/admin/users", requirePermission("users:create"), async (req, res) => {
    const { scrypt, randomBytes } = await import("crypto");
    const { promisify } = await import("util");
    const scryptAsync = promisify(scrypt);

    async function hashPassword(password: string) {
      const salt = randomBytes(16).toString("hex");
      const buf = (await scryptAsync(password, salt, 64)) as Buffer;
      return `${buf.toString("hex")}.${salt}`;
    }

    const existingUser = await storage.getUserByUsername(req.body.username);
    if (existingUser) {
      return res.status(400).send("El nombre de usuario ya existe");
    }

    // If workerId is provided, get the workers companyId
    let companyId = req.user?.companyId || req.body.companyId || null;
    let workerId = req.body.workerId || null;
    
    if (workerId) {
      const worker = await storage.getWorkerById(workerId);
      if (worker) {
        companyId = worker.companyId;
      }
    }

    const user = await storage.createUser({
      username: req.body.username,
      password: await hashPassword(req.body.password),
      role: req.body.role || "trabajador",
      workerId: workerId,
      companyId: companyId,
      fullName: req.body.fullName || null,
      email: req.body.email || null,
    });

    // Don't send password to frontend
    res.status(201).json(stripPassword(user));
  });

  // Superadmin-only: Create support staff user
  app.post("/api/admin/support-users", requireRole(["superadmin"]), async (req, res) => {
    try {
      const { scrypt, randomBytes } = await import("crypto");
      const { promisify } = await import("util");
      const scryptAsync = promisify(scrypt);

      async function hashPassword(password: string) {
        const salt = randomBytes(16).toString("hex");
        const buf = (await scryptAsync(password, salt, 64)) as Buffer;
        return `${buf.toString("hex")}.${salt}`;
      }

      const { username, password, fullName, email, supportSpecialties } = req.body;

      if (!username || !password) {
        return res.status(400).send("Se requiere nombre de usuario y contraseña");
      }

      const existingUser = await storage.getUserByUsername(username);
      if (existingUser) {
        return res.status(400).send("El nombre de usuario ya existe");
      }

      const user = await storage.createUser({
        username,
        password: await hashPassword(password),
        role: "soporte",
        fullName: fullName || null,
        email: email || null,
        companyId: null,
        workerId: null,
        supportSpecialties: supportSpecialties || null,
      });

      res.status(201).json(stripPassword(user));
    } catch (error: any) {
      console.error('Error creating support user:', error);
      res.status(500).send("Error al crear usuario de soporte");
    }
  });

