  // Upload evidence file
  app.post("/api/sst-evidence/upload", requirePermission("sst_evaluations:create"), upload.single('file'), async (req, res) => {
    try {
      const companyId = req.user!.companyId;
      if (!companyId) {
        return res.status(403).send("Usuario no asociado a una empresa");
      }
      
      if (!req.file) {
        return res.status(400).send("No se proporcionó ningún archivo");
      }
      
      const { evaluationItemId, description } = req.body;
      
      if (!evaluationItemId) {
        return res.status(400).send("evaluationItemId es requerido");
      }
      
      // Upload to Object Storage
      let fileUrl: string;
      try {
        const storageService = new ObjectStorageService();
        const objectId = randomUUID();
        const ext = path.extname(req.file.originalname);
        const objectPath = `${objectId}${ext}`;
        
        // Read temp file and upload to S3
        const fileBuffer = await fs.promises.readFile(req.file.path);
        fileUrl = await storageService.uploadObject(objectPath, fileBuffer, req.file.mimetype);
        
        // Delete temp file
        await fs.promises.unlink(req.file.path);
      } catch (objStorageError: any) {
        // Fallback to local storage if Object Storage fails
        console.error('Object Storage upload failed, using local storage:', objStorageError.message);
        fileUrl = `/uploads/evidences/${req.file.filename}`;
      }
      
      const evidenceData = {
        evaluationItemId,
        fileName: req.file.originalname,
        fileUrl,
        fileType: req.file.mimetype,
        description: description || null,
        uploadDate: new Date(),
      };
      
      const evidence = await storage.createSstEvidence(evidenceData, companyId);
      res.status(201).json(evidence);
    } catch (error: any) {
      res.status(400).send(error.message);
    }
  });

