  // Generate PDF report for evaluation (multi-tenant isolated)
  app.get("/api/sst-evaluations/:id/report", requireAuth, async (req, res) => {
    try {
      const companyId = req.user!.companyId;
      if (!companyId) {
        return res.status(403).send("Usuario no asociado a una empresa");
      }
      
      const evaluationId = req.params.id;
      
      // Get evaluation data
      const evaluation = await storage.getSstEvaluation(evaluationId, companyId);
      if (!evaluation) {
        return res.status(404).send("Evaluación no encontrada");
      }
      
      // Get company data for logo
      const company = await storage.getCompany(companyId);
      
      // Get evaluation items
      const evaluationItems = await storage.getSstEvaluationItems(evaluationId, companyId);
      
      // Get all SST items and standards for this evaluation type
      const allItems = await storage.getSstItems(evaluation.standardType);
      const allStandards = await storage.getSstStandards(evaluation.standardType);

      // Fetch worker data for approval signatures if IDs are present
      let elaboroName = evaluation.evaluator || 'Evaluador SST';
      let autorizoName = req.user?.username || 'Sistema';
      let aproboName = 'Gerencia';

      if (evaluation.elaboradoPorId) {
        const worker = await storage.getWorker(evaluation.elaboradoPorId, companyId);
        if (worker && worker.companyId === companyId) {
          elaboroName = `${worker.name} - ${worker.position}`;
        }
      }

      if (evaluation.autorizadoPorId) {
        const worker = await storage.getWorker(evaluation.autorizadoPorId, companyId);
        if (worker && worker.companyId === companyId) {
          autorizoName = `${worker.name} - ${worker.position}`;
        }
      }

      if (evaluation.aprobadoPorId) {
        const worker = await storage.getWorker(evaluation.aprobadoPorId, companyId);
        if (worker && worker.companyId === companyId) {
          aproboName = `${worker.name} - ${worker.position}`;
        }
      }
      
      // Create PDF document
      const { default: PDFDocument } = await import('pdfkit');
      const doc = new PDFDocument({ margin: 35, size: 'LETTER' });
      // Obtener estado de suscripción para marca de agua
      const sst_subscription = await storage.getSubscriptionByCompany(companyId);
      const sst_trialStatus = getTrialStatus(sst_subscription?.status || 'trial', sst_subscription?.trialEnd || null, true, true);
      setupTrialWatermarkOnAllPages(doc, sst_trialStatus.requiresWatermark);
      const margin = 35;
      const pageWidth = doc.page.width;
      
      // Set response headers for PDF download
      res.setHeader('Content-Type', 'application/pdf');
      res.setHeader('Content-Disposition', `attachment; filename="Informe-SST-${evaluation.title.replace(/\s+/g, '-')}.pdf"`);
      
      // Pipe PDF to response
      doc.pipe(res);
      
      
      // Standard Header with logo, version control, and signatures
      let currentY = setupPdfHeadersFooters({
        doc,
        company: company || { name: 'Empresa', nit: 'N/A', address: null, logoUrl: null },
        documentTitle: 'INFORME DE EVALUACIÓN SST',
        documentCode: `SST-EVAL-${new Date(evaluation.evaluationDate).getFullYear()}-${String(Math.floor(Math.random() * 1000)).padStart(3, '0')}`,
        version: '1.0',
        date: new Date(evaluation.evaluationDate),
        elaboro: elaboroName,
        autorizo: autorizoName,
        aprobo: aproboName
      });

      doc.y = currentY;
      
      // Evaluation information
      doc.fontSize(9).font('Helvetica-Bold').text('INFORMACIÓN DE LA EVALUACIÓN', { underline: true });
      doc.moveDown(0.5);
      
      doc.fontSize(9).font('Helvetica-Bold').text('Título: ', { continued: true });
      doc.font('Helvetica').text(evaluation.title);
      
      doc.font('Helvetica-Bold').text('Tipo de Norma: ', { continued: true });
      const standardTypeText = evaluation.standardType === 'ISO_45001' 
        ? 'ISO 45001:2018 (Norma Internacional)' 
        : 'Resolución 0312/2019 (Estándares Mínimos Colombia)';
      doc.font('Helvetica').text(standardTypeText);
      
      doc.font('Helvetica-Bold').text('Fecha de Evaluación: ', { continued: true });
      doc.font('Helvetica').text(new Date(evaluation.evaluationDate).toLocaleDateString('es-CO', { year: 'numeric', month: 'long', day: 'numeric' }));
      
      doc.font('Helvetica-Bold').text('Estado: ', { continued: true });
      const statusMap: Record<string, string> = {
        'en-progreso': 'En Progreso',
        'completada': 'Completada',
        'aprobada': 'Aprobada',
        'rechazada': 'Rechazada'
      };
      doc.font('Helvetica').text(statusMap[evaluation.status] || evaluation.status);
      
      doc.font('Helvetica-Bold').text('Evaluador: ', { continued: true });
      doc.font('Helvetica').text(evaluation.evaluator || 'No especificado');
      
      if (evaluation.observations) {
        doc.font('Helvetica-Bold').text('Observaciones: ', { continued: true });
        doc.font('Helvetica').text(evaluation.observations);
      }
      
      doc.moveDown(1.5);
      
      // Compliance summary
      doc.fontSize(9).font('Helvetica-Bold').text('RESUMEN DE CUMPLIMIENTO', { underline: true });
      doc.moveDown(0.5);
      
      const compliancePercentage = evaluation.compliancePercentage;
      let complianceStatus = '';
      if (compliancePercentage >= 85) {
        complianceStatus = 'EXCELENTE - Cumplimiento satisfactorio';
      } else if (compliancePercentage >= 60) {
        complianceStatus = 'ACEPTABLE - Requiere mejoras';
      } else {
        complianceStatus = 'CRÍTICO - Acción inmediata requerida';
      }
      
      doc.fontSize(9).font('Helvetica-Bold').text('Puntaje Total: ', { continued: true });
      doc.font('Helvetica').text(`${evaluation.totalScore} / ${evaluation.maxTotalScore} puntos`);
      
      doc.font('Helvetica-Bold').text('Porcentaje de Cumplimiento: ', { continued: true });
      doc.font('Helvetica').text(`${compliancePercentage.toFixed(1)}% - ${complianceStatus}`);
      
      doc.moveDown(1.5);
      
      // Items evaluated by standard
      doc.fontSize(9).font('Helvetica-Bold').text('DETALLE DE ESTÁNDARES EVALUADOS', { underline: true });
      doc.moveDown(0.5);
      
      // Group items by standard
      const itemsByStandard = new Map<string, typeof evaluationItems>();
      for (const evalItem of evaluationItems) {
        const item = allItems.find(i => i.id === evalItem.itemId);
        if (item) {
          if (!itemsByStandard.has(item.standardId)) {
            itemsByStandard.set(item.standardId, []);
          }
          itemsByStandard.get(item.standardId)!.push(evalItem);
        }
      }
      
      // Render each standard with its items
      for (const standard of allStandards) {
        const standardItems = itemsByStandard.get(standard.id) || [];
        if (standardItems.length === 0) continue;
        
        // Check if we need a new page
        if (doc.y > 650) {
          doc.addPage();
        }
        
        doc.fontSize(9).font('Helvetica-Bold').fillColor('#1a73e8').text(`${standard.phvaCycle.toUpperCase()} - ${standard.name}`, { underline: false });
        doc.fillColor('#000000');
        doc.fontSize(7).font('Helvetica').text(standard.description || '');
        doc.moveDown(0.3);
        
        // Calculate standard score
        const standardTotal = standardItems.reduce((sum, item) => sum + (item.score || 0), 0);
        const standardMax = standardItems.reduce((sum, item) => {
          const itemDef = allItems.find(i => i.id === item.itemId);
          return sum + (itemDef?.maxScore || 0);
        }, 0);
        const standardPercentage = standardMax > 0 ? (standardTotal / standardMax) * 100 : 0;
        
        doc.fontSize(8).font('Helvetica-Bold').text(`Cumplimiento: ${standardPercentage.toFixed(1)}% (${standardTotal}/${standardMax} puntos)`, { indent: 20 });
        doc.moveDown(0.5);
        
        // Render items
        for (const evalItem of standardItems) {
          const item = allItems.find(i => i.id === evalItem.itemId);
          if (!item) continue;
          
          // Check if we need a new page for this item
          if (doc.y > 680) {
            doc.addPage();
          }
          
          doc.fontSize(8).font('Helvetica-Bold').text(`• Ítem ${item.itemNumber}: `, { indent: 40, continued: true });
          doc.font('Helvetica').text(item.description);
          doc.fontSize(7).font('Helvetica').text(`Puntaje: ${evalItem.score || 0} / ${item.maxScore}`, { indent: 50 });
          
          if (evalItem.observations) {
            doc.fontSize(9).font('Helvetica-Oblique').text(`Observaciones: ${evalItem.observations}`, { indent: 50 });
          }
          
          doc.moveDown(0.3);
        }
        
        doc.moveDown(0.5);
      }
      
      // Footer with signature section
      doc.addPage();
      doc.moveDown(10);
      doc.fontSize(9).font('Helvetica-Bold').text('FIRMAS Y APROBACIONES', { align: 'center' });
      doc.moveDown(2);
      
      // Signature lines
      const signatureY = doc.y;
      doc.fontSize(7).font('Helvetica').text('_________________________', 100, signatureY);
      doc.text('_________________________', 350, signatureY);
      doc.moveDown(0.5);
      doc.text('Responsable de Evaluación', 100, doc.y);
      doc.text('Coordinador SST', 350, doc.y);
      doc.moveDown(2);
      
      doc.fontSize(9).font('Helvetica-Oblique').text(`Fecha de generación: ${new Date().toLocaleDateString('es-CO', { year: 'numeric', month: 'long', day: 'numeric', hour: '2-digit', minute: '2-digit' })}`, { align: 'center' });
      
      // Finalize PDF
      doc.end();
    } catch (error: any) {
      console.error('Error generating PDF:', error);
      res.status(500).send(error.message);
    }
  });

  // Statistics endpoint for dashboard (multi-tenant isolated)
  app.get("/api/stats", requireAuth, async (req, res) => {
    const companyId = getEffectiveCompanyId(req);
    if (!companyId) {
      return res.status(403).send("Usuario no asociado a una empresa");
    }
    
    const [accidents, trainings, inspections, workers, evaluaciones] = await Promise.all([
      storage.getAccidents(companyId),
      storage.getTrainings(companyId),
      storage.getInspections(companyId),
      storage.getWorkers(companyId),
      storage.getEvaluacionesSst(companyId),
    ]);

    // Calculate monthly accidents
    const now = new Date();
    const currentMonth = now.getMonth();
    const currentYear = now.getFullYear();
    
    const monthlyAccidents = accidents.filter(a => {
      const accidentDate = new Date(a.date);
      return accidentDate.getMonth() === currentMonth && accidentDate.getFullYear() === currentYear;
    });

    // Get compliance from the latest SST evaluation
    let avgCompliance = 0;
    if (evaluaciones.length > 0) {
      // Sort by year and month descending to get the latest
      const sortedEvaluaciones = [...evaluaciones].sort((a, b) => {
        if (a.anio !== b.anio) return b.anio - a.anio;
        return b.mes - a.mes;
      });
      avgCompliance = sortedEvaluaciones[0].porcentajeCumplimiento ?? 0;
    }

    res.json({
      monthlyAccidents: monthlyAccidents.length,
      totalTrainings: trainings.length,
      totalInspections: inspections.length,
      avgCompliance,
      totalWorkers: workers.length,
    });
  });

