  app.post("/api/road-safety-attendees/bulk", requirePermission("road_safety_trainings:create"), async (req, res) => {
    try {
      const companyId = req.user!.companyId;
      if (!companyId) {
        return res.status(403).send("Usuario no asociado a una empresa");
      }
      
      const { trainingId, attendance } = req.body;
      if (!trainingId || !Array.isArray(attendance)) {
        return res.status(400).send("Datos de asistencia inválidos");
      }
      
      for (const record of attendance) {
        const { driverId, attended } = record;
        const existing = await storage.getRoadSafetyAttendees(trainingId, companyId);
        const existingRecord = existing.find((a: any) => a.driverId === driverId);
        
        if (existingRecord) {
          await storage.updateRoadSafetyAttendance(trainingId, driverId, attended, companyId);
        } else {
          await storage.addRoadSafetyAttendee({
            trainingId,
            driverId,
            attended,
          }, companyId);
        }
      }
      
      res.json({ success: true });
    } catch (error: any) {
      res.status(400).send(error.message);
    }
  });

