  // Get job profile references - check what's associated before deletion
  app.get("/api/job-profiles/:id/references", requireAnyPermission(["job_profiles:view", "job_profiles:delete"]), async (req, res) => {
    try {
      const userRole = req.user!.role;
      const isAdmin = hasGlobalAccess(userRole);
      
      const profile = await storage.getJobProfileById(req.params.id);
      if (!profile) {
        return res.status(404).send("Perfil de cargo no encontrado");
      }
      
      // Verify company access for non-admin users
      if (!isAdmin) {
        const companyId = req.user!.companyId;
        if (!companyId || profile.companyId !== companyId) {
          return res.status(403).send("No tiene permiso para ver este perfil");
        }
      }
      
      const refs = await storage.getJobProfileReferences(req.params.id);
      res.json({
        profileId: req.params.id,
        profileName: profile.name,
        references: refs,
        canForceDeleteWorkers: refs.workers > 0 && refs.medicalExams === 0 && refs.altoRiesgo === 0 && refs.contracts === 0 && refs.designaciones === 0
      });
    } catch (error: any) {
      console.error("Error getting job profile references:", error);
      res.status(500).send("Error al obtener referencias del perfil");
    }
  });

  app.delete("/api/job-profiles/:id", requirePermission("job_profiles:delete"), async (req, res) => {
    try {
      const userRole = req.user!.role;
      const isAdmin = hasGlobalAccess(userRole);
      const forceDisassociateWorkers = req.query.forceDisassociateWorkers === 'true';
      
      let companyId: string;
      if (isAdmin) {
        // Admin can delete job profiles from any company
        const existingProfile = await storage.getJobProfileById(req.params.id);
        if (!existingProfile) {
          return res.status(404).send("Perfil de cargo no encontrado");
        }
        companyId = existingProfile.companyId;
      } else {
        companyId = req.user!.companyId || "";
        if (!companyId) {
          return res.status(403).send("Usuario no asociado a una empresa");
        }
      }
      
      // Verificar referencias antes de eliminar (incluyendo todas las tablas con FK)
      const refs = await storage.getJobProfileReferences(req.params.id);
      const nonWorkerRefs = refs.medicalExams + refs.altoRiesgo + refs.contracts + refs.designaciones;
      const totalRefs = refs.workers + nonWorkerRefs;
      
      // If force disassociate is requested, only allow if there are only worker references
      if (forceDisassociateWorkers && refs.workers > 0 && nonWorkerRefs === 0) {
        // Disassociate all workers from this profile (set jobProfileId to null)
        await storage.disassociateWorkersFromJobProfile(req.params.id);
        // Now delete the profile
        await storage.deleteJobProfile(req.params.id, companyId);
        return res.json({ 
          message: "Perfil eliminado", 
          disassociatedWorkers: refs.workers 
        });
      }
      
      if (totalRefs > 0) {
        const details: string[] = [];
        if (refs.workers > 0) details.push(`${refs.workers} trabajador(es)`);
        if (refs.medicalExams > 0) details.push(`${refs.medicalExams} examen(es) médico(s)`);
        if (refs.altoRiesgo > 0) details.push(`${refs.altoRiesgo} designación(es) de alto riesgo`);
        if (refs.contracts > 0) details.push(`${refs.contracts} contrato(s)`);
        if (refs.designaciones > 0) details.push(`${refs.designaciones} designación(es) de responsable`);
        
        return res.status(409).json({
          message: "No se puede eliminar el perfil de cargo porque está en uso",
          details: `Este perfil está asociado a: ${details.join(", ")}. Debe desasociar estos registros primero.`,
          references: refs,
          canForceDeleteWorkers: refs.workers > 0 && nonWorkerRefs === 0
        });
      }
      
      try {
        await storage.deleteJobProfile(req.params.id, companyId);
        res.sendStatus(204);
      } catch (deleteError: any) {
        console.error("Error deleting job profile:", deleteError);
        // Check if it's a FK constraint violation
        if (deleteError.code === '23503') {
          return res.status(409).json({
            message: "No se puede eliminar el perfil de cargo porque está en uso",
            details: "El perfil tiene registros asociados en otras tablas. Por favor, elimine primero esos registros.",
            error: deleteError.detail || deleteError.message
          });
        }
        const errorMessage = deleteError.message || "Error al eliminar el perfil de cargo";
        res.status(500).send(errorMessage);
      }
    } catch (error: any) {
      console.error("Error in job profile delete endpoint:", error);
      const errorMessage = error.message || "Error al eliminar el perfil de cargo";
      res.status(500).send(errorMessage);
    }
  });

  // Batch update workers with job profile - Asignar perfil de cargo a múltiples trabajadores
  app.post("/api/job-profiles/:id/assign-workers", requirePermission("job_profiles:edit"), async (req, res) => {
    try {
      const userRole = req.user!.role;
      const isAdmin = hasGlobalAccess(userRole);
      const profileId = req.params.id;
      const { workerIds } = req.body;
      
      if (!Array.isArray(workerIds) || workerIds.length === 0) {
        return res.status(400).send("Debe proporcionar una lista de IDs de trabajadores");
      }
      
      // Validate job profile exists and get companyId
      const profile = await storage.getJobProfileById(profileId);
      if (!profile) {
        return res.status(404).send("Perfil de cargo no encontrado");
      }
      
      // Verify access
      if (!isAdmin) {
        const userCompanyId = req.user!.companyId;
        if (!userCompanyId || userCompanyId !== profile.companyId) {
          return res.status(403).send("No tiene acceso a este perfil de cargo");
        }
      }
      
      // Update each worker's position with the profile name
      let updatedCount = 0;
      const errors: string[] = [];
      
      for (const workerId of workerIds) {
        try {
          const worker = await storage.getWorkerById(workerId);
          if (!worker) {
            errors.push(`Trabajador ${workerId} no encontrado`);
            continue;
          }
          
          // Verify worker belongs to same company as profile
          if (worker.companyId !== profile.companyId) {
            errors.push(`Trabajador ${worker.name} no pertenece a la misma empresa del perfil`);
            continue;
          }
          
          // Update worker's position with profile name and set jobProfileId for proper linking
          await storage.updateWorker(workerId, { position: profile.name, jobProfileId: profile.id }, profile.companyId);
          updatedCount++;
        } catch (err: any) {
          errors.push(`Error actualizando trabajador ${workerId}: ${err.message}`);
        }
      }
      
      res.json({
        success: true,
        updatedCount,
        totalRequested: workerIds.length,
        profileName: profile.name,
        errors: errors.length > 0 ? errors : undefined
      });
    } catch (error: any) {
      console.error('[POST /api/job-profiles/:id/assign-workers] Error:', error.message);
      res.status(500).send(error.message);
    }
  });

  // Batch create job profiles - Create multiple job profiles in a single transaction
  app.post("/api/job-profiles/batch", requirePermission("job_profiles:create"), async (req, res) => {
    try {
      const userRole = req.user!.role;
      const isAdmin = hasGlobalAccess(userRole);
      
      const { profiles, companyId: requestCompanyId } = req.body;
      
      if (!Array.isArray(profiles) || profiles.length === 0) {
        return res.status(400).send("Debe proporcionar una lista de perfiles a crear");
      }
      
      // Determine companyId
      let companyId: string;
      if (isAdmin) {
        companyId = requestCompanyId;
        if (!companyId) {
          return res.status(400).send("Debe seleccionar una empresa");
        }
      } else {
        companyId = req.user!.companyId || "";
        if (!companyId) {
          return res.status(403).send("Usuario no asociado a una empresa");
        }
      }
      
      // Validate each profile
      const validatedProfiles = [];
      const errors: string[] = [];
      
      for (let i = 0; i < profiles.length; i++) {
        try {
          const validatedData = insertJobProfileSchema.parse(profiles[i]);
          validatedProfiles.push(validatedData);
        } catch (err: any) {
          errors.push(`Perfil ${i + 1} (${profiles[i]?.name || 'sin nombre'}): ${err.message}`);
        }
      }
      
      if (errors.length > 0) {
        return res.status(400).json({
          success: false,
          message: "Errores de validación",
          errors
        });
      }
      
      // Get existing profiles for this company to check for duplicates
      const existingProfiles = await storage.getJobProfiles(companyId);
      const existingProfilesByName = new Map<string, typeof existingProfiles[0]>();
      for (const p of existingProfiles) {
        existingProfilesByName.set(p.name.toLowerCase().trim(), p);
      }
      
      // Create all profiles and auto-assign workers
      const createdProfiles = [];
      const reusedProfiles: { id: string; name: string }[] = [];
      let totalWorkersAssigned = 0;
      let totalWorkersSkipped = 0;
      
      // Get all workers for this company to match by position
      const companyWorkers = await storage.getWorkers(companyId);
      
      for (const profileData of validatedProfiles) {
        try {
          const profileNameLower = profileData.name.toLowerCase().trim();
          let profile;
          
          // Check if profile with this name already exists
          const existingProfile = existingProfilesByName.get(profileNameLower);
          if (existingProfile) {
            profile = existingProfile;
            reusedProfiles.push({ id: profile.id, name: profile.name });
          } else {
            profile = await storage.createJobProfile(profileData, companyId);
            createdProfiles.push(profile);
            existingProfilesByName.set(profileNameLower, profile);
          }
          
          // Find all workers whose position matches this profile name
          const allMatchingWorkers = companyWorkers.filter(w => 
            w.position && 
            w.position.toLowerCase().trim() === profileNameLower
          );
          
          // Separate: workers without jobProfileId can be assigned, others are skipped
          const workersToAssign = allMatchingWorkers.filter(w => !w.jobProfileId);
          const workersAlreadyLinked = allMatchingWorkers.filter(w => w.jobProfileId);
          
          totalWorkersSkipped += workersAlreadyLinked.length;
          
          if (workersToAssign.length > 0) {
            for (const worker of workersToAssign) {
              try {
                await storage.updateWorker(worker.id, { jobProfileId: profile.id });
                totalWorkersAssigned++;
              } catch (assignErr: any) {
                console.warn(`Could not auto-assign worker ${worker.id} to profile ${profile.id}: ${assignErr.message}`);
              }
            }
          }
        } catch (err: any) {
          errors.push(`Error creando perfil '${profileData.name}': ${err.message}`);
        }
      }
      
      res.status(201).json({
        success: true,
        createdCount: createdProfiles.length,
        reusedCount: reusedProfiles.length,
        totalRequested: profiles.length,
        workersAssigned: totalWorkersAssigned,
        workersSkipped: totalWorkersSkipped,
        profiles: createdProfiles,
        reusedProfiles,
        errors: errors.length > 0 ? errors : undefined
      });
    } catch (error: any) {
      console.error('[POST /api/job-profiles/batch] Error:', error.message);
      res.status(500).send(error.message);
    }
  });



  // Sync workers to job profiles based on position matching
  app.post("/api/job-profiles/sync-workers", requirePermission("job_profiles:edit"), async (req, res) => {
    try {
      const userRole = req.user!.role;
      const isAdmin = hasGlobalAccess(userRole);
      const { companyId: requestCompanyId } = req.body;
      
      let companyId: string;
      if (isAdmin) {
        companyId = requestCompanyId;
        if (!companyId) {
          return res.status(400).send("Debe seleccionar una empresa");
        }
      } else {
        companyId = req.user!.companyId || "";
        if (!companyId) {
          return res.status(403).send("Usuario no asociado a una empresa");
        }
      }
      
      const profiles = await storage.getJobProfiles(companyId);
      const workers = await storage.getWorkers(companyId);
      
      const profilesByName = new Map<string, typeof profiles[0]>();
      for (const p of profiles) {
        profilesByName.set(p.name.toLowerCase().trim(), p);
      }
      
      let totalAssigned = 0;
      let alreadyLinked = 0;
      let noMatchingProfile = 0;
      const errors: string[] = [];
      
      for (const worker of workers) {
        if (!worker.position) {
          continue;
        }
        
        if (worker.jobProfileId) {
          alreadyLinked++;
          continue;
        }
        
        const positionLower = worker.position.toLowerCase().trim();
        const matchingProfile = profilesByName.get(positionLower);
        
        if (!matchingProfile) {
          noMatchingProfile++;
          continue;
        }
        
        try {
          await storage.updateWorker(worker.id, { jobProfileId: matchingProfile.id }, companyId);
          totalAssigned++;
        } catch (err: any) {
          errors.push(`Error vinculando ${worker.name}: ${err.message}`);
        }
      }
      
      res.json({
        success: true,
        totalAssigned,
        alreadyLinked,
        noMatchingProfile,
        totalWorkers: workers.length,
        errors: errors.length > 0 ? errors : undefined
      });
    } catch (error: any) {
      console.error('[POST /api/job-profiles/sync-workers] Error:', error.message);
      res.status(500).send(error.message);
    }
  });

  // Bulk delete job profiles for a company
  app.delete("/api/job-profiles/bulk-delete/:companyId", requirePermission("job_profiles:delete"), async (req, res) => {
    const targetCompanyId = req.params.companyId;
    const userRole = req.user!.role;
    const isAdmin = hasGlobalAccess(userRole);
    const userCompanyId = req.user!.companyId;

    if (!isAdmin && userCompanyId !== targetCompanyId) {
      return res.status(403).json({ error: "No tiene permisos para eliminar perfiles de esta empresa" });
    }

    const { confirmationCode, confirmCompanyName } = req.body;
    if (confirmationCode !== "ELIMINAR-TODOS-LOS-PERFILES") {
      return res.status(400).json({ error: "Código de confirmación incorrecto" });
    }

    try {
      const company = await storage.getCompany(targetCompanyId);
      if (!company) {
        return res.status(404).json({ error: "Empresa no encontrada" });
      }

      if (confirmCompanyName !== company.name) {
        return res.status(400).json({ error: "El nombre de la empresa no coincide" });
      }

      const profiles = await storage.getJobProfiles(targetCompanyId);
      if (profiles.length === 0) {
        return res.status(400).json({ error: "No hay perfiles para eliminar" });
      }

      let deleted = 0;
      let errors: string[] = [];

      for (const profile of profiles) {
        try {
          await storage.deleteJobProfile(profile.id, targetCompanyId);
          deleted++;
        } catch (error: any) {
          if (error.code === '23503') {
            errors.push(`\${profile.name}: Tiene trabajadores asignados`);
          } else {
            errors.push(`\${profile.name}: Error desconocido`);
          }
        }
      }

      console.log("[Bulk Worker Delete] Critical action:", {
        action: "bulk_delete_job_profiles",
        companyId: targetCompanyId,
        companyName: company.name,
        userId: req.user!.id,
        totalProfiles: profiles.length,
        deleted,
        errors: errors.length,
      }, `Eliminación masiva de perfiles: \${deleted}/\${profiles.length}`);

      if (errors.length > 0) {
        return res.status(207).json({
          message: `Se eliminaron \${deleted} de \${profiles.length} perfiles`,
          deleted,
          total: profiles.length,
          errors,
        });
      }

      res.json({
        message: `Se eliminaron exitosamente los \${deleted} perfiles`,
        deleted,
        total: profiles.length,
      });
    } catch (error: any) {
      console.error("Error en eliminación masiva de perfiles:", error.message);
      res.status(500).json({ error: "Error al eliminar perfiles: " + error.message });
    }
  });
