  app.post("/api/contracts", requirePermission("contracts:create"), async (req, res) => {
    try {
      // Extract worker data from request body
      const { workerName, workerEmail, companyId: requestCompanyId, ...contractData } = req.body;
      
      const validatedData = insertContractSchema.parse(contractData);
      
      // For admin/super_admin: use companyId from request or worker's company
      // For other roles: use their own companyId
      const userRole = req.user!.role;
      const isAdmin = hasGlobalAccess(userRole);
      
      let companyId: string;
      if (isAdmin) {
        // Admin can specify companyId in request, or we get it from worker
        if (requestCompanyId) {
          companyId = requestCompanyId;
        } else if (validatedData.workerId) {
          const worker = await storage.getWorkerById(validatedData.workerId);
          if (!worker) {
            return res.status(400).send("Trabajador no encontrado");
          }
          companyId = worker.companyId;
        } else {
          return res.status(400).send("Admin debe especificar empresa o trabajador existente");
        }
      } else {
        // Non-admin users can only create contracts for workers in their own company
        companyId = req.user!.companyId || "";
        if (!companyId) {
          return res.status(403).send("Usuario no asociado a una empresa");
        }
      }
      
      // Determine or create worker
      let worker;
      let workerId = validatedData.workerId;
      
      if (workerId) {
        // Using existing worker by ID
        worker = await storage.getWorker(workerId, companyId);
        if (!worker) {
          return res.status(400).send("Trabajador no encontrado o no pertenece a esta empresa");
        }
      } else if (validatedData.identificationNumber) {
        // Try to find existing worker by identification number
        const workers = await storage.getWorkers(companyId);
        worker = workers.find(w => w.identificationNumber === validatedData.identificationNumber);
        
        if (worker) {
          // Use existing worker
          workerId = worker.id;
        } else {
          // Create new worker
          if (!workerName) {
            return res.status(400).send("Nombre del trabajador es requerido para crear nuevo trabajador");
          }
          
          const workerData = {
            companyId: companyId,
            name: workerName,
            identificationNumber: validatedData.identificationNumber,
            email: workerEmail || null,
            position: validatedData.position,
            department: validatedData.department || "Sin asignar",
            contractType: validatedData.contractType as "indefinido" | "fijo" | "temporal" | "obra-labor" | "aprendizaje",
            contractNumber: validatedData.contractNumber || `TEMP-${Date.now()}`,
            startDate: validatedData.startDate,
            status: "activo" as const,
          };
          
          worker = await storage.createWorker(workerData, companyId);
          workerId = worker.id;
        }
      } else {
        return res.status(400).send("Debe proporcionar trabajador existente o número de identificación");
      }
      
      // Update validatedData with resolved workerId
      validatedData.workerId = workerId;
      
      // Auto-generate contract number if not provided or empty
      // Format: CONT-{COMPANY_CODE}-{YEAR}-{SEQUENCE}
      if (!validatedData.contractNumber || validatedData.contractNumber.trim() === '') {
        const year = new Date().getFullYear();
        const companyCode = companyId.substring(0, 6).toUpperCase();
        
        // Get existing contracts for this company in this year to determine sequence
        const existingContracts = await storage.getContracts(companyId);
        const currentYearContracts = existingContracts.filter(c => 
          c.contractNumber && c.contractNumber.includes(`-${year}-`)
        );
        const nextSequence = currentYearContracts.length + 1;
        const paddedSequence = nextSequence.toString().padStart(4, '0');
        
        validatedData.contractNumber = `CONT-${companyCode}-${year}-${paddedSequence}`;
        
        // Retry logic in case of race conditions (up to 5 attempts)
        let attempts = 0;
        const maxAttempts = 5;
        while (attempts < maxAttempts) {
          const existing = await storage.getContractByNumber(validatedData.contractNumber, companyId);
          if (!existing) break;
          
          attempts++;
          const newSequence = currentYearContracts.length + attempts + 1;
          const newPaddedSequence = newSequence.toString().padStart(4, '0');
          validatedData.contractNumber = `CONT-${companyCode}-${year}-${newPaddedSequence}`;
          
          if (attempts < maxAttempts) {
            await new Promise(resolve => setTimeout(resolve, Math.random() * 100));
          }
        }
        
        if (attempts >= maxAttempts) {
          return res.status(500).send("No se pudo generar un número de contrato único. Intente nuevamente.");
        }
      } else {
        // Validate that the provided contract number doesn't exist
        const existing = await storage.getContractByNumber(validatedData.contractNumber, companyId);
        if (existing) {
          return res.status(400).send("Ya existe un contrato con este número");
        }
      }
      
      // Validar fechas según tipo de contrato
      if (validatedData.contractType === "fijo") {
        if (!validatedData.endDate) {
          return res.status(400).send("Los contratos a término fijo requieren fecha de finalización");
        }
        
        // Calcular duración en años
        const startDate = new Date(validatedData.startDate);
        const endDate = new Date(validatedData.endDate);
        const durationYears = (endDate.getTime() - startDate.getTime()) / (1000 * 60 * 60 * 24 * 365);
        
        // Validar máximo 4 años según Ley 2466/2025
        if (durationYears > 4) {
          return res.status(400).send("Los contratos a término fijo no pueden exceder 4 años según Ley 2466/2025");
        }
      }
      
      if (validatedData.contractType === "ocasional" && validatedData.endDate) {
        const startDate = new Date(validatedData.startDate);
        const endDate = new Date(validatedData.endDate);
        const durationDays = (endDate.getTime() - startDate.getTime()) / (1000 * 60 * 60 * 24);
        
        if (durationDays > 30) {
          return res.status(400).send("Los contratos ocasionales no pueden exceder 30 días");
        }
      }
      
      const contract = await storage.createContract(validatedData, companyId);
      res.status(201).json(contract);
    } catch (error: any) {
      res.status(400).send(error.message);
    }
  });

  // Endpoint para crear contratos en masa
  app.post("/api/contracts/batch", requirePermission("contracts:create"), async (req, res) => {
    try {
      const { workerIds, contractData } = req.body;
      
      if (!Array.isArray(workerIds) || workerIds.length === 0) {
        return res.status(400).send("Debe proporcionar una lista de IDs de trabajadores");
      }

      const userRole = req.user!.role;
      const isAdmin = hasGlobalAccess(userRole);
      
      let companyId: string;
      if (isAdmin && contractData.companyId) {
        companyId = contractData.companyId;
      } else {
        companyId = req.user!.companyId || "";
        if (!companyId) {
          return res.status(403).send("Usuario no asociado a una empresa");
        }
      }

      // Validar fechas según tipo de contrato
      if (contractData.contractType === "fijo") {
        if (!contractData.endDate) {
          return res.status(400).send("Los contratos a término fijo requieren fecha de finalización");
        }
        
        const startDate = new Date(contractData.startDate);
        const endDate = new Date(contractData.endDate);
        const durationYears = (endDate.getTime() - startDate.getTime()) / (1000 * 60 * 60 * 24 * 365);
        
        if (durationYears > 4) {
          return res.status(400).send("Los contratos a término fijo no pueden exceder 4 años según Ley 2466/2025");
        }
      }
      
      if (contractData.contractType === "ocasional" && contractData.endDate) {
        const startDate = new Date(contractData.startDate);
        const endDate = new Date(contractData.endDate);
        const durationDays = (endDate.getTime() - startDate.getTime()) / (1000 * 60 * 60 * 24);
        
        if (durationDays > 30) {
          return res.status(400).send("Los contratos ocasionales no pueden exceder 30 días");
        }
      }

      // Obtener contratos existentes para generar secuencia
      const existingContracts = await storage.getContracts(companyId);
      const year = new Date().getFullYear();
      const companyCode = companyId.substring(0, 6).toUpperCase();
      const currentYearContracts = existingContracts.filter(c => 
        c.contractNumber && c.contractNumber.includes(`-${year}-`)
      );
      let nextSequence = currentYearContracts.length + 1;

      const results = {
        total: workerIds.length,
        successful: 0,
        failed: 0,
        errors: [] as { workerId: string; error: string }[],
      };

      // Procesar cada trabajador
      for (const workerId of workerIds) {
        try {
          // Verificar que el trabajador existe y pertenece a la empresa
          const worker = await storage.getWorker(workerId, companyId);
          if (!worker) {
            results.failed++;
            results.errors.push({ workerId, error: "Trabajador no encontrado o no pertenece a la empresa" });
            continue;
          }

          // Verificar si ya tiene un contrato activo
          const workerContracts = await storage.getContractsByWorker(workerId, companyId);
          const activeContract = workerContracts.find(c => c.status === "activo");
          if (activeContract) {
            results.failed++;
            results.errors.push({ workerId, error: `${worker.name} ya tiene un contrato activo (${activeContract.contractNumber})` });
            continue;
          }

          // Generar número de contrato único
          let contractNumber: string;
          let attempts = 0;
          const maxAttempts = 10;
          
          do {
            const paddedSequence = nextSequence.toString().padStart(4, '0');
            contractNumber = `CONT-${companyCode}-${year}-${paddedSequence}`;
            const existing = await storage.getContractByNumber(contractNumber, companyId);
            if (!existing) break;
            nextSequence++;
            attempts++;
          } while (attempts < maxAttempts);

          if (attempts >= maxAttempts) {
            results.failed++;
            results.errors.push({ workerId, error: "No se pudo generar número de contrato único" });
            continue;
          }

          // Crear contrato con datos del trabajador
          const newContractData = {
            workerId,
            contractType: contractData.contractType || "indefinido",
            contractNumber,
            startDate: contractData.startDate,
            endDate: contractData.endDate || null,
            position: contractData.position || worker.position,
            department: contractData.department || worker.department,
            workSchedule: contractData.workSchedule || null,
            arlRate: contractData.arlRate || null,
            additionalClauses: contractData.additionalClauses || null,
            jobProfileId: contractData.jobProfileId || null,
            status: "activo" as const,
          };

          await storage.createContract(newContractData, companyId);
          results.successful++;
          nextSequence++;

        } catch (error: any) {
          results.failed++;
          results.errors.push({ workerId, error: error.message || "Error desconocido" });
        }
      }

      res.status(201).json(results);
    } catch (error: any) {
      res.status(400).send(error.message);
    }
  });

  app.patch("/api/contracts/:id", requirePermission("contracts:edit"), async (req, res) => {
    try {
      const userRole = req.user!.role;
      const isAdmin = hasGlobalAccess(userRole);
      
      let companyId: string;
      if (isAdmin) {
        // Admin: get companyId from the existing contract
        const existingContract = await storage.getContractById(req.params.id);
        if (!existingContract) {
          return res.status(404).send("Contrato no encontrado");
        }
        companyId = existingContract.companyId;
      } else {
        // Non-admin: use their own companyId
        companyId = req.user!.companyId || "";
        if (!companyId) {
          return res.status(403).send("Usuario no asociado a una empresa");
        }
      }
      
      const validatedData = insertContractSchema.partial().parse(req.body);
      
      // Si se actualiza el número de contrato, validar que no exista
      if (validatedData.contractNumber) {
        const existing = await storage.getContractByNumber(validatedData.contractNumber, companyId);
        if (existing && existing.id !== req.params.id) {
          return res.status(400).send("Ya existe un contrato con este número");
        }
      }
      
      const contract = await storage.updateContract(req.params.id, validatedData, companyId);
      if (!contract) {
        return res.status(404).send("Contrato no encontrado");
      }
      res.json(contract);
    } catch (error: any) {
      res.status(400).send(error.message);
    }
  });

