  // Configure multer for contract Excel upload
  const contractExcelUpload = multer({
    storage: multer.memoryStorage(),
    limits: {
      fileSize: 5 * 1024 * 1024, // 5MB limit
    },
    fileFilter: (req, file, cb) => {
      const allowedMimeTypes = [
        'application/vnd.ms-excel',
        'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
        'text/csv'
      ];
      const allowedExtensions = ['.xls', '.xlsx', '.csv'];
      const extname = path.extname(file.originalname).toLowerCase();
      
      if (allowedMimeTypes.includes(file.mimetype) && allowedExtensions.includes(extname)) {
        return cb(null, true);
      } else {
        cb(new Error('Tipo de archivo no permitido. Solo se permiten archivos Excel (.xlsx, .xls) o CSV'));
      }
    }
  });

  app.post("/api/contracts/import", requirePermission("contracts:create"), contractExcelUpload.single('file'), async (req, res) => {
    try {
      const userRole = req.user!.role;
      const isAdmin = hasGlobalAccess(userRole);
      
      let companyId: string;
      if (isAdmin) {
        companyId = req.body.companyId || "";
        if (!companyId) {
          return res.status(400).json({ error: "Admin debe especificar companyId" });
        }
      } else {
        companyId = req.user!.companyId || "";
        if (!companyId) {
          return res.status(403).json({ error: "Usuario no asociado a una empresa" });
        }
      }

      if (!req.file) {
        return res.status(400).json({ error: 'No se proporcionó ningún archivo' });
      }

      const XLSX = await import('xlsx');
      const workbook = XLSX.read(req.file.buffer, { type: 'buffer' });
      const sheetName = workbook.SheetNames[0];
      const worksheet = workbook.Sheets[sheetName];
      const data = XLSX.utils.sheet_to_json(worksheet);

      if (data.length === 0) {
        return res.status(400).json({ error: 'El archivo está vacío' });
      }

      // Helper function to convert Excel serial date to JavaScript Date
      const excelDateToJSDate = (excelDate: any): string | undefined => {
        if (!excelDate) return undefined;
        
        // If it's already a string date format, return it
        if (typeof excelDate === 'string') {
          const trimmed = excelDate.trim();
          // Check if it looks like a date string (contains - or /)
          if (trimmed.includes('-') || trimmed.includes('/')) {
            return trimmed;
          }
          // Try to parse as number if it's a numeric string
          const num = parseFloat(trimmed);
          if (!isNaN(num) && num > 25569) { // Excel dates start from 25569 (1970-01-01)
            excelDate = num;
          } else {
            return trimmed;
          }
        }
        
        // If it's a number (Excel serial date), convert it
        if (typeof excelDate === 'number') {
          const excelEpoch = new Date(1899, 11, 30); // Dec 30, 1899
          const millisecondsPerDay = 24 * 60 * 60 * 1000;
          const date = new Date(excelEpoch.getTime() + excelDate * millisecondsPerDay);
          
          // Format as YYYY-MM-DD
          const year = date.getFullYear();
          const month = String(date.getMonth() + 1).padStart(2, '0');
          const day = String(date.getDate()).padStart(2, '0');
          return `${year}-${month}-${day}`;
        }
        
        return undefined;
      };

      // Get workers for matching by identification number
      const workers = await storage.getWorkers(companyId);
      const workersByIdNumber = new Map(workers.map(w => [w.identificationNumber, w]));

      const results = {
        total: data.length,
        successful: 0,
        failed: 0,
        errors: [] as Array<{ row: number; error: string; data: any }>
      };

      // Process each row
      for (let i = 0; i < data.length; i++) {
        const row: any = data[i];
        const rowNumber = i + 2; // +2 because Excel starts at 1 and header is row 1

        try {
          const identificationNumber = row['Cédula Trabajador']?.toString().trim();
          const contractNumber = row['Número de Contrato']?.toString().trim();
          const contractType = row['Tipo de Contrato']?.toString().toLowerCase().trim();
          
          // Get raw date values (may be Excel serial numbers or strings)
          const rawStartDate = row['Fecha de Inicio (AAAA-MM-DD)'];
          const rawEndDate = row['Fecha de Finalización (AAAA-MM-DD)'];
          const startDate = excelDateToJSDate(rawStartDate);
          const endDate = excelDateToJSDate(rawEndDate);
          const position = row['Cargo Actual']?.toString().trim();
          const department = row['Departamento']?.toString().trim();
          const arlRate = row['Tasa ARL (%)']?.toString().trim();
          const workSchedule = row['Horario de Trabajo']?.toString().trim();
          const status = row['Estado']?.toString().toLowerCase().trim() || 'activo';

          // Skip empty rows
          if (!identificationNumber) {
            continue;
          }

          // Validate required fields
          if (!identificationNumber) {
            throw new Error('La Cédula del Trabajador es obligatoria');
          }
          // contractNumber es opcional - se generará automáticamente si no se proporciona
          if (!startDate) {
            throw new Error('La Fecha de Inicio es obligatoria');
          }
          if (!position) {
            throw new Error('El Cargo es obligatorio');
          }

          // Find worker by identification number
          const worker = workersByIdNumber.get(identificationNumber);
          if (!worker) {
            throw new Error(`No se encontró trabajador con cédula ${identificationNumber}`);
          }

          // Validate contract type
          const validContractTypes = ['indefinido', 'fijo', 'obra_labor', 'ocasional', 'aprendizaje', 'servicios'];
          if (!validContractTypes.includes(contractType || 'indefinido')) {
            throw new Error(`Tipo de contrato inválido. Debe ser: ${validContractTypes.join(', ')}`);
          }

          // Validate status
          const validStatuses = ['activo', 'vencido', 'terminado', 'suspendido'];
          if (!validStatuses.includes(status)) {
            throw new Error(`Estado inválido. Debe ser: ${validStatuses.join(', ')}`);
          }

          // Validate dates
          const parsedStartDate = new Date(startDate);
          if (isNaN(parsedStartDate.getTime())) {
            throw new Error('Fecha de inicio inválida. Use formato AAAA-MM-DD');
          }

          if (endDate) {
            const parsedEndDate = new Date(endDate);
            if (isNaN(parsedEndDate.getTime())) {
              throw new Error('Fecha de finalización inválida. Use formato AAAA-MM-DD');
            }
            if (parsedEndDate < parsedStartDate) {
              throw new Error('La fecha de finalización debe ser posterior a la fecha de inicio');
            }
          }

          // Check for duplicate contract number only if provided
          if (contractNumber) {
            const existingContract = await storage.getContractByNumber(contractNumber, companyId);
            if (existingContract) {
              throw new Error(`Ya existe un contrato con el número ${contractNumber}`);
            }
          }

          // Auto-generate contract number if not provided
          let finalContractNumber = contractNumber;
          if (!finalContractNumber || finalContractNumber.trim() === '') {
            const year = new Date().getFullYear();
            const companyCode = companyId.substring(0, 6).toUpperCase();
            
            // Get existing contracts for this company in this year to determine sequence
            const existingContracts = await storage.getContracts(companyId);
            const currentYearContracts = existingContracts.filter(c => 
              c.contractNumber && c.contractNumber.includes(`-${year}-`)
            );
            let nextSequence = currentYearContracts.length + i + 1; // Add row index to avoid duplicates in same import
            let paddedSequence = nextSequence.toString().padStart(4, '0');
            finalContractNumber = `CONT-${companyCode}-${year}-${paddedSequence}`;
            
            // Retry logic in case of race conditions
            let attempts = 0;
            const maxAttempts = 10;
            while (attempts < maxAttempts) {
              const existing = await storage.getContractByNumber(finalContractNumber, companyId);
              if (!existing) break;
              
              attempts++;
              nextSequence++;
              paddedSequence = nextSequence.toString().padStart(4, '0');
              finalContractNumber = `CONT-${companyCode}-${year}-${paddedSequence}`;
            }
          }

          // Create contract data
          const contractData = {
            workerId: worker.id,
            identificationNumber,
            contractNumber: finalContractNumber,
            contractType: (contractType || 'indefinido') as "indefinido" | "fijo" | "obra_labor" | "ocasional" | "aprendizaje" | "servicios",
            startDate,
            endDate: endDate || undefined,
            position,
            department: department || undefined,
            arlRate: arlRate || undefined,
            workSchedule: workSchedule || undefined,
            status: status as "activo" | "vencido" | "terminado" | "suspendido",
            salary: 0, // Salary removed from form but still in DB
          };

          // Validate using Zod schema
          const validatedData = insertContractSchema.parse(contractData);
          
          // Create contract
          await storage.createContract(validatedData, companyId);
          results.successful++;

        } catch (error: any) {
          results.failed++;
          results.errors.push({
            row: rowNumber,
            error: formatZodErrorForBulkImport(error),
            data: row
          });
        }
      }

      res.status(200).json(results);
    } catch (error: any) {
      console.error('Error importing contracts:', error);
      res.status(500).json({ error: 'Error al importar contratos: ' + error.message });
    }
  });

  // MEDICAL EXAMS ROUTES - Exámenes Médicos Ocupacionales
  
  app.get("/api/medical-exams", requireAuth, async (req, res) => {
    const userRole = req.user!.role;
    const companyId = req.user!.companyId;
    
    if (!companyId) {
      return res.status(403).send("Usuario no asociado a una empresa");
    }
    
    // Role-based access control for medical data (Ley 1581/2012 - Habeas Data)
    // Only admin and coordinador_salud can view all medical exams
    if (!canAccessMedicalData(userRole)) {
      // If trabajador, only return their own medical exams
      if (userRole === 'trabajador' && req.user!.workerId) {
        const exams = await storage.getMedicalExamsByWorker(req.user!.workerId, companyId);
        return res.json(exams);
      }
      // responsable_sst and other roles cannot access detailed medical data
      return res.status(403).json({ 
        error: "No tiene permisos para ver datos médicos. Contacte al Coordinador de Salud Ocupacional." 
      });
    }
    
    // Full access for admin/coordinador_salud
    const exams = await storage.getMedicalExams(companyId);
    res.json(exams);
  });

