  app.post("/api/medical-exams", requirePermission("medical_exams:create"), async (req, res) => {
    try {
      const userRole = req.user!.role;
      const isAdmin = hasGlobalAccess(userRole);
      const validatedData = insertMedicalExamSchema.parse(req.body);
      
      let companyId: string;
      
      if (isAdmin) {
        // Admin: Get companyId from worker
        const worker = await storage.getWorkerById(validatedData.workerId);
        if (!worker) {
          return res.status(400).send("Trabajador no encontrado");
        }
        companyId = worker.companyId;
      } else {
        // Non-admin: use their own companyId
        companyId = req.user!.companyId || "";
        if (!companyId) {
          return res.status(403).send("Usuario no asociado a una empresa");
        }
        
        // Validate worker belongs to their company
        const worker = await storage.getWorker(validatedData.workerId, companyId);
        if (!worker) {
          return res.status(400).send("Trabajador no encontrado o no pertenece a esta empresa");
        }
      }
      
      const exam = await storage.createMedicalExam(validatedData, companyId);
      
      // Always mark notification as sent for tracking - even if no portal user exists
      // This ensures the read confirmation flow works consistently
      const now = new Date();
      await storage.updateMedicalExam(exam.id, { notificationSentAt: now }, companyId);
      
      // Send notification to employee portal (if worker has portal access)
      try {
        const worker = await storage.getWorkerById(validatedData.workerId);
        if (worker) {
          const workerUser = await storage.getUserByWorkerId(worker.id);
          if (workerUser) {
            const examTypeText = validatedData.examType === 'preocupacional' ? 'Pre-ocupacional (Ingreso)' :
              validatedData.examType === 'periodico' ? 'Periódico' :
              validatedData.examType === 'retiro' ? 'Retiro' : 'Seguimiento';
            
            const scheduledDate = validatedData.scheduledDate 
              ? new Date(validatedData.scheduledDate).toLocaleDateString('es-CO', { year: 'numeric', month: 'long', day: 'numeric' })
              : 'Por definir';
            
            await storage.createInternalMessage({
              companyId,
              senderId: req.user!.id,
              senderName: req.user!.fullName || req.user!.username,
              senderRole: req.user!.role,
              receiverId: workerUser.id,
              receiverName: workerUser.fullName || workerUser.username,
              receiverRole: workerUser.role,
              subject: 'Examen Medico Ocupacional Programado',
              content: 'Se ha programado un examen medico ocupacional para usted.\n\nTipo de examen: ' + examTypeText + '\nFecha programada: ' + scheduledDate + '\nEstado: ' + (validatedData.status || 'Programado') + '\n\nPor favor, presente los documentos requeridos y asista puntualmente a la cita.',
              priority: 'normal',
              status: 'unread',
              relatedEntity: 'medical_exam',
              relatedEntityId: exam.id
            });
          }
        }
      } catch (notifError) {
        console.error('Error sending portal notification for medical exam:', notifError);
        // Don't fail the request if notification fails
      }
      
      // Return updated exam with notificationSentAt
      const updatedExam = await storage.getMedicalExam(exam.id, companyId);
      res.status(201).json(updatedExam || exam);
    } catch (error: any) {
      res.status(400).send(error.message);
    }
  });

