  // Generate Acta de Designación PDF - Resolución 0312/2019 Estándar 1.1.1
  app.get("/api/responsible-designations/:id/acta-pdf", requirePermission("companies:view"), async (req, res) => {
    try {
      const isAdmin = hasGlobalAccess(req.user!.role);
      let companyId: string;
      
      // Get designation
      const designation = await storage.getResponsibleDesignationById(req.params.id);
      if (!designation) {
        return res.status(404).send("Designación no encontrada");
      }
      
      // Get worker
      const worker = await storage.getWorkerById(designation.workerId);
      if (!worker) {
        return res.status(404).send("Trabajador no encontrado");
      }
      
      if (isAdmin) {
        companyId = worker.companyId;
      } else {
        companyId = req.user!.companyId || "";
        if (!companyId) {
          return res.status(403).send("Usuario no asociado a una empresa");
        }
        // Verify designation belongs to user's company
        if (worker.companyId !== companyId) {
          return res.status(403).send("No tiene acceso a esta designación");
        }
      }
      
      // Get company
      const company = await storage.getCompany(companyId);
      if (!company) {
        return res.status(404).send("Empresa no encontrada");
      }
      
      // Create PDF
      const doc = new PDFDocument({ margin: 35, size: 'LETTER' });
      
      // Add trial watermark if subscription is in trial period
      const desig_subscription = await storage.getSubscriptionByCompany(companyId);
      const desig_trialStatus = getTrialStatus(desig_subscription?.status || 'trial', desig_subscription?.trialEnd || null, true, true);
      setupTrialWatermarkOnAllPages(doc, desig_trialStatus.requiresWatermark);
      // Set response headers
      res.setHeader('Content-Type', 'application/pdf');
      res.setHeader('Content-Disposition', `attachment; filename="Acta-Designacion-Responsable-SST-${designation.id.substring(0, 8)}.pdf"`);
      
      // Pipe PDF to response
      doc.pipe(res);
      
      // Define PDF layout constants
      const margin = 35;
      const pageWidth = doc.page.width;
      const contentWidth = pageWidth - (margin * 2);
      
      let headerY = 50;
      
      // Preload company logo and worker photo from Object Storage
      const logoBuffer = await loadCompanyLogoBuffer(company.logoUrl);
      // Worker photo not needed for muestreo PDF
      
      // Add company logo if available
      if (logoBuffer) {
        try {
          doc.image(logoBuffer, margin, headerY, { width: 60, height: 60 });
        } catch (logoError) {
          console.warn('Could not load company logo for PDF:', logoError);
        }
      }
      
      // Header - adjusted position if logo exists
      const textStartX = logoBuffer ? margin + 70 : margin;
      const textWidth = logoBuffer ? contentWidth - 70 : contentWidth;
      
      doc.fontSize(9).font('Helvetica-Bold').text('ACTA DE DESIGNACIÓN DEL RESPONSABLE', textStartX, headerY, { width: textWidth, align: 'center', lineBreak: false });
      doc.fontSize(9).text('DEL SISTEMA DE GESTIÓN DE SEGURIDAD Y SALUD EN EL TRABAJO', textStartX, headerY + 18, { width: textWidth, align: 'center', lineBreak: false });
      doc.fontSize(7).font('Helvetica').text('(Resolución 0312 de 2019 - Estándar 1.1.1)', textStartX, headerY + 36, { width: textWidth, align: 'center', lineBreak: false });
      
      let currentY = 130;
      
      // Company info box
      doc.rect(margin, currentY, contentWidth, 60).stroke();
      doc.fontSize(8).font('Helvetica-Bold').text('DATOS DE LA EMPRESA', margin + 10, currentY + 8, { lineBreak: false });
      currentY += 22;
      doc.font('Helvetica').text(`Razón Social: ${company.name}`, margin + 10, currentY, { lineBreak: false });
      currentY += 14;
      doc.text(`NIT: ${company.nit || 'No registrado'}`, margin + 10, currentY, { lineBreak: false });
      currentY += 14;
      doc.text(`Dirección: ${company.address || 'No registrada'}`, margin + 10, currentY, { lineBreak: false });
      
      currentY += 35;
      
      // Designation date
      const designationDate = new Date(designation.designationDate);
      const formattedDate = designationDate.toLocaleDateString('es-CO', { 
        day: '2-digit', 
        month: 'long', 
        year: 'numeric' 
      });
      
      // Usar campo city de la empresa, o extraer de dirección si no existe (retrocompatibilidad)
      const extractCity = (address: string | null | undefined): string => {
        if (!address) return '________________';
        const ciudades = ['Bogotá', 'Medellín', 'Cali', 'Barranquilla', 'Cartagena', 'Bucaramanga', 'Pereira', 'Manizales', 'Santa Marta', 'Ibagué', 'Cúcuta', 'Villavicencio', 'Pasto', 'Montería', 'Neiva', 'Armenia', 'Popayán', 'Sincelejo', 'Valledupar', 'Tunja', 'Riohacha', 'Florencia', 'Quibdó', 'Yopal', 'Mocoa', 'Leticia', 'San José del Guaviare', 'Inírida', 'Puerto Carreño', 'Mitú', 'Arauca', 'Bogotá D.C.', 'D.C.'];
        for (const ciudad of ciudades) {
          if (address.toLowerCase().includes(ciudad.toLowerCase())) {
            return ciudad === 'D.C.' ? 'Bogotá D.C.' : ciudad;
          }
        }
        return address.split(',')[0] || '________________';
      };
      
      // Priorizar campo city, fallback a extracción de dirección
      const city = company.city || extractCity(company.address);
      
      doc.fontSize(9).text(
        `En la ciudad de ${city}, a los ${formattedDate}, la empresa ${company.name}, identificada con NIT ${company.nit || '____________'}, en cumplimiento de lo establecido en el artículo 8 del Decreto 1072 de 2015 y la Resolución 0312 de 2019, procede a designar formalmente al siguiente funcionario como:`,
        margin, currentY, { width: contentWidth, align: 'justify' }
      );
      
      currentY = doc.y + 15;
      
      // Position box
      doc.rect(margin, currentY, contentWidth, 30).fill('#f0f0f0').stroke();
      doc.fillColor('black').fontSize(9).font('Helvetica-Bold').text(designation.position.toUpperCase(), margin, currentY + 8, { align: 'center', lineBreak: false });
      
      currentY += 50;
      
      // Worker info box - SST-2025-0012: Fixed layout overlap issue
      const workerBoxStartY = currentY;
      const workerBoxPadding = 10;
      
      // Draw section title first
      doc.fontSize(8).font('Helvetica-Bold').text('DATOS DEL DESIGNADO', margin + workerBoxPadding, workerBoxStartY + workerBoxPadding);
      currentY = doc.y + 6;
      
      // Worker data fields - use doc.y to track actual position
      doc.font('Helvetica');
      doc.text(`Nombre Completo: ${worker.name}`, margin + workerBoxPadding, currentY);
      currentY = doc.y + 4;
      
      doc.text(`Documento de Identidad: CC ${worker.identificationNumber}`, margin + workerBoxPadding, currentY);
      currentY = doc.y + 4;
      
      doc.text(`Cargo: ${worker.position || designation.position}`, margin + workerBoxPadding, currentY);
      currentY = doc.y + 4;
      
      // License info
      const licenciaInfo = designation.licenciaSstNumero 
        ? `No. ${designation.licenciaSstNumero}${designation.licenciaSstVigencia ? ` (Vigente hasta: ${new Date(designation.licenciaSstVigencia).toLocaleDateString('es-CO')})` : ''}`
        : 'No registrada';
      doc.text(`Licencia SST: ${licenciaInfo}`, margin + workerBoxPadding, currentY);
      currentY = doc.y + 4;
      
      // Formation level and 50h course
      const nivelInfo = designation.nivelFormacion || 'No registrado';
      const curso50Info = designation.curso50Horas 
        ? `Sí${designation.curso50HorasFecha ? ` (${new Date(designation.curso50HorasFecha).toLocaleDateString('es-CO')})` : ''}`
        : 'No';
      doc.text(`Nivel de Formación: ${nivelInfo} | Curso 50 horas: ${curso50Info}`, margin + workerBoxPadding, currentY);
      
      // Calculate actual box height based on rendered content
      const workerBoxEndY = doc.y + workerBoxPadding;
      const workerBoxHeight = workerBoxEndY - workerBoxStartY;
      
      // Draw box around content after knowing the actual height
      doc.rect(margin, workerBoxStartY, contentWidth, workerBoxHeight).stroke();
      
      // Set currentY after the box with proper spacing for next section
      currentY = workerBoxEndY + 15;
      
      // Responsibilities section - SST-2025-0012: Use doc.y for proper positioning
      doc.fontSize(9).font('Helvetica-Bold').text('RESPONSABILIDADES ASIGNADAS:', margin, currentY);
      currentY = doc.y + 8;
      
      doc.font('Helvetica').fontSize(9);
      const responsibilities = designation.responsibilities || [];
      for (const resp of responsibilities) {
        // Check if we need a page break before rendering
        const respHeight = doc.heightOfString(`• ${resp}`, { width: contentWidth - 20 });
        if (currentY + respHeight > doc.page.height - 80) {
          doc.addPage();
          currentY = 50;
        }
        doc.text(`• ${resp}`, margin + 10, currentY, { width: contentWidth - 20 });
        currentY = doc.y + 4;
      }
      
      currentY += 3;
      
      // Authority paragraph
      checkPageSpace(doc, 60);
      
      doc.fontSize(8).text(
        `El designado tendrá la autoridad y el respaldo de la alta dirección para tomar decisiones en materia de seguridad y salud en el trabajo, asignar recursos y solicitar la colaboración de todas las áreas de la organización para el cumplimiento de sus funciones.`,
        margin, currentY, { width: contentWidth, align: 'justify' }
      );
      
      currentY = doc.y + 15;
      
      // Signature section
      checkSignatureSpace(doc);
      
      doc.fontSize(8).text('En constancia de lo anterior, se firma la presente acta:', margin, currentY, { lineBreak: false });
      currentY += 50;
      
      const signatureWidth = (contentWidth - 40) / 2;
      
      // Left signature (Company Representative)
      doc.text('_________________________________', margin, currentY, { lineBreak: false });
      doc.text('_________________________________', margin + signatureWidth + 40, currentY, { lineBreak: false });
      currentY += 14;
      
      doc.font('Helvetica-Bold').text('REPRESENTANTE LEGAL', margin, currentY, { lineBreak: false });
      doc.text('RESPONSABLE DESIGNADO', margin + signatureWidth + 40, currentY, { lineBreak: false });
      currentY += 12;
      
      doc.font('Helvetica').fontSize(9);
      const repLegalName = company.legalRepName || '________________________';
      const repLegalId = company.legalRepId || '___________________________';
      const repLegalPosition = company.legalRepPosition || '__________________________';
      
      doc.text(`Nombre: ${repLegalName}`, margin, currentY, { lineBreak: false });
      doc.text(`Nombre: ${worker.name}`, margin + signatureWidth + 40, currentY, { lineBreak: false });
      currentY += 12;
      
      doc.text(`C.C.: ${repLegalId}`, margin, currentY, { lineBreak: false });
      doc.text(`C.C.: ${worker.identificationNumber}`, margin + signatureWidth + 40, currentY, { lineBreak: false });
      currentY += 12;
      
      // Licencia SST del responsable designado
      const licenciaResponsable = designation.licenciaSstNumero 
        ? `Licencia SST No. ${designation.licenciaSstNumero}`
        : 'Licencia SST: ___________________';
      doc.text(`Cargo: ${repLegalPosition}`, margin, currentY, { lineBreak: false });
      doc.text(licenciaResponsable, margin + signatureWidth + 40, currentY, { lineBreak: false });
      
      // Update currentY after signatures
      currentY = doc.y + 12;
      
      // Footer - ensure adequate margin from signatures (SST-2025-0087)
      const footerHeight = 40;
      const minFooterMargin = 30;
      const footerY = Math.max(currentY + minFooterMargin, doc.page.height - 60);
      
      // If footer would go off page, add new page
      if (footerY + footerHeight > doc.page.height - 20) {
        doc.addPage();
        currentY = doc.page.height - 60;
      } else {
        currentY = footerY;
      }
      
      doc.fontSize(8).fillColor('gray')
        .text(`Documento generado el ${new Date().toLocaleDateString('es-CO')} - SST Colombia`, margin, currentY, { align: 'center', lineBreak: false })
        .text('Este documento cumple con los requisitos del Estándar 1.1.1 de la Resolución 0312 de 2019', margin, currentY + 10, { align: 'center', lineBreak: false });
      // Finalize PDF
      doc.end();
    } catch (error: any) {
      console.error('Error generating Acta de Designación PDF:', error);
      res.status(500).send(error.message);
    }
  });

