  // Generate PDF Summary Report of all Resource Allocations (Estándar 1.1.3)
  app.get("/api/resource-allocations/resumen-pdf", requirePermission("companies:view"), async (req, res) => {
    try {
      const companyId = req.user!.companyId;
      if (!companyId) {
        return res.status(403).send("Usuario no asociado a una empresa");
      }

      const allocations = await storage.getResourceAllocations(companyId);
      const company = await storage.getCompany(companyId);
      
      if (!company) {
        return res.status(404).send("Empresa no encontrada");
      }

      // Calculate summary by type
      const parseAmount = (str: string | null | undefined): number => {
        if (!str) return 0;
        return parseFloat(str.replace(/[^0-9.-]+/g, '')) || 0;
      };

      const humanoAllocations = allocations.filter(a => a.resourceType === 'humano');
      const fisicoAllocations = allocations.filter(a => a.resourceType === 'fisico');
      const financieroAllocations = allocations.filter(a => a.resourceType === 'financiero');

      const resumen = {
        humano: { cantidad: humanoAllocations.length, total: humanoAllocations.reduce((sum, a) => sum + parseAmount(a.inversionEstimada), 0) },
        fisico: { cantidad: fisicoAllocations.length, total: fisicoAllocations.reduce((sum, a) => sum + parseAmount(a.inversionEstimada), 0) },
        financiero: { cantidad: financieroAllocations.length, total: financieroAllocations.reduce((sum, a) => sum + parseAmount(a.inversionEstimada), 0) },
        total: allocations.reduce((sum, a) => sum + parseAmount(a.inversionEstimada), 0)
      };

      const formatCurrency = (value: number) => {
        return new Intl.NumberFormat('es-CO', { style: 'currency', currency: 'COP', minimumFractionDigits: 0 }).format(value);
      };

      // Create PDF document
      const doc = new PDFDocument({ margin: 35, size: 'LETTER' });
      
      // Add trial watermark if subscription is in trial period
      const budget_subscription = await storage.getSubscriptionByCompany(companyId);
      const budget_trialStatus = getTrialStatus(budget_subscription?.status || 'trial', budget_subscription?.trialEnd || null, true, true);
      setupTrialWatermarkOnAllPages(doc, budget_trialStatus.requiresWatermark);
      const margin = 35;
      const pageWidth = doc.page.width;

      res.setHeader('Content-Type', 'application/pdf');
      res.setHeader('Content-Disposition', `attachment; filename="Resumen-Presupuestal-SST-${new Date().toISOString().split('T')[0]}.pdf"`);

      doc.pipe(res);

      // Preload company logo and worker photo from Object Storage
      const logoBuffer = await loadCompanyLogoBuffer(company.logoUrl);
      // Worker photo not needed for muestreo PDF

      // Standard Header
      let currentY = setupPdfHeadersFooters({
        doc,
        company: {
          name: company.name,
          nit: company.nit,
          address: company.address,
          logoUrl: company.logoUrl,
        },
        documentTitle: 'INFORME DE EJECUCIÓN PRESUPUESTAL SG-SST',
        documentCode: `SST-PRES-${new Date().getFullYear()}`,
        version: '1.0',
        date: new Date(),
        elaboro: 'Responsable SST',
        autorizo: company.legalRepName || 'Representante Legal',
        aprobo: company.legalRepName || 'Gerencia General',
        logoBuffer,
      });

      currentY += 15;

      // Color definitions for green bars
      const colorVerdeSst = '#1e7e34';
      const contentWidth = pageWidth - 2 * margin;

      // Section: Resumen General - Green Bar
      doc.rect(margin, currentY, contentWidth, 20).fillColor(colorVerdeSst).fill();
      doc.fontSize(10).font('Helvetica-Bold').fillColor('#ffffff');
      doc.text('1. RESUMEN GENERAL DE ASIGNACIÓN DE RECURSOS', margin + 5, currentY + 5, { lineBreak: false });
      currentY += 25;
      doc.fillColor('#000000');

      // Summary Table
      const tableHeaders = ['Tipo de Recurso', 'Cantidad Asignaciones', 'Inversión Total'];
      const tableData = [
        ['Recurso Humano', resumen.humano.cantidad.toString(), formatCurrency(resumen.humano.total)],
        ['Recurso Físico/Técnico', resumen.fisico.cantidad.toString(), formatCurrency(resumen.fisico.total)],
        ['Recurso Financiero', resumen.financiero.cantidad.toString(), formatCurrency(resumen.financiero.total)],
        ['TOTAL INVERSIÓN SST', allocations.length.toString(), formatCurrency(resumen.total)],
      ];

      const colWidths = [200, 120, 150];
      let tableY = currentY;

      // Draw table header
      doc.rect(margin, tableY, colWidths.reduce((a, b) => a + b, 0), 20).fillAndStroke('#1e7e34', '#000000');
      let xPos = margin;
      tableHeaders.forEach((header, i) => {
        doc.fontSize(9).font('Helvetica-Bold').fillColor('#ffffff');
        doc.text(header, xPos + 5, tableY + 6, { width: colWidths[i] - 10, align: 'center', lineBreak: false });
        xPos += colWidths[i];
      });
      tableY += 20;

      // Draw table rows
      tableData.forEach((row, rowIndex) => {
        const isTotal = rowIndex === tableData.length - 1;
        xPos = margin;
        
        row.forEach((cell, colIndex) => {
          if (isTotal) {
            doc.rect(xPos, tableY, colWidths[colIndex], 22).fillAndStroke('#e8f5e9', '#000000');
          } else {
            doc.rect(xPos, tableY, colWidths[colIndex], 22).stroke('#000000');
          }
          
          doc.fontSize(isTotal ? 10 : 9).font(isTotal ? 'Helvetica-Bold' : 'Helvetica').fillColor('#000000');
          doc.text(cell, xPos + 5, tableY + 6, { width: colWidths[colIndex] - 10, align: colIndex === 0 ? 'left' : 'center', lineBreak: false });
          xPos += colWidths[colIndex];
        });
        tableY += 22;
      });

      currentY = tableY + 25;

      // Section: Detalle por Tipo de Recurso - Green Bar
      doc.rect(margin, currentY, contentWidth, 20).fillColor(colorVerdeSst).fill();
      doc.fontSize(10).font('Helvetica-Bold').fillColor('#ffffff');
      doc.text('2. DETALLE DE ASIGNACIONES', margin + 5, currentY + 5, { lineBreak: false });
      currentY += 25;
      doc.fillColor('#000000');

      // Detail for each resource type
      const resourceTypes = [
        { type: 'humano', label: 'Recursos Humanos', items: humanoAllocations },
        { type: 'fisico', label: 'Recursos Físicos/Técnicos', items: fisicoAllocations },
        { type: 'financiero', label: 'Recursos Financieros', items: financieroAllocations },
      ];

      resourceTypes.forEach(({ label, items }) => {
        if (items.length > 0) {
          doc.fontSize(8).font('Helvetica-Bold').fillColor('#000000');
          doc.text(`• ${label} (${items.length})`, margin, currentY, { lineBreak: false });
          currentY += 12;

          const contentWidth = pageWidth - 2 * margin - 20;
          items.slice(0, 5).forEach((item) => {
            const description = item.nombreCompleto || item.nombreEquipo || item.objetivoGeneral || 'Sin descripción';
            const amount = formatCurrency(parseAmount(item.inversionEstimada));
            doc.fontSize(7).font('Helvetica').fillColor('#333333');
            const textHeight = doc.heightOfString(`   - ${description}: ${amount}`, { width: contentWidth });
            doc.text(`   - ${description}: ${amount}`, margin + 10, currentY, { width: contentWidth });
            currentY += Math.max(textHeight, 12) + 2;
          });

          if (items.length > 5) {
            doc.fontSize(7).font('Helvetica').fillColor('#666666');
            doc.text(`   ... y ${items.length - 5} asignaciones más`, margin + 10, currentY, { lineBreak: false });
            currentY += 12;
          }
          currentY += 10;
        }
      });

      currentY += 6;

      // Section: Marco Legal - Green Bar
      doc.rect(margin, currentY, contentWidth, 20).fillColor(colorVerdeSst).fill();
      doc.fontSize(10).font('Helvetica-Bold').fillColor('#ffffff');
      doc.text('3. MARCO NORMATIVO', margin + 5, currentY + 5, { lineBreak: false });
      currentY += 25;
      doc.fillColor('#000000');

      doc.fontSize(7).font('Helvetica').fillColor('#333333');
      doc.text('Este informe evidencia el cumplimiento del Estándar 1.1.3 de la Resolución 0312 de 2019:', margin, currentY, { width: pageWidth - 2 * margin });
      currentY = doc.y + 8;
      doc.text('"Asignación de recursos para el Sistema de Gestión en Seguridad y Salud en el Trabajo – SG-SST"', margin + 10, currentY, { width: pageWidth - 2 * margin - 20, align: 'justify' });
      currentY = doc.y + 8;
      
      doc.fontSize(7).font('Helvetica').fillColor('#666666');
      doc.text('• Decreto 1072 de 2015, Artículo 2.2.4.6.8, Numeral 4', margin + 10, currentY, { lineBreak: false });
      currentY += 12;
      doc.text('• Resolución 0312 de 2019 - Estándares Mínimos del SG-SST', margin + 10, currentY, { lineBreak: false });

      doc.end();

    } catch (error: any) {
      console.error('Error generating resumen PDF:', error);
      if (!res.headersSent) {
        res.status(500).send(error.message || 'Error al generar el resumen');
      }
    }
  });

