  // Generate ISO-compliant PDF for Resource Allocation
  app.get("/api/resource-allocations/:id/acta", requirePermission("companies:view"), async (req, res) => {
    try {
      const companyId = req.user!.companyId;
      if (!companyId) {
        return res.status(403).send("Usuario no asociado a una empresa");
      }

      const allocation = await storage.getResourceAllocation(req.params.id, companyId);
      if (!allocation) {
        return res.status(404).send("Acta de asignación no encontrada");
      }

      const company = await storage.getCompany(companyId);
      if (!company) {
        return res.status(404).send("Empresa no encontrada");
      }

      // Fetch worker data for approval signatures if IDs are present
      let elaboroName = 'Responsable SST';
      let autorizoName = req.user?.username || 'Sistema';
      let aproboName = 'Gerencia';

      if (allocation.elaboradoPorId) {
        const worker = await storage.getWorker(allocation.elaboradoPorId, companyId);
        if (worker && worker.companyId === companyId) {
          elaboroName = `${worker.name} - ${worker.position}`;
        }
      }

      if (allocation.autorizadoPorId) {
        const worker = await storage.getWorker(allocation.autorizadoPorId, companyId);
        if (worker && worker.companyId === companyId) {
          autorizoName = `${worker.name} - ${worker.position}`;
        }
      }

      if (allocation.aprobadoPorId) {
        const worker = await storage.getWorker(allocation.aprobadoPorId, companyId);
        if (worker && worker.companyId === companyId) {
          aproboName = `${worker.name} - ${worker.position}`;
        }
      }

      // Create PDF document with standard SST Colombia format
      const doc = new PDFDocument({ margin: 35, size: 'LETTER' });
      
      // Add trial watermark if subscription is in trial period
      const resalloc_subscription = await storage.getSubscriptionByCompany(companyId);
      const resalloc_trialStatus = getTrialStatus(resalloc_subscription?.status || 'trial', resalloc_subscription?.trialEnd || null, true, true);
      setupTrialWatermarkOnAllPages(doc, resalloc_trialStatus.requiresWatermark);
      const margin = 35;
      const pageWidth = doc.page.width;

      res.setHeader('Content-Type', 'application/pdf');
      res.setHeader('Content-Disposition', `attachment; filename="Acta-Recurso-${allocation.resourceType}-${allocation.date}.pdf"`);

      doc.pipe(res);

      // Preload company logo and worker photo from Object Storage
      const logoBuffer = await loadCompanyLogoBuffer(company.logoUrl);
      // Worker photo not needed for muestreo PDF

      // Standard Header with logo, company info, and version table
      let currentY = setupPdfHeadersFooters({
        doc,
        company: {
          name: company.name,
          nit: company.nit,
          address: company.address,
          logoUrl: company.logoUrl,
        },
        documentTitle: 'ACTA DE ASIGNACIÓN DE RECURSOS SG-SST',
        documentCode: `SST-REC-${new Date(allocation.date).getFullYear()}`,
        version: '1.0',
        date: new Date(allocation.date),
        elaboro: elaboroName,
        autorizo: autorizoName,
        aprobo: aproboName,
        logoBuffer,
      });

      currentY += 10;

      // Color definitions for green bars
      const colorVerdeSst = '#1e7e34';
      const contentWidth = pageWidth - 2 * margin;

      // ==========================================
      // INTRO PARAGRAPH
      // ==========================================
      doc.fontSize(9).font('Helvetica').fillColor('#000000');
      doc.text(`La empresa ${company.name} con el fin de dar cumplimiento al objetivo del Sistema de Gestión de la Seguridad y Salud en el Trabajo y de acuerdo a la legislación vigente, asigna los siguientes recursos:`, margin, currentY, { width: contentWidth });
      currentY = doc.y + 15;

      // ==========================================
      // RESOURCE TYPE HEADER - Green Bar
      // ==========================================
      const resourceTypeLabels: Record<string, string> = {
        'humano': 'RECURSO HUMANO',
        'fisico': 'RECURSO FÍSICO',
        'financiero': 'RECURSO FINANCIERO'
      };
      
      doc.rect(margin, currentY, contentWidth, 20).fillColor(colorVerdeSst).fill();
      doc.fontSize(10).font('Helvetica-Bold').fillColor('#ffffff');
      doc.text(resourceTypeLabels[allocation.resourceType] || 'RECURSO', margin + 5, currentY + 5, { lineBreak: false });
      currentY += 30;
      doc.fillColor('#000000');

      // ==========================================
      // RESOURCE DETAILS
      // ==========================================
      doc.fontSize(9).font('Helvetica').fillColor('#000000');
      
      if (allocation.resourceType === 'humano') {
        doc.font('Helvetica-Bold').text('Nombre: ', margin, currentY, { continued: true });
        doc.font('Helvetica').text(allocation.nombreCompleto || 'N/A');
        currentY = doc.y + 8;
        doc.font('Helvetica-Bold').text('Cédula: ', margin, currentY, { continued: true });
        doc.font('Helvetica').text(allocation.cedula || 'N/A');
        currentY = doc.y + 8;
        doc.font('Helvetica-Bold').text('Cargo: ', margin, currentY, { continued: true });
        doc.font('Helvetica').text(allocation.cargo || 'N/A');
        currentY = doc.y + 8;
        if (allocation.profesion) {
          doc.font('Helvetica-Bold').text('Profesión: ', margin, currentY, { continued: true });
          doc.font('Helvetica').text(allocation.profesion);
          currentY = doc.y + 8;
        }
        if (allocation.licenciaSst) {
          doc.font('Helvetica-Bold').text('Licencia SST: ', margin, currentY, { continued: true });
          doc.font('Helvetica').text(allocation.licenciaSst);
          currentY = doc.y + 8;
        }
      } else if (allocation.resourceType === 'fisico') {
        doc.font('Helvetica-Bold').text('Equipo/Recurso: ', margin, currentY, { continued: true });
        doc.font('Helvetica').text(allocation.nombreEquipo || 'N/A');
        currentY = doc.y + 8;
        doc.font('Helvetica-Bold').text('Cantidad: ', margin, currentY, { continued: true });
        doc.font('Helvetica').text(`${allocation.numUnidades || 'N/A'} unidades`);
        currentY = doc.y + 8;
        doc.font('Helvetica-Bold').text('Nivel: ', margin, currentY, { continued: true });
        doc.font('Helvetica').text(allocation.implementosNivel || 'N/A');
        currentY = doc.y + 8;
        if (allocation.categoria) {
          doc.font('Helvetica-Bold').text('Categoría: ', margin, currentY, { continued: true });
          doc.font('Helvetica').text(allocation.categoria);
          currentY = doc.y + 8;
        }
      } else if (allocation.resourceType === 'financiero') {
        doc.font('Helvetica-Bold').text('Inversión Estimada: ', margin, currentY, { continued: true });
        doc.font('Helvetica').text(allocation.inversionEstimada || 'N/A');
        currentY = doc.y + 8;
        doc.font('Helvetica-Bold').text('Fecha de Desembolso: ', margin, currentY, { continued: true });
        doc.font('Helvetica').text(allocation.fechaDesembolso ? new Date(allocation.fechaDesembolso).toLocaleDateString('es-CO') : 'N/A');
        currentY = doc.y + 8;
        if (allocation.tipoGasto) {
          doc.font('Helvetica-Bold').text('Tipo de Gasto: ', margin, currentY, { continued: true });
          doc.font('Helvetica').text(allocation.tipoGasto);
          currentY = doc.y + 8;
        }
      }

      // Common fields for all resource types
      currentY += 5;
      doc.font('Helvetica-Bold').text('Objetivo: ', margin, currentY, { continued: true });
      doc.font('Helvetica').text(allocation.objetivoGeneral || 'N/A', { width: contentWidth - 60 });
      currentY = doc.y + 8;
      
      if (allocation.actividades) {
        doc.font('Helvetica-Bold').text('Actividades: ', margin, currentY, { continued: true });
        doc.font('Helvetica').text(allocation.actividades, { width: contentWidth - 60 });
        currentY = doc.y + 8;
      }
      
      doc.font('Helvetica-Bold').text('Fecha de Asignación: ', margin, currentY, { continued: true });
      doc.font('Helvetica').text(new Date(allocation.date).toLocaleDateString('es-CO'));
      currentY = doc.y + 15;

      // ==========================================
      // MARCO NORMATIVO Section - Green Bar
      // ==========================================
      doc.rect(margin, currentY, contentWidth, 20).fillColor(colorVerdeSst).fill();
      doc.fontSize(10).font('Helvetica-Bold').fillColor('#ffffff');
      doc.text('MARCO NORMATIVO', margin + 5, currentY + 5, { lineBreak: false });
      currentY += 25;
      doc.fillColor('#000000');

      doc.fontSize(8).font('Helvetica').fillColor('#333333');
      doc.text('Esta acta evidencia el cumplimiento del Estándar 1.1.3 de la Resolución 0312 de 2019:', margin, currentY, { width: contentWidth });
      currentY = doc.y + 5;
      doc.text('"Asignación de recursos para el Sistema de Gestión en Seguridad y Salud en el Trabajo – SG-SST"', margin + 10, currentY, { width: contentWidth - 20 });
      currentY = doc.y + 10;
      
      doc.fontSize(7).font('Helvetica').fillColor('#666666');
      doc.text('• Decreto 1072 de 2015, Artículo 2.2.4.6.8, Numeral 4', margin + 10, currentY);
      currentY = doc.y + 5;
      doc.text('• Resolución 0312 de 2019 - Estándares Mínimos del SG-SST', margin + 10, currentY);

      // Footer is handled by setupPdfHeadersFooters automatically
      doc.end();

    } catch (error: any) {
      console.error('Error generating acta PDF:', error);
      if (!res.headersSent) {
        res.status(500).send(error.message || 'Error al generar el acta');
      }
    }
  });




