  // Upload archivo adjunto para Acta COPASST (SST-2025-0039, SST-2025-0042)
  app.post("/api/copasst-actas/:id/upload", requirePermission("companies:edit"), (req, res, next) => {
    uploadCopasstActa.single('archivo')(req, res, (err: any) => {
      if (err) {
        if (err.code === 'LIMIT_FILE_SIZE') {
          return res.status(400).json({ error: "El archivo excede el límite de 10MB" });
        }
        return res.status(400).json({ error: err.message || "Error al subir archivo" });
      }
      next();
    });
  }, async (req, res) => {
    try {
      const companyId = req.user!.companyId!;
      const actaId = req.params.id;
      
      if (!req.file) {
        return res.status(400).json({ error: "No se proporcionó ningún archivo" });
      }
      
      // Verify the acta exists and belongs to the company
      const acta = await storage.getCopasstActa(actaId, companyId);
      if (!acta) {
        // Delete uploaded file if acta not found
        fs.unlinkSync(req.file.path);
        return res.status(404).json({ error: "Acta COPASST no encontrada" });
      }
      
      // Upload to Object Storage for persistence
      const objectStorageService = new ObjectStorageService();
      const fileBuffer = fs.readFileSync(req.file.path);
      const ext = path.extname(req.file.originalname);
      const uniqueId = crypto.randomUUID();
      const objectPath = `uploads/copasst-actas/${companyId}/${uniqueId}${ext}`;
      
      await objectStorageService.uploadObject(objectPath, fileBuffer, req.file.mimetype);
      
      // Clean up local file
      fs.unlinkSync(req.file.path);
      
      const fileUrl = `/objects/${objectPath}`;
      
      // Update the acta with the file URL
      const updatedActa = await storage.updateCopasstActaFile(actaId, {
        archivoAdjuntoUrl: fileUrl,
        archivoAdjuntoNombre: req.file.originalname
      }, companyId);
      
      res.json({
        archivoAdjuntoUrl: fileUrl,
        archivoAdjuntoNombre: req.file.originalname,
        message: "Archivo subido exitosamente"
      });
    } catch (error: any) {
      res.status(400).json({ error: error.message });
    }
  });

