  // Generate PDF for COPASST Acta
  app.get("/api/copasst-actas/:id/pdf", requirePermission("companies:view"), async (req, res) => {
    try {
      const companyId = req.user!.companyId!;
      const acta = await storage.getCopasstActa(req.params.id, companyId);
      if (!acta) {
        return res.status(404).send("Acta COPASST no encontrada");
      }

      const company = await storage.getCompany(companyId);
      if (!company) {
        return res.status(404).send("Empresa no encontrada");
      }

      const { default: PDFDocument } = await import('pdfkit');
      const doc = new PDFDocument({ margin: 35, size: 'LETTER' });
      
      // Add trial watermark if subscription is in trial period
      const workers_subscription = await storage.getSubscriptionByCompany(companyId);
      const workers_trialStatus = getTrialStatus(workers_subscription?.status || 'trial', workers_subscription?.trialEnd || null, true, true);
      setupTrialWatermarkOnAllPages(doc, workers_trialStatus.requiresWatermark);
      const margin = 35;
      const pageWidth = doc.page.width;

      res.setHeader('Content-Type', 'application/pdf');
      res.setHeader('Content-Disposition', `attachment; filename="Acta-COPASST-${acta.numeroActa}.pdf"`);

      doc.pipe(res);

      // Preload company logo and worker photo from Object Storage
      const logoBuffer = await loadCompanyLogoBuffer(company.logoUrl);
      // Worker photo not needed for muestreo PDF

      // Standard Header with logo, version control table in green, and automatic footer with signatures
      let currentY = setupPdfHeadersFooters({
        doc,
        company,
        documentTitle: 'ACTA DE CONSTITUCIÓN DEL COPASST',
        logoBuffer,
        documentCode: `SST-COP-${acta.numeroActa}`,
        version: '1.0',
        date: new Date(acta.fecha),
        elaboro: acta.secretaria || 'Secretario COPASST',
        autorizo: req.user?.username || 'Sistema',
        aprobo: acta.presidente || 'Presidente COPASST'
      });

      currentY += 15;

      // Acta details section with green header
      doc.fontSize(9).font('Helvetica-Bold').fillColor('#1e7e34')
        .text('INFORMACIÓN DEL ACTA', margin, currentY);
      currentY = doc.y + 10;

      doc.fontSize(8).font('Helvetica-Bold').fillColor('#000000')
        .text('Acta N°: ', margin, currentY, { continued: true });
      doc.font('Helvetica').text(acta.numeroActa);
      currentY = doc.y + 5;

      doc.fontSize(8).font('Helvetica-Bold')
        .text('Fecha: ', margin, currentY, { continued: true });
      doc.font('Helvetica').text(new Date(acta.fecha).toLocaleDateString('es-CO', { year: 'numeric', month: 'long', day: 'numeric' }));
      currentY = doc.y + 15;

      // Presidente y Secretaria info
      if (acta.presidente || acta.secretaria) {
        doc.fontSize(9).font('Helvetica-Bold').fillColor('#1e7e34')
          .text('DIRECTIVOS DEL COMITÉ', margin, currentY);
        currentY = doc.y + 10;

        if (acta.presidente) {
          doc.fontSize(8).font('Helvetica-Bold').fillColor('#000000')
            .text('Presidente: ', margin, currentY, { continued: true });
          doc.font('Helvetica').text(acta.presidente);
          currentY = doc.y + 5;
        }

        if (acta.secretaria) {
          doc.fontSize(8).font('Helvetica-Bold')
            .text('Secretario(a): ', margin, currentY, { continued: true });
          doc.font('Helvetica').text(acta.secretaria);
          currentY = doc.y + 15;
        }
      }

      // Content/Notes section with green header
      doc.fontSize(9).font('Helvetica-Bold').fillColor('#1e7e34')
        .text('CONTENIDO DEL ACTA', margin, currentY);
      currentY = doc.y + 10;

      doc.fontSize(8).font('Helvetica').fillColor('#000000')
        .text(acta.notas || 'Sin contenido registrado', margin, currentY, {
          width: pageWidth - 2 * margin,
          align: 'justify'
        });

      doc.end();

    } catch (error: any) {
      console.error('Error generating COPASST acta PDF:', error);
      if (!res.headersSent) {
        res.status(500).send(error.message || 'Error al generar el PDF del acta');
      }
    }
  });

