  app.post("/api/copasst-elecciones", requirePermission("companies:edit"), async (req, res) => {
    try {
      const companyId = getEffectiveCompanyId(req);
      if (!companyId) {
        return res.status(403).send("Usuario no asociado a una empresa");
      }
      const validatedData = insertCopasstEleccionSchema.parse({
        ...req.body,
        companyId
      });
      const eleccion = await storage.createCopasstEleccion(validatedData);
      
      // Send notification to all workers when convocatoria is created
      try {
        const workers = await storage.getWorkers(companyId);
        for (const worker of workers) {
          try {
            const workerUser = await storage.getUserByWorkerId(worker.id);
            if (workerUser) {
              await storage.createInternalMessage({
                companyId,
                senderId: req.user!.id,
                senderName: req.user!.fullName || req.user!.username,
                senderRole: req.user!.role,
                receiverId: workerUser.id,
                receiverName: workerUser.fullName || workerUser.username,
                receiverRole: workerUser.role,
                subject: 'Convocatoria a Elecciones COPASST',
                content: 'Se ha abierto una nueva convocatoria para las elecciones del Comite Paritario de Seguridad y Salud en el Trabajo (COPASST). Si desea participar como candidato, inscribase en el portal de empleados.',
                priority: 'normal',
                status: 'unread',
                relatedEntity: 'copasst_eleccion',
                relatedEntityId: eleccion.id
              });
            }
          } catch (workerErr) {
            console.error('Error notifying worker for COPASST:', workerErr);
          }
        }
      } catch (notifErr) {
        console.error('Error sending COPASST convocatoria notifications:', notifErr);
      }
      
      res.status(201).json(eleccion);
    } catch (error: any) {
      res.status(400).send(error.message);
    }
  });

  app.patch("/api/copasst-elecciones/:id", requirePermission("companies:edit"), async (req, res) => {
    try {
      const companyId = getEffectiveCompanyId(req);
      if (!companyId) {
        return res.status(403).send("Usuario no asociado a una empresa");
      }
      const existing = await storage.getCopasstEleccion(req.params.id);
      if (!existing) {
        return res.status(404).send("Elección no encontrada");
      }
      if (existing.companyId !== companyId) {
        return res.status(403).send("Acceso no autorizado");
      }
      const validatedData = insertCopasstEleccionSchema.partial().parse(req.body);
      const eleccion = await storage.updateCopasstEleccion(req.params.id, validatedData);
      
      // Send notification when votacion period opens
      if (validatedData.estado === 'votacion' && existing.estado !== 'votacion') {
        try {
          const workers = await storage.getWorkers(companyId);
          for (const worker of workers) {
            try {
              const workerUser = await storage.getUserByWorkerId(worker.id);
              if (workerUser) {
                await storage.createInternalMessage({
                  companyId,
                  senderId: req.user!.id,
                  senderName: req.user!.fullName || req.user!.username,
                  senderRole: req.user!.role,
                  receiverId: workerUser.id,
                  receiverName: workerUser.fullName || workerUser.username,
                  receiverRole: workerUser.role,
                  subject: 'Votacion COPASST Abierta',
                  content: 'Se ha abierto el periodo de votacion para las elecciones del Comite Paritario de Seguridad y Salud en el Trabajo (COPASST). Acceda al portal de empleados para ejercer su voto.',
                  priority: 'normal',
                  status: 'unread',
                  relatedEntity: 'copasst_eleccion',
                  relatedEntityId: req.params.id
                });
              }
            } catch (workerErr) {
              console.error('Error notifying worker for COPASST voting:', workerErr);
            }
          }
        } catch (notifErr) {
          console.error('Error sending COPASST votacion notifications:', notifErr);
        }
      }
      
      // Auto-determine elected candidates when entering escrutinio phase
      if (validatedData.estado === 'escrutinio' && existing.estado !== 'escrutinio') {
        try {
          const candidatos = await storage.getCopasstCandidatos(req.params.id);
          // Sort by votes (descending)
          const candidatosOrdenados = [...candidatos].sort((a, b) => 
            (b.votosRecibidos || 0) - (a.votosRecibidos || 0)
          );
          
          let principalesCount = 0;
          let suplentesCount = 0;
          
          for (const candidato of candidatosOrdenados) {
            let nuevoEstado = candidato.estado;
            
            if (principalesCount < (existing.principalesRequeridos || 1)) {
              nuevoEstado = 'electo_principal';
              principalesCount++;
            } else if (suplentesCount < (existing.suplentesRequeridos || 1)) {
              nuevoEstado = 'electo_suplente';
              suplentesCount++;
            }
            
            if (nuevoEstado !== candidato.estado) {
              await storage.updateCopasstCandidato(candidato.id, { 
                estado: nuevoEstado,
                ordenEleccion: principalesCount + suplentesCount
              });
            }
          }
          console.log("[COPASST] Auto-elected " + principalesCount + " principales and " + suplentesCount + " suplentes");
        } catch (electError: any) {
          console.error('[COPASST] Error auto-electing candidates:', electError.message);
        }
      }
      // Auto-convert elected candidates to COPASST members when election is completed
      if (validatedData.estado === 'completada' && existing.estado !== 'completada') {
        try {
          // Get active period for this company
          const activoPeriodo = await storage.getCopasstPeriodoActivo(companyId);
          if (activoPeriodo) {
            // Get all elected candidates
            const candidatos = await storage.getCopasstCandidatos(req.params.id);
            const electos = candidatos.filter(c => 
              c.estado === 'electo_principal' || c.estado === 'electo_suplente'
            );
            
            // Get existing members to avoid duplicates
            const existingMiembros = await storage.getCopasstMiembros(activoPeriodo.id);
            const existingWorkerIds = new Set(existingMiembros.map(m => m.workerId));
            
            // Create members for each elected candidate
            for (const candidato of electos) {
              if (!existingWorkerIds.has(candidato.workerId)) {
                await storage.createCopasstMiembro({
                  periodoId: activoPeriodo.id,
                  workerId: candidato.workerId,
                  tipoRepresentante: 'trabajador',
                  rolMiembro: candidato.estado === 'electo_principal' ? 'principal' : 'suplente',
                  cargo: null,
                  votosObtenidos: candidato.votosRecibidos || 0,
                  fechaDesignacion: new Date().toISOString().split('T')[0],
                  activo: true,
                  capacitado: false,
                  fechaCapacitacion: null,
                });
              }
            }
            console.log(`[COPASST] Auto-created ${electos.length} members from election ${req.params.id}`);
          }
        } catch (memberError: any) {
          console.error('[COPASST] Error creating members from election:', memberError.message);
          // Don't fail the election update if member creation fails
        }
      }
      
      res.json(eleccion);
    } catch (error: any) {
      res.status(400).send(error.message);
    }
  });

