  app.post("/api/copasst-votacion/:eleccionId/votar", requireAuth, async (req, res) => {
    try {
      const companyId = req.user!.companyId;
      if (!companyId) {
        return res.status(403).send("Usuario no asociado a una empresa");
      }
      const { workerId, candidatoId } = req.body;
      if (!workerId || !candidatoId) {
        return res.status(400).send("workerId y candidatoId son requeridos");
      }
      const eleccion = await storage.getCopasstEleccion(req.params.eleccionId);
      if (!eleccion || eleccion.companyId !== companyId) {
        return res.status(404).send("Elección no encontrada o acceso no autorizado");
      }
      if (eleccion.estado !== 'en_curso') {
        return res.status(400).send("La elección no está en curso");
      }
      const yaVoto = await storage.hasVoted(req.params.eleccionId, workerId);
      if (yaVoto) {
        return res.status(400).send("El trabajador ya ha votado en esta elección");
      }
      await storage.registrarVoto(req.params.eleccionId, workerId, candidatoId);
      res.status(201).json({ mensaje: "Voto registrado exitosamente" });
    } catch (error: any) {
      res.status(400).send(error.message);
    }
  });

