  // 1. Convocatoria a Elecciones COPASST
  app.get("/api/copasst-elecciones/:id/convocatoria-pdf", requireAuth, async (req, res) => {
    try {
      const companyId = req.user!.companyId;
      if (!companyId) {
        return res.status(403).send("Usuario no asociado a una empresa");
      }
      
      const eleccion = await storage.getCopasstEleccion(req.params.id);
      if (!eleccion) {
        return res.status(404).send("Elección no encontrada");
      }
      if (eleccion.companyId !== companyId) {
        return res.status(403).send("Acceso no autorizado");
      }
      
      const company = await storage.getCompany(companyId);
      if (!company) {
        return res.status(404).send("Empresa no encontrada");
      }
      
      const PDFDocument = (await import('pdfkit')).default;
      const doc = new PDFDocument({ size: 'LETTER', margin: 50 });
      
      // Add trial watermark if subscription is in trial period
      const pdf10428_subscription = await storage.getSubscriptionByCompany(companyId);
      const pdf10428_trialStatus = getTrialStatus(pdf10428_subscription?.status || 'trial', pdf10428_subscription?.trialEnd || null, true, true);
      setupTrialWatermarkOnAllPages(doc, pdf10428_trialStatus.requiresWatermark);
      const margin = 35;
      const pageWidth = 612; // LETTER width
      
      res.setHeader('Content-Type', 'application/pdf');
      res.setHeader('Content-Disposition', `attachment; filename="convocatoria-copasst-${eleccion.id}.pdf"`);
      doc.pipe(res);
      
      // Preload company logo and worker photo from Object Storage
      const logoBuffer = await loadCompanyLogoBuffer(company.logoUrl);
      // Worker photo not needed for muestreo PDF
      
      const year = new Date(eleccion.fechaConvocatoria).getFullYear();
      
      const contentStartY = setupPdfHeadersFooters({
        doc,
        company: {
          name: company.name,
          nit: company.nit,
          address: company.address,
          logoUrl: company.logoUrl
        },
        documentTitle: `CONVOCATORIA A ELECCIONES COPASST ${year}`,
        documentCode: 'SST-COPASST-CONV',
        version: '1.0',
        date: new Date(eleccion.fechaConvocatoria),
        elaboro: company.legalRepName || 'Representante Legal',
        autorizo: 'Responsable SST',
        aprobo: company.legalRepName || 'Representante Legal',
        logoBuffer,
      });
      
      doc.y = contentStartY + 10;
      
      const fechaConvocatoria = new Date(eleccion.fechaConvocatoria).toLocaleDateString('es-CO', {
        year: 'numeric',
        month: 'long',
        day: 'numeric'
      });
      
      doc.fontSize(7).font('Helvetica').fillColor('#000000');
      doc.text(`${company.city || 'Ciudad'}, ${fechaConvocatoria}`, margin, doc.y, { align: 'right' });
      doc.moveDown(2);
      
      doc.fontSize(9).font('Helvetica-Bold');
      doc.text('A LOS TRABAJADORES:', margin);
      doc.moveDown(1.5);
      
      doc.fontSize(7).font('Helvetica');
      const introText = `De conformidad con lo establecido en la Resolución 2013 de 1986 del Ministerio de Trabajo y Seguridad Social, el Decreto 1072 de 2015 y la Resolución 0312 de 2019, la empresa ${company.name} convoca a todos los trabajadores al proceso de elección de los representantes de los trabajadores al Comité Paritario de Seguridad y Salud en el Trabajo (COPASST) para el período ${year}-${year + 2}.`;
      
      doc.text(introText, margin, doc.y, {
        width: pageWidth - 2 * margin,
        align: 'justify'
      });
      doc.moveDown(1.5);
      
      doc.fontSize(9).font('Helvetica-Bold');
      doc.text('CRONOGRAMA DEL PROCESO:', margin);
      doc.moveDown(0.5);
      
      doc.fontSize(7).font('Helvetica');
      const fechaInicioInscripcion = new Date(eleccion.fechaInicioInscripcion).toLocaleDateString('es-CO', {
        year: 'numeric', month: 'long', day: 'numeric'
      });
      const fechaFinInscripcion = new Date(eleccion.fechaFinInscripcion).toLocaleDateString('es-CO', {
        year: 'numeric', month: 'long', day: 'numeric'
      });
      const fechaVotacion = new Date(eleccion.fechaVotacion).toLocaleDateString('es-CO', {
        year: 'numeric', month: 'long', day: 'numeric'
      });
      
      doc.text(`• Publicación de convocatoria: ${fechaConvocatoria}`, margin + 20);
      doc.text(`• Período de inscripción de candidatos: ${fechaInicioInscripcion} al ${fechaFinInscripcion}`, margin + 20);
      doc.text(`• Fecha de votación: ${fechaVotacion}${eleccion.horaInicioVotacion ? ` de ${eleccion.horaInicioVotacion} a ${eleccion.horaFinVotacion}` : ''}`, margin + 20);
      doc.moveDown(1.5);
      
      doc.fontSize(9).font('Helvetica-Bold');
      doc.text('CARGOS A ELEGIR:', margin);
      doc.moveDown(0.5);
      
      doc.fontSize(7).font('Helvetica');
      doc.text(`• Representantes principales de los trabajadores: ${eleccion.principalesRequeridos}`, margin + 20);
      doc.text(`• Representantes suplentes de los trabajadores: ${eleccion.suplentesRequeridos}`, margin + 20);
      doc.moveDown(1.5);
      
      doc.fontSize(9).font('Helvetica-Bold');
      doc.text('REQUISITOS PARA SER CANDIDATO:', margin);
      doc.moveDown(0.5);
      
      doc.fontSize(7).font('Helvetica');
      doc.text('• Ser trabajador de la empresa con contrato vigente', margin + 20);
      doc.text('• Tener interés voluntario en participar en actividades de SST', margin + 20);
      doc.text('• Disponer de tiempo para cumplir con las funciones del COPASST', margin + 20);
      doc.text('• No haber sido sancionado disciplinariamente en el último año', margin + 20);
      doc.moveDown(1.5);
      
      doc.fontSize(9).font('Helvetica-Bold');
      doc.text('INFORMACIÓN GENERAL:', margin);
      doc.moveDown(0.5);
      
      doc.fontSize(7).font('Helvetica');
      doc.text(`• Total de trabajadores habilitados para votar: ${eleccion.totalTrabajadores}`, margin + 20);
      doc.text('• El voto es libre, secreto y voluntario', margin + 20);
      doc.text('• Los candidatos electos tendrán un período de dos (2) años', margin + 20);
      doc.moveDown(2);
      
      doc.text('Los interesados en inscribirse como candidatos deberán manifestar su intención por escrito ante el área de Recursos Humanos o Seguridad y Salud en el Trabajo.', margin, doc.y, {
        width: pageWidth - 2 * margin,
        align: 'justify'
      });
      doc.moveDown(3);
      
      doc.text('Atentamente,', margin);
      doc.moveDown(3);
      
      doc.text('_______________________________', margin);
      doc.text(company.legalRepName || 'REPRESENTANTE LEGAL', margin);
      doc.text(company.legalRepPosition || 'Gerente General', margin);
      doc.text(company.name, margin);
      
      doc.end();
    } catch (error: any) {
      res.status(500).send(`Error generando PDF: ${error.message}`);
    }
  });

  // 2. Acta de Escrutinio COPASST
  app.get("/api/copasst-elecciones/:id/acta-escrutinio-pdf", requireAuth, async (req, res) => {
    try {
      const companyId = req.user!.companyId;
      if (!companyId) {
        return res.status(403).send("Usuario no asociado a una empresa");
      }
      
      const eleccion = await storage.getCopasstEleccion(req.params.id);
      if (!eleccion) {
        return res.status(404).send("Elección no encontrada");
      }
      if (eleccion.companyId !== companyId) {
        return res.status(403).send("Acceso no autorizado");
      }
      
      const company = await storage.getCompany(companyId);
      if (!company) {
        return res.status(404).send("Empresa no encontrada");
      }
      
      const candidatos = await storage.getCopasstCandidatos(req.params.id);
      const candidatosOrdenados = [...candidatos].sort((a, b) => (b.votosRecibidos || 0) - (a.votosRecibidos || 0));
      
      const workerIds = candidatos.map(c => c.workerId);
      const workers = await Promise.all(workerIds.map(id => storage.getWorkerById(id)));
      const workerMap = new Map(workers.filter(w => w).map(w => [w!.id, w!]));
      
      const PDFDocument = (await import('pdfkit')).default;
      const doc = new PDFDocument({ size: 'LETTER', margin: 50 });
      
      // Add trial watermark if subscription is in trial period
      const pdf10584_subscription = await storage.getSubscriptionByCompany(companyId);
      const pdf10584_trialStatus = getTrialStatus(pdf10584_subscription?.status || 'trial', pdf10584_subscription?.trialEnd || null, true, true);
      setupTrialWatermarkOnAllPages(doc, pdf10584_trialStatus.requiresWatermark);
      const margin = 35;
      const pageWidth = 612; // LETTER width
      
      res.setHeader('Content-Type', 'application/pdf');
      res.setHeader('Content-Disposition', `attachment; filename="acta-escrutinio-copasst-${eleccion.id}.pdf"`);
      doc.pipe(res);
      
      // Preload company logo and worker photo from Object Storage
      const logoBuffer = await loadCompanyLogoBuffer(company.logoUrl);
      // Worker photo not needed for muestreo PDF
      
      const year = new Date(eleccion.fechaVotacion).getFullYear();
      
      const contentStartY = setupPdfHeadersFooters({
        doc,
        company: {
          name: company.name,
          nit: company.nit,
          address: company.address,
          logoUrl: company.logoUrl
        },
        documentTitle: `ACTA DE ESCRUTINIO - ELECCIONES COPASST ${year}`,
        documentCode: 'SST-COPASST-ESC',
        version: '1.0',
        date: new Date(eleccion.fechaVotacion),
        elaboro: 'Jurado de Votación',
        autorizo: 'Responsable SST',
        aprobo: company.legalRepName || 'Representante Legal',
        logoBuffer,
      });
      
      doc.y = contentStartY + 10;
      
      const fechaVotacion = new Date(eleccion.fechaVotacion).toLocaleDateString('es-CO', {
        year: 'numeric', month: 'long', day: 'numeric'
      });
      
      doc.fontSize(7).font('Helvetica').fillColor('#000000');
      doc.text(`Fecha: ${fechaVotacion}`, margin);
      doc.text(`Lugar: ${company.city || 'Instalaciones de la empresa'}`, margin);
      doc.moveDown(1.5);
      
      const totalVotantes = eleccion.totalVotantes || 0;
      const participacion = eleccion.totalTrabajadores > 0 
        ? ((totalVotantes / eleccion.totalTrabajadores) * 100).toFixed(1)
        : '0';
      
      doc.fontSize(9).font('Helvetica-Bold');
      doc.text('1. DATOS GENERALES DE LA VOTACIÓN', margin);
      doc.moveDown(0.5);
      
      doc.fontSize(7).font('Helvetica');
      doc.text(`• Total de trabajadores habilitados para votar: ${eleccion.totalTrabajadores}`, margin + 20);
      doc.text(`• Total de trabajadores que votaron: ${totalVotantes}`, margin + 20);
      doc.text(`• Porcentaje de participación: ${participacion}%`, margin + 20);
      doc.moveDown(1.5);
      
      doc.fontSize(9).font('Helvetica-Bold');
      doc.text('2. RESULTADOS DEL ESCRUTINIO', margin);
      doc.moveDown(0.5);
      
      doc.fontSize(7).font('Helvetica');
      doc.text(`• Votos válidos: ${eleccion.votosValidos || 0}`, margin + 20);
      doc.text(`• Votos nulos: ${eleccion.votosNulos || 0}`, margin + 20);
      doc.text(`• Votos en blanco: ${eleccion.votosEnBlanco || 0}`, margin + 20);
      doc.moveDown(1.5);
      
      doc.fontSize(9).font('Helvetica-Bold');
      doc.text('3. VOTACIÓN POR CANDIDATO', margin);
      doc.moveDown(0.5);
      
      const tableStartX = margin;
      const tableWidth = pageWidth - 2 * margin;
      const colWidths = [40, 200, 80, 100];
      let tableY = doc.y;
      
      doc.rect(tableStartX, tableY, tableWidth, 20).fill('#1e7e34');
      doc.fontSize(9).font('Helvetica-Bold').fillColor('#ffffff');
      doc.text('No.', tableStartX + 5, tableY + 6, { width: colWidths[0] });
      doc.text('CANDIDATO', tableStartX + colWidths[0] + 5, tableY + 6, { width: colWidths[1] });
      doc.text('VOTOS', tableStartX + colWidths[0] + colWidths[1] + 5, tableY + 6, { width: colWidths[2] });
      doc.text('RESULTADO', tableStartX + colWidths[0] + colWidths[1] + colWidths[2] + 5, tableY + 6, { width: colWidths[3] });
      
      tableY += 20;
      doc.fillColor('#000000');
      
      candidatosOrdenados.forEach((candidato, idx) => {
        const worker = workerMap.get(candidato.workerId);
        const nombre = worker ? worker.name : 'Candidato';
        const estado = candidato.estado === 'electo_principal' ? 'PRINCIPAL' 
          : candidato.estado === 'electo_suplente' ? 'SUPLENTE' : '-';
        
        const bgColor = idx % 2 === 0 ? '#f9f9f9' : '#ffffff';
        doc.rect(tableStartX, tableY, tableWidth, 18).fill(bgColor);
        
        doc.fontSize(7).font('Helvetica').fillColor('#000000');
        doc.text(`${idx + 1}`, tableStartX + 5, tableY + 5, { width: colWidths[0] });
        doc.text(nombre, tableStartX + colWidths[0] + 5, tableY + 5, { width: colWidths[1] });
        doc.text(`${candidato.votosRecibidos || 0}`, tableStartX + colWidths[0] + colWidths[1] + 5, tableY + 5, { width: colWidths[2] });
        
        if (estado !== '-') {
          doc.font('Helvetica-Bold').fillColor(estado === 'PRINCIPAL' ? '#1e7e34' : '#0066cc');
        }
        doc.text(estado, tableStartX + colWidths[0] + colWidths[1] + colWidths[2] + 5, tableY + 5, { width: colWidths[3] });
        doc.fillColor('#000000');
        
        tableY += 18;
      });
      
      doc.rect(tableStartX, doc.y, tableWidth, tableY - doc.y + 20).stroke('#cccccc');
      doc.y = tableY + 10;
      doc.moveDown(1.5);
      
      const principales = candidatosOrdenados.filter(c => c.estado === 'electo_principal');
      const suplentes = candidatosOrdenados.filter(c => c.estado === 'electo_suplente');
      
      doc.fontSize(9).font('Helvetica-Bold');
      doc.text('4. REPRESENTANTES ELECTOS', margin);
      doc.moveDown(0.5);
      
      doc.fontSize(8).font('Helvetica-Bold');
      doc.text('Principales:', margin);
      principales.forEach(c => {
        const w = workerMap.get(c.workerId);
        doc.font('Helvetica').text(`  • ${w?.name || 'N/A'} - ${c.votosRecibidos || 0} votos`, margin + 10);
      });
      
      doc.moveDown(0.5);
      doc.font('Helvetica-Bold').text('Suplentes:', margin);
      suplentes.forEach(c => {
        const w = workerMap.get(c.workerId);
        doc.font('Helvetica').text(`  • ${w?.name || 'N/A'} - ${c.votosRecibidos || 0} votos`, margin + 10);
      });
      doc.moveDown(2);
      
      doc.fontSize(7).font('Helvetica');
      doc.text('Los abajo firmantes, en calidad de jurados de votación, certificamos que el presente escrutinio se realizó de manera transparente y conforme a la ley.', margin, doc.y, {
        width: pageWidth - 2 * margin,
        align: 'justify'
      });
      doc.moveDown(3);
      
      checkSignatureSpace(doc, 100);
      doc.moveDown(2);
      
      const sigWidth = (pageWidth - 2 * margin - 40) / 3;
      const sigY = doc.y;
      
      doc.text('_______________________', margin, sigY);
      doc.text('_______________________', margin + sigWidth + 20, sigY);
      doc.text('_______________________', margin + (sigWidth + 20) * 2, sigY);
      
      const labelY = sigY + 15;
      doc.text('Jurado 1', margin, labelY, { width: sigWidth });
      doc.text('Jurado 2', margin + sigWidth + 20, labelY, { width: sigWidth });
      doc.text('Jurado 3', margin + (sigWidth + 20) * 2, labelY, { width: sigWidth });
      
      doc.end();
    } catch (error: any) {
      res.status(500).send(`Error generando PDF: ${error.message}`);
    }
  });

