  // Generate certificate PDF
  app.get("/api/copasst-capacitacion/certificados/:id/pdf", requireAuth, async (req, res) => {
    try {
      const companyId = req.user!.companyId;
      const userId = req.user!.id;
      if (!companyId) {
        return res.status(403).send("Usuario no asociado a una empresa");
      }
      
      const certificados = await storage.getCopasstCertificadosByUser(companyId, userId);
      const certificado = certificados.find(c => c.id === req.params.id);
      
      if (!certificado) {
        return res.status(404).send("Certificado no encontrado");
      }
      
      const company = await storage.getCompany(companyId);
      if (!company) {
        return res.status(404).send("Empresa no encontrada");
      }
      
      const PDFDocument = (await import('pdfkit')).default;
      const doc = new PDFDocument({ size: 'LETTER', layout: 'landscape', margin: 50 });
      
      // Add trial watermark if subscription is in trial period
      const pdf11509_subscription = await storage.getSubscriptionByCompany(companyId);
      const pdf11509_trialStatus = getTrialStatus(pdf11509_subscription?.status || 'trial', pdf11509_subscription?.trialEnd || null, true, true);
      setupTrialWatermarkOnAllPages(doc, pdf11509_trialStatus.requiresWatermark);
      
      res.setHeader('Content-Type', 'application/pdf');
      res.setHeader('Content-Disposition', `attachment; filename="certificado-${certificado.codigoCertificado}.pdf"`);
      doc.pipe(res);
      
      const pageHeight = doc.page.height;
      
      // Border
      doc.rect(margin, margin, pageWidth - 2 * margin, pageHeight - 2 * margin)
         .lineWidth(3).stroke('#1e3a5f');
      doc.rect(margin + 10, margin + 10, pageWidth - 2 * margin - 20, pageHeight - 2 * margin - 20)
         .lineWidth(1).stroke('#1e3a5f');
      
      // Header
      doc.fontSize(24).font('Helvetica-Bold').fillColor('#1e3a5f');
      doc.text('CERTIFICADO DE CAPACITACIÓN', margin, margin + 40, { align: 'center', width: pageWidth - 2 * margin });
      
      doc.fontSize(9).font('Helvetica');
      doc.text('COMITÉ PARITARIO DE SEGURIDAD Y SALUD EN EL TRABAJO', { align: 'center', width: pageWidth - 2 * margin });
      doc.moveDown(2);
      
      // Content
      doc.fontSize(9).fillColor('#333333');
      doc.text('Se certifica que:', { align: 'center', width: pageWidth - 2 * margin });
      doc.moveDown(0.5);
      
      doc.fontSize(20).font('Helvetica-Bold').fillColor('#1e3a5f');
      doc.text(certificado.nombreCompleto.toUpperCase(), { align: 'center', width: pageWidth - 2 * margin });
      doc.moveDown(0.5);
      
      doc.fontSize(9).font('Helvetica').fillColor('#333333');
      doc.text(`Identificación: ${certificado.identificacion}`, { align: 'center', width: pageWidth - 2 * margin });
      doc.moveDown(1);
      
      doc.text('Ha completado satisfactoriamente el curso:', { align: 'center', width: pageWidth - 2 * margin });
      doc.moveDown(0.5);
      
      doc.fontSize(9).font('Helvetica-Bold').fillColor('#1e3a5f');
      doc.text(`"${certificado.tituloCurso}"`, { align: 'center', width: pageWidth - 2 * margin });
      doc.moveDown(1);
      
      doc.fontSize(9).font('Helvetica').fillColor('#333333');
      doc.text(`Duración: ${certificado.duracionHoras} horas`, { align: 'center', width: pageWidth - 2 * margin });
      doc.text(`Calificación: ${certificado.puntajeObtenido}/${certificado.puntajeMaximo} puntos`, { align: 'center', width: pageWidth - 2 * margin });
      doc.moveDown(2);
      
      const fechaEmision = new Date(certificado.fechaEmision).toLocaleDateString('es-CO', {
        year: 'numeric', month: 'long', day: 'numeric'
      });
      doc.text(`Emitido el ${fechaEmision}`, { align: 'center', width: pageWidth - 2 * margin });
      
      if (certificado.fechaVencimiento) {
        const fechaVenc = new Date(certificado.fechaVencimiento).toLocaleDateString('es-CO', {
          year: 'numeric', month: 'long', day: 'numeric'
        });
        doc.text(`Válido hasta: ${fechaVenc}`, { align: 'center', width: pageWidth - 2 * margin });
      }
      
      doc.moveDown(2);
      
      // Footer
      doc.fontSize(8).fillColor('#666666');
      doc.text(`Código de verificación: ${certificado.codigoCertificado}`, { align: 'center', width: pageWidth - 2 * margin });
      doc.text(`${company.name} - NIT: ${company.nit}`, { align: 'center', width: pageWidth - 2 * margin });
      
      doc.end();
    } catch (error: any) {
      res.status(500).send(`Error generando PDF: ${error.message}`);
    }
  });


