  // Submit a decision
  app.post("/api/copasst-capacitacion/escenarios/:id/decision", requireAuth, async (req, res) => {
    try {
      const companyId = req.user!.companyId;
      const userId = req.user!.id;
      if (!companyId) {
        return res.status(403).send("Usuario no asociado a una empresa");
      }
      
      const { progresoId, nodoId, opcionIndex, puntos } = req.body;
      if (!progresoId || !nodoId || opcionIndex === undefined) {
        return res.status(400).send("Se requiere progresoId, nodoId y opcionIndex");
      }
      
      const progreso = await storage.updateEscenarioProgreso(progresoId, nodoId, opcionIndex, puntos || 0);
      
      const nodos = await storage.getEscenarioNodos(req.params.id);
      const nodoActual = nodos.find(n => n.id === nodoId);
      const opciones = (nodoActual?.opciones as any[]) || [];
      const opcionSeleccionada = opciones[opcionIndex];
      const siguienteNodoId = opcionSeleccionada?.siguienteNodoId;
      const siguienteNodo = siguienteNodoId ? nodos.find(n => n.id === siguienteNodoId) : null;
      
      res.json({
        progreso,
        feedback: opcionSeleccionada?.feedback || null,
        siguienteNodo
      });
    } catch (error: any) {
      res.status(400).send(error.message);
    }
  });

