  app.post("/api/copasst-capacitacion/banco-preguntas/importar", requireAuth, async (req, res) => {
    try {
      const companyId = (req.user as schema.User).companyId;
      if (!companyId) {
        return res.status(400).json({ error: "No company assigned" });
      }
      const { preguntas } = req.body;
      if (!Array.isArray(preguntas)) {
        return res.status(400).json({ error: "Se espera un array de preguntas en el campo 'preguntas'" });
      }
      let importedCount = 0;
      const errors: string[] = [];
      for (let i = 0; i < preguntas.length; i++) {
        try {
          const validatedData = insertCopasstBancoPreguntaSchema.parse({
            ...preguntas[i],
            companyId,
          });
          await storage.createCopasstBancoPregunta(validatedData);
          importedCount++;
        } catch (err: any) {
          errors.push(`Pregunta ${i + 1}: ${err.message}`);
        }
      }
      res.status(201).json({
        importedCount,
        totalReceived: preguntas.length,
        errors: errors.length > 0 ? errors : undefined,
      });
    } catch (error: any) {
      res.status(400).json({ error: error.message });
    }
  });

