  // POST /api/copasst-capacitacion/notificaciones/enviar-pendientes - Process pending notifications (for cron)
  app.post("/api/copasst-capacitacion/notificaciones/enviar-pendientes", requireAuth, async (req, res) => {
    try {
      const companyId = (req.user as schema.User).companyId;
      if (!companyId) {
        return res.status(400).json({ error: "No company assigned" });
      }
      
      const pendientes = await storage.listCopasstNotificaciones(companyId, { estado: "pendiente" });
      const now = new Date();
      let enviadas = 0;
      let fallidas = 0;
      
      for (const notificacion of pendientes) {
        const fechaProgramada = notificacion.fechaProgramada ? new Date(notificacion.fechaProgramada) : null;
        if (!fechaProgramada || fechaProgramada <= now) {
          try {
            const user = await storage.getUser(notificacion.userId);
            if (!user || !user.email) {
              await storage.marcarNotificacionEnviada(notificacion.id, false, 'Usuario no encontrado o sin email');
              fallidas++;
              continue;
            }
            
            let companyName: string | undefined;
            const company = await storage.getCompany(companyId);
            companyName = company?.name;
            
            const result = await sendNotificationEmail({
              to: user.email,
              titulo: notificacion.titulo,
              mensaje: notificacion.mensaje,
              tipo: notificacion.tipo,
              companyName
            });
            
            if (result.success) {
              await storage.marcarNotificacionEnviada(notificacion.id, true);
              enviadas++;
            } else {
              await storage.marcarNotificacionEnviada(notificacion.id, false, result.error);
              fallidas++;
            }
          } catch (err: any) {
            await storage.marcarNotificacionEnviada(notificacion.id, false, err.message);
            fallidas++;
          }
        }
      }
      
      res.json({
        procesadas: enviadas,
        fallidas,
        totalPendientes: pendientes.length,
        mensaje: `Se enviaron ${enviadas} notificaciones, ${fallidas} fallaron`,
      });
    } catch (error: any) {
      res.status(500).json({ error: error.message });
    }
  });

  
