  // Generate PDF for Comité de Convivencia Acta
  app.get("/api/comite-convivencia-actas/:id/pdf", requirePermission("companies:view"), async (req, res) => {
    try {
      const companyId = req.user!.companyId!;
      const acta = await storage.getComiteConvivenciaActa(req.params.id, companyId);
      if (!acta) {
        return res.status(404).send("Acta del Comité de Convivencia no encontrada");
      }

      const company = await storage.getCompany(companyId);
      if (!company) {
        return res.status(404).send("Empresa no encontrada");
      }

      // Import PDFKit dynamically
      const { default: PDFDocument } = await import('pdfkit');
      
      // Create PDF
      const doc = new PDFDocument({ size: 'letter', margin: 35 });
      
      // Add trial watermark if subscription is in trial period
      const pdf12724_subscription = await storage.getSubscriptionByCompany(companyId);
      const pdf12724_trialStatus = getTrialStatus(pdf12724_subscription?.status || 'trial', pdf12724_subscription?.trialEnd || null, true, true);
      setupTrialWatermarkOnAllPages(doc, pdf12724_trialStatus.requiresWatermark);
      const margin = 35;
      const pageWidth = doc.page.width;
      const chunks: Buffer[] = [];
      
      doc.on('data', (chunk) => chunks.push(chunk));
      doc.on('end', () => {
        const pdfBuffer = Buffer.concat(chunks);
        res.setHeader('Content-Type', 'application/pdf');
        res.setHeader('Content-Disposition', `attachment; filename="acta-comite-convivencia-${acta.numeroActa}.pdf"`);
        res.send(pdfBuffer);
      });

      // Preload company logo and worker photo from Object Storage
      const logoBuffer = await loadCompanyLogoBuffer(company.logoUrl);
      // Worker photo not needed for muestreo PDF
      
      // Standard Header with logo, version control table in green, and automatic footer with signatures
      let currentY = setupPdfHeadersFooters({
        doc,
        company,
        documentTitle: 'ACTA DE CONSTITUCIÓN DEL COMITÉ DE CONVIVENCIA LABORAL',
        logoBuffer,
        documentCode: `SST-CC-${acta.numeroActa}`,
        version: '1.0',
        date: new Date(acta.fecha),
        elaboro: 'Secretario Comité',
        autorizo: req.user?.username || 'Sistema',
        aprobo: 'Presidente Comité'
      });

      currentY += 15;

      // Acta info section with green header
      doc.fontSize(9).font('Helvetica-Bold').fillColor('#1e7e34')
        .text('INFORMACIÓN DEL ACTA', margin, currentY);
      currentY = doc.y + 10;

      doc.fontSize(8).font('Helvetica-Bold').fillColor('#000000')
        .text('Acta N°: ', margin, currentY, { continued: true });
      doc.font('Helvetica').text(acta.numeroActa);
      currentY = doc.y + 5;

      doc.fontSize(8).font('Helvetica-Bold')
        .text('Fecha: ', margin, currentY, { continued: true });
      doc.font('Helvetica').text(new Date(acta.fecha).toLocaleDateString('es-CO', { year: 'numeric', month: 'long', day: 'numeric' }));
      currentY = doc.y + 15;

      // Representantes por los trabajadores with green header
      doc.fontSize(9).font('Helvetica-Bold').fillColor('#1e7e34')
        .text('REPRESENTANTES POR LOS TRABAJADORES', margin, currentY);
      currentY = doc.y + 10;

      const representantesTrabajadores = [
        { nombre: acta.trabajador1Nombre, cedula: acta.trabajador1Cedula, tipo: acta.trabajador1Tipo },
        { nombre: acta.trabajador2Nombre, cedula: acta.trabajador2Cedula, tipo: acta.trabajador2Tipo },
        { nombre: acta.trabajador3Nombre, cedula: acta.trabajador3Cedula, tipo: acta.trabajador3Tipo },
      ];

      representantesTrabajadores.forEach((rep, index) => {
        if (rep.nombre || rep.cedula) {
          doc.fontSize(8).font('Helvetica').fillColor('#000000')
            .text(`${index + 1}. `, margin, currentY, { continued: true })
            .font('Helvetica-Bold')
            .text(rep.nombre || '-', { continued: true })
            .font('Helvetica')
            .text(` | CC: ${rep.cedula || '-'} | ${rep.tipo || '-'}`);
          currentY = doc.y + 5;
        }
      });

      currentY += 10;

      // Representantes por los empleadores with green header
      doc.fontSize(9).font('Helvetica-Bold').fillColor('#1e7e34')
        .text('REPRESENTANTES POR LOS EMPLEADORES', margin, currentY);
      currentY = doc.y + 10;

      const representantesEmpleadores = [
        { nombre: acta.empleador1Nombre, cedula: acta.empleador1Cedula, tipo: acta.empleador1Tipo },
        { nombre: acta.empleador2Nombre, cedula: acta.empleador2Cedula, tipo: acta.empleador2Tipo },
        { nombre: acta.empleador3Nombre, cedula: acta.empleador3Cedula, tipo: acta.empleador3Tipo },
      ];

      representantesEmpleadores.forEach((rep, index) => {
        if (rep.nombre || rep.cedula) {
          doc.fontSize(8).font('Helvetica').fillColor('#000000')
            .text(`${index + 1}. `, margin, currentY, { continued: true })
            .font('Helvetica-Bold')
            .text(rep.nombre || '-', { continued: true })
            .font('Helvetica')
            .text(` | CC: ${rep.cedula || '-'} | ${rep.tipo || '-'}`);
          currentY = doc.y + 5;
        }
      });

      currentY += 15;

      // Notas content with green header
      doc.fontSize(9).font('Helvetica-Bold').fillColor('#1e7e34')
        .text('CONTENIDO DEL ACTA', margin, currentY);
      currentY = doc.y + 10;

      doc.fontSize(8).font('Helvetica').fillColor('#000000')
        .text(acta.notas || 'Sin contenido registrado', margin, currentY, {
          width: pageWidth - 2 * margin,
          align: 'justify'
        });

      doc.end();

    } catch (error: any) {
      console.error('Error generating Comité de Convivencia acta PDF:', error);
      if (!res.headersSent) {
        res.status(500).send(error.message || 'Error al generar el PDF del acta');
      }
    }
  });

