  // Create programa de capacitación with file upload
  app.post("/api/programas-capacitacion", requirePermission("companies:edit"), uploadProgramaCapacitacion.single('archivo'), async (req, res) => {
    try {
      const companyId = req.user!.companyId!;
      
      let archivoUrl = null;
      let archivoNombre = null;
      
      if (req.file) {
        // Upload to Object Storage for persistence
        const objectStorageService = new ObjectStorageService();
        const fileBuffer = fs.readFileSync(req.file.path);
        const ext = path.extname(req.file.originalname);
        const uniqueId = crypto.randomUUID();
        const objectPath = `uploads/programas-capacitacion/${companyId}/${uniqueId}${ext}`;
        
        await objectStorageService.uploadObject(objectPath, fileBuffer, req.file.mimetype);
        
        // Clean up local file
        fs.unlinkSync(req.file.path);
        
        archivoUrl = `/objects/${objectPath}`;
        archivoNombre = req.file.originalname;
      }
      
      const programaData = {
        fecha: req.body.fecha,
        titulo: req.body.titulo,
        archivoUrl,
        archivoNombre,
      };

      const validatedData = insertProgramaCapacitacionSchema.parse(programaData);
      const programa = await storage.createProgramaCapacitacion(validatedData, companyId);
      res.json(programa);
    } catch (error: any) {
      if (error.name === 'ZodError') {
        return res.status(400).send(error.errors);
      }
      res.status(400).send(error.message);
    }
  });

