  // Generate PDF from markdown documentation
  app.get("/api/docs/programa-capacitacion-prevencion/pdf", requireAuth, async (req, res) => {
    try {
      const markdownPath = path.join(process.cwd(), 'docs', 'PROGRAMA_CAPACITACION_PREVENCION.md');
      
      if (!fs.existsSync(markdownPath)) {
        return res.status(404).send("Archivo de documentación no encontrado");
      }

      const markdownContent = fs.readFileSync(markdownPath, 'utf-8');
      const tokens = marked.lexer(markdownContent);

      const doc = new PDFDocument({ 
        margins: { top: 50, left: 50, bottom: 50, right: 50 },
        size: 'A4'
      });
      
      // Add trial watermark if subscription is in trial period
      const doc_subscription = await storage.getSubscriptionByCompany(companyId);
      const doc_trialStatus = getTrialStatus(doc_subscription?.status || 'trial', doc_subscription?.trialEnd || null, true, true);
      setupTrialWatermarkOnAllPages(doc, doc_trialStatus.requiresWatermark);

      res.contentType('application/pdf');
      doc.pipe(res);

      let currentY = doc.y;

      for (const token of tokens) {
        if (token.type === 'heading') {
          const fontSize = [32, 24, 18, 16, 14, 12][token.depth - 1] || 12;
          doc.fontSize(fontSize)
            .font('Helvetica-Bold')
            .fillColor('#1a472a')
            .text(token.text, { 
              align: token.depth === 1 ? 'center' : 'left',
              continued: false
            });
          doc.moveDown(0.5);
        } else if (token.type === 'paragraph') {
          doc.fontSize(9)
            .font('Helvetica')
            .fillColor('#000000')
            .text(token.text, {
              align: 'justify',
              continued: false
            });
          doc.moveDown(0.3);
        } else if (token.type === 'list') {
          const items = token.items || [];
          const isOrdered = token.ordered || false;
          
          for (let i = 0; i < items.length; i++) {
            const item = items[i];
            const prefix = isOrdered ? `${i + 1}. ` : '• ';
            
            doc.fontSize(9)
              .font('Helvetica')
              .fillColor('#000000')
              .text(prefix + item.text, {
                indent: 20,
                align: 'left',
                continued: false
              });
          }
          doc.moveDown(0.3);
        } else if (token.type === 'code') {
          doc.fontSize(9)
            .font('Courier')
            .fillColor('#333333')
            .text(token.text, {
              continued: false
            });
          doc.moveDown(0.5);
        } else if (token.type === 'space') {
          doc.moveDown(0.2);
        }

        if (doc.y > doc.page.height - 100) {
          doc.addPage();
        }
      }

      doc.end();

    } catch (error: any) {
      console.error('Error generating PDF from markdown:', error);
      if (!res.headersSent) {
        res.status(500).send(error.message || 'Error al generar el PDF');
      }
    }
  });

