  // Create registro de inducción
  app.post("/api/registros-induccion", requirePermission("workers:edit"), async (req, res) => {
    try {
      const parsed = schema.insertRegistroInduccionSchema.parse(req.body);
      
      const userRole = req.user!.role;
      const isAdmin = hasGlobalAccess(userRole);
      
      let companyId: string;
      if (isAdmin) {
        // Admin: get companyId from the worker
        const worker = await storage.getWorkerById(parsed.workerId);
        if (!worker) {
          return res.status(400).send("Trabajador no encontrado");
        }
        companyId = worker.companyId;
      } else {
        // Non-admin: use their own companyId
        companyId = req.user!.companyId || "";
        if (!companyId) {
          return res.status(403).send("Usuario no asociado a una empresa");
        }
      }
      
      const registro = await storage.createRegistroInduccion(parsed, companyId);
      
      // Send notification to worker's portal
      try {
        const worker = await storage.getWorkerById(parsed.workerId);
        if (worker) {
          const workerUser = await storage.getUserByWorkerId(worker.id);
          if (workerUser) {
            const tipoInduccion = parsed.tipo === 'reinduccion' ? 'Reinducción' : 'Inducción';
            const fechaFormateada = parsed.fecha 
              ? new Date(parsed.fecha).toLocaleDateString('es-CO', { year: 'numeric', month: 'long', day: 'numeric' })
              : 'Por definir';
            
            await storage.createInternalMessage({
              companyId,
              senderId: req.user!.id,
              senderName: req.user!.fullName || req.user!.username,
              senderRole: req.user!.role,
              receiverId: workerUser.id,
              receiverName: workerUser.fullName || workerUser.username,
              receiverRole: workerUser.role,
              subject: 'Registro de Inducción Asignado',
              content: `Se ha registrado una ${tipoInduccion.toLowerCase()} para usted.\n\nTipo: ${tipoInduccion}\nFecha: ${fechaFormateada}\nResponsable: ${parsed.responsable || 'Por asignar'}\n\nPor favor, complete los requisitos correspondientes.`,
              priority: 'normal',
              status: 'unread',
              relatedEntity: 'registro_induccion',
              relatedEntityId: registro.id
            });
          }
        }
      } catch (notifError) {
        console.error('Error sending portal notification for inducción:', notifError);
      }
      
      res.json(registro);
    } catch (error: any) {
      if (error.name === 'ZodError') {
        return res.status(400).send(error.errors);
      }
      res.status(400).send(error.message);
    }
  });

