  // Get all detalles for a verificacion (enriched with worker data)
  app.get("/api/verificaciones-muestreo-sgss/:id/detalles", requirePermission("companies:view"), async (req, res) => {
    try {
      const companyId = req.user!.companyId;
      if (!companyId) {
        return res.status(403).send("Usuario no asociado a una empresa");
      }
      // Verify the verificacion belongs to the company
      const verificacion = await storage.getVerificacionMuestreoSgss(req.params.id, companyId);
      if (!verificacion) {
        return res.status(404).send("Verificación no encontrada");
      }
      const detalles = await storage.getDetallesVerificacionSgss(req.params.id);
      
      // Get afiliaciones for this company to enrich worker data
      const afiliaciones = await storage.getAfiliacionesSsss(companyId!);
      
      // Enrich detalles with worker information and affiliation data (SST-2026-0017 fix)
      const detallesEnriquecidos = await Promise.all(
        detalles.map(async (detalle) => {
          const worker = await storage.getWorkerById(detalle.workerId);
          // Find affiliation data - first from afiliaciones table, then from worker record
          const afiliacion = afiliaciones.find(a => a.workerId === detalle.workerId);
          
          // Enrich with worker data
          const enrichedEps = afiliacion?.epsNombre || worker?.epsNombre || null;
          const enrichedArl = afiliacion?.arlNombre || worker?.arlNombre || null;
          const enrichedAfp = afiliacion?.afpNombre || worker?.afpNombre || null;
          const enrichedCcf = afiliacion?.ccfNombre || worker?.ccfNombre || null;
          
          // Recalculate verification status based on enriched data (for existing records)
          const verificadoEpsCalc = !!enrichedEps;
          const verificadoArlCalc = !!enrichedArl;
          const verificadoAfpCalc = !!enrichedAfp;
          const verificadoCcfCalc = !!enrichedCcf;
          const cumpleCalc = verificadoEpsCalc && verificadoArlCalc && verificadoAfpCalc;
          
          return { 
            ...detalle, 
            workerName: worker?.name || null,
            workerIdentificationNumber: worker?.identificationNumber || null,
            workerPosition: worker?.position || null,
            // Include affiliation data from afiliaciones table or worker record
            epsNombre: enrichedEps,
            arlNombre: enrichedArl,
            afpNombre: enrichedAfp,
            ccfNombre: enrichedCcf,
            // Override stored verificado* with recalculated values based on enriched data
            verificadoEps: verificadoEpsCalc,
            verificadoArl: verificadoArlCalc,
            verificadoAfp: verificadoAfpCalc,
            verificadoCcf: verificadoCcfCalc,
            cumple: cumpleCalc,
          };
        })
      );
      
      res.json(detallesEnriquecidos);
    } catch (error: any) {
      res.status(400).send(error.message);
    }
  });

