  // Generate Evidencia de Verificación PDF - Resolución 0312/2019 Estándar 1.1.4
  app.get("/api/verificaciones-muestreo-sgss/:id/evidencia-pdf", requirePermission("companies:view"), async (req, res) => {
    try {
      const isAdmin = hasGlobalAccess(req.user!.role);
      let companyId: string;
      
      // Get verificacion
      const verificacion = await storage.getVerificacionMuestreoSgssById(req.params.id);
      if (!verificacion) {
        return res.status(404).send("Verificación no encontrada");
      }
      
      if (isAdmin) {
        companyId = verificacion.companyId;
      } else {
        companyId = req.user!.companyId || "";
        if (!companyId) {
          return res.status(403).send("Usuario no asociado a una empresa");
        }
        if (verificacion.companyId !== companyId) {
          return res.status(403).send("No tiene acceso a esta verificación");
        }
      }
      
      // Get company
      const company = await storage.getCompany(companyId);
      if (!company) {
        return res.status(404).send("Empresa no encontrada");
      }
      
      // Get detalles (verified workers)
      const detalles = await storage.getDetallesVerificacionSgss(req.params.id);
      
      // Get afiliaciones and worker data for each detalle (with recalculation)
      const afiliaciones = await storage.getAfiliacionesSsss(companyId);
      const detallesConTrabajador = await Promise.all(
        detalles.map(async (detalle) => {
          const worker = await storage.getWorkerById(detalle.workerId);
          const afiliacion = afiliaciones.find(a => a.workerId === detalle.workerId);
          
          // Recalculate verification based on enriched data (afiliacion + worker)
          const verificadoEps = !!(afiliacion?.epsNombre || worker?.epsNombre);
          const verificadoArl = !!(afiliacion?.arlNombre || worker?.arlNombre);
          const verificadoAfp = !!(afiliacion?.afpNombre || worker?.afpNombre);
          const verificadoCcf = !!(afiliacion?.ccfNombre || worker?.ccfNombre);
          const cumple = verificadoEps && verificadoArl && verificadoAfp;
          
          return { 
            ...detalle, 
            worker,
            verificadoEps,
            verificadoArl,
            verificadoAfp,
            verificadoCcf,
            cumple,
            epsNombre: afiliacion?.epsNombre || worker?.epsNombre || null,
            arlNombre: afiliacion?.arlNombre || worker?.arlNombre || null,
            afpNombre: afiliacion?.afpNombre || worker?.afpNombre || null,
            ccfNombre: afiliacion?.ccfNombre || worker?.ccfNombre || null,
          };
        })
      );
      
      // Get verificadoPor worker if exists
      let verificadoPorWorker = null;
      if (verificacion.verificadoPor) {
        verificadoPorWorker = await storage.getWorkerById(verificacion.verificadoPor);
      }
      
      // Create PDF with standard format
      const doc = new PDFDocument({ margin: 35, size: 'LETTER' });
      
      // Add trial watermark if subscription is in trial period
      const pdf14739_subscription = await storage.getSubscriptionByCompany(companyId);
      const pdf14739_trialStatus = getTrialStatus(pdf14739_subscription?.status || 'trial', pdf14739_subscription?.trialEnd || null, true, true);
      setupTrialWatermarkOnAllPages(doc, pdf14739_trialStatus.requiresWatermark);
      const margin = 35;
      const pageWidth = doc.page.width;
      const contentWidth = pageWidth - (margin * 2);
      const GREEN_HEADER = '#1e7e34';
      
      // Set response headers
      res.setHeader('Content-Type', 'application/pdf');
      res.setHeader('Content-Disposition', `attachment; filename="Evidencia-Verificacion-SGSS-${verificacion.id.substring(0, 8)}.pdf"`);
      
      // Pipe PDF to response
      doc.pipe(res);
      
      // Preload company logo
      const logoBuffer = await loadCompanyLogoBuffer(company.logoUrl);
      
      // Setup standard headers and footers
      const fechaVerificacion = new Date(verificacion.fecha);
      const startY = setupPdfHeadersFooters({
        doc,
        company: {
          name: company.name,
          nit: company.nit || 'No registrado',
          address: company.address,
          logoUrl: company.logoUrl,
        },
        documentTitle: 'VERIFICACIÓN MUESTREO SGSS',
        documentCode: 'SST-VER-001',
        version: '1.0',
        date: fechaVerificacion,
        elaboro: verificadoPorWorker?.name || 'Responsable SST',
        autorizo: 'Representante Legal',
        aprobo: 'Gerencia',
        logoBuffer,
      });
      
      let currentY = startY;
      
      // Title with green bar
      doc.rect(margin, currentY, contentWidth, 22).fill(GREEN_HEADER);
      doc.fontSize(11).font('Helvetica-Bold').fillColor('#FFFFFF');
      doc.text('EVIDENCIA DE VERIFICACIÓN DE AFILIACIÓN AL SGSS', margin, currentY + 6, { width: contentWidth, align: 'center' });
      doc.fillColor('#000000');
      currentY += 28;
      
      // Subtitle
      doc.fontSize(8).font('Helvetica').fillColor('#666666');
      doc.text('Resolución 0312 de 2019 - Estándar 1.1.4', margin, currentY, { width: contentWidth, align: 'center' });
      doc.fillColor('#000000');
      currentY += 18;
      
      // Section: DATOS DE LA VERIFICACIÓN
      doc.rect(margin, currentY, contentWidth, 18).fill(GREEN_HEADER);
      doc.fontSize(9).font('Helvetica-Bold').fillColor('#FFFFFF');
      doc.text('DATOS DE LA VERIFICACIÓN', margin + 8, currentY + 4);
      doc.fillColor('#000000');
      currentY += 22;
      
      const fechaVerif = fechaVerificacion.toLocaleDateString('es-CO', { day: '2-digit', month: 'long', year: 'numeric' });
      doc.fontSize(9).font('Helvetica');
      doc.text(`Fecha de Verificación: ${fechaVerif}`, margin + 8, currentY);
      currentY += 14;
      doc.text(`Período Verificado: ${verificacion.periodoVerificado || 'Últimos 4 meses PILA'}`, margin + 8, currentY);
      currentY += 14;
      doc.text(`Total Trabajadores Activos: ${verificacion.totalTrabajadores}`, margin + 8, currentY);
      currentY += 14;
      doc.text(`Muestra Requerida (Res. 0312/2019): ${verificacion.muestraRequerida}`, margin + 8, currentY);
      currentY += 14;
      
      // Compliance percentage with color coding
      const cumplimientoColor = (verificacion.porcentajeCumplimiento || 0) >= 80 ? GREEN_HEADER : '#dc3545';
      doc.text(`Muestra Verificada: ${verificacion.muestraVerificada || 0}`, margin + 8, currentY);
      doc.text(`Porcentaje de Cumplimiento: `, margin + 200, currentY);
      doc.font('Helvetica-Bold').fillColor(cumplimientoColor);
      doc.text(`${verificacion.porcentajeCumplimiento || 0}%`, margin + 340, currentY);
      doc.font('Helvetica').fillColor('#000000');
      currentY += 22;
      
      // Section: CRITERIO DE MUESTREO
      doc.rect(margin, currentY, contentWidth, 18).fill(GREEN_HEADER);
      doc.fontSize(9).font('Helvetica-Bold').fillColor('#FFFFFF');
      doc.text('CRITERIO DE MUESTREO APLICADO (Resolución 0312 de 2019)', margin + 8, currentY + 4);
      doc.fillColor('#000000');
      currentY += 22;
      
      doc.fontSize(8).font('Helvetica');
      doc.text('• Hasta 50 trabajadores: 100% de la población', margin + 8, currentY);
      currentY += 12;
      doc.text('• De 51 a 200 trabajadores: 10% de la población', margin + 8, currentY);
      currentY += 12;
      doc.text('• Más de 200 trabajadores: 30 trabajadores fijos', margin + 8, currentY);
      currentY += 20;
      
      // Section: TRABAJADORES VERIFICADOS
      doc.rect(margin, currentY, contentWidth, 18).fill(GREEN_HEADER);
      doc.fontSize(9).font('Helvetica-Bold').fillColor('#FFFFFF');
      doc.text('TRABAJADORES VERIFICADOS EN LA MUESTRA', margin + 8, currentY + 4);
      doc.fillColor('#000000');
      currentY += 22;
      
      // Table dimensions
      const colWidths = [30, 140, 75, 100, 40, 40, 40, 40, 40];
      const tableWidth = colWidths.reduce((a, b) => a + b, 0);
      const startX = margin;
      
      // Table header
      doc.rect(startX, currentY, tableWidth, 18).fill('#e8e8e8').stroke('#cccccc');
      doc.fontSize(7).font('Helvetica-Bold').fillColor('#000000');
      
      let colX = startX + 3;
      doc.text('No.', colX, currentY + 5, { width: colWidths[0] - 6, align: 'center' });
      colX += colWidths[0];
      doc.text('Nombre del Trabajador', colX, currentY + 5, { width: colWidths[1] - 6 });
      colX += colWidths[1];
      doc.text('Identificación', colX, currentY + 5, { width: colWidths[2] - 6 });
      colX += colWidths[2];
      doc.text('Cargo', colX, currentY + 5, { width: colWidths[3] - 6 });
      colX += colWidths[3];
      doc.text('EPS', colX, currentY + 5, { width: colWidths[4] - 6, align: 'center' });
      colX += colWidths[4];
      doc.text('ARL', colX, currentY + 5, { width: colWidths[5] - 6, align: 'center' });
      colX += colWidths[5];
      doc.text('AFP', colX, currentY + 5, { width: colWidths[6] - 6, align: 'center' });
      colX += colWidths[6];
      doc.text('CCF', colX, currentY + 5, { width: colWidths[7] - 6, align: 'center' });
      colX += colWidths[7];
      doc.text('Cumple', colX, currentY + 5, { width: colWidths[8] - 6, align: 'center' });
      
      currentY += 18;
      
      // Table rows
      doc.font('Helvetica').fontSize(7);
      let rowNum = 1;
      for (const detalle of detallesConTrabajador) {
        if (currentY > doc.page.height - 100) {
          doc.addPage();
          currentY = 115;
        }
        
        const rowHeight = 16;
        const bgColor = rowNum % 2 === 0 ? '#f8f9fa' : '#ffffff';
        doc.rect(startX, currentY, tableWidth, rowHeight).fill(bgColor).stroke('#dddddd');
        
        colX = startX + 3;
        const workerName = detalle.worker?.name || 'N/A';
        const workerId = detalle.worker?.identificationNumber || 'N/A';
        const workerPosition = detalle.worker?.position || 'N/A';
        
        doc.fillColor('#000000');
        doc.text(String(rowNum), colX, currentY + 4, { width: colWidths[0] - 6, align: 'center' });
        colX += colWidths[0];
        doc.text(workerName.substring(0, 28), colX, currentY + 4, { width: colWidths[1] - 6 });
        colX += colWidths[1];
        doc.text(workerId, colX, currentY + 4, { width: colWidths[2] - 6 });
        colX += colWidths[2];
        doc.text(workerPosition.substring(0, 18), colX, currentY + 4, { width: colWidths[3] - 6 });
        colX += colWidths[3];
        
        // Checkmarks with color
        const checkColor = GREEN_HEADER;
        const xColor = '#dc3545';
        
        doc.fillColor(detalle.verificadoEps ? checkColor : xColor);
        doc.text(detalle.verificadoEps ? '✓' : '✗', colX, currentY + 4, { width: colWidths[4] - 6, align: 'center' });
        colX += colWidths[4];
        
        doc.fillColor(detalle.verificadoArl ? checkColor : xColor);
        doc.text(detalle.verificadoArl ? '✓' : '✗', colX, currentY + 4, { width: colWidths[5] - 6, align: 'center' });
        colX += colWidths[5];
        
        doc.fillColor(detalle.verificadoAfp ? checkColor : xColor);
        doc.text(detalle.verificadoAfp ? '✓' : '✗', colX, currentY + 4, { width: colWidths[6] - 6, align: 'center' });
        colX += colWidths[6];
        
        doc.fillColor(detalle.verificadoCcf ? checkColor : xColor);
        doc.text(detalle.verificadoCcf ? '✓' : '✗', colX, currentY + 4, { width: colWidths[7] - 6, align: 'center' });
        colX += colWidths[7];
        
        doc.font('Helvetica-Bold').fillColor(detalle.cumple ? checkColor : xColor);
        doc.text(detalle.cumple ? 'SÍ' : 'NO', colX, currentY + 4, { width: colWidths[8] - 6, align: 'center' });
        doc.font('Helvetica').fillColor('#000000');
        
        currentY += rowHeight;
        rowNum++;
      }
      
      // If no workers verified, show message
      if (detallesConTrabajador.length === 0) {
        doc.rect(startX, currentY, tableWidth, 24).fill('#fff3cd').stroke('#ffc107');
        doc.fontSize(9).font('Helvetica-Oblique').fillColor('#856404');
        doc.text('No se han registrado trabajadores verificados en esta muestra', startX + 10, currentY + 7);
        doc.fillColor('#000000');
        currentY += 28;
      }
      
      currentY += 10;
      
      // Section: RESUMEN DE CUMPLIMIENTO
      if (currentY > doc.page.height - 120) {
        doc.addPage();
        currentY = 115;
      }
      
      doc.rect(margin, currentY, contentWidth, 18).fill(GREEN_HEADER);
      doc.fontSize(9).font('Helvetica-Bold').fillColor('#FFFFFF');
      doc.text('RESUMEN DE CUMPLIMIENTO', margin + 8, currentY + 4);
      doc.fillColor('#000000');
      currentY += 22;
      
      const totalVerificados = detallesConTrabajador.length;
      const totalCumplen = detallesConTrabajador.filter(d => d.cumple).length;
      const totalNoCumplen = totalVerificados - totalCumplen;
      
      doc.fontSize(9).font('Helvetica');
      doc.text(`Total trabajadores en muestra: ${totalVerificados}`, margin + 8, currentY);
      currentY += 14;
      doc.fillColor(GREEN_HEADER);
      doc.text(`Trabajadores que cumplen (EPS + ARL + AFP): ${totalCumplen}`, margin + 8, currentY);
      currentY += 14;
      doc.fillColor('#dc3545');
      doc.text(`Trabajadores que no cumplen: ${totalNoCumplen}`, margin + 8, currentY);
      doc.fillColor('#000000');
      currentY += 20;
      
      // Observations
      if (verificacion.observaciones) {
        if (currentY > doc.page.height - 100) {
          doc.addPage();
          currentY = 115;
        }
        
        doc.rect(margin, currentY, contentWidth, 18).fill(GREEN_HEADER);
        doc.fontSize(9).font('Helvetica-Bold').fillColor('#FFFFFF');
        doc.text('OBSERVACIONES', margin + 8, currentY + 4);
        doc.fillColor('#000000');
        currentY += 22;
        
        doc.fontSize(9).font('Helvetica');
        doc.text(verificacion.observaciones, margin + 8, currentY, { width: contentWidth - 16 });
        currentY += doc.heightOfString(verificacion.observaciones, { width: contentWidth - 16 }) + 10;
      }
      
      // Generation info
      currentY += 8;
      doc.fontSize(7).font('Helvetica').fillColor('#888888');
      const generationDate = new Date().toLocaleDateString('es-CO', { day: '2-digit', month: 'long', year: 'numeric', hour: '2-digit', minute: '2-digit' });
      doc.text(`Documento generado automáticamente el: ${generationDate}`, margin, currentY, { width: contentWidth, align: 'center' });
      
      // Finalize PDF
      doc.end();
      
    } catch (error: any) {
      console.error('Error generating verification PDF:', error);
      res.status(500).send("Error al generar el PDF de verificación");
    }
  });


  // ===== TRABAJADORES DE ALTO RIESGO ROUTES =====
