        const inspections = await storage.getInspections(effectiveCompanyId);
        
        // Filter by period
        const filterByPeriod = (items: any[], dateField: string) => {
          const now = new Date();
          const currentMonth = now.getMonth();
          const currentYear = now.getFullYear();
          
          return items.filter(item => {
            const itemDate = new Date(item[dateField]);
            const itemMonth = itemDate.getMonth();
            const itemYear = itemDate.getFullYear();
            
            switch (period) {
              case 'mes-actual':
                return itemMonth === currentMonth && itemYear === currentYear;
              case 'mes-anterior':
                const prevMonth = currentMonth === 0 ? 11 : currentMonth - 1;
                const prevYear = currentMonth === 0 ? currentYear - 1 : currentYear;
                return itemMonth === prevMonth && itemYear === prevYear;
              case 'trimestre':
                const quarterStart = new Date(currentYear, Math.floor(currentMonth / 3) * 3, 1);
                return itemDate >= quarterStart && itemDate <= now;
              case 'semestre':
                const semesterStart = new Date(currentYear, currentMonth < 6 ? 0 : 6, 1);
                return itemDate >= semesterStart && itemDate <= now;
              case 'anio':
                return itemYear === currentYear;
              default:
                return true;
            }
          });
        };
        
        const filteredInspections = filterByPeriod(inspections, 'date');
        
