  app.get("/api/hazardous-substances-inventory/pdf", requirePermission("inspections:view"), async (req, res) => {
    try {
      const user = (req as any).user;
      const substances = await storage.getHazardousSubstances(user.companyId);
      const company = await storage.getCompany(user.companyId);

      const { default: PDFDocument } = await import('pdfkit');
      const doc = new PDFDocument({ margin: 35, size: 'LETTER' });
      
      // Add trial watermark if subscription is in trial period
      const pdf18615_subscription = await storage.getSubscriptionByCompany(companyId);
      const pdf18615_trialStatus = getTrialStatus(pdf18615_subscription?.status || 'trial', pdf18615_subscription?.trialEnd || null, true, true);
      setupTrialWatermarkOnAllPages(doc, pdf18615_trialStatus.requiresWatermark);
      const margin = 35;
      const pageWidth = doc.page.width;

      res.setHeader('Content-Type', 'application/pdf');
      res.setHeader('Content-Disposition', `inline; filename="Inventario-Sustancias-Quimicas-${company?.name?.replace(/\s+/g, '-') || 'Empresa'}.pdf"`);

      doc.pipe(res);

      // Preload company logo and worker photo from Object Storage
      const logoBuffer = await loadCompanyLogoBuffer(company?.logoUrl);

      // Standard Header with logo, version control, and signatures
      let currentY = setupPdfHeadersFooters({
        doc,
        company: company || { name: 'Empresa', nit: 'N/A', address: null, logoUrl: null },
        documentTitle: 'INVENTARIO DE SUSTANCIAS QUÍMICAS PELIGROSAS',
        documentCode: `SST-SQP-${new Date().getFullYear()}-001`,
        version: '1.0',
        date: new Date(),
        elaboro: 'Responsable Químicos',
        autorizo: req.user?.username || 'Sistema',
        aprobo: 'Coordinador SST'
      });

      // Summary section
      doc.fontSize(9).font('Helvetica-Bold').fillColor('#2d5016').text('RESUMEN DEL INVENTARIO', { underline: true });
      currentY = doc.y + 10;

      const totalSubstances = substances.length;
      const activeSubstances = substances.filter(s => s.isActive === 1).length;
      
      // Count by hazard class
      const hazardCounts: Record<string, number> = {};
      substances.forEach(s => {
        s.hazardClass.forEach(hc => {
          hazardCounts[hc] = (hazardCounts[hc] || 0) + 1;
        });
      });

      doc.fontSize(8).font('Helvetica-Bold').fillColor('#000000').text('Total de sustancias registradas: ', margin, currentY, { continued: true });
      doc.font('Helvetica').text(`${totalSubstances}`);
      
      doc.font('Helvetica-Bold').text('Sustancias activas: ', margin, doc.y + 3, { continued: true });
      doc.font('Helvetica').text(`${activeSubstances}`);
      
      doc.font('Helvetica-Bold').text('Sustancias descontinuadas: ', margin, doc.y + 3, { continued: true });
      doc.font('Helvetica').text(`${totalSubstances - activeSubstances}`);
      
      currentY = doc.y + 15;

      // Substances list
      doc.fontSize(9).font('Helvetica-Bold').fillColor('#2d5016').text('DETALLE DE SUSTANCIAS', { underline: true });
      currentY = doc.y + 10;

      if (substances.length === 0) {
        doc.fontSize(8).font('Helvetica-Oblique').fillColor('#666666').text('No hay sustancias químicas registradas.', margin, currentY);
      } else {
        const hazardClassLabels: Record<string, string> = {
          "cancerígena": "Cancerígena", "toxicidad_aguda": "Toxicidad Aguda", "corrosiva": "Corrosiva",
          "inflamable": "Inflamable", "explosiva": "Explosiva", "oxidante": "Oxidante",
          "irritante": "Irritante", "sensibilizante": "Sensibilizante", "mutagena": "Mutagénica",
          "teratogenica": "Teratogénica",
        };

        substances.forEach((substance, index) => {
          // Check if we need a new page
          if (currentY > doc.page.height - 100) {
            doc.addPage();
            currentY = 115;
          }

          // Substance header
          doc.fontSize(9).font('Helvetica-Bold').fillColor('#2d5016').text(`${index + 1}. ${substance.commercialName}`, margin, currentY);
          if (!substance.isActive) {
            doc.fontSize(9).fillColor('#ef4444').text(' (DESCONTINUADA)', { continued: true });
          }
          currentY = doc.y + 5;

          // Chemical details
          if (substance.chemicalName) {
            doc.fontSize(9).font('Helvetica-Bold').fillColor('#000000').text('Nombre Químico: ', margin + 10, currentY, { continued: true });
            doc.font('Helvetica').text(substance.chemicalName);
            currentY = doc.y + 3;
          }

          if (substance.casNumber) {
            doc.fontSize(9).font('Helvetica-Bold').text('Número CAS: ', margin + 10, currentY, { continued: true });
            doc.font('Helvetica').text(substance.casNumber);
            currentY = doc.y + 3;
          }

          // Hazard classifications
          doc.fontSize(9).font('Helvetica-Bold').text('Clasificación de Peligro: ', margin + 10, currentY);
          currentY = doc.y + 8;
          const classifications = substance.hazardClass.map(hc => hazardClassLabels[hc] || hc).join(', ');
          doc.fontSize(7).font('Helvetica').text(classifications, margin + 10, currentY, { width: pageWidth - margin - 20, align: 'justify' });
          currentY = doc.y + 3;

          // Storage location
          doc.fontSize(9).font('Helvetica-Bold').text('Ubicación: ', margin + 10, currentY, { continued: true });
          doc.font('Helvetica').text(substance.storageLocation);
          currentY = doc.y + 3;

          // Quantity
          if (substance.quantity) {
            doc.fontSize(9).font('Helvetica-Bold').text('Cantidad: ', margin + 10, currentY, { continued: true });
            doc.font('Helvetica').text(`${substance.quantity} ${substance.unit || ''}`);
            currentY = doc.y + 3;
          }

          // Usage area
          if (substance.usageArea) {
            doc.fontSize(9).font('Helvetica-Bold').text('Área de uso: ', margin + 10, currentY, { continued: true });
            doc.font('Helvetica').text(substance.usageArea);
            currentY = doc.y + 3;
          }

          // Supplier
          if (substance.supplier) {
            doc.fontSize(9).font('Helvetica-Bold').text('Proveedor: ', margin + 10, currentY, { continued: true });
            doc.font('Helvetica').text(substance.supplier);
            currentY = doc.y + 3;
          }

          // Emergency phone
          if (substance.emergencyPhone) {
            doc.fontSize(9).font('Helvetica-Bold').text('Teléfono de emergencia: ', margin + 10, currentY, { continued: true });
            doc.font('Helvetica').text(substance.emergencyPhone);
            currentY = doc.y + 3;
          }

          // Control measures
          if (substance.controlMeasures) {
            doc.fontSize(9).font('Helvetica-Bold').text('Medidas de control: ', margin + 10, currentY);
            currentY = doc.y + 8;
            doc.fontSize(7).font('Helvetica').text(substance.controlMeasures, margin + 10, currentY, { width: pageWidth - margin - 20, align: 'justify' });
            currentY = doc.y + 3;
          }

          // Required PPE
          if (substance.requiredPpe) {
            doc.fontSize(9).font('Helvetica-Bold').text('EPP requerido: ', margin + 10, currentY);
            currentY = doc.y + 8;
            doc.fontSize(7).font('Helvetica').text(substance.requiredPpe, margin + 10, currentY, { width: pageWidth - margin - 20, align: 'justify' });
            currentY = doc.y + 3;
          }

          // SDS information
          if (substance.sdsUrl) {
            doc.fontSize(9).font('Helvetica-Bold').text('Ficha de seguridad: ', margin + 10, currentY, { continued: true });
            doc.font('Helvetica').fillColor('#0066cc').text(substance.sdsUrl, { link: substance.sdsUrl, underline: true });
            doc.fillColor('#000000');
            currentY = doc.y + 3;
          }

          // Observations
          if (substance.observations) {
            doc.fontSize(9).font('Helvetica-Bold').text('Observaciones: ', margin + 10, currentY);
            currentY = doc.y + 8;
            doc.fontSize(7).font('Helvetica').text(substance.observations, margin + 10, currentY, { width: pageWidth - margin - 20, align: 'justify' });
            currentY = doc.y + 3;
          }

          // Separator line
          doc.strokeColor('#cccccc').lineWidth(0.5).moveTo(margin, currentY + 5).lineTo(pageWidth - margin, currentY + 5).stroke();
          currentY = doc.y + 15;
        });
      }

      // Footer on all pages
      const pageCount = doc.bufferedPageRange().count;
      for (let i = 0; i < pageCount; i++) {
        doc.switchToPage(i);
        const footerY = doc.page.height - 40;
        doc.fontSize(7).font('Helvetica').fillColor('#666666').text(
          `Página ${i + 1} de ${pageCount} | Generado el ${new Date().toLocaleDateString('es-CO')} | ${company?.name || ''}`,
          margin, footerY, { width: pageWidth - 2 * margin, align: 'center' }
        );
      }

      doc.end();
    } catch (error: any) {
      console.error('Error generating hazardous substances inventory PDF:', error);
      if (!res.headersSent) {
        res.status(500).send(error.message);
      }
    }
  });

  // Generate PDF report for environmental measurement
  app.get("/api/environmental-measurements/:id/pdf", requireAuth, async (req, res) => {
    try {
      const user = (req as any).user;
      const measurement = await storage.getEnvironmentalMeasurement(req.params.id, user.companyId);
      
      if (!measurement) {
        return res.status(404).send("Medición no encontrada");
      }

      const company = await storage.getCompany(user.companyId);
      if (!company) {
        return res.status(404).send("Empresa no encontrada");
      }

      const { default: PDFDocument } = await import('pdfkit');
      const doc = new PDFDocument({ margin: 35, size: 'LETTER' });
      
      // Add trial watermark if subscription is in trial period
      const pdf18821_subscription = await storage.getSubscriptionByCompany(companyId);
      const pdf18821_trialStatus = getTrialStatus(pdf18821_subscription?.status || 'trial', pdf18821_subscription?.trialEnd || null, true, true);
      setupTrialWatermarkOnAllPages(doc, pdf18821_trialStatus.requiresWatermark);
      const margin = 35;
      const pageWidth = doc.page.width;

      const measurementTypeLabels: Record<string, string> = {
        "ruido": "Ruido",
        "iluminacion": "Iluminación",
        "temperatura": "Temperatura",
        "agente_quimico": "Agente Químico",
        "material_particulado": "Material Particulado",
        "vibraciones": "Vibraciones",
      };

      const statusLabels: Record<string, string> = {
        "conforme": "Conforme",
        "no_conforme": "No Conforme",
        "pendiente_analisis": "Pendiente de Análisis",
      };

      const statusColors: Record<string, string> = {
        "conforme": "#22c55e",
        "no_conforme": "#ef4444",
        "pendiente_analisis": "#f59e0b",
      };

      const measurementDate = String(measurement.measurementDate);

      res.setHeader('Content-Type', 'application/pdf');
      res.setHeader('Content-Disposition', `inline; filename="Medicion-Ambiental-${measurement.area.replace(/\s+/g, '-')}-${measurementDate}.pdf"`);

      doc.pipe(res);

      // Preload company logo and worker photo from Object Storage
      const logoBuffer = await loadCompanyLogoBuffer(company.logoUrl);
      // Worker photo not needed for muestreo PDF

      // Standard Header with logo, version control, and signatures
      let currentY = setupPdfHeadersFooters({
        doc,
        company,
        documentTitle: 'INFORME DE MEDICIÓN AMBIENTAL OCUPACIONAL',
        documentCode: `SST-MA-${new Date(measurement.measurementDate).getFullYear()}-${String(Math.floor(Math.random() * 1000)).padStart(3, '0')}`,
        version: '1.0',
        date: new Date(measurement.measurementDate),
        elaboro: measurement.measuredBy || 'Técnico Ambiental',
        autorizo: req.user?.username || 'Sistema',
        aprobo: 'Coordinador SST'
      });

      doc.y = currentY;

      // Measurement Type and Status
      doc.fontSize(9).fillColor('#166534').text(`Tipo de Medición: ${measurementTypeLabels[measurement.measurementType] || measurement.measurementType}`, { continued: false });
      doc.moveDown(0.5);
      
      const statusColor = statusColors[measurement.status] || '#666666';
      doc.fontSize(9).fillColor(statusColor).text(`Estado: ${statusLabels[measurement.status] || measurement.status}`, { continued: false });
      doc.moveDown(1);

      // Measurement Details
      doc.fontSize(9).fillColor('#000000');
      
      const details: Array<{ label: string; value: string }> = [
        { label: 'Área de Medición', value: measurement.area },
        { label: 'Fecha de Medición', value: measurementDate },
        { label: 'Medido por', value: measurement.measuredBy || 'No especificado' },
      ];

      // Add value and limit only if they exist
      if (measurement.valueNumeric && measurement.unit) {
        details.push({ label: 'Valor Medido', value: `${measurement.valueNumeric} ${measurement.unit}` });
      }
      if (measurement.legalLimit && measurement.unit) {
        details.push({ label: 'Límite Legal', value: `${measurement.legalLimit} ${measurement.unit}` });
      }

      details.forEach(({ label, value }) => {
        doc.fontSize(8).fillColor('#666666').text(label + ':', { continued: true });
        doc.fontSize(9).fillColor('#000000').text(' ' + value);
        doc.moveDown(0.3);
      });

      doc.moveDown(1);

      // Analysis Section
      doc.fontSize(9).fillColor('#166534').text('ANÁLISIS DE CONFORMIDAD', { underline: true });
      doc.moveDown(0.5);
      
      doc.fontSize(8).fillColor('#000000');
      if (measurement.status === 'conforme' && measurement.valueNumeric && measurement.legalLimit && measurement.unit) {
        doc.text(`La medición se encuentra CONFORME con los límites legales establecidos. El valor medido (${measurement.valueNumeric} ${measurement.unit}) es menor o igual al límite legal permitido (${measurement.legalLimit} ${measurement.unit}).`);
      } else if (measurement.status === 'no_conforme' && measurement.valueNumeric && measurement.legalLimit && measurement.unit) {
        doc.fillColor('#ef4444').text(`⚠️ ALERTA: La medición se encuentra NO CONFORME con los límites legales. El valor medido (${measurement.valueNumeric} ${measurement.unit}) supera el límite legal permitido (${measurement.legalLimit} ${measurement.unit}).`);
        doc.fillColor('#000000').moveDown(0.5);
        doc.text('Se requiere implementar acciones correctivas inmediatas para garantizar la seguridad y salud de los trabajadores.');
      } else if (measurement.status === 'conforme') {
        doc.text('La medición se encuentra CONFORME con los límites legales establecidos.');
      } else if (measurement.status === 'no_conforme') {
        doc.fillColor('#ef4444').text('⚠️ ALERTA: La medición se encuentra NO CONFORME con los límites legales.');
        doc.fillColor('#000000').moveDown(0.5);
        doc.text('Se requiere implementar acciones correctivas inmediatas para garantizar la seguridad y salud de los trabajadores.');
      } else {
        doc.text('Esta medición se encuentra pendiente de análisis por parte del equipo técnico.');
      }

      doc.moveDown(1);

      // Observations
      if (measurement.observations) {
        doc.fontSize(9).fillColor('#166534').text('OBSERVACIONES', { underline: true });
        doc.moveDown(0.5);
        doc.fontSize(8).fillColor('#000000').text(measurement.observations);
        doc.moveDown(1);
      }

      // Footer with regulatory info
      doc.moveDown(2);
      doc.strokeColor('#cccccc').lineWidth(1).moveTo(50, doc.y).lineTo(562, doc.y).stroke();
      doc.moveDown(0.5);
      doc.fontSize(8).fillColor('#666666').text(
        'Este informe se genera en cumplimiento de la Resolución 0312 de 2019 del Ministerio del Trabajo\n' +
        'Sistema de Gestión de Seguridad y Salud en el Trabajo (SG-SST)',
        { align: 'center' }
      );
      doc.moveDown(0.3);
      doc.text(`Fecha de generación: ${new Date().toLocaleDateString('es-CO', { year: 'numeric', month: 'long', day: 'numeric' })}`, { align: 'center' });

      doc.end();
    } catch (error: any) {
      console.error('Error generating PDF:', error);
      res.status(500).send(error.message);
    }
  });

