  // Training Program PDF Generation
  app.get("/api/training-programs/:id/pdf", requirePermission("trainings:view"), async (req, res) => {
    try {
      if (!req.user!.companyId) {
        return res.status(403).send("Esta operación requiere pertenecer a una empresa");
      }
      const companyId = req.user!.companyId;
      const PDFDocument = (await import("pdfkit")).default;
      
      // Get program with all related data
      const program = await storage.getTrainingProgram(req.params.id, companyId);
      if (!program) {
        return res.status(404).send("Programa de capacitación no encontrado");
      }

      // Get all trainings for this program
      const trainings = await storage.getProgramTrainings(req.params.id, companyId);

      // Get company for branding
      const company = await storage.getCompany(companyId);

      // Load company logo for PDF header
      const logoBuffer = await loadCompanyLogoBuffer(company?.logoUrl);

      const doc = new PDFDocument({ margin: 35, size: 'LETTER' });
      
      // Add trial watermark if subscription is in trial period
      const pdf19254_subscription = await storage.getSubscriptionByCompany(companyId);
      const pdf19254_trialStatus = getTrialStatus(pdf19254_subscription?.status || 'trial', pdf19254_subscription?.trialEnd || null, true, true);
      setupTrialWatermarkOnAllPages(doc, pdf19254_trialStatus.requiresWatermark);
      const margin = 35;
      res.setHeader('Content-Type', 'application/pdf');
      res.setHeader('Content-Disposition', 'inline; filename="programa-capacitacion.pdf"');
      doc.pipe(res);

      
      // Standard Header with logo, version control, and signatures
      let currentY = setupPdfHeadersFooters({
        doc,
        company: company || { name: 'Empresa', nit: 'N/A', address: null, logoUrl: null },
        logoBuffer,
        documentTitle: `PROGRAMA DE CAPACITACIÓN Y ENTRENAMIENTO SST - AÑO ${program.year}`,
        documentCode: `SST-CAP-${program.year}`,
        version: '1.0',
        date: new Date(),
        elaboro: program.responsible || 'Responsable SST',
        autorizo: req.user?.username || 'Sistema',
        aprobo: 'Gerencia'
      });

      doc.y = currentY;
      const pageWidth = 612 - (margin * 2);

      // Program information section - use structured box
      const boxPadding = 10;
      const boxStartY = doc.y;
      doc.rect(margin, boxStartY, pageWidth, 70)
        .fillAndStroke('#f8fafc', '#e2e8f0');
      
      doc.y = boxStartY + boxPadding;
      doc.x = margin + boxPadding;
      
      doc.fontSize(10).fillColor('#166534').text('1. INFORMACIÓN GENERAL DEL PROGRAMA', margin + boxPadding);
      doc.moveDown(0.3);
      
      doc.fontSize(8).fillColor('#000000');
      doc.text(`Año: ${program.year}`, margin + boxPadding + 10);
      doc.text(`Título: ${program.title}`, margin + boxPadding + 10);
      doc.text(`Responsable: ${program.responsible || 'Por asignar'}`, margin + boxPadding + 10);
      
      doc.y = boxStartY + 75;

      // Objective and Scope section
      if (program.generalObjective || program.scope) {
        doc.moveDown(0.3);
        doc.fontSize(10).fillColor('#166534').text('2. OBJETIVO Y ALCANCE', margin);
        doc.moveDown(0.3);
        
        if (program.generalObjective) {
          doc.fontSize(8).fillColor('#333333').text('Objetivo General:', margin, doc.y, { continued: true });
          doc.fillColor('#000000').text(` ${program.generalObjective}`, { width: pageWidth - 10 });
        }
        
        if (program.scope) {
          doc.moveDown(0.2);
          doc.fontSize(8).fillColor('#333333').text('Alcance:', margin, doc.y, { continued: true });
          doc.fillColor('#000000').text(` ${program.scope}`, { width: pageWidth - 10 });
        }
        doc.moveDown(0.5);
      }

      // Summary statistics box
      doc.fontSize(10).fillColor('#166534').text('3. RESUMEN DE CUMPLIMIENTO', margin);
      doc.moveDown(0.3);
      
      const completedTrainings = trainings.filter(t => t.status === 'completada').length;
      const pendingTrainings = trainings.filter(t => t.status === 'programada').length;
      const inProgressTrainings = trainings.filter(t => t.status === 'en_curso').length;
      const completionRate = trainings.length > 0 
        ? Math.round((completedTrainings / trainings.length) * 100) 
        : 0;

      // Summary table
      const summaryStartY = doc.y;
      const colWidth = pageWidth / 4;
      const summaryHeight = 35;
      
      // Header row
      doc.rect(margin, summaryStartY, pageWidth, 15).fill('#166534');
      doc.fontSize(8).fillColor('#ffffff');
      doc.text('Total Programadas', margin + 5, summaryStartY + 4, { width: colWidth - 10, align: 'center' });
      doc.text('Completadas', margin + colWidth + 5, summaryStartY + 4, { width: colWidth - 10, align: 'center' });
      doc.text('En Progreso', margin + colWidth * 2 + 5, summaryStartY + 4, { width: colWidth - 10, align: 'center' });
      doc.text('% Cumplimiento', margin + colWidth * 3 + 5, summaryStartY + 4, { width: colWidth - 10, align: 'center' });
      
      // Data row
      doc.rect(margin, summaryStartY + 15, pageWidth, 20).fillAndStroke('#f8fafc', '#e2e8f0');
      doc.fontSize(10).fillColor('#000000');
      doc.text(String(trainings.length), margin + 5, summaryStartY + 20, { width: colWidth - 10, align: 'center' });
      doc.text(String(completedTrainings), margin + colWidth + 5, summaryStartY + 20, { width: colWidth - 10, align: 'center' });
      doc.text(String(inProgressTrainings), margin + colWidth * 2 + 5, summaryStartY + 20, { width: colWidth - 10, align: 'center' });
      doc.fillColor(completionRate >= 80 ? '#166534' : completionRate >= 50 ? '#ca8a04' : '#dc2626');
      doc.text(`${completionRate}%`, margin + colWidth * 3 + 5, summaryStartY + 20, { width: colWidth - 10, align: 'center' });
      
      doc.y = summaryStartY + summaryHeight + 10;

      // Trainings table header
      doc.fontSize(10).fillColor('#166534').text('4. CRONOGRAMA DE CAPACITACIONES', margin);
      doc.moveDown(0.3);

      if (trainings.length > 0) {
        // Table header
        const tableStartY = doc.y;
        const cols = [25, 140, 80, 80, 80, 55, 82];
        const headerHeight = 20;
        
        doc.rect(margin, tableStartY, pageWidth, headerHeight).fill('#166534');
        doc.fontSize(7).fillColor('#ffffff');
        let xPos = margin;
        ['#', 'Tema', 'Fecha', 'Duración', 'Instructor', 'Categoría', 'Estado'].forEach((header, i) => {
          doc.text(header, xPos + 3, tableStartY + 6, { width: cols[i] - 6, align: 'center' });
          xPos += cols[i];
        });
        
        doc.y = tableStartY + headerHeight;

        // Sort trainings by date
        const sortedTrainings = [...trainings].sort((a, b) => {
          if (!a.scheduledDate && !b.scheduledDate) return 0;
          if (!a.scheduledDate) return 1;
          if (!b.scheduledDate) return -1;
          return new Date(a.scheduledDate).getTime() - new Date(b.scheduledDate).getTime();
        });

        sortedTrainings.forEach((training, index) => {
          const rowHeight = 22;
          
          // Check if we need a new page
          if (doc.y + rowHeight > 720) {
            doc.addPage();
            doc.y = margin;
            // Redraw header on new page
            doc.rect(margin, doc.y, pageWidth, headerHeight).fill('#166534');
            doc.fontSize(7).fillColor('#ffffff');
            let xPos = margin;
            ['#', 'Tema', 'Fecha', 'Duración', 'Instructor', 'Categoría', 'Estado'].forEach((header, i) => {
              doc.text(header, xPos + 3, doc.y + 6, { width: cols[i] - 6, align: 'center' });
              xPos += cols[i];
            });
            doc.y += headerHeight;
          }

          const rowY = doc.y;
          const bgColor = index % 2 === 0 ? '#ffffff' : '#f8fafc';
          doc.rect(margin, rowY, pageWidth, rowHeight).fillAndStroke(bgColor, '#e2e8f0');
          
          doc.fontSize(7).fillColor('#000000');
          xPos = margin;
          
          // Row number
          doc.text(String(index + 1), xPos + 3, rowY + 7, { width: cols[0] - 6, align: 'center' });
          xPos += cols[0];
          
          // Topic (truncate if too long)
          const topic = training.topic.length > 30 ? training.topic.substring(0, 27) + '...' : training.topic;
          doc.text(topic, xPos + 3, rowY + 7, { width: cols[1] - 6 });
          xPos += cols[1];
          
          // Date
          const dateStr = training.scheduledDate 
            ? new Date(training.scheduledDate).toLocaleDateString('es-CO', { day: '2-digit', month: 'short', year: 'numeric' })
            : 'Por definir';
          doc.text(dateStr, xPos + 3, rowY + 7, { width: cols[2] - 6, align: 'center' });
          xPos += cols[2];
          
          // Duration
          doc.text(training.duration ? `${training.duration}h` : '-', xPos + 3, rowY + 7, { width: cols[3] - 6, align: 'center' });
          xPos += cols[3];
          
          // Instructor
          const instructor = (training.instructor && training.instructor.length > 15) 
            ? training.instructor.substring(0, 12) + '...' 
            : (training.instructor || '-');
          doc.text(instructor, xPos + 3, rowY + 7, { width: cols[4] - 6, align: 'center' });
          xPos += cols[4];
          
          // Category
          const category = (training.trainingCategory && training.trainingCategory.length > 10) 
            ? training.trainingCategory.substring(0, 8) + '...' 
            : (training.trainingCategory || '-');
          doc.text(category, xPos + 3, rowY + 7, { width: cols[5] - 6, align: 'center' });
          xPos += cols[5];
          
          // Status with color
          const statusConfig: Record<string, { text: string; color: string }> = {
            'completada': { text: 'Completada', color: '#166534' },
            'en_curso': { text: 'En Progreso', color: '#ca8a04' },
            'cancelada': { text: 'Cancelada', color: '#dc2626' },
            'reprogramada': { text: 'Reprogramada', color: '#7c3aed' },
            'programada': { text: 'Programada', color: '#2563eb' }
          };
          const status = statusConfig[training.status] || statusConfig['programada'];
          doc.fillColor(status.color).text(status.text, xPos + 3, rowY + 7, { width: cols[6] - 6, align: 'center' });
          
          doc.y = rowY + rowHeight;
        });
      } else {
        doc.fontSize(8).fillColor('#666666').text('No hay capacitaciones programadas para este año.', margin);
      }

      // Regulatory footer
      doc.moveDown(0.2);
      if (doc.y > 700) {
        doc.addPage();
      }
      
      doc.strokeColor('#cccccc').lineWidth(1).moveTo(50, doc.y).lineTo(562, doc.y).stroke();
      doc.moveDown(0.2);
      doc.fontSize(8).fillColor('#666666').text(
        'Este programa se elabora en cumplimiento del Decreto 1072 de 2015 (Artículos 2.2.4.6.8 y 2.2.4.6.11)\n' +
        'y la Resolución 0312 de 2019 del Ministerio del Trabajo.\n' +
        'Sistema de Gestión de Seguridad y Salud en el Trabajo (SG-SST)',
        { align: 'center' }
      );
      doc.moveDown(0.1);
      doc.text(
        `Fecha de generación: ${new Date().toLocaleDateString('es-CO', { year: 'numeric', month: 'long', day: 'numeric' })}`,
        { align: 'center' }
      );

      doc.end();
    } catch (error: any) {
      console.error('Error generating PDF:', error);
      res.status(500).send(error.message);
    }
  });

