  // Generate PDF report for SVE program
  app.get("/api/sve-programs/:id/pdf", requirePermission("trainings:view"), async (req, res) => {
    try {
      if (!req.user!.companyId) {
        return res.status(403).send("Esta operación requiere pertenecer a una empresa");
      }
      const companyId = req.user!.companyId;
      const programId = req.params.id;

      const program = await storage.getSveProgram(programId, companyId);
      if (!program) {
        return res.status(404).send("Programa SVE no encontrado");
      }

      const cases = await storage.getSveCases(companyId, programId);
      const company = await storage.getCompany(companyId);

      // Preload company logo and worker photo from Object Storage
      const logoBuffer = await loadCompanyLogoBuffer(company?.logoUrl);

      const { default: PDFDocument } = await import('pdfkit');
      const doc = new PDFDocument({ margin: 35, size: 'LETTER' });
      
      // Add trial watermark if subscription is in trial period
      const pdf19712_subscription = await storage.getSubscriptionByCompany(companyId);
      const pdf19712_trialStatus = getTrialStatus(pdf19712_subscription?.status || 'trial', pdf19712_subscription?.trialEnd || null, true, true);
      setupTrialWatermarkOnAllPages(doc, pdf19712_trialStatus.requiresWatermark);
      const margin = 35;
      const pageWidth = doc.page.width;

      res.setHeader('Content-Type', 'application/pdf');
      res.setHeader('Content-Disposition', `inline; filename="Programa-SVE-${program.name.replace(/\s+/g, '-')}.pdf"`);

      doc.pipe(res);

      
      // Standard Header with logo, version control, and signatures
      let currentY = setupPdfHeadersFooters({
        doc,
        company: company || { name: 'Empresa', nit: 'N/A', address: null, logoUrl: null },
        documentTitle: 'SISTEMA DE VIGILANCIA EPIDEMIOLÓGICA OCUPACIONAL',
        documentCode: `SST-SVE-${new Date().getFullYear()}-${String(Math.floor(Math.random() * 1000)).padStart(3, '0')}`,
        version: '1.0',
        date: new Date(program.startDate || new Date()),
        elaboro: program.responsibleName || 'Responsable SVE',
        autorizo: req.user?.username || 'Sistema',
        aprobo: 'Coordinador SST'
      });

      doc.fontSize(9).font('Helvetica-Bold').fillColor('#2d5016').text(program.name, margin, currentY, { width: pageWidth - 2 * margin, align: 'left' });
      currentY = doc.y + 4;

      const riskTypeLabels: Record<string, string> = {
        "biomecanico": "Biomecánico", "psicosocial": "Psicosocial", "auditivo": "Auditivo", "quimico": "Químico",
        "biologico": "Biológico", "visual": "Visual", "cardiovascular": "Cardiovascular", "respiratorio": "Respiratorio",
      };

      doc.fontSize(7).font('Helvetica-Bold').fillColor('#000000').text('Tipo de Riesgo: ', { continued: true });
      doc.font('Helvetica').text(riskTypeLabels[program.riskType] || program.riskType);
      currentY = doc.y + 1;

      const statusLabels: Record<string, string> = { "activo": "Activo", "inactivo": "Inactivo", "en_revision": "En Revisión" };
      doc.fontSize(7).font('Helvetica-Bold').text('Estado: ', { continued: true });
      doc.font('Helvetica').text(statusLabels[program.status] || program.status);
      currentY = doc.y + 6;

      doc.fontSize(9).font('Helvetica-Bold').fillColor('#2d5016').text('DETALLES DEL PROGRAMA', { underline: true });
      currentY = doc.y + 4;

      doc.fontSize(8).font('Helvetica-Bold').fillColor('#000000').text('Objetivo:', margin, currentY);
      currentY = doc.y + 1;
      doc.fontSize(7).font('Helvetica').text(program.objective || 'No especificado', margin, currentY, { width: pageWidth - 2 * margin, align: 'justify' });
      currentY = doc.y + 4;

      doc.fontSize(8).font('Helvetica-Bold').text('Población Objetivo:', margin, currentY);
      currentY = doc.y + 1;
      doc.fontSize(7).font('Helvetica').text(program.targetPopulation || 'No especificado', margin, currentY, { width: pageWidth - 2 * margin, align: 'justify' });
      currentY = doc.y + 4;

      if (program.protocol) {
        doc.fontSize(8).font('Helvetica-Bold').text('Protocolo:', margin, currentY);
        currentY = doc.y + 1;
        doc.fontSize(7).font('Helvetica').text(program.protocol, margin, currentY, { width: pageWidth - 2 * margin, align: 'justify' });
        currentY = doc.y + 4;
      }

      doc.fontSize(8).font('Helvetica-Bold').text('Responsable: ', { continued: true });
      doc.font('Helvetica').text(`${program.responsibleName || 'No especificado'} - ${program.responsiblePosition || ''}`);
      currentY = doc.y + 1;

      doc.fontSize(8).font('Helvetica-Bold').text('Fecha de Inicio: ', { continued: true });
      doc.font('Helvetica').text(program.startDate ? new Date(program.startDate).toLocaleDateString('es-CO') : 'No especificado');
      
      if (program.reviewDate) {
        doc.fontSize(8).font('Helvetica-Bold').text('Fecha de Revisión: ', { continued: true });
        doc.font('Helvetica').text(new Date(program.reviewDate).toLocaleDateString('es-CO'));
      }
      currentY = doc.y + 8;

      doc.fontSize(9).font('Helvetica-Bold').fillColor('#2d5016').text('CASOS REGISTRADOS', { underline: true });
      currentY = doc.y + 4;

      if (cases.length === 0) {
        doc.fontSize(8).font('Helvetica-Oblique').fillColor('#666666').text('No hay casos registrados para este programa.', margin, currentY);
      } else {
        doc.fontSize(8).font('Helvetica-Bold').fillColor('#000000').text(`Total de casos: ${cases.length}`, margin, currentY);
        currentY = doc.y + 4;

        const sortedCases = [...cases].sort((a, b) => new Date(b.evaluationDate).getTime() - new Date(a.evaluationDate).getTime());
        const classificationLabels: Record<string, string> = { "normal": "Normal", "vigilancia": "Vigilancia", "caso_confirmado": "Caso Confirmado", "caso_cerrado": "Caso Cerrado" };
        const evaluationTypeLabels: Record<string, string> = { "medica": "Médica", "higienica": "Higiénica", "seguimiento": "Seguimiento", "inicial": "Inicial" };

        sortedCases.forEach((caseItem, index) => {
          if (currentY > doc.page.height - 80) {
            doc.addPage();
            currentY = 115;
          }

          doc.fontSize(8).font('Helvetica-Bold').fillColor('#2d5016').text(`Caso ${index + 1}:`, margin, currentY);
          currentY = doc.y + 1;

          doc.fontSize(7).font('Helvetica-Bold').fillColor('#000000').text('ID Trabajador: ', margin + 10, currentY, { continued: true });
          doc.font('Helvetica').text(caseItem.workerId);

          doc.font('Helvetica-Bold').text('Fecha: ', margin + 200, currentY, { continued: true });
          doc.font('Helvetica').text(new Date(caseItem.evaluationDate).toLocaleDateString('es-CO'));
          currentY = doc.y + 1;

          doc.font('Helvetica-Bold').text('Tipo Evaluación: ', margin + 10, currentY, { continued: true });
          doc.font('Helvetica').text(evaluationTypeLabels[caseItem.evaluationType as keyof typeof evaluationTypeLabels] || caseItem.evaluationType);

          doc.font('Helvetica-Bold').text('Clasificación: ', margin + 200, currentY, { continued: true });
          doc.font('Helvetica').text(classificationLabels[caseItem.classification] || caseItem.classification);
          currentY = doc.y + 1;

          doc.font('Helvetica-Bold').text('Evaluado por: ', margin + 10, currentY, { continued: true });
          doc.font('Helvetica').text(caseItem.evaluatedBy);
          currentY = doc.y + 1;

          if (caseItem.findings) {
            doc.fontSize(7).font('Helvetica-Bold').text('Hallazgos: ', margin + 10, currentY);
            currentY = doc.y + 1;
            doc.fontSize(7).font('Helvetica').text(caseItem.findings, margin + 10, currentY, { width: pageWidth - margin - 20, align: 'justify' });
            currentY = doc.y + 1;
          }

          if (caseItem.results) {
            doc.fontSize(7).font('Helvetica-Bold').text('Resultados: ', margin + 10, currentY);
            currentY = doc.y + 1;
            doc.fontSize(7).font('Helvetica').text(caseItem.results, margin + 10, currentY, { width: pageWidth - margin - 20, align: 'justify' });
            currentY = doc.y + 1;
          }

          if (caseItem.recommendations) {
            doc.fontSize(7).font('Helvetica-Bold').text('Recomendaciones: ', margin + 10, currentY);
            currentY = doc.y + 1;
            doc.fontSize(7).font('Helvetica').text(caseItem.recommendations, margin + 10, currentY, { width: pageWidth - margin - 20, align: 'justify' });
            currentY = doc.y + 1;
          }

          if (caseItem.followUpDate) {
            doc.fontSize(7).font('Helvetica-Bold').text('Fecha Seguimiento: ', margin + 10, currentY, { continued: true });
            doc.font('Helvetica').text(new Date(caseItem.followUpDate).toLocaleDateString('es-CO'));
            currentY = doc.y + 1;
          }

          doc.strokeColor('#cccccc').lineWidth(0.5).moveTo(margin, currentY + 5).lineTo(pageWidth - margin, currentY + 5).stroke();
          currentY = doc.y + 6;
        });
      }

      const pageCount = doc.bufferedPageRange().count;
      for (let i = 0; i < pageCount; i++) {
        doc.switchToPage(i);
        const footerY = doc.page.height - 40;
        doc.fontSize(7).font('Helvetica').fillColor('#666666').text(
          `Página ${i + 1} de ${pageCount} | Generado el ${new Date().toLocaleDateString('es-CO')} | ${company?.name || ''}`,
          margin, footerY, { width: pageWidth - 2 * margin, align: 'center' }
        );
      }

      doc.end();
    } catch (error: any) {
      console.error('Error generating SVE program PDF:', error);
      if (!res.headersSent) {
        res.status(500).send(error.message);
      }
    }
  });

