  // ============================================================================
  // API v1 - Endpoints protegidos para cálculo de estándares SST
  // Propiedad intelectual protegida - DNDA 13-197-177
  // ============================================================================
  
  /**
   * POST /api/v1/get-standards
   * Calcula y devuelve los estándares SST aplicables según Resolución 0312/2019
   * 
   * Body: { workers: number, riskLevel: "I" | "II" | "III" | "IV" | "V" }
   * Response: Lista de estándares aplicables con su puntaje
   * 
   * Protección:
   * - Requiere autenticación
   * - Requiere suscripción activa
   * - Bloquea acceso desde orígenes no autorizados
   */
  app.post('/api/v1/get-standards', requireActiveSubscription, async (req, res) => {
    try {
      const { workers, riskLevel } = req.body;
      
      // Validar parámetros requeridos
      if (workers === undefined || workers === null) {
        return res.status(400).json({ 
          error: 'Parámetro requerido', 
          code: 'MISSING_WORKERS',
          message: 'El número de trabajadores es requerido' 
        });
      }
      
      if (!riskLevel) {
        return res.status(400).json({ 
          error: 'Parámetro requerido', 
          code: 'MISSING_RISK_LEVEL',
          message: 'El nivel de riesgo es requerido' 
        });
      }
      
      // Validar tipos
      const workersCount = parseInt(workers, 10);
      if (isNaN(workersCount) || workersCount < 1) {
        return res.status(400).json({ 
          error: 'Valor inválido', 
          code: 'INVALID_WORKERS',
          message: 'El número de trabajadores debe ser un entero positivo' 
        });
      }
      
      const validRiskLevels = ['I', 'II', 'III', 'IV', 'V'];
      if (!validRiskLevels.includes(riskLevel)) {
        return res.status(400).json({ 
          error: 'Valor inválido', 
          code: 'INVALID_RISK_LEVEL',
          message: 'El nivel de riesgo debe ser I, II, III, IV o V' 
        });
      }
      
      // Calcular capítulo según Resolución 0312/2019
      const chapter = calculateChapter(workersCount, riskLevel as "I" | "II" | "III" | "IV" | "V");
      
      // Determinar tipo de empresa para filtrar estándares
      const tipoEmpresa = getEmpresaTipoFromChapterAndRisk(
        chapter,
        riskLevel as "I" | "II" | "III" | "IV" | "V"
      );
      
      // Obtener estándares aplicables
      const estandares = await storage.getEstandaresByTipoEmpresa(tipoEmpresa);
      
      // Obtener el campo de puntaje correcto
      const puntajeField = `puntaje${tipoEmpresa.charAt(0).toUpperCase() + tipoEmpresa.slice(1)}` as 'puntajeTipo1' | 'puntajeTipo2' | 'puntajeTipo3';
      
      // Calcular totales
      const puntajeMaximo = estandares.reduce((sum, e) => sum + (e[puntajeField] || 0), 0);
      
      // Mapear estándares con información relevante (sin exponer estructura interna)
      const standardsList = estandares.map(e => ({
        id: e.id,
        numero: e.numeroEstandar,
        nombre: e.nombre,
        descripcion: e.descripcion,
        puntaje: e[puntajeField],
        cicloPhva: e.cicloPhva
      }));
      
      // Respuesta con metadatos
      res.json({
        clasificacion: {
          capitulo: parseInt(chapter),
          capituloDescripcion: getChapterDescription(chapter),
          tipoEmpresa,
          workers: workersCount,
          riskLevel
        },
        resumen: {
          totalEstandares: estandares.length,
          puntajeMaximo,
          descripcion: `${estandares.length} estándares aplicables según Resolución 0312/2019`
        },
        estandares: standardsList
      });
      
    } catch (error: any) {
      console.error('Error en /api/v1/get-standards:', error);
      res.status(500).json({ 
        error: 'Error interno', 
        code: 'INTERNAL_ERROR',
        message: 'Error al procesar la solicitud' 
      });
    }
  });

  // GET /api/estandares-sst/mi-empresa - Obtener estándares SST aplicables a la empresa del usuario
  app.get('/api/estandares-sst/mi-empresa', requireAuth, requirePermission('sst_management:view'), async (req, res) => {
    try {
      const companyId = req.user!.companyId;
      if (!companyId) {
        return res.status(403).json({ error: 'Usuario no asociado a una empresa' });
      }

      const company = await storage.getCompany(companyId);
      if (!company) {
        return res.status(404).json({ error: 'Empresa no encontrada' });
      }

      // Validate that company has required chapter and risk data
      const validChapters = ['1', '2', '3'];
      const validRiskLevels = ['I', 'II', 'III', 'IV', 'V'];
      
      if (!company.calculatedChapter || !validChapters.includes(company.calculatedChapter)) {
        return res.status(409).json({ 
          error: 'La empresa no tiene un capítulo calculado válido. Actualice el número de trabajadores y nivel de riesgo de la empresa.',
          requiresUpdate: true
        });
      }
      
      if (!company.riskLevel || !validRiskLevels.includes(company.riskLevel)) {
        return res.status(409).json({ 
          error: 'La empresa no tiene un nivel de riesgo válido. Actualice la información de la empresa.',
          requiresUpdate: true
        });
      }

      // Use the utility function to determine the empresa tipo
      const tipoEmpresa = getEmpresaTipoFromChapterAndRisk(
        company.calculatedChapter as "1" | "2" | "3",
        company.riskLevel as "I" | "II" | "III" | "IV" | "V"
      );

      const estandares = await storage.getEstandaresByTipoEmpresa(tipoEmpresa);
      
      res.json({
        tipoEmpresa,
        chapter: company.calculatedChapter,
        riskLevel: company.riskLevel,
        totalEstandares: estandares.length,
        estandares
      });
    } catch (error: any) {
      console.error('Error fetching estándares SST for company:', error);
      res.status(500).send(error.message);
    }
  });

