  // POST /api/diagnostico/corregir-estandares - Corregir puntajes de estándares según Res. 0312/2019
  app.post('/api/diagnostico/corregir-estandares', requireAuth, async (req, res) => {
    try {
      const userRole = req.user!.role;
      if (userRole !== 'superadmin') {
        return res.status(403).send("Solo superadmin puede corregir estándares");
      }

      // Los 7 estándares que aplican a tipo1 según Resolución 0312/2019 Artículo 3
      // Para empleadores con 10 o menos trabajadores y riesgo I, II o III
      const estandaresTipo1: Record<string, number> = {
        "1.1.1": 5,  // Asignación persona que diseña el SG-SST
        "1.1.4": 5,  // Afiliación al Sistema de Seguridad Social Integral
        "1.2.1": 15, // Programa de capacitación anual en SST
        "2.4.1": 10, // Plan Anual de Trabajo
        "3.1.4": 15, // Evaluaciones médicas ocupacionales
        "4.1.1": 30, // Identificación de peligros, evaluación y valoración de riesgos
        "4.2.1": 20  // Medidas de prevención y control frente a peligros
      };
      const allEstandares = await storage.getEstandaresSst();
      let corregidos = 0;
      let errores: string[] = [];

      for (const estandar of allEstandares) {
        const puntajeCorrecto = estandaresTipo1[estandar.numeroEstandar];
        const debeTenerPuntaje = puntajeCorrecto !== undefined;
        const tienePuntaje = estandar.puntajeTipo1 !== null;
        
        // Si debe tener puntaje pero no lo tiene, o tiene valor incorrecto
        if (debeTenerPuntaje && estandar.puntajeTipo1 !== puntajeCorrecto) {
          try {
            await db.update(schema.estandaresSst)
              .set({ puntajeTipo1: puntajeCorrecto })
              .where(eq(schema.estandaresSst.id, estandar.id));
            corregidos++;
          } catch (err: any) {
            errores.push(`Error actualizando ${estandar.numeroEstandar}: ${err.message}`);
          }
        }
        // Si no debe tener puntaje pero lo tiene
        else if (!debeTenerPuntaje && tienePuntaje) {
          try {
            await db.update(schema.estandaresSst)
              .set({ puntajeTipo1: null })
              .where(eq(schema.estandaresSst.id, estandar.id));
            corregidos++;
          } catch (err: any) {
            errores.push(`Error limpiando ${estandar.numeroEstandar}: ${err.message}`);
          }
        }
      }

      res.json({
        mensaje: `Corrección completada. ${corregidos} estándares actualizados.`,
        corregidos,
        errores: errores.length > 0 ? errores : undefined
      });
    } catch (error: any) {
      console.error('Error corrigiendo estándares:', error);
      res.status(500).send(error.message);
    }
  });

  // GET /api/diagnostico/empresas - Diagnóstico de configuración de empresas (superadmin only)
  app.get('/api/diagnostico/empresas', requireAuth, async (req, res) => {
    try {
      const userRole = req.user!.role;
      if (userRole !== 'superadmin') {
        return res.status(403).send("Solo superadmin puede acceder a este diagnóstico");
      }

      // Get all companies with their subscriptions
      const companies = await storage.getCompanies();
      const plans = await storage.getSubscriptionPlans();
      
      const diagnostico = companies.map(company => {
        const expectedChapter = calculateChapter(company.numberOfWorkers || 1, company.riskLevel || 'I');
        const currentChapter = company.calculatedChapter;
        const chapterMismatch = currentChapter !== expectedChapter;
        
        // Map chapter to expected plan
        const chapterToPlan: Record<string, string> = {
          '1': 'microempresa',
          '2': 'pequena',
          '3': 'mediana'
        };
        const expectedPlanId = chapterToPlan[expectedChapter] || 'microempresa';
        
        const plan = plans.find(p => p.id === company.subscriptionPlanId);
        const planMismatch = company.subscriptionPlanId !== expectedPlanId;
        
        return {
          id: company.id,
          name: company.name,
          nit: company.nit,
          numberOfWorkers: company.numberOfWorkers || 0,
          riskLevel: company.riskLevel || 'I',
          currentChapter,
          expectedChapter,
          chapterMismatch,
          subscriptionPlanId: company.subscriptionPlanId,
          expectedPlanId,
          planMismatch,
          subscriptionStatus: company.subscriptionStatus,
          currentPlanName: plan?.name || 'Sin plan',
          hasIssues: chapterMismatch || planMismatch
        };
      });

      const summary = {
        totalCompanies: companies.length,
        companiesWithIssues: diagnostico.filter(d => d.hasIssues).length,
        chapterMismatches: diagnostico.filter(d => d.chapterMismatch).length,
        planMismatches: diagnostico.filter(d => d.planMismatch).length
      };

      res.json({ summary, companies: diagnostico });
    } catch (error: any) {
      console.error('Error en diagnóstico de empresas:', error);
      res.status(500).send(error.message);
    }
  });

  // POST /api/diagnostico/corregir-empresa/:id - Corregir configuración de una empresa (superadmin only)
  app.post('/api/diagnostico/corregir-empresa/:id', requireAuth, async (req, res) => {
    try {
      const userRole = req.user!.role;
      if (userRole !== 'superadmin') {
        return res.status(403).send("Solo superadmin puede corregir configuración de empresas");
      }

      const companyId = req.params.id;
      const company = await storage.getCompany(companyId);
      
      if (!company) {
        return res.status(404).send("Empresa no encontrada");
      }

      // Recalculate chapter based on workers and risk
      const correctChapter = calculateChapter(company.numberOfWorkers || 1, company.riskLevel || 'I');
      
      // Map chapter to plan
      const chapterToPlan: Record<string, string> = {
        '1': 'microempresa',
        '2': 'pequena',
        '3': 'mediana'
      };
      const correctPlanId = chapterToPlan[correctChapter] || 'microempresa';
      
      // Update company
      const updatedCompany = await storage.updateCompany(companyId, {
        calculatedChapter: correctChapter,
        subscriptionPlanId: correctPlanId
      });

      res.json({
        mensaje: `Empresa corregida exitosamente`,
        company: {
          id: updatedCompany.id,
          name: updatedCompany.name,
          newChapter: correctChapter,
          newPlanId: correctPlanId
        }
      });
    } catch (error: any) {
      console.error('Error corrigiendo empresa:', error);
      res.status(500).send(error.message);
    }
  });

