  // GET /api/evaluaciones-sst/comparativo/:companyId - Obtener evolución histórica de evaluaciones para gráficos de tendencia
  app.get('/api/evaluaciones-sst/comparativo/:companyId', requireAuth, requirePermission('sst_management:view'), async (req, res) => {
    try {
      const { companyId } = req.params;
      const userRole = req.user!.role;
      const isAdmin = hasGlobalAccess(userRole);
      
      // Validar acceso a la empresa - non-admin users can only see their own company
      if (!isAdmin && req.user!.companyId !== companyId) {
        return res.status(403).send("No tienes acceso a esta empresa");
      }
      
      // Obtener evaluaciones de la empresa (ya ordenadas por año DESC, mes DESC)
      const evaluaciones = await storage.getEvaluacionesSst(companyId);
      
      // Construir array de comparativo con los campos necesarios
      const comparativo = evaluaciones.map(evaluation => ({
        id: evaluation.id,
        anio: evaluation.anio,
        mes: evaluation.mes,
        porcentajeCumplimiento: evaluation.porcentajeCumplimiento,
        nivelCumplimiento: evaluation.nivelCumplimiento,
        puntajeTotal: evaluation.puntajeTotal,
        puntajeMaximo: evaluation.puntajeMaximo,
        estado: evaluation.estado,
        puntajesPorCicloPhva: evaluation.puntajesPorCicloPhva ? JSON.parse(evaluation.puntajesPorCicloPhva) : null
      }));
      
      // Calcular tendencia (mejora y diferencia porcentual)
      let tendencia = {
        mejora: false,
        diferencia: 0
      };
      
      if (comparativo.length >= 2) {
        const evaluacionMasReciente = comparativo[0];
        const evaluacionAnterior = comparativo[1];
        const diferencia = evaluacionMasReciente.porcentajeCumplimiento - evaluacionAnterior.porcentajeCumplimiento;
        
        tendencia = {
          mejora: diferencia > 0,
          diferencia: diferencia
        };
      }
      
      res.json({
        comparativo,
        tendencia
      });
    } catch (error: any) {
      console.error('Error fetching comparativo evaluaciones SST:', error);
      res.status(500).send(error.message);
    }
  });
  // POST /api/evaluaciones-sst - Crear nueva evaluación
  app.post('/api/evaluaciones-sst', requireAuth, requirePermission('sst_management:create'), async (req, res) => {
    try {
      const validatedData = insertEvaluacionSstSchema.parse(req.body);
      
      const userRole = req.user!.role;
      const isAdmin = hasGlobalAccess(userRole);
      
      let companyId: string;
      if (isAdmin) {
        const requestedCompanyId = req.body.companyId;
        if (!requestedCompanyId) {
          return res.status(400).send("Administrador debe especificar la empresa para crear la evaluación");
        }
        companyId = requestedCompanyId as string;
      } else {
        companyId = req.user!.companyId || "";
        if (!companyId) {
          return res.status(403).send("Usuario no asociado a una empresa");
        }
      }
      
      // VALIDACIÓN: Obtener empresa y calcular tipoEmpresa correcto según Res. 0312/2019
      const company = await storage.getCompany(companyId);
      if (!company) {
        return res.status(400).send("La empresa especificada no existe");
      }
      
      // Validar que la empresa tenga capítulo y riesgo configurados
      if (!company.calculatedChapter || !['1', '2', '3'].includes(company.calculatedChapter)) {
        return res.status(409).json({ 
          error: 'La empresa no tiene un capítulo calculado válido. Actualice el número de trabajadores y nivel de riesgo.',
          requiresUpdate: true
        });
      }
      if (!company.riskLevel || !['I', 'II', 'III', 'IV', 'V'].includes(company.riskLevel)) {
        return res.status(409).json({ 
          error: 'La empresa no tiene un nivel de riesgo válido. Actualice la información de la empresa.',
          requiresUpdate: true
        });
      }
      
      // Calcular y FORZAR tipoEmpresa correcto (ignora valor del frontend)
      // Garantiza: Cap.1=tipo1(7 est.), Cap.2=tipo2(21 est.), Cap.3=tipo3/4(61 est.)
      const tipoEmpresaCorrecto = getEmpresaTipoFromChapterAndRisk(
        company.calculatedChapter as "1" | "2" | "3",
        company.riskLevel as "I" | "II" | "III" | "IV" | "V"
      );
      
      // Sobrescribir tipoEmpresa con el valor correcto
      const evaluacionConTipoCorrecto = {
        ...validatedData,
        tipoEmpresa: tipoEmpresaCorrecto
      };
      
      const evaluacion = await storage.createEvaluacionSst(evaluacionConTipoCorrecto, companyId);
      
      // AUTO-INICIALIZAR: Crear respuestas "No Cumple" para todos los estándares aplicables
      try {
        const estandaresAplicables = await storage.getEstandaresByTipoEmpresa(tipoEmpresaCorrecto);
        const puntajeKey = `puntaje${tipoEmpresaCorrecto.charAt(0).toUpperCase() + tipoEmpresaCorrecto.slice(1)}` as 'puntajeTipo1' | 'puntajeTipo2' | 'puntajeTipo3' | 'puntajeTipo4';
        
        for (const estandar of estandaresAplicables) {
          const puntajeMaximo = estandar[puntajeKey] || 0;
          await storage.createRespuestaEstandar({
            evaluacionId: evaluacion.id,
            estandarId: estandar.id,
            cumple: 0,
            noAplica: 0,
            puntajeObtenido: 0,
            puntajeMaximo: puntajeMaximo,
            hallazgo: null,
            causaRaiz: null,
            evidencias: null,
            modoVerificacion: null,
            observaciones: null,
            justificacionNoAplica: null,
          }, companyId);
        }
        console.log(`Evaluación ${evaluacion.id} inicializada con ${estandaresAplicables.length} estándares en No Cumple`);
      } catch (initError) {
        console.error('Error inicializando estándares:', initError);
      }
      
      res.status(201).json(evaluacion);
    } catch (error: any) {
      console.error('Error creating evaluación SST:', error);
      res.status(400).send(error.message);
    }
  });


  // PATCH /api/evaluaciones-sst/:id - Actualizar evaluación
  app.patch('/api/evaluaciones-sst/:id', requireAuth, requirePermission('sst_management:edit'), async (req, res) => {
    try {
      const validatedData = insertEvaluacionSstSchema.partial().parse(req.body);
      
      const userRole = req.user!.role;
      const isAdmin = hasGlobalAccess(userRole);
      
      let companyId: string;
      if (isAdmin) {
        // Admin: get companyId from existing evaluacion
        const existing = await storage.getEvaluacionSstById(req.params.id);
        if (!existing) {
          return res.status(404).send("Evaluación no encontrada");
        }
        companyId = existing.companyId;
      } else {
        // Non-admin: use their own companyId
        companyId = req.user!.companyId || "";
        if (!companyId) {
          return res.status(403).send("Usuario no asociado a una empresa");
        }
      }

      // Proteger y validar tipoEmpresa
      const company = await storage.getCompany(companyId);
      if (!company) {
        return res.status(404).send("Empresa no encontrada");
      }

      const correctChapter = calculateChapter(
        company.numberOfWorkers,
        company.riskLevel as "I" | "II" | "III" | "IV" | "V"
      );
      const correctTipoEmpresa = getEmpresaTipoFromChapterAndRisk(
        correctChapter,
        company.riskLevel as "I" | "II" | "III" | "IV" | "V"
      );

      // Si se intenta cambiar o si es incorrecto, forzar el valor correcto
      if (validatedData.tipoEmpresa && validatedData.tipoEmpresa !== correctTipoEmpresa) {
        console.log(`[Validation] Overwriting incorrect tipoEmpresa in PATCH: ${validatedData.tipoEmpresa} -> ${correctTipoEmpresa}`);
      }
      
      // Siempre nos aseguramos de que el tipoEmpresa sea el correcto según los datos actuales de la empresa
      validatedData.tipoEmpresa = correctTipoEmpresa;
      
      const evaluacion = await storage.updateEvaluacionSst(req.params.id, validatedData, companyId);
      
      if (!evaluacion) {
        return res.status(404).send('Evaluación no encontrada');
      }
      
      res.json(evaluacion);
    } catch (error: any) {
      console.error('Error updating evaluación SST:', error);
      res.status(400).send(error.message);
    }
  });
