  // POST /api/evaluaciones-sst/:id/importar-anterior - Importar respuestas de evaluación anterior
  // Solo copia estándares persistentes marcándolos con isInherited=1 y requiresRefresh=1
  app.post('/api/evaluaciones-sst/:id/importar-anterior', requireAuth, requirePermission('sst_management:edit'), async (req, res) => {
    try {
      const userRole = req.user!.role;
      const isAdmin = hasGlobalAccess(userRole);
      
      // Obtener la evaluación nueva (destino)
      const evaluacionNueva = await storage.getEvaluacionSstById(req.params.id);
      if (!evaluacionNueva) {
        return res.status(404).json({ error: "Evaluación nueva no encontrada" });
      }
      
      let companyId: string;
      if (isAdmin) {
        companyId = evaluacionNueva.companyId;
      } else {
        if (!req.user!.companyId || req.user!.companyId !== evaluacionNueva.companyId) {
          return res.status(403).json({ error: "No tiene permisos para importar en esta evaluación" });
        }
        companyId = req.user!.companyId;
      }
      
      // Buscar la evaluación anterior
      let evaluacionAnterior = null;
      
      if (evaluacionNueva.evaluacionAnteriorId) {
        // Si está vinculada explícitamente, usar esa
        evaluacionAnterior = await storage.getEvaluacionSstById(evaluacionNueva.evaluacionAnteriorId);
      } else {
        // Si no, buscar evaluación del año anterior de la misma empresa
        const allEvaluaciones = await storage.getEvaluacionesSst(companyId);
        const evaluacionesOrdenadas = allEvaluaciones
          .sort((a, b) => (b.anio || 0) - (a.anio || 0));
        
        // Buscar la evaluación más reciente anterior a esta
        for (const evalu of evaluacionesOrdenadas) {
          if ((evalu.anio || 0) < (evaluacionNueva.anio || 0) && evalu.id !== evaluacionNueva.id) {
            evaluacionAnterior = evalu;
            break;
          }
        }
      }
      
      if (!evaluacionAnterior) {
        return res.status(404).json({ 
          error: "No se encontró evaluación anterior para importar",
          message: "Debe haber una evaluación previa del mismo período o años anteriores"
        });
      }
      
      // Obtener todas las respuestas de la evaluación anterior
      const respuestasAnteriores = await storage.getRespuestasEstandares(evaluacionAnterior.id, companyId);
      
      // Obtener estándares persistentes codigos para validación
      const persistentCodes = getPersistentStandardCodes();
      
      // Filtrar solo las respuestas de estándares persistentes
      const respuestasAherdar = respuestasAnteriores.filter(respuesta => {
        // Validar que el estandarId esté en la lista de persistentes
        return persistentCodes.includes(respuesta.estandarId);
      });
      
      // Crear las nuevas respuestas para la evaluación nueva
      let importedCount = 0;
      
      for (const respuesta of respuestasAherdar) {
        try {
          const nuevaRespuesta: schema.InsertRespuestaEstandar = {
            evaluacionId: evaluacionNueva.id,
            estandarId: respuesta.estandarId,
            cumple: respuesta.cumple,
            noAplica: respuesta.noAplica,
            justificacionNoAplica: respuesta.justificacionNoAplica,
            puntajeObtenido: respuesta.puntajeObtenido,
            puntajeMaximo: respuesta.puntajeMaximo,
            evidencias: respuesta.evidencias,
            modoVerificacion: respuesta.modoVerificacion,
            observaciones: respuesta.observaciones,
            hallazgo: respuesta.hallazgo,
            causaRaiz: respuesta.causaRaiz,
            isInherited: 1,
            inheritedFromRespuestaId: respuesta.id,
            requiresRefresh: 1,
            lastVerifiedAt: new Date(),
          };
          
          await storage.createRespuestaEstandar(nuevaRespuesta, companyId);
          importedCount++;
        } catch (error: any) {
          console.error(`Error al importar respuesta ${respuesta.id}:`, error);
        }
      }
      
      // Recalcular puntajes de la nueva evaluación
      try {
        await storage.calcularPuntajesEvaluacion(evaluacionNueva.id, companyId);
      } catch (error: any) {
        console.error('Error al recalcular puntajes:', error);
      }
      
      res.json({
        message: `Se importaron ${importedCount} respuestas del año anterior`,
        importedCount,
        totalPersistent: persistentCodes.length,
        evaluacionOrigenId: evaluacionAnterior.id
      });
    } catch (error: any) {
      console.error('Error importing previous responses:', error);
      res.status(500).json({ error: error.message });
    }
  });
  // POST /api/evaluaciones-sst/:id/corregir-tipo - Corregir tipoEmpresa de evaluación existente
  // Recalcula el tipoEmpresa basado en el capítulo/riesgo actual de la empresa
  app.post('/api/evaluaciones-sst/:id/corregir-tipo', requireAuth, requirePermission('sst_management:edit'), async (req, res) => {
    try {
      const userRole = req.user!.role;
      const isAdmin = hasGlobalAccess(userRole);
      
      // Obtener la evaluación existente
      const evaluacion = await storage.getEvaluacionSstById(req.params.id);
      if (!evaluacion) {
        return res.status(404).send("Evaluación no encontrada");
      }
      
      let companyId: string;
      if (isAdmin) {
        companyId = evaluacion.companyId;
      } else {
        if (!req.user!.companyId || req.user!.companyId !== evaluacion.companyId) {
          return res.status(403).send("No tiene permisos para corregir esta evaluación");
        }
        companyId = req.user!.companyId;
      }
      
      // Obtener la empresa y calcular el tipo correcto
      const company = await storage.getCompany(companyId);
      if (!company) {
        return res.status(404).send("Empresa no encontrada");
      }
      
      if (!company.calculatedChapter || !company.riskLevel) {
        return res.status(409).json({ 
          error: 'La empresa no tiene capítulo o nivel de riesgo configurado.',
          requiresUpdate: true
        });
      }
      
      const tipoEmpresaCorrecto = getEmpresaTipoFromChapterAndRisk(
        company.calculatedChapter as "1" | "2" | "3",
        company.riskLevel as "I" | "II" | "III" | "IV" | "V"
      );
      
      // Si ya tiene el tipo correcto, no hacer nada
      if (evaluacion.tipoEmpresa === tipoEmpresaCorrecto) {
        return res.json({
          message: 'La evaluación ya tiene el tipo de empresa correcto',
          tipoEmpresa: tipoEmpresaCorrecto,
          evaluacion
        });
      }
      
      // Actualizar el tipoEmpresa
      const evaluacionCorregida = await storage.updateEvaluacionSst(
        req.params.id, 
        { tipoEmpresa: tipoEmpresaCorrecto },
        companyId
      );
      
      // Recalcular puntajes con el nuevo tipo
      await storage.calcularPuntajesEvaluacion(req.params.id, companyId);
      const evaluacionFinal = await storage.getEvaluacionSstById(req.params.id);
      
      res.json({
        message: `Tipo de empresa corregido: ${evaluacion.tipoEmpresa} → ${tipoEmpresaCorrecto}`,
        tipoAnterior: evaluacion.tipoEmpresa,
        tipoCorregido: tipoEmpresaCorrecto,
        evaluacion: evaluacionFinal
      });
    } catch (error: any) {
      console.error('Error correcting evaluation type:', error);
      res.status(500).send(error.message);
    }
  });

