  // POST /api/planes-trabajo-anual - Crear nuevo plan de trabajo
  app.post('/api/planes-trabajo-anual', requireAuth, requirePermission('sst_management:create'), async (req, res) => {
    try {
      const isAdmin = hasGlobalAccess(req.user!.role);
      let companyId: string;
      
      if (isAdmin) {
        // Admin: obtener companyId del body y validar que existe
        const bodyCompanyId = req.body.companyId;
        if (!bodyCompanyId) {
          return res.status(400).send("Debe seleccionar una empresa");
        }
        const company = await storage.getCompany(bodyCompanyId);
        if (!company) {
          return res.status(404).send("Empresa no encontrada");
        }
        companyId = bodyCompanyId;
      } else {
        // Usuario regular: usar su companyId
        companyId = req.user!.companyId!;
      }
      
      const validatedData = insertPlanTrabajoAnualSchema.parse(req.body);
      
      // Verificar si ya existe un plan para ese año
      const existingPlan = await storage.getPlanTrabajoByYear(validatedData.anio, companyId);
      if (existingPlan) {
        return res.status(400).send(`Ya existe un plan de trabajo para el año ${validatedData.anio}`);
      }
      
      const plan = await storage.createPlanTrabajoAnual(validatedData, companyId);
      
      // Disparar validación automática de matriz legal en background
      void triggerMatrizLegalAutoValidation(companyId);
      
      res.status(201).json(plan);
    } catch (error: any) {
      console.error('Error creating plan trabajo anual:', error);
      res.status(400).send(error.message);
    }
  });

  // PATCH /api/planes-trabajo-anual/:id - Actualizar plan de trabajo
  app.patch('/api/planes-trabajo-anual/:id', requireAuth, requirePermission('sst_management:edit'), async (req, res) => {
    try {
      const isAdmin = hasGlobalAccess(req.user!.role);
      const validatedData = insertPlanTrabajoAnualSchema.partial().parse(req.body);
      
      // Admin: get plan by ID, extract companyId from existing plan
      // Non-admin: use their own companyId
      let companyId: string;
      if (isAdmin) {
        const existingPlan = await storage.getPlanTrabajoAnualById(req.params.id);
        if (!existingPlan) {
          return res.status(404).send('Plan de trabajo no encontrado');
        }
        companyId = existingPlan.companyId;
      } else {
        const userCompanyId = req.user!.companyId;
        if (!userCompanyId) {
          return res.status(403).send("Esta operación requiere pertenecer a una empresa");
        }
        companyId = userCompanyId;
      }
      
      // Compliance check (Estándar 1.1.2): Block approval if missing matriz or IPERC activity
      if (validatedData.estado === 'aprobado') {
        const currentPlan = isAdmin 
          ? await storage.getPlanTrabajoAnualById(req.params.id)
          : await storage.getPlanTrabajoAnual(req.params.id, companyId);
        
        if (!currentPlan) {
          return res.status(404).send('Plan de trabajo no encontrado');
        }
        
        const finalMatrizId = validatedData.matrizIpercId !== undefined 
          ? validatedData.matrizIpercId 
          : currentPlan.matrizIpercId;
        
        if (!finalMatrizId) {
          return res.status(422).send('No se puede aprobar el plan sin vincular una matriz IPERC (Estándar 1.1.2 - Resolución 0312/2019)');
        }
        
        const hasIpercActivity = await storage.ensurePlanHasIpercActivity(req.params.id, companyId);
        if (!hasIpercActivity) {
          return res.status(422).send('No se puede aprobar el plan sin al menos una actividad de "Identificación de Peligros" (Estándar 1.1.2)');
        }
      }
      
      const plan = await storage.updatePlanTrabajoAnual(req.params.id, validatedData, companyId);
      
      if (!plan) {
        return res.status(404).send('Plan de trabajo no encontrado');
      }
      
      // Disparar validación automática de matriz legal en background
      void triggerMatrizLegalAutoValidation(companyId);
      
      res.json(plan);
    } catch (error: any) {
      console.error('Error updating plan trabajo anual:', error);
      res.status(400).send(error.message);
    }
  });

