  // GET /api/planes-trabajo-anual/:id/validar-iperc - Validar cumplimiento Estándar 1.1.2
  app.get('/api/planes-trabajo-anual/:id/validar-iperc', requireAuth, requirePermission('sst_management:view'), async (req, res) => {
    try {
      const isAdmin = hasGlobalAccess(req.user!.role);
      let companyId: string;
      
      if (isAdmin) {
        const plan = await storage.getPlanTrabajoAnualById(req.params.id);
        if (!plan) {
          return res.status(404).send('Plan de trabajo no encontrado');
        }
        companyId = plan.companyId;
      } else {
        const userCompanyId = req.user!.companyId;
        if (!userCompanyId) {
          return res.status(403).send("Esta operación requiere pertenecer a una empresa");
        }
        companyId = userCompanyId;
        const plan = await storage.getPlanTrabajoAnual(req.params.id, companyId);
        if (!plan) {
          return res.status(404).send('Plan de trabajo no encontrado');
        }
      }
      
      const plan = isAdmin 
        ? await storage.getPlanTrabajoAnualById(req.params.id)
        : await storage.getPlanTrabajoAnual(req.params.id, companyId);
      
      const hasMatriz = !!plan?.matrizIpercId;
      const hasIpercActivity = await storage.ensurePlanHasIpercActivity(req.params.id, companyId);
      const isCompliant = hasMatriz && hasIpercActivity;
      
      let matrizInfo = null;
      if (hasMatriz && plan?.matrizIpercId) {
        const matriz = await storage.getMatrizIpercById(plan.matrizIpercId);
        if (matriz) {
          matrizInfo = {
            id: matriz.id,
            nombre: matriz.nombre,
            fechaEvaluacion: matriz.fechaEvaluacion,
            vigenciaDesde: matriz.vigenciaDesde,
            vigenciaHasta: matriz.vigenciaHasta,
            vigenteAuto: matriz.vigenteAuto,
          };
        }
      }
      
      res.json({ hasMatriz, hasIpercActivity, isCompliant, matrizInfo });
    } catch (error: any) {
      console.error('Error validating plan IPERC compliance:', error);
      res.status(500).send(error.message);
    }
  });

  // POST /api/planes-trabajo-anual/:id/link-matriz - Vincular matriz IPERC a plan
  app.post('/api/planes-trabajo-anual/:id/link-matriz', requireAuth, requirePermission('sst_management:edit'), async (req, res) => {
    try {
      const isAdmin = hasGlobalAccess(req.user!.role);
      let companyId: string;
      let plan;
      
      if (isAdmin) {
        plan = await storage.getPlanTrabajoAnualById(req.params.id);
        if (!plan) {
          return res.status(404).send('Plan de trabajo no encontrado');
        }
        companyId = plan.companyId;
      } else {
        const userCompanyId = req.user!.companyId;
        if (!userCompanyId) {
          return res.status(403).send("Esta operación requiere pertenecer a una empresa");
        }
        companyId = userCompanyId;
        plan = await storage.getPlanTrabajoAnual(req.params.id, companyId);
        if (!plan) {
          return res.status(404).send('Plan de trabajo no encontrado');
        }
      }
      
      // Zod validation for request body
      const bodySchema = z.object({
        matrizIpercId: z.string().min(1, 'matrizIpercId es requerido'),
      });
      const { matrizIpercId } = bodySchema.parse(req.body);
      
      if (plan.matrizIpercId) {
        return res.status(422).send('El plan ya tiene una matriz IPERC vinculada');
      }
      
      const matriz = await storage.getMatrizIperc(matrizIpercId, companyId);
      if (!matriz) {
        return res.status(404).send('Matriz IPERC no encontrada');
      }
      
      if (matriz.estado !== 'vigente') {
        return res.status(422).send('La matriz IPERC debe estar en estado vigente');
      }
      
      // Validate vigencia: matriz must be active for the plan year
      const activeMatriz = await storage.getActiveMatrizIperc(companyId, plan.anio);
      if (!activeMatriz || activeMatriz.id !== matrizIpercId) {
        return res.status(422).send(`La matriz IPERC no está vigente para el año ${plan.anio}. Verifique las fechas de vigencia.`);
      }
      
      await storage.linkPlanToMatriz(req.params.id, matrizIpercId, companyId);
      res.status(200).json({ success: true, message: 'Matriz vinculada exitosamente' });
    } catch (error: any) {
      console.error('Error linking matriz to plan:', error);
      if (error.message.includes('not found') || error.message.includes('access denied')) {
        return res.status(403).send(error.message);
      }
      if (error.name === 'ZodError') {
        return res.status(400).send(error.message);
      }
      res.status(500).send(error.message);
    }
  });

