  // ================================================================================
  // Indicadores SST - Cálculo Automático y Tendencias
  // ================================================================================

  // POST /api/indicadores-sst/:id/calcular-automatico - Calcular automáticamente un indicador
  app.post('/api/indicadores-sst/:id/calcular-automatico', requireAuth, requirePermission('sst_management:create'), async (req, res) => {
    try {
      if (!req.user!.companyId) {
        return res.status(403).send("Esta operación requiere pertenecer a una empresa");
      }
      const companyId = req.user!.companyId;
      const { id } = req.params;
      const { periodo } = req.body;
      
      if (!periodo) {
        return res.status(400).json({ error: "Periodo es requerido (ej: '2025-Q1', '2025-12')" });
      }
      
      const indicador = await storage.getIndicadorSst(id, companyId);
      if (!indicador) {
        return res.status(404).json({ error: "Indicador no encontrado" });
      }
      
      if (!indicador.esCalculoAutomatico || !indicador.codigoCalculo) {
        return res.status(400).json({ error: "Este indicador no tiene cálculo automático configurado" });
      }
      
      const dateRange = parsePeriodoToDateRange(periodo);
      const resultado = await calcularIndicador(indicador.codigoCalculo, companyId, dateRange);
      
      const cumpleMeta = indicador.valorMeta 
        ? (resultado.valorCalculado >= indicador.valorMeta ? 1 : 0) 
        : null;
      const desviacion = indicador.valorMeta 
        ? Math.round(((resultado.valorCalculado - indicador.valorMeta) / indicador.valorMeta) * 100) 
        : null;
      
      const medicion = await storage.createMedicionIndicador({
        indicadorId: id,
        periodo,
        fechaMedicion: new Date().toISOString().split('T')[0],
        valorMedido: resultado.valorCalculado.toString(),
        valorNumerico: Math.round(resultado.valorCalculado),
        cumpleMeta,
        desviacion,
        analisis: JSON.stringify(resultado.detallesCalculo),
        responsableMedicion: req.user!.fullName || "Sistema Automático"
      }, companyId);
      
      res.status(201).json({ 
        medicion, 
        detallesCalculo: resultado.detallesCalculo 
      });
    } catch (error: any) {
      console.error('Error en cálculo automático:', error);
      res.status(500).send(error.message);
    }
  });

  // GET /api/indicadores-sst/:id/tendencias - Obtener estadísticas y tendencias de un indicador

  // POST /api/indicadores-sst/ejecutar-calculo-masivo - Ejecutar cálculo masivo de indicadores automáticos
  app.post('/api/indicadores-sst/ejecutar-calculo-masivo', requireAuth, requirePermission('sst_management:create'), async (req, res) => {
    try {
      if (!req.user!.companyId) {
        return res.status(403).send("Esta operación requiere pertenecer a una empresa");
      }
      const companyId = req.user!.companyId;
      const { periodo } = req.body;
      
      if (!periodo) {
        return res.status(400).json({ error: "Periodo es requerido (ej: '2025-Q1', '2025-12', '2025')" });
      }
      
      const { ejecutarCalculoMasivoEmpresa } = await import("./jobs/indicadores-scheduler");
      const resumen = await ejecutarCalculoMasivoEmpresa(companyId, periodo);
      
      res.json(resumen);
    } catch (error: any) {
      console.error('Error en cálculo masivo de indicadores:', error);
      res.status(500).send(error.message);
    }
  });
  app.get('/api/indicadores-sst/:id/tendencias', requireAuth, requirePermission('sst_management:view'), async (req, res) => {
    try {
      if (!req.user!.companyId) {
        return res.status(403).send("Esta operación requiere pertenecer a una empresa");
      }
      const companyId = req.user!.companyId;
      const { id } = req.params;
      
      const indicador = await storage.getIndicadorSst(id, companyId);
      if (!indicador) {
        return res.status(404).json({ error: "Indicador no encontrado" });
      }
      
      const todasMediciones = await storage.getMedicionesIndicador(id, companyId);
      const ultimasMediciones = todasMediciones
        .sort((a, b) => new Date(a.fechaMedicion || '').getTime() - new Date(b.fechaMedicion || '').getTime())
        .slice(-12);
      
      const valores = ultimasMediciones.map(m => m.valorNumerico || 0);
      const promedio = valores.length ? valores.reduce((a, b) => a + b, 0) / valores.length : 0;
      const minimo = valores.length ? Math.min(...valores) : 0;
      const maximo = valores.length ? Math.max(...valores) : 0;
      
      let tendencia: "ascendente" | "descendente" | "estable" = "estable";
      if (valores.length >= 2) {
        const primeraMitad = valores.slice(0, Math.floor(valores.length / 2));
        const segundaMitad = valores.slice(Math.floor(valores.length / 2));
        const promPrimera = primeraMitad.reduce((a, b) => a + b, 0) / primeraMitad.length;
        const promSegunda = segundaMitad.reduce((a, b) => a + b, 0) / segundaMitad.length;
        if (promSegunda > promPrimera * 1.05) tendencia = "ascendente";
        else if (promSegunda < promPrimera * 0.95) tendencia = "descendente";
      }
      
      const cumplimientos = ultimasMediciones.filter(m => m.cumpleMeta === 1).length;
      const cumplimientoHistorico = ultimasMediciones.length 
        ? (cumplimientos / ultimasMediciones.length) * 100 
        : 0;
      
      res.json({
        indicador,
        mediciones: ultimasMediciones,
        estadisticas: {
          promedio: Math.round(promedio * 100) / 100,
          minimo,
          maximo,
          tendencia,
          cumplimientoHistorico: Math.round(cumplimientoHistorico * 100) / 100,
          totalMediciones: ultimasMediciones.length
        }
      });
    } catch (error: any) {
      console.error('Error fetching tendencias:', error);
      res.status(500).send(error.message);
    }
  });

