  // POST /api/indicadores/:id/calcular - Calcular automáticamente un indicador de resultado
  app.post('/api/indicadores/:id/calcular', requireAuth, requirePermission('sst_management:view'), async (req, res) => {
    try {
      if (!req.user!.companyId) {
        return res.status(403).send("Esta operación requiere pertenecer a una empresa");
      }
      const companyId = req.user!.companyId;
      const { periodo } = req.body;
      
      if (!periodo) {
        return res.status(400).send('El periodo es requerido');
      }

      // Obtener el indicador
      const indicador = await storage.getIndicadorSst(req.params.id, companyId);
      if (!indicador) {
        return res.status(404).send('Indicador no encontrado');
      }

      // Verificar que sea auto-calculable
      if (!indicador.esCalculoAutomatico || !indicador.codigoCalculo) {
        return res.status(400).send('Este indicador no tiene cálculo automático configurado');
      }

      // Obtener datos del periodo
      const datosCalculo = await storage.getDatosCalculoByPeriodo(periodo, companyId);
      if (!datosCalculo) {
        return res.status(404).send(`No hay datos registrados para el periodo ${periodo}. Por favor registre los datos base primero.`);
      }

      // Constante K según NTC-3701/3793 (240,000 para Colombia)
      const K = 240000;
      
      let valorCalculado: number;
      let valorMedidoTexto: string;

      // Calcular según código
      switch (indicador.codigoCalculo) {
        case 'IF': // Índice de Frecuencia
          if (datosCalculo.horasTrabajadas === 0) {
            return res.status(400).send('No se puede calcular IF: horas trabajadas = 0');
          }
          valorCalculado = (datosCalculo.numeroAccidentes / datosCalculo.horasTrabajadas) * K;
          valorMedidoTexto = `${valorCalculado.toFixed(2)}`;
          break;

        case 'IS': // Índice de Severidad
          if (datosCalculo.horasTrabajadas === 0) {
            return res.status(400).send('No se puede calcular IS: horas trabajadas = 0');
          }
          valorCalculado = (datosCalculo.diasPerdidos / datosCalculo.horasTrabajadas) * K;
          valorMedidoTexto = `${valorCalculado.toFixed(2)}`;
          break;

        case 'ILI': // Índice de Lesiones Incapacitantes
          if (datosCalculo.horasTrabajadas === 0) {
            return res.status(400).send('No se puede calcular ILI: horas trabajadas = 0');
          }
          const IF = (datosCalculo.numeroAccidentes / datosCalculo.horasTrabajadas) * K;
          const IS = (datosCalculo.diasPerdidos / datosCalculo.horasTrabajadas) * K;
          valorCalculado = (IF * IS) / 1000;
          valorMedidoTexto = `${valorCalculado.toFixed(2)}`;
          break;

        case 'AUSENTISMO': // Tasa de Ausentismo
          if (datosCalculo.diasTrabajados === 0) {
            return res.status(400).send('No se puede calcular AUSENTISMO: días trabajados = 0');
          }
          valorCalculado = (datosCalculo.diasAusencia / datosCalculo.diasTrabajados) * 100;
          valorMedidoTexto = `${valorCalculado.toFixed(2)}%`;
          break;

        default:
          return res.status(400).send(`Código de cálculo no soportado: ${indicador.codigoCalculo}`);
      }

      // Retornar el resultado calculado
      res.json({
        indicadorId: indicador.id,
        indicadorNombre: indicador.nombre,
        codigoCalculo: indicador.codigoCalculo,
        periodo,
        valorCalculado,
        valorMedidoTexto,
        datosUtilizados: {
          numeroTrabajadores: datosCalculo.numeroTrabajadores,
          horasTrabajadas: datosCalculo.horasTrabajadas,
          numeroAccidentes: datosCalculo.numeroAccidentes,
          diasPerdidos: datosCalculo.diasPerdidos,
          diasAusencia: datosCalculo.diasAusencia,
          diasTrabajados: datosCalculo.diasTrabajados,
        }
      });
    } catch (error: any) {
      console.error('Error calculating indicador:', error);
      res.status(500).send(error.message);
    }
  });

