  // GET /api/proveedores/:id/validar-documentacion - Validar cumplimiento documental normativo
  app.get("/api/proveedores/:id/validar-documentacion", async (req, res) => {
    try {
      const companyId = req.user?.companyId;
      if (!companyId) return res.status(401).json({ error: "No autorizado" });
      
      const proveedorId = req.params.id;
      
      // Verificar que el proveedor existe y pertenece a la empresa
      const proveedor = await storage.getProveedorContratista(proveedorId, companyId);
      if (!proveedor) {
        return res.status(404).json({ error: "Proveedor no encontrado" });
      }
      
      // Obtener documentos del proveedor
      const documentos = await storage.getDocumentosProveedor(proveedorId, companyId);
      
      // Documentos obligatorios según Decreto 1072/2015 Art. 2.2.4.6.8.1.6
      const documentosObligatorios = [
        { tipo: "certificado_arl", nombre: "Certificado ARL Vigente", obligatorio: true },
        { tipo: "matriz_riesgos", nombre: "Matriz de Identificación de Peligros y Riesgos", obligatorio: true },
        { tipo: "politica_sst", nombre: "Política SST Firmada", obligatorio: true },
        { tipo: "afiliacion_seguridad_social", nombre: "Afiliación Seguridad Social", obligatorio: true },
        { tipo: "plan_trabajo_anual", nombre: "Plan de Trabajo Anual SST", obligatorio: proveedor.nivelRiesgoServicio === "critico" },
      ];
      
      // Verificar qué documentos tiene el proveedor
      const documentosPresentes = documentosObligatorios.map(docReq => {
        const docEncontrado = documentos.find(d => d.tipoDocumento === docReq.tipo);
        return {
          tipo: docReq.tipo,
          nombre: docReq.nombre,
          obligatorio: docReq.obligatorio,
          presente: !!docEncontrado,
          vigente: docEncontrado ? docEncontrado.vigente === 1 : false,
          fechaVencimiento: docEncontrado?.fechaVencimiento || null,
        };
      });
      
      // Calcular cumplimiento
      const obligatoriosTotal = documentosPresentes.filter(d => d.obligatorio).length;
      const obligatoriosCumplidos = documentosPresentes.filter(d => d.obligatorio && d.presente && d.vigente).length;
      const porcentajeCumplimiento = obligatoriosTotal > 0 ? Math.round((obligatoriosCumplidos / obligatoriosTotal) * 100) : 0;
      const cumplimientoCompleto = obligatoriosCumplidos === obligatoriosTotal;
      
      res.json({
        proveedorId: proveedor.id,
        razonSocial: proveedor.razonSocial,
        nivelRiesgoServicio: proveedor.nivelRiesgoServicio,
        documentosObligatorios: documentosPresentes,
        obligatoriosTotal,
        obligatoriosCumplidos,
        porcentajeCumplimiento,
        cumplimientoCompleto,
        mensaje: cumplimientoCompleto 
          ? "Cumple con todos los requisitos documentales normativos" 
          : `Faltan ${obligatoriosTotal - obligatoriosCumplidos} documento(s) obligatorio(s)`,
      });
    } catch (error: any) {
      console.error('Error validating documentacion:', error);
      res.status(500).json({ error: error.message || "Error al validar documentación" });
    }
  });

