  // GET /api/adquisiciones-sst/panel/pdf - Generate PDF report for Adquisiciones SST Panel
  app.get("/api/adquisiciones-sst/panel/pdf", requireAuth, async (req, res) => {
    try {
      const companyId = req.user?.companyId;
      if (!companyId) return res.status(401).json({ error: "No autorizado" });

      const company = await storage.getCompany(companyId);
      if (!company) return res.status(404).json({ error: "Empresa no encontrada" });

      const dashboard = await storage.getDashboardAdquisiciones(companyId);
      const solicitudes = await storage.getSolicitudesAdquisicion(companyId);
      const evaluaciones = await storage.getEvaluacionesAdquisicion(companyId);

      const logoBuffer = await loadCompanyLogoBuffer(company.logoUrl);
      // Worker photo not needed for muestreo PDF
      const doc = new PDFDocument({ margin: 35, size: 'LETTER' });
      
      // Add trial watermark if subscription is in trial period
      const pdf27472_subscription = await storage.getSubscriptionByCompany(companyId);
      const pdf27472_trialStatus = getTrialStatus(pdf27472_subscription?.status || 'trial', pdf27472_subscription?.trialEnd || null, true, true);
      setupTrialWatermarkOnAllPages(doc, pdf27472_trialStatus.requiresWatermark);
      const margin = 35;
      const pageWidth = doc.page.width;

      res.setHeader('Content-Type', 'application/pdf');
      res.setHeader('Content-Disposition', `attachment; filename="Informe-Panel-Adquisiciones-SST-${Date.now()}.pdf"`);
      doc.pipe(res);

      const contentStartY = setupPdfHeadersFooters({
        doc,
        company: { name: company.name, nit: company.nit, address: company.address || '' },
        documentTitle: 'INFORME PANEL DE ADQUISICIONES SST',
        documentCode: 'SST-ADQ-PAN-001',
        version: '1.0',
        date: new Date(),
        logoBuffer
      });

      doc.y = contentStartY + 15;

      const drawGreenHeader = (title: string) => {
        const startY = doc.y;
        doc.rect(margin, startY, pageWidth - 2 * margin, 18).fill('#1e7e34');
        doc.fontSize(10).font('Helvetica-Bold').fillColor('#ffffff')
          .text(title, margin + 10, startY + 4, { lineBreak: false });
        doc.fillColor('#000000');
        doc.y = startY + 24;
        doc.x = margin;
      };

      drawGreenHeader('RESUMEN EJECUTIVO');

      doc.fontSize(9).font('Helvetica');
      doc.font('Helvetica-Bold').text('Total de Solicitudes: ', { continued: true });
      doc.font('Helvetica').text(dashboard.totalSolicitudes.toString());

      doc.font('Helvetica-Bold').text('Total de Evaluaciones: ', { continued: true });
      doc.font('Helvetica').text(evaluaciones.length.toString());

      doc.font('Helvetica-Bold').text('Evaluaciones Pendientes: ', { continued: true });
      doc.font('Helvetica').text(dashboard.evaluacionesPendientes.toString());

      doc.font('Helvetica-Bold').text('Presupuesto Total Estimado: ', { continued: true });
      doc.font('Helvetica').text(`$${(dashboard.presupuestoTotal || 0).toLocaleString('es-CO')} COP`);

      doc.moveDown(0.5);
      doc.font('Helvetica-Bold').text('Solicitudes por Estado:');
      const estadoLabels: Record<string, string> = {
        'pendiente': 'Pendiente',
        'en_evaluacion': 'En Evaluación',
        'aprobada': 'Aprobada',
        'rechazada': 'Rechazada',
        'en_compra': 'En Compra',
        'recibida': 'Recibida',
        'cerrada': 'Cerrada'
      };
      Object.entries(dashboard.solicitudesPorEstado).forEach(([estado, count]) => {
        doc.font('Helvetica').text(`  • ${estadoLabels[estado] || estado}: ${count}`);
      });

      doc.moveDown(1.5);
      checkPageSpace(doc, 100);
      drawGreenHeader('SOLICITUDES RECIENTES');
      doc.moveDown(0.3);

      const tipoLabels: Record<string, string> = {
        'epp': 'EPP',
        'maquinaria': 'Maquinaria',
        'herramientas': 'Herramientas',
        'sustancias_quimicas': 'Sustancias Químicas',
        'equipos_emergencia': 'Equipos Emergencia',
        'mobiliario': 'Mobiliario',
        'software': 'Software',
        'servicios': 'Servicios',
        'otros': 'Otros'
      };

      const recentSolicitudes = solicitudes.slice(0, 15);

      if (recentSolicitudes.length === 0) {
        doc.fontSize(9).font('Helvetica').text('No hay solicitudes registradas.');
      } else {
        const tableHeaderY = doc.y;
        const colWidths = [70, 70, 160, 80, 70, 70];
        const headers = ['Número', 'Tipo', 'Descripción', 'Presupuesto', 'Estado', 'Fecha'];

        doc.fontSize(8).font('Helvetica-Bold').fillColor('#1e7e34');
        let xPos = margin;
        headers.forEach((header, i) => {
          doc.text(header, xPos, tableHeaderY, { width: colWidths[i], lineBreak: false });
          xPos += colWidths[i];
        });
        doc.fillColor('#000000');
        doc.moveDown(0.3);
        doc.moveTo(margin, doc.y).lineTo(pageWidth - margin, doc.y).stroke('#1e7e34');
        doc.moveDown(0.3);

        recentSolicitudes.forEach(sol => {
          checkPageSpace(doc, 20);
          const rowY = doc.y;
          doc.fontSize(7).font('Helvetica');
          xPos = margin;

          const truncate = (str: string, maxLen: number) => str.length > maxLen ? str.substring(0, maxLen - 3) + '...' : str;

          doc.text(sol.numeroSolicitud || '-', xPos, rowY, { width: colWidths[0], lineBreak: false });
          xPos += colWidths[0];

          doc.text(tipoLabels[sol.tipoAdquisicion] || sol.tipoAdquisicion, xPos, rowY, { width: colWidths[1], lineBreak: false });
          xPos += colWidths[1];

          doc.text(truncate(sol.descripcion, 40), xPos, rowY, { width: colWidths[2], lineBreak: false });
          xPos += colWidths[2];

          doc.text(sol.presupuestoEstimado ? `$${sol.presupuestoEstimado.toLocaleString('es-CO')}` : '-', xPos, rowY, { width: colWidths[3], lineBreak: false });
          xPos += colWidths[3];

          doc.text(estadoLabels[sol.estado] || sol.estado, xPos, rowY, { width: colWidths[4], lineBreak: false });
          xPos += colWidths[4];

          const fechaSol = sol.fechaSolicitud ? new Date(sol.fechaSolicitud).toLocaleDateString('es-CO') : '-';
          doc.text(fechaSol, xPos, rowY, { width: colWidths[5], lineBreak: false });

          doc.moveDown(0.5);
        });
      }

      doc.moveDown(1.5);
      checkPageSpace(doc, 100);
      drawGreenHeader('EVALUACIONES REALIZADAS');
      doc.moveDown(0.3);

      const recentEvaluaciones = evaluaciones.slice(0, 15);

      if (recentEvaluaciones.length === 0) {
        doc.fontSize(9).font('Helvetica').text('No hay evaluaciones registradas.');
      } else {
        const evalTableHeaderY = doc.y;
        const evalColWidths = [90, 100, 80, 80, 170];
        const evalHeaders = ['No. Solicitud', 'Evaluador', 'Fecha', 'Resultado', 'Recomendaciones'];

        doc.fontSize(8).font('Helvetica-Bold').fillColor('#1e7e34');
        let xPos = margin;
        evalHeaders.forEach((header, i) => {
          doc.text(header, xPos, evalTableHeaderY, { width: evalColWidths[i], lineBreak: false });
          xPos += evalColWidths[i];
        });
        doc.fillColor('#000000');
        doc.moveDown(0.3);
        doc.moveTo(margin, doc.y).lineTo(pageWidth - margin, doc.y).stroke('#1e7e34');
        doc.moveDown(0.3);

        const resultadoLabels: Record<string, string> = {
          'aprobado': 'Cumple',
          'aprobado_condiciones': 'Cumple con condiciones',
          'rechazado': 'No cumple',
          'requiere_controles': 'Requiere controles'
        };

        for (const ev of recentEvaluaciones) {
          checkPageSpace(doc, 20);
          const rowY = doc.y;
          doc.fontSize(7).font('Helvetica');
          xPos = margin;

          const solicitud = solicitudes.find(s => s.id === ev.solicitudId);
          doc.text(solicitud?.numeroSolicitud || '-', xPos, rowY, { width: evalColWidths[0], lineBreak: false });
          xPos += evalColWidths[0];

          doc.text(ev.evaluador || '-', xPos, rowY, { width: evalColWidths[1], lineBreak: false });
          xPos += evalColWidths[1];

          const fechaEv = ev.fechaEvaluacion ? new Date(ev.fechaEvaluacion).toLocaleDateString('es-CO') : '-';
          doc.text(fechaEv, xPos, rowY, { width: evalColWidths[2], lineBreak: false });
          xPos += evalColWidths[2];

          const resultado = ev.resultado ? (resultadoLabels[ev.resultado] || ev.resultado) : '-';
          doc.text(resultado, xPos, rowY, { width: evalColWidths[3], lineBreak: false });
          xPos += evalColWidths[3];

          const recomendaciones = ev.recomendaciones ? (ev.recomendaciones.length > 45 ? ev.recomendaciones.substring(0, 42) + '...' : ev.recomendaciones) : '-';
          doc.text(recomendaciones, xPos, rowY, { width: evalColWidths[4], lineBreak: false });

          doc.moveDown(0.5);
        }
      }

      checkSignatureSpace(doc, 120);
      doc.moveDown(2);

      const signatureY = doc.y;
      const signatureWidth = (pageWidth - 2 * margin - 40) / 2;

      doc.fontSize(8).font('Helvetica');
      doc.moveTo(margin, signatureY).lineTo(margin + signatureWidth, signatureY).stroke('#000000');
      doc.text('Elaborado por: Coordinador SST', margin, signatureY + 5, { width: signatureWidth, align: 'center' });

      doc.moveTo(margin + signatureWidth + 40, signatureY).lineTo(pageWidth - margin, signatureY).stroke('#000000');
      doc.text('Aprobado por: Representante Legal', margin + signatureWidth + 40, signatureY + 5, { width: signatureWidth, align: 'center' });

      doc.moveDown(3);
      doc.fontSize(7).fillColor('#666666').text(
        `Documento generado automáticamente el ${new Date().toLocaleDateString('es-CO', { year: 'numeric', month: 'long', day: 'numeric', hour: '2-digit', minute: '2-digit' })}`,
        margin,
        doc.y,
        { width: pageWidth - 2 * margin, align: 'center' }
      );

      doc.end();
    } catch (error: any) {
      console.error('Error generating adquisiciones panel PDF:', error);
      res.status(500).json({ error: error.message || "Error al generar PDF" });
    }


  });

  // GET /api/evaluacion-proveedores/panel/pdf - Generate PDF report for Evaluación de Proveedores Panel
  app.get("/api/evaluacion-proveedores/panel/pdf", requireAuth, async (req, res) => {
    try {
      const companyId = req.user?.companyId;
      if (!companyId) return res.status(401).json({ error: "No autorizado" });

      const company = await storage.getCompany(companyId);
      if (!company) return res.status(404).json({ error: "Empresa no encontrada" });

      const proveedores = await storage.getProveedoresContratistas(companyId);
      const evaluaciones = await storage.getAllEvaluacionesProveedores(companyId);
      const seguimientos = await storage.getAllSeguimientosProveedores(companyId);

      const logoBuffer = await loadCompanyLogoBuffer(company.logoUrl);
      // Worker photo not needed for muestreo PDF
      const doc = new PDFDocument({ margin: 35, size: 'LETTER' });
      
      // Add trial watermark if subscription is in trial period
      const pdf27704_subscription = await storage.getSubscriptionByCompany(companyId);
      const pdf27704_trialStatus = getTrialStatus(pdf27704_subscription?.status || 'trial', pdf27704_subscription?.trialEnd || null, true, true);
      setupTrialWatermarkOnAllPages(doc, pdf27704_trialStatus.requiresWatermark);
      const margin = 35;
      const pageWidth = doc.page.width;

      res.setHeader('Content-Type', 'application/pdf');
      res.setHeader('Content-Disposition', `attachment; filename="Informe-Panel-Evaluacion-Proveedores-SST-${Date.now()}.pdf"`);
      doc.pipe(res);

      const contentStartY = setupPdfHeadersFooters({
        doc,
        company: { name: company.name, nit: company.nit, address: company.address || '' },
        documentTitle: 'INFORME PANEL DE EVALUACIÓN DE PROVEEDORES SST',
        documentCode: 'SST-PROV-PAN-001',
        version: '1.0',
        date: new Date(),
        logoBuffer
      });

      doc.y = contentStartY + 15;

      const drawGreenHeader = (title: string) => {
        const startY = doc.y;
        doc.rect(margin, startY, pageWidth - 2 * margin, 18).fill('#1e7e34');
        doc.fontSize(10).font('Helvetica-Bold').fillColor('#ffffff')
          .text(title, margin + 10, startY + 4, { lineBreak: false });
        doc.fillColor('#000000');
        doc.y = startY + 24;
        doc.x = margin;
      };

      // Calculate statistics
      const totalProveedores = proveedores.length;
      const proveedoresAprobados = proveedores.filter(p => p.estadoEvaluacion === 'aprobado').length;
      const proveedoresRechazados = proveedores.filter(p => p.estadoEvaluacion === 'rechazado').length;
      const proveedoresSinEvaluar = proveedores.filter(p => !p.estadoEvaluacion || p.estadoEvaluacion === 'pendiente').length;
      const totalEvaluaciones = evaluaciones.length;
      
      // Seguimientos del mes actual
      const now = new Date();
      const startOfMonth = new Date(now.getFullYear(), now.getMonth(), 1);
      const seguimientosMes = seguimientos.filter(s => {
        const fecha = new Date(s.fechaSeguimiento);
        return fecha >= startOfMonth && fecha <= now;
      }).length;

      drawGreenHeader('RESUMEN EJECUTIVO');

      doc.fontSize(9).font('Helvetica');
      doc.font('Helvetica-Bold').text('Total de Proveedores: ', { continued: true });
      doc.font('Helvetica').text(totalProveedores.toString());

      doc.font('Helvetica-Bold').text('Proveedores Aprobados: ', { continued: true });
      doc.font('Helvetica').text(proveedoresAprobados.toString());

      doc.font('Helvetica-Bold').text('Proveedores Rechazados: ', { continued: true });
      doc.font('Helvetica').text(proveedoresRechazados.toString());

      doc.font('Helvetica-Bold').text('Sin Evaluar / Pendiente: ', { continued: true });
      doc.font('Helvetica').text(proveedoresSinEvaluar.toString());

      doc.font('Helvetica-Bold').text('Total de Evaluaciones: ', { continued: true });
      doc.font('Helvetica').text(totalEvaluaciones.toString());

      doc.font('Helvetica-Bold').text('Seguimientos del Mes: ', { continued: true });
      doc.font('Helvetica').text(seguimientosMes.toString());

      doc.moveDown(1.5);
      checkPageSpace(doc, 100);
      drawGreenHeader('DISTRIBUCIÓN POR ESTADO');
      doc.moveDown(0.3);

      const estadoLabels: Record<string, string> = {
        'aprobado': 'Aprobado',
        'rechazado': 'Rechazado',
        'pendiente': 'Pendiente',
        'en_proceso': 'En Proceso',
        'condicional': 'Condicional',
        'suspendido': 'Suspendido'
      };

      // Count by estado
      const estadoCounts: Record<string, number> = {};
      proveedores.forEach(p => {
        const estado = p.estadoEvaluacion || 'pendiente';
        estadoCounts[estado] = (estadoCounts[estado] || 0) + 1;
      });

      doc.fontSize(9).font('Helvetica');
      Object.entries(estadoCounts).forEach(([estado, count]) => {
        doc.text(`  • ${estadoLabels[estado] || estado}: ${count}`);
      });

      doc.moveDown(1.5);
      checkPageSpace(doc, 120);
      drawGreenHeader('TOP 5 PROVEEDORES MEJOR CALIFICADOS');
      doc.moveDown(0.3);

      // Sort by ultimaCalificacion and take top 5
      const top5 = [...proveedores]
        .filter(p => p.ultimaCalificacion !== null && p.ultimaCalificacion !== undefined)
        .sort((a, b) => (b.ultimaCalificacion || 0) - (a.ultimaCalificacion || 0))
        .slice(0, 5);

      if (top5.length > 0) {
        const topTableHeaderY = doc.y;
        const topColWidths = [180, 100, 80, 100];
        const topHeaders = ['Razón Social', 'Tipo', 'Calificación', 'Estado'];

        doc.fontSize(8).font('Helvetica-Bold').fillColor('#1e7e34');
        let xPos = margin;
        topHeaders.forEach((header, i) => {
          doc.text(header, xPos, topTableHeaderY, { width: topColWidths[i], lineBreak: false });
          xPos += topColWidths[i];
        });
        doc.fillColor('#000000');
        doc.moveDown(0.3);
        doc.moveTo(margin, doc.y).lineTo(pageWidth - margin, doc.y).stroke('#1e7e34');
        doc.moveDown(0.3);

        const tipoLabels: Record<string, string> = {
          'proveedor': 'Proveedor',
          'contratista': 'Contratista',
          'subcontratista': 'Subcontratista'
        };

        for (const prov of top5) {
          checkPageSpace(doc, 20);
          const rowY = doc.y;
          doc.fontSize(7).font('Helvetica');
          xPos = margin;

          const razon = prov.razonSocial.length > 35 ? prov.razonSocial.substring(0, 32) + '...' : prov.razonSocial;
          doc.text(razon, xPos, rowY, { width: topColWidths[0], lineBreak: false });
          xPos += topColWidths[0];

          doc.text(tipoLabels[prov.tipoProveedor] || prov.tipoProveedor, xPos, rowY, { width: topColWidths[1], lineBreak: false });
          xPos += topColWidths[1];

          doc.text(`${prov.ultimaCalificacion || 0}%`, xPos, rowY, { width: topColWidths[2], lineBreak: false });
          xPos += topColWidths[2];

          doc.text(estadoLabels[prov.estadoEvaluacion || 'pendiente'] || prov.estadoEvaluacion || 'Pendiente', xPos, rowY, { width: topColWidths[3], lineBreak: false });

          doc.moveDown(0.5);
        }
      } else {
        doc.fontSize(9).font('Helvetica-Oblique').text('No hay proveedores con calificación registrada.');
      }

      doc.moveDown(1.5);
      checkPageSpace(doc, 120);
      drawGreenHeader('EVALUACIONES RECIENTES');
      doc.moveDown(0.3);

      // Get recent evaluations (last 10)
      const recentEvaluaciones = [...evaluaciones]
        .sort((a, b) => new Date(b.fechaEvaluacion).getTime() - new Date(a.fechaEvaluacion).getTime())
        .slice(0, 10);

      if (recentEvaluaciones.length > 0) {
        const evalTableHeaderY = doc.y;
        const evalColWidths = [140, 80, 80, 80, 140];
        const evalHeaders = ['Proveedor', 'Tipo', 'Fecha', 'Puntaje', 'Observaciones'];

        doc.fontSize(8).font('Helvetica-Bold').fillColor('#1e7e34');
        let xPos = margin;
        evalHeaders.forEach((header, i) => {
          doc.text(header, xPos, evalTableHeaderY, { width: evalColWidths[i], lineBreak: false });
          xPos += evalColWidths[i];
        });
        doc.fillColor('#000000');
        doc.moveDown(0.3);
        doc.moveTo(margin, doc.y).lineTo(pageWidth - margin, doc.y).stroke('#1e7e34');
        doc.moveDown(0.3);

        const tipoEvaluacionLabels: Record<string, string> = {
          'inicial': 'Inicial',
          'seguimiento': 'Seguimiento',
          'reevaluacion': 'Reevaluación'
        };

        for (const ev of recentEvaluaciones) {
          checkPageSpace(doc, 20);
          const rowY = doc.y;
          doc.fontSize(7).font('Helvetica');
          xPos = margin;

          const proveedor = proveedores.find(p => p.id === ev.proveedorId);
          const provNombre = proveedor ? (proveedor.razonSocial.length > 30 ? proveedor.razonSocial.substring(0, 27) + '...' : proveedor.razonSocial) : '-';
          doc.text(provNombre, xPos, rowY, { width: evalColWidths[0], lineBreak: false });
          xPos += evalColWidths[0];

          doc.text(tipoEvaluacionLabels[ev.tipoEvaluacion] || ev.tipoEvaluacion, xPos, rowY, { width: evalColWidths[1], lineBreak: false });
          xPos += evalColWidths[1];

          const fechaEv = ev.fechaEvaluacion ? new Date(ev.fechaEvaluacion).toLocaleDateString('es-CO') : '-';
          doc.text(fechaEv, xPos, rowY, { width: evalColWidths[2], lineBreak: false });
          xPos += evalColWidths[2];

          doc.text(`${ev.puntajeTotal || 0}%`, xPos, rowY, { width: evalColWidths[3], lineBreak: false });
          xPos += evalColWidths[3];

          const obs = ev.observaciones ? (ev.observaciones.length > 35 ? ev.observaciones.substring(0, 32) + '...' : ev.observaciones) : '-';
          doc.text(obs, xPos, rowY, { width: evalColWidths[4], lineBreak: false });

          doc.moveDown(0.5);
        }
      } else {
        doc.fontSize(9).font('Helvetica-Oblique').text('No hay evaluaciones registradas.');
      }

      checkSignatureSpace(doc, 120);
      doc.moveDown(2);
      doc.fontSize(8).font('Helvetica-Oblique').fillColor('#666666');
      doc.text(`Documento generado el ${new Date().toLocaleDateString('es-CO')} a las ${new Date().toLocaleTimeString('es-CO')}`, margin);
      doc.fillColor('#000000');

      doc.end();
    } catch (error: any) {
      console.error('Error generating evaluacion proveedores panel PDF:', error);
      res.status(500).json({ error: error.message || "Error al generar PDF" });
    }
  });

  // GET /api/gestion-cambios/panel/pdf - Generate PDF report for Gestión de Cambios SST Panel
  app.get("/api/gestion-cambios/panel/pdf", requireAuth, async (req, res) => {
    try {
      const companyId = req.user?.companyId;
      if (!companyId) return res.status(401).json({ error: "No autorizado" });

      const company = await storage.getCompany(companyId);
      if (!company) return res.status(404).json({ error: "Empresa no encontrada" });

      const cambios = await storage.getCambiosSst(companyId);
      const automatizaciones = await storage.getAutomatizacionLogsForCompany(companyId);

      const logoBuffer = await loadCompanyLogoBuffer(company.logoUrl);
      // Worker photo not needed for muestreo PDF
      const doc = new PDFDocument({ margin: 35, size: 'LETTER' });
      
      // Add trial watermark if subscription is in trial period
      const pdf27942_subscription = await storage.getSubscriptionByCompany(companyId);
      const pdf27942_trialStatus = getTrialStatus(pdf27942_subscription?.status || 'trial', pdf27942_subscription?.trialEnd || null, true, true);
      setupTrialWatermarkOnAllPages(doc, pdf27942_trialStatus.requiresWatermark);
      const margin = 35;
      const pageWidth = doc.page.width;
      const contentWidth = pageWidth - 2 * margin;

      res.setHeader('Content-Type', 'application/pdf');
      res.setHeader('Content-Disposition', `attachment; filename="Informe-Panel-Gestion-Cambios-SST-${Date.now()}.pdf"`);
      doc.pipe(res);

      const contentStartY = setupPdfHeadersFooters({
        doc,
        company: { name: company.name, nit: company.nit, address: company.address || '' },
        documentTitle: 'INFORME PANEL DE GESTIÓN DE CAMBIOS SST',
        documentCode: 'SST-GC-PAN-001',
        version: '1.0',
        date: new Date(),
        logoBuffer
      });

      doc.y = contentStartY + 15;

      const drawGreenHeader = (title: string) => {
        const startY = doc.y;
        doc.rect(margin, startY, contentWidth, 18).fill('#1e7e34');
        doc.fontSize(10).font('Helvetica-Bold').fillColor('#ffffff')
          .text(title, margin + 10, startY + 4, { lineBreak: false });
        doc.fillColor('#000000');
        doc.y = startY + 24;
        doc.x = margin;
      };

      // RESUMEN EJECUTIVO
      drawGreenHeader('RESUMEN EJECUTIVO');

      const totalCambios = cambios.length;
      const enEvaluacion = cambios.filter(c => c.estado === 'en_evaluacion' || c.estado === 'propuesto').length;
      const aprobados = cambios.filter(c => c.estado === 'aprobado' || c.estado === 'implementado').length;
      const enImplementacion = cambios.filter(c => c.estado === 'en_implementacion').length;

      doc.fontSize(9).font('Helvetica');
      doc.font('Helvetica-Bold').text('Total Cambios: ', { continued: true });
      doc.font('Helvetica').text(totalCambios.toString());

      doc.font('Helvetica-Bold').text('En Evaluación: ', { continued: true });
      doc.font('Helvetica').text(enEvaluacion.toString());

      doc.font('Helvetica-Bold').text('Aprobados: ', { continued: true });
      doc.font('Helvetica').text(aprobados.toString());

      doc.font('Helvetica-Bold').text('En Implementación: ', { continued: true });
      doc.font('Helvetica').text(enImplementacion.toString());

      doc.moveDown(1.5);

      // AUTOMATIZACIONES EJECUTADAS
      drawGreenHeader('AUTOMATIZACIONES EJECUTADAS');

      const totalAutomatizaciones = automatizaciones.length;
      const exitosas = automatizaciones.filter(a => a.estado === 'exito').length;
      const errores = automatizaciones.filter(a => a.estado === 'error').length;
      const pendientes = automatizaciones.filter(a => a.estado === 'pendiente').length;

      doc.fontSize(9).font('Helvetica');
      doc.font('Helvetica-Bold').text('Total Ejecutadas: ', { continued: true });
      doc.font('Helvetica').text(totalAutomatizaciones.toString());

      doc.font('Helvetica-Bold').text('Exitosas: ', { continued: true });
      doc.font('Helvetica').text(exitosas.toString());

      doc.font('Helvetica-Bold').text('Errores: ', { continued: true });
      doc.font('Helvetica').text(errores.toString());

      doc.font('Helvetica-Bold').text('Pendientes: ', { continued: true });
      doc.font('Helvetica').text(pendientes.toString());

      doc.moveDown(0.5);

      // Group by module
      const moduleLabels: Record<string, string> = {
        'matriz_riesgos': 'Matriz de Riesgos',
        'plan_trabajo': 'Plan Anual de Trabajo',
        'capacitaciones': 'Capacitaciones',
        'copasst': 'Aprobación COPASST',
        'matriz_legal': 'Matriz Legal',
        'notificaciones': 'Notificaciones',
        'indicadores_sst': 'Indicadores SST'
      };

      const byModule: Record<string, number> = {};
      automatizaciones.forEach(a => {
        const mod = a.moduloDestino || 'otros';
        byModule[mod] = (byModule[mod] || 0) + 1;
      });

      doc.font('Helvetica-Bold').text('Automatizaciones por Módulo:');
      Object.entries(byModule).forEach(([mod, count]) => {
        doc.font('Helvetica').text(`  • ${moduleLabels[mod] || mod}: ${count}`);
      });

      doc.moveDown(1.5);

      // REGISTROS RECIENTES
      drawGreenHeader('REGISTROS RECIENTES');
      doc.moveDown(0.3);

      const recentCambios = cambios.slice(0, 10);

      if (recentCambios.length === 0) {
        doc.fontSize(9).font('Helvetica').text('No hay cambios registrados.');
      } else {
        const tableY = doc.y;
        const colWidths = [70, 120, 80, 250];
        const totalTableWidth = colWidths.reduce((a, b) => a + b, 0);

        // Header
        doc.rect(margin, tableY, totalTableWidth, 16).fill('#1e7e34');
        let xPos = margin;
        doc.fontSize(8).font('Helvetica-Bold').fillColor('#ffffff');
        doc.text('Fecha', xPos + 3, tableY + 4, { width: colWidths[0] - 6 });
        xPos += colWidths[0];
        doc.text('Tipo', xPos + 3, tableY + 4, { width: colWidths[1] - 6 });
        xPos += colWidths[1];
        doc.text('Estado', xPos + 3, tableY + 4, { width: colWidths[2] - 6 });
        xPos += colWidths[2];
        doc.text('Descripción', xPos + 3, tableY + 4, { width: colWidths[3] - 6 });

        doc.fillColor('#000000');
        let rowY = tableY + 16;

        const estadoLabels: Record<string, string> = {
          'propuesto': 'Propuesto',
          'en_evaluacion': 'En Evaluación',
          'aprobado': 'Aprobado',
          'rechazado': 'Rechazado',
          'en_implementacion': 'En Implementación',
          'implementado': 'Implementado',
          'cancelado': 'Cancelado'
        };

        const tipoLabels: Record<string, string> = {
          'proceso': 'Proceso',
          'tecnologia': 'Tecnología',
          'infraestructura': 'Infraestructura',
          'organizacional': 'Organizacional',
          'legal': 'Legal',
          'otro': 'Otro'
        };

        recentCambios.forEach((cambio, idx) => {
          const bgColor = idx % 2 === 0 ? '#ffffff' : '#f5f5f5';
          doc.rect(margin, rowY, totalTableWidth, 14).fill(bgColor);

          xPos = margin;
          doc.fontSize(7).font('Helvetica').fillColor('#000000');
          const fecha = cambio.fechaPropuesta ? new Date(cambio.fechaPropuesta).toLocaleDateString('es-CO') : '-';
          doc.text(fecha, xPos + 3, rowY + 4, { width: colWidths[0] - 6 });
          xPos += colWidths[0];
          doc.text(tipoLabels[cambio.tipoCambio] || cambio.tipoCambio, xPos + 3, rowY + 4, { width: colWidths[1] - 6 });
          xPos += colWidths[1];
          doc.text(estadoLabels[cambio.estado] || cambio.estado, xPos + 3, rowY + 4, { width: colWidths[2] - 6 });
          xPos += colWidths[2];
          const desc = cambio.descripcion || '-';
          doc.text(desc, xPos + 3, rowY + 4, { width: colWidths[3] - 6, lineBreak: true });

          rowY += 14;
        });
      }

      doc.moveDown(2);
      doc.fontSize(8).font('Helvetica').fillColor('#666666');
      doc.text(`Documento generado automáticamente el ${new Date().toLocaleDateString('es-CO')} a las ${new Date().toLocaleTimeString('es-CO')}.`, margin, doc.y, { align: 'center', width: contentWidth });

      doc.end();
    } catch (error: any) {
      console.error('Error generating gestion cambios panel PDF:', error);
      res.status(500).json({ error: error.message || "Error al generar PDF" });
    }
  });

