      doc.text(`Total de Revisiones: ${data.length}`, margin, currentY);
      currentY = doc.y + 15;

      // Executive Summary
      doc.fontSize(9).font('Helvetica-Bold').fillColor('#1e7e34').text('RESUMEN EJECUTIVO', margin, currentY);
