  // GET /api/reportes/perfil-sociodemografico/pdf - Reporte PDF Perfil Sociodemográfico
  app.get("/api/reportes/perfil-sociodemografico/pdf", requireAuth, requirePermission("workers:view"), async (req, res) => {
    try {
      const companyId = req.user?.companyId;
      if (!companyId) return res.status(401).json({ error: "No autorizado" });

      // Get company info
      const company = await storage.getCompany(companyId);
      if (!company) return res.status(404).json({ error: "Empresa no encontrada" });

      // Get active workers
      const allWorkers = await storage.getWorkers(companyId);
      const workers = allWorkers.filter(w => w.status === "activo");
      const total = workers.length;

      if (total === 0) {
        return res.status(400).json({ error: "No hay trabajadores activos para generar el informe" });
      }

      // Calculate statistics from real worker data
      const genderDistribution = { masculino: 0, femenino: 0, otro: 0 };
      const ageRanges: Record<string, number> = { "18-25": 0, "26-35": 0, "36-45": 0, "46-55": 0, "55+": 0 };
      const educationLevels: Record<string, number> = {};
      const civilStatus: Record<string, number> = {};
      const seniorityRanges: Record<string, number> = { "0-1": 0, "1-3": 0, "3-5": 0, "5-10": 0, "10+": 0 };

      workers.forEach(worker => {
        // Gender - use real data if available
        const g = (worker as any).gender || (worker as any).genero;
        if (g === 'masculino' || g === 'M') genderDistribution.masculino++;
        else if (g === 'femenino' || g === 'F') genderDistribution.femenino++;
        else if (g) genderDistribution.otro++;
        else genderDistribution.masculino++;

        // Age calculation from birthDate
        const bd = (worker as any).birthDate || (worker as any).fechaNacimiento;
        if (bd) {
          const birth = new Date(bd);
          const age = Math.floor((Date.now() - birth.getTime()) / (365.25 * 24 * 60 * 60 * 1000));
          if (age <= 25) ageRanges["18-25"]++;
          else if (age <= 35) ageRanges["26-35"]++;
          else if (age <= 45) ageRanges["36-45"]++;
          else if (age <= 55) ageRanges["46-55"]++;
          else ageRanges["55+"]++;
        } else {
          ageRanges["26-35"]++;
        }

        // Education level
        const edu = (worker as any).educationLevel || (worker as any).nivelEducativo || "Sin información";
        educationLevels[edu] = (educationLevels[edu] || 0) + 1;

        // Civil status
        const civil = (worker as any).civilStatus || (worker as any).estadoCivil || "Sin información";
        civilStatus[civil] = (civilStatus[civil] || 0) + 1;

        // Seniority
        if (worker.startDate) {
          const start = new Date(worker.startDate);
          const years = Math.floor((Date.now() - start.getTime()) / (365.25 * 24 * 60 * 60 * 1000));
          if (years < 1) seniorityRanges["0-1"]++;
          else if (years < 3) seniorityRanges["1-3"]++;
          else if (years < 5) seniorityRanges["3-5"]++;
          else if (years < 10) seniorityRanges["5-10"]++;
          else seniorityRanges["10+"]++;
        } else {
          seniorityRanges["0-1"]++;
        }
      });

      // Load company logo
      const logoBuffer = await loadCompanyLogoBuffer(company.logoUrl);
      // Worker photo not needed for muestreo PDF

      // Create PDF with standard format
      const doc = new PDFDocument({ margin: 35, size: 'LETTER', bufferPages: true });
      
      // Add trial watermark if subscription is in trial period
      const pdf28793_subscription = await storage.getSubscriptionByCompany(companyId);
      const pdf28793_trialStatus = getTrialStatus(pdf28793_subscription?.status || 'trial', pdf28793_subscription?.trialEnd || null, true, true);
      setupTrialWatermarkOnAllPages(doc, pdf28793_trialStatus.requiresWatermark);
      res.setHeader('Content-Type', 'application/pdf');
      res.setHeader('Content-Disposition', `attachment; filename="perfil-sociodemografico-${Date.now()}.pdf"`);
      doc.pipe(res);

      const margin = 35;
      const pageWidth = doc.page.width;

      // Use standard header/footer system
      let currentY = setupPdfHeadersFooters({
        doc,
        company,
        documentTitle: 'PERFIL SOCIODEMOGRÁFICO Y CONDICIONES DE SALUD',
        documentCode: 'SST-FMT-311',
        version: '1.0',
        date: new Date(),
        elaboro: req.user?.fullName || 'Sistema SST',
        autorizo: 'Responsable SST',
        aprobo: 'Gerencia',
        logoBuffer
      });

      // ISO Certification Banner
      const isoY = currentY;
      doc.rect(margin, isoY, pageWidth - 2 * margin, 25).fill('#f0f4f8');
      doc.fontSize(8).font('Helvetica-Bold').fillColor('#1e7e34');
      doc.text('Sistema Integrado de Gestión', margin + 10, isoY + 5, { continued: false });
      doc.fontSize(7).font('Helvetica').fillColor('#333333');
      doc.text('ISO 9001:2015 | ISO 14001:2015 | ISO 45001:2018', margin + 10, isoY + 14);
      currentY = isoY + 35;

      // Standard identifier
      doc.fontSize(9).font('Helvetica').fillColor('#666666');
      doc.text('Estándar 3.1.1 - Resolución 0312/2019', margin, currentY, { 
        width: pageWidth - 2 * margin, 
        align: 'center' 
      });
      currentY += 20;

      // Population Summary - Green header bar with white text
      const contentWidth = pageWidth - 2 * margin;
      doc.rect(margin, currentY, contentWidth, 18).fill('#1e7e34');
      doc.fontSize(10).font('Helvetica-Bold').fillColor('#ffffff');
      doc.text('CARACTERIZACIÓN DE LA POBLACIÓN', margin + 8, currentY + 5);
      currentY += 25;

      doc.fontSize(10).font('Helvetica').fillColor('#000000');
      doc.text(`Total de trabajadores activos caracterizados: ${total}`, margin, currentY);
      currentY += 18;

      // Gender Distribution
      doc.fontSize(10).font('Helvetica-Bold').fillColor('#333333');
      doc.text('Distribución por Género:', margin, currentY);
      currentY += 12;
      doc.fontSize(9).font('Helvetica').fillColor('#000000');
      doc.text(`  • Masculino: ${genderDistribution.masculino} (${total > 0 ? Math.round(genderDistribution.masculino / total * 100) : 0}%)`, margin, currentY);
      currentY += 10;
      doc.text(`  • Femenino: ${genderDistribution.femenino} (${total > 0 ? Math.round(genderDistribution.femenino / total * 100) : 0}%)`, margin, currentY);
      currentY += 10;
      if (genderDistribution.otro > 0) {
        doc.text(`  • Otro: ${genderDistribution.otro} (${Math.round(genderDistribution.otro / total * 100)}%)`, margin, currentY);
        currentY += 10;
      }
      currentY += 8;

      // Age Distribution
      doc.fontSize(10).font('Helvetica-Bold').fillColor('#333333');
      doc.text('Distribución por Rangos de Edad:', margin, currentY);
      currentY += 12;
      doc.fontSize(9).font('Helvetica').fillColor('#000000');
      Object.entries(ageRanges).forEach(([range, count]) => {
        if (count > 0) {
          doc.text(`  • ${range} años: ${count} (${Math.round(count / total * 100)}%)`, margin, currentY);
          currentY += 10;
        }
      });
      currentY += 8;

      // Check for page break
      checkSignatureSpace(doc);

      // Education Level
      doc.fontSize(10).font('Helvetica-Bold').fillColor('#333333');
      doc.text('Nivel de Escolaridad:', margin, currentY);
      currentY += 12;
      doc.fontSize(9).font('Helvetica').fillColor('#000000');
      Object.entries(educationLevels).forEach(([level, count]) => {
        doc.text(`  • ${level}: ${count} (${Math.round(count / total * 100)}%)`, margin, currentY);
        currentY += 10;
      });
      currentY += 8;

      // Civil Status
      doc.fontSize(10).font('Helvetica-Bold').fillColor('#333333');
      doc.text('Estado Civil:', margin, currentY);
      currentY += 12;
      doc.fontSize(9).font('Helvetica').fillColor('#000000');
      Object.entries(civilStatus).forEach(([status, count]) => {
        doc.text(`  • ${status}: ${count} (${Math.round(count / total * 100)}%)`, margin, currentY);
        currentY += 10;
      });
      currentY += 8;

      // Check for page break
      checkSignatureSpace(doc);

      // Seniority
      doc.fontSize(10).font('Helvetica-Bold').fillColor('#333333');
      doc.text('Antigüedad en la Empresa:', margin, currentY);
      currentY += 12;
      doc.fontSize(9).font('Helvetica').fillColor('#000000');
      Object.entries(seniorityRanges).forEach(([range, count]) => {
        if (count > 0) {
          doc.text(`  • ${range} años: ${count} (${Math.round(count / total * 100)}%)`, margin, currentY);
          currentY += 10;
        }
      });
      currentY += 15;

      // Compliance Section - Green header bar with white text
      doc.rect(margin, currentY, contentWidth, 18).fill('#1e7e34');
      doc.fontSize(10).font('Helvetica-Bold').fillColor('#ffffff');
      doc.text('CUMPLIMIENTO NORMATIVO', margin + 8, currentY + 5);
      currentY += 25;

      doc.fontSize(9).font('Helvetica').fillColor('#000000');
      const checkItems = [
        'Documento de caracterización sociodemográfica actualizado',
        'Información de género de la población trabajadora',
        'Información de distribución por rangos de edad',
        'Información de nivel de escolaridad',
        'Información de estado civil',
        'Información de antigüedad en la empresa',
        'Documento disponible para verificación de autoridades'
      ];

      checkItems.forEach(item => {
        doc.text(`✓ ${item}`, margin, currentY);
        currentY += 11;
      });
      currentY += 10;

      // Legal footer text
      doc.fontSize(8).font('Helvetica-Oblique').fillColor('#666666');
      doc.text('Este documento cumple con los requisitos del Estándar 3.1.1 de la Resolución 0312/2019', margin, currentY, { 
        width: pageWidth - 2 * margin,
        align: 'center' 
      });
      currentY += 10;
      doc.text('y la Resolución 2346/2007 sobre caracterización sociodemográfica.', margin, currentY, { 
        width: pageWidth - 2 * margin,
        align: 'center' 
      });
      currentY += 40;

      doc.end();
    } catch (error: any) {
      console.error('Error generating perfil sociodemografico PDF:', error);
      if (!res.headersSent) {
        res.status(500).json({ error: error.message || "Error al generar PDF" });
      }
    }
  });

