  // POST /api/adquisiciones-sst - Crear nueva solicitud de adquisición
  app.post("/api/adquisiciones-sst", requireAuth, async (req, res) => {
    try {
      const companyId = req.user?.companyId;
      if (!companyId) return res.status(401).json({ error: "No autorizado" });
      
      const validatedData = insertSolicitudAdquisicionSchema.parse(req.body);
      const solicitud = await storage.createSolicitudAdquisicion(validatedData, companyId);
      
      res.status(201).json(solicitud);
    } catch (error: any) {
      console.error('Error creating solicitud adquisición:', error);
      res.status(500).json({ error: error.message || "Error al crear solicitud de adquisición" });
    }
  });

  // PATCH /api/adquisiciones-sst/:id - Actualizar solicitud de adquisición
  app.patch("/api/adquisiciones-sst/:id", requireAuth, async (req, res) => {
    try {
      const companyId = req.user?.companyId;
      if (!companyId) return res.status(401).json({ error: "No autorizado" });
      
      // Get current solicitud to check state change
      const currentSolicitud = await storage.getSolicitudAdquisicion(req.params.id, companyId);
      if (!currentSolicitud) {
        return res.status(404).json({ error: "Solicitud no encontrada" });
      }
      
      const validatedData = insertSolicitudAdquisicionSchema.partial().parse(req.body);
      
      // Capture old values before update
      const oldEstado = currentSolicitud.estado;
      const oldPresupuesto = currentSolicitud.presupuestoEstimado;
      const oldRecursoId = currentSolicitud.recursoFinancieroId;
      
      const solicitud = await storage.updateSolicitudAdquisicion(req.params.id, validatedData, companyId);
      if (!solicitud) {
        return res.status(404).json({ error: "Solicitud no encontrada" });
      }
      
      // Determine new values (use updated value if provided, otherwise keep old)
      const newEstado = validatedData.estado !== undefined ? validatedData.estado : oldEstado;
      const newPresupuesto = validatedData.presupuestoEstimado !== undefined ? validatedData.presupuestoEstimado : oldPresupuesto;
      const newRecursoId = validatedData.recursoFinancieroId !== undefined ? validatedData.recursoFinancieroId : oldRecursoId;
      
      // Handle budget tracking for all scenarios
      // Case 1: Estado changes TO "comprada" from any other state
      if (newEstado === "comprada" && oldEstado !== "comprada") {
        if (newRecursoId && newPresupuesto && newPresupuesto > 0) {
          await storage.updateMontoEjecutado(newRecursoId, newPresupuesto, companyId);
        }
      }
      // Case 2: Estado changes FROM "comprada" to any other state
      else if (oldEstado === "comprada" && newEstado !== "comprada") {
        if (oldRecursoId && oldPresupuesto && oldPresupuesto > 0) {
          await storage.updateMontoEjecutado(oldRecursoId, -oldPresupuesto, companyId);
        }
      }
      // Case 3: Estado stays "comprada" but resource or amount may have changed
      else if (oldEstado === "comprada" && newEstado === "comprada") {
        // Check if resource changed
        if (oldRecursoId !== newRecursoId) {
          // Subtract from old resource
          if (oldRecursoId && oldPresupuesto && oldPresupuesto > 0) {
            await storage.updateMontoEjecutado(oldRecursoId, -oldPresupuesto, companyId);
          }
          // Add to new resource
          if (newRecursoId && newPresupuesto && newPresupuesto > 0) {
            await storage.updateMontoEjecutado(newRecursoId, newPresupuesto, companyId);
          }
        }
        // Same resource, but amount changed
        else if (oldPresupuesto !== newPresupuesto && newRecursoId) {
          const difference = (newPresupuesto || 0) - (oldPresupuesto || 0);
          if (difference !== 0) {
            await storage.updateMontoEjecutado(newRecursoId, difference, companyId);
          }
        }
      }
      
      res.json(solicitud);
    } catch (error: any) {
      console.error('Error updating solicitud adquisición:', error);
      res.status(500).json({ error: error.message || "Error al actualizar solicitud de adquisición" });
    }
  });

