  // POST /api/comunicaciones-sst - Crear y enviar nueva comunicación
  app.post("/api/comunicaciones-sst", requireAuth, requirePermission("comunicaciones_sst:create"), async (req, res) => {
    try {
      const companyId = req.user?.companyId;
      const userId = req.user?.id;
      if (!companyId || !userId) return res.status(401).json({ error: "No autorizado" });
      
      // Extract trabajadoresDestinatarios from request body
      const { trabajadoresDestinatarios, ...comunicacionData } = req.body;
      
      const validatedData = insertComunicacionSstSchema.parse(comunicacionData);
      const comunicacion = await storage.createComunicacionSst(
        validatedData, 
        companyId, 
        userId,
        trabajadoresDestinatarios || []
      );
      
      // Send notifications to each worker in the recipients list
      try {
        if (trabajadoresDestinatarios && trabajadoresDestinatarios.length > 0) {
          const fechaFormateada = validatedData.fechaEnvio 
            ? new Date(validatedData.fechaEnvio).toLocaleDateString('es-CO', { year: 'numeric', month: 'long', day: 'numeric' })
            : new Date().toLocaleDateString('es-CO', { year: 'numeric', month: 'long', day: 'numeric' });
          
          for (const workerId of trabajadoresDestinatarios) {
            try {
              const worker = await storage.getWorkerById(workerId);
              if (worker) {
                const workerUser = await storage.getUserByWorkerId(worker.id);
                if (workerUser) {
                  await storage.createInternalMessage({
                    companyId,
                    senderId: req.user!.id,
                    senderName: req.user!.fullName || req.user!.username,
                    senderRole: req.user!.role,
                    receiverId: workerUser.id,
                    receiverName: workerUser.fullName || workerUser.username,
                    receiverRole: workerUser.role,
                    subject: 'Nueva Comunicación SST',
                    content: 'Se le ha enviado una nueva comunicacion de Seguridad y Salud en el Trabajo.' + '\n\nTitulo: ' + (validatedData.titulo || 'Sin titulo') + '\nTipo: ' + (validatedData.tipoComunicacion || 'General') + '\nFecha: ' + fechaFormateada + '\n\nPor favor, revise la comunicacion en el portal.',
                    priority: 'normal',
                    status: 'unread',
                    relatedEntity: 'comunicacion_sst',
                    relatedEntityId: comunicacion.id
                  });
                }
              }
            } catch (workerNotifError) {
              console.error('Error sending notification to worker ' + workerId + ':', workerNotifError);
            }
          }
        }
      } catch (notifError) {
        console.error('Error sending portal notifications for comunicación SST:', notifError);
      }
      
      res.status(201).json(comunicacion);
    } catch (error: any) {
      console.error('Error creating comunicación SST:', error);
      res.status(500).json({ error: error.message || "Error al crear comunicación" });
    }
  });

