  // GET /api/comunicaciones-sst/:id/pdf - Generar PDF de comunicación SST
  app.get("/api/comunicaciones-sst/:id/pdf", requireAuth, requirePermission("comunicaciones_sst:view"), async (req, res) => {
    try {
      const companyId = req.user?.companyId;
      if (!companyId) return res.status(401).json({ error: "No autorizado" });

      // Get communication
      const comunicacion = await storage.getComunicacionSstById(req.params.id, companyId);
      if (!comunicacion) {
        return res.status(404).json({ error: "Comunicación no encontrada" });
      }

      // Get company info
      const company = await storage.getCompany(companyId);
      if (!company) return res.status(404).json({ error: "Empresa no encontrada" });

      // Get sender info
      let senderName = "Sistema SST";
      if (comunicacion.enviadoPor) {
        const sender = await storage.getUser(comunicacion.enviadoPor);
        if (sender) {
          senderName = sender.fullName || sender.username;
        }
      }

      // Load company logo
      const logoBuffer = await loadCompanyLogoBuffer(company.logoUrl);
      // Worker photo not needed for muestreo PDF

      // Create PDF
      const doc = new PDFDocument({ margin: 35, size: 'LETTER', bufferPages: true });
      
      // Add trial watermark if subscription is in trial period
      const pdf29754_subscription = await storage.getSubscriptionByCompany(companyId);
      const pdf29754_trialStatus = getTrialStatus(pdf29754_subscription?.status || 'trial', pdf29754_subscription?.trialEnd || null, true, true);
      setupTrialWatermarkOnAllPages(doc, pdf29754_trialStatus.requiresWatermark);
      res.setHeader('Content-Type', 'application/pdf');
      res.setHeader('Content-Disposition', `attachment; filename="comunicacion-sst-${comunicacion.id.substring(0, 8)}.pdf"`);
      doc.pipe(res);

      const margin = 35;
      const pageWidth = doc.page.width;

      // Format type label
      const tipoLabels: Record<string, string> = {
        "alerta": "Alerta",
        "campana": "Campaña",
        "informativo": "Informativo",
        "normativo": "Normativo",
        "preventivo": "Preventivo",
        "emergencia": "Emergencia"
      };
      const tipoLabel = tipoLabels[comunicacion.tipo] || comunicacion.tipo;

      // Format date
      const fechaEnvio = comunicacion.fechaEnvio ? new Date(comunicacion.fechaEnvio).toLocaleDateString('es-CO', {
        year: 'numeric',
        month: 'long',
        day: 'numeric',
        hour: '2-digit',
        minute: '2-digit'
      }) : 'No especificada';

      // Setup standard PDF headers and footers
      let currentY = setupPdfHeadersFooters({
        doc,
        company: {
          name: company.name,
          nit: company.nit,
          address: company.address,
          logoUrl: company.logoUrl,
        },
        documentTitle: 'COMUNICACIÓN SST',
        documentCode: `COM-${comunicacion.id.substring(0, 8).toUpperCase()}`,
        version: '1.0',
        date: comunicacion.fechaEnvio ? new Date(comunicacion.fechaEnvio) : new Date(),
        elaboro: senderName,
        autorizo: company.legalRepName || "Representante Legal",
        aprobo: company.legalRepName || "Representante Legal",
        logoBuffer,
      });

      currentY = 165;

      // Type badge
      const badgeColors: Record<string, string> = {
        "alerta": "#DC2626",
        "campana": "#2563EB",
        "informativo": "#059669",
        "normativo": "#7C3AED",
        "preventivo": "#D97706",
        "emergencia": "#DC2626"
      };
      const badgeColor = badgeColors[comunicacion.tipo] || "#166534";

      // Section: Información de la Comunicación
      doc.fontSize(11).font('Helvetica-Bold').fillColor('#1e7e34');
      doc.text('INFORMACIÓN DE LA COMUNICACIÓN', margin, currentY);
      currentY += 18;

      // Type and Subject box
      doc.rect(margin, currentY, pageWidth - margin * 2, 60).stroke('#E5E5E5');
      
      // Type badge
      doc.fontSize(8).font('Helvetica-Bold').fillColor(badgeColor);
      doc.text(`[${tipoLabel.toUpperCase()}]`, margin + 10, currentY + 8);
      
      // Subject
      doc.fontSize(12).font('Helvetica-Bold').fillColor('#333333');
      doc.text(comunicacion.asunto, margin + 10, currentY + 22, { 
        width: pageWidth - margin * 2 - 20,
        lineBreak: true 
      });
      
      currentY += 70;

      // Metadata table
      doc.fontSize(9).font('Helvetica');
      
      const metaItems = [
        { label: 'Fecha de Envío:', value: fechaEnvio },
        { label: 'Enviado por:', value: senderName },
        { label: 'Público Objetivo:', value: comunicacion.publicoObjetivo === 'todos' ? 'Todos los trabajadores' : 
          comunicacion.publicoObjetivo === 'area_especifica' ? `Área: ${comunicacion.departamentoEspecifico || 'No especificada'}` : 
          comunicacion.publicoObjetivo },
        { label: 'Destinatarios:', value: `${comunicacion.totalDestinatarios || 0} trabajadores` },
      ];

      if (comunicacion.requiereConfirmacionLectura) {
        metaItems.push({ 
          label: 'Confirmación de Lectura:', 
          value: `${comunicacion.totalLecturas || 0} de ${comunicacion.totalDestinatarios || 0} lecturas` 
        });
      }

      metaItems.forEach(item => {
        doc.font('Helvetica-Bold').fillColor('#666666').text(item.label, margin, currentY, { continued: true });
        doc.font('Helvetica').fillColor('#333333').text(` ${item.value}`);
        currentY = doc.y + 4;
      });

      currentY += 15;

      // Divider
      doc.moveTo(margin, currentY).lineTo(pageWidth - margin, currentY).strokeColor('#E5E5E5').stroke();
      currentY += 15;

      // Section: Contenido
      doc.fontSize(11).font('Helvetica-Bold').fillColor('#1e7e34');
      doc.text('CONTENIDO DE LA COMUNICACIÓN', margin, currentY);
      currentY += 18;

      // Content box with padding
      const contentBoxY = currentY;
      doc.fontSize(10).font('Helvetica').fillColor('#333333');
      
      // Split content into paragraphs and render
      const contentLines = comunicacion.contenido.split('\n');
      contentLines.forEach(line => {
        // Check if we need a new page
        if (doc.y > doc.page.height - 120) {
          doc.addPage();
          currentY = 60;
        }
        doc.text(line, margin + 5, doc.y, { 
          width: pageWidth - margin * 2 - 10,
          lineBreak: true,
          paragraphGap: 3
        });
      });

      currentY = doc.y + 20;

      // Vigencia section if applicable
      if (comunicacion.fechaVigenciaInicio || comunicacion.fechaVigenciaFin) {
        if (doc.y > doc.page.height - 100) {
          doc.addPage();
          currentY = 60;
        }

        doc.fontSize(11).font('Helvetica-Bold').fillColor('#1e7e34');
        doc.text('VIGENCIA', margin, currentY);
        currentY += 15;

        doc.fontSize(9).font('Helvetica').fillColor('#333333');
        if (comunicacion.fechaVigenciaInicio) {
          const inicio = new Date(comunicacion.fechaVigenciaInicio).toLocaleDateString('es-CO', { year: 'numeric', month: 'long', day: 'numeric' });
          doc.text(`Desde: ${inicio}`, margin, currentY);
          currentY = doc.y + 4;
        }
        if (comunicacion.fechaVigenciaFin) {
          const fin = new Date(comunicacion.fechaVigenciaFin).toLocaleDateString('es-CO', { year: 'numeric', month: 'long', day: 'numeric' });
          doc.text(`Hasta: ${fin}`, margin, currentY);
          currentY = doc.y + 4;
        }
        currentY += 10;
      }

      // Observations section if applicable
      if (comunicacion.observaciones) {
        if (doc.y > doc.page.height - 100) {
          doc.addPage();
          currentY = 60;
        }

        doc.fontSize(11).font('Helvetica-Bold').fillColor('#1e7e34');
        doc.text('OBSERVACIONES', margin, currentY);
        currentY += 15;

        doc.fontSize(9).font('Helvetica').fillColor('#333333');
        doc.text(comunicacion.observaciones, margin, currentY, { width: pageWidth - margin * 2 });
        currentY = doc.y + 15;
      }

      // Compliance footer
      if (doc.y > doc.page.height - 80) {
        doc.addPage();
        currentY = 60;
      }

      doc.fontSize(8).font('Helvetica').fillColor('#666666');
      doc.text(
        'Este documento hace parte del Sistema de Gestión de Seguridad y Salud en el Trabajo (SG-SST) de conformidad con el Decreto 1072 de 2015, Artículo 2.2.4.6.14 (Comunicación).',
        margin,
        doc.page.height - 70,
        { width: pageWidth - margin * 2, align: 'center' }
      );

      doc.end();
    } catch (error: any) {
      console.error('Error generating comunicación SST PDF:', error);
      res.status(500).json({ error: error.message || "Error al generar PDF" });
    }
  });

