  // PORTAL DE EMPLEADOS - Endpoints para trabajadores
  
  
  // GET /api/portal/my-contract - Obtener contrato activo del trabajador
  app.get("/api/portal/my-contract", requireAuth, async (req, res) => {
    try {
      const user = req.user!;
      const companyId = user.companyId;
      
      if (!companyId) {
        return res.status(403).json({ error: "Usuario no asociado a una empresa" });
      }

      let workerId = user.workerId;

      // Fallback: buscar worker por email si workerId es null
      if (!workerId && user.email) {
        const worker = await storage.getWorkerByEmail(user.email, companyId);
        if (worker) {
          workerId = worker.id;
        }
      }

      if (!workerId) {
        return res.status(404).json({ error: "Usuario no asociado a un trabajador. Contacte a recursos humanos." });
      }

      // Obtener contratos del trabajador
      const contracts = await storage.getContractsByWorker(workerId, companyId);
      
      // Buscar contrato activo por status Y validar fechas
      const today = new Date();
      today.setHours(0, 0, 0, 0);

      const activeContract = contracts.find(c => {
        if (c.status !== "activo") return false;
        const startDate = new Date(c.startDate);
        startDate.setHours(0, 0, 0, 0);
        if (startDate > today) return false;
        if (c.endDate) {
          const endDate = new Date(c.endDate);
          endDate.setHours(0, 0, 0, 0);
          if (endDate < today) return false;
        }
        return true;
      });
      
      if (!activeContract) {
        return res.status(404).json({ error: "No se encontró un contrato activo" });
      }

      res.json(activeContract);
    } catch (error: any) {
      console.error('Error fetching worker contract:', error);
      res.status(500).json({ error: error.message || "Error al obtener el contrato" });
    }
  });

