  // GET /api/portal/mis-capacitaciones - Obtener capacitaciones del trabajador
  app.get("/api/portal/mis-capacitaciones", requireAuth, async (req, res) => {
    try {
      const user = req.user!;
      const companyId = user.companyId;
      
      if (!companyId) {
        return res.status(403).json({ error: "Usuario no asociado a una empresa" });
      }

      if (!user.workerId) {
        return res.status(404).json({ error: "Usuario no asociado a un trabajador" });
      }

      const capacitaciones: Array<{
        id: string;
        eventoId: string;
        tituloCurso: string;
        categoria: string;
        fechaInicio: string;
        fechaFin: string | null;
        horaInicio: string | null;
        horaFin: string | null;
        lugar: string | null;
        instructor: string | null;
        duracionHoras: number | null;
        normativa: string | null;
        estado: string;
        asistenciaId: string;
        source: 'programa' | 'legacy';
      }> = [];
      
      // === Source 1: Programa de Capacitación (capacitacion_eventos + capacitacion_asistentes) ===
      const misAsistencias = await storage.getAsistentesByWorker(user.workerId);
      const eventos = await storage.getCapacitacionEventos(companyId);
      const eventosMap = new Map(eventos.map(e => [e.id, e]));
      
      for (const asistencia of misAsistencias) {
        const evento = eventosMap.get(asistencia.eventoId);
        if (evento && evento.companyId === companyId) {
          capacitaciones.push({
            id: evento.id,
            eventoId: evento.id,
            tituloCurso: evento.tituloCurso,
            categoria: evento.categoria || 'otro',
            fechaInicio: evento.fechaInicio,
            fechaFin: evento.fechaFin,
            horaInicio: evento.horaInicio,
            horaFin: evento.horaFin,
            lugar: evento.lugar,
            instructor: evento.instructor,
            duracionHoras: evento.duracionHoras,
            normativa: evento.normativa,
            estado: asistencia.estado,
            asistenciaId: asistencia.id,
            source: 'programa',
          });
        }
      }
      
      // === Source 2: Sistema Legacy (trainings + training_attendees) ===
      const legacyAttendees = await storage.getTrainingAttendeesByWorker(user.workerId);
      const legacyTrainings = await storage.getTrainings(companyId);
      const trainingsMap = new Map(legacyTrainings.map(t => [t.id, t]));
      
      for (const attendee of legacyAttendees) {
        const training = trainingsMap.get(attendee.trainingId);
        if (training && training.companyId === companyId) {
          const dateStr = training.date ? (typeof training.date === 'string' ? training.date : training.date.toISOString().split('T')[0]) : new Date().toISOString().split('T')[0];
          capacitaciones.push({
            id: training.id,
            eventoId: training.id,
            tituloCurso: training.title,
            categoria: 'otro',
            fechaInicio: dateStr,
            fechaFin: null,
            horaInicio: training.startTime || null,
            horaFin: training.endTime || null,
            lugar: training.location || null,
            instructor: training.instructor || null,
            duracionHoras: null,
            normativa: null,
            estado: attendee.attended ? 'asistio' : (attendee.confirmed ? 'confirmado' : 'invitado'),
            asistenciaId: attendee.id,
            source: 'legacy',
          });
        }
      }
      
      // Ordenar por fecha (más recientes primero)
      capacitaciones.sort((a, b) => new Date(b.fechaInicio).getTime() - new Date(a.fechaInicio).getTime());

      res.json(capacitaciones);
    } catch (error: any) {
      console.error('Error fetching worker capacitaciones:', error);
      res.status(500).json({ error: error.message || "Error al obtener las capacitaciones" });
    }
  });

    // POST /api/portal/capacitaciones/:asistenciaId/confirmar - Confirmar asistencia a capacitación
  app.post("/api/portal/capacitaciones/:asistenciaId/confirmar", requireAuth, async (req, res) => {
    try {
      const user = req.user!;
      const companyId = user.companyId;
      const { asistenciaId } = req.params;
      
      if (!companyId) {
        return res.status(403).json({ error: "Usuario no asociado a una empresa" });
      }

      if (!user.workerId) {
        return res.status(404).json({ error: "Usuario no asociado a un trabajador" });
      }

      // Primero buscar en el nuevo sistema (capacitacion_asistentes)
      const asistencia = await storage.getCapacitacionAsistente(asistenciaId);
      
      if (asistencia) {
        // Nuevo sistema de programa de capacitación
        if (asistencia.workerId !== user.workerId) {
          return res.status(403).json({ error: "No tiene permiso para confirmar esta asistencia" });
        }
        
        if (asistencia.estado !== 'invitado') {
          return res.status(400).json({ error: "Solo puede confirmar asistencia cuando está en estado 'invitado'" });
        }

        // Actualizar estado a confirmado
        const updated = await storage.updateCapacitacionAsistente(asistenciaId, {
          estado: 'confirmado',
          fechaConfirmacion: new Date(),
        });

        return res.json(updated);
      }
      
      // Si no está en el nuevo sistema, buscar en el sistema legacy (training_attendees)
      const legacyAttendee = await storage.getTrainingAttendeeById(asistenciaId);
      
      if (legacyAttendee) {
        if (legacyAttendee.workerId !== user.workerId) {
          return res.status(403).json({ error: "No tiene permiso para confirmar esta asistencia" });
        }
        
        // En el sistema legacy, "confirmado" se representa con confirmed=1
        if (legacyAttendee.confirmed === 1) {
          return res.status(400).json({ error: "Ya ha confirmado asistencia a esta capacitación" });
        }

        // Actualizar a confirmado en el sistema legacy
        const updated = await storage.updateTrainingAttendee(asistenciaId, {
          confirmed: 1,
          confirmedAt: new Date(),
        });

        return res.json(updated);
      }
      
      // No encontrado en ningún sistema
      return res.status(404).json({ error: "Registro de asistencia no encontrado" });
    } catch (error: any) {
      console.error('Error confirming attendance:', error);
      res.status(500).json({ error: error.message || "Error al confirmar asistencia" });
    }
  });

  // ============================================================================
  // EXÁMENES MÉDICOS - Portal de Empleados
  // Resolución 2346/2007 - Estándar 3.1.4
  // ============================================================================

  // GET /api/portal/mis-examenes-medicos - Obtener exámenes médicos del trabajador
  app.get("/api/portal/mis-examenes-medicos", requireAuth, async (req, res) => {
    try {
      const user = req.user!;
      const companyId = user.companyId;
      
      if (!companyId) {
        return res.status(403).json({ error: "Usuario no asociado a una empresa" });
      }

      if (!user.workerId) {
        return res.status(404).json({ error: "Usuario no asociado a un trabajador" });
      }

      // Obtener exámenes del trabajador
      const exams = await storage.getMedicalExamsByWorker(user.workerId, companyId);
      
      // Marcar como leídos los que no tienen notificationReadAt
      const now = new Date();
      for (const exam of exams) {
        if (exam.notificationSentAt && !exam.notificationReadAt) {
          await storage.updateMedicalExam(exam.id, { notificationReadAt: now }, companyId);
        }
      }
      
      res.json(exams);
    } catch (error: any) {
      console.error('Error fetching worker medical exams:', error);
      res.status(500).json({ error: error.message || "Error al obtener los exámenes médicos" });
    }
  });

  // POST /api/portal/mis-examenes-medicos/:id/confirmar-lectura - Confirmar lectura de examen
  app.post("/api/portal/mis-examenes-medicos/:id/confirmar-lectura", requireAuth, async (req, res) => {
    try {
      const user = req.user!;
      const companyId = user.companyId;
      const { id } = req.params;
      
      if (!companyId) {
        return res.status(403).json({ error: "Usuario no asociado a una empresa" });
      }

      if (!user.workerId) {
        return res.status(404).json({ error: "Usuario no asociado a un trabajador" });
      }

      // Verificar que el examen pertenece al trabajador
      const exam = await storage.getMedicalExam(id, companyId);
      if (!exam) {
        return res.status(404).json({ error: "Examen no encontrado" });
      }
      
      if (exam.workerId !== user.workerId) {
        return res.status(403).json({ error: "No tiene permiso para confirmar este examen" });
      }

      // Actualizar confirmación
      const updated = await storage.updateMedicalExam(id, {
        readConfirmedAt: new Date(),
        readConfirmedBy: user.id,
      }, companyId);

      res.json(updated);
    } catch (error: any) {
      console.error('Error confirming medical exam read:', error);
      res.status(500).json({ error: error.message || "Error al confirmar lectura" });
    }
  });

