  // POST /api/portal/copasst/votar - Trabajador emite su voto
  app.post("/api/portal/copasst/votar", requireAuth, async (req, res) => {
    try {
      const user = req.user!;
      const companyId = user.companyId;
      const { eleccionId, candidatoIds } = req.body;

      if (!companyId) {
        return res.status(403).json({ error: "Usuario no asociado a una empresa" });
      }

      if (!user.workerId) {
        return res.status(403).json({ error: "Usuario no asociado a un trabajador" });
      }

      if (!eleccionId || !candidatoIds || !Array.isArray(candidatoIds) || candidatoIds.length === 0) {
        return res.status(400).json({ error: "ID de elección y lista de candidatos requeridos" });
      }

      // Verificar que la elección existe y pertenece a la empresa
      const eleccion = await storage.getCopasstEleccionById(eleccionId);
      if (!eleccion || eleccion.companyId !== companyId) {
        return res.status(403).json({ error: "Elección no encontrada o no pertenece a su empresa" });
      }

      // Verificar que la elección está en fase de votación
      if (eleccion.estado !== 'votacion') {
        return res.status(400).json({ error: "La votación no está habilitada en esta fase" });
      }

      // Verificar que el trabajador no haya votado ya
      const yaVoto = await storage.hasVoted(eleccionId, user.workerId);
      if (yaVoto) {
        return res.status(400).json({ error: "Ya ha emitido su voto en esta elección" });
      }

      // Verificar límite de candidatos seleccionados
      const maxVotos = (eleccion.principalesRequeridos || 0) + (eleccion.suplentesRequeridos || 0);
      if (candidatoIds.length > maxVotos) {
        return res.status(400).json({ error: `Solo puede votar por máximo ${maxVotos} candidatos` });
      }

      // Registrar el voto (anónimo)
      await storage.registrarVoto(eleccionId, user.workerId, candidatoIds);

      res.json({ success: true, message: "Voto registrado exitosamente" });
    } catch (error: any) {
      console.error('Error casting vote:', error);
      res.status(500).json({ error: error.message || "Error al registrar voto" });
    }
  });

