  // ============================================================================
  // EVS (Estilos de Vida Saludable) - PORTAL EMPLEADOS
  // Estándar 3.1.7 - Resolución 0312/2019
  // ============================================================================

  // GET /api/portal/evs-activities - Obtener actividades EVS virtuales programadas para el trabajador
  app.get("/api/portal/evs-activities", requireAuth, async (req, res) => {
    try {
      const user = req.user!;
      const companyId = user.companyId;

      if (!companyId) {
        return res.status(403).json({ error: "Usuario no asociado a una empresa" });
      }

      // Get all EVS activities for the company that are virtual or mixta and programada/ejecutada
      const allActivities = await storage.getEvsActivities(companyId);
      
      // Filter to only virtual/mixta activities that are still relevant (programada or recently executed)
      const today = new Date();
      const oneWeekAgo = new Date(today.getTime() - 7 * 24 * 60 * 60 * 1000);
      
      const virtualActivities = allActivities.filter(activity => {
        const isVirtualOrMixta = activity.modality === "virtual" || activity.modality === "mixta";
        const scheduledDate = new Date(activity.scheduledDate);
        const isProgramada = activity.status === "programada";
        const isRecentlyExecuted = activity.status === "ejecutada" && scheduledDate >= oneWeekAgo;
        
        return isVirtualOrMixta && (isProgramada || isRecentlyExecuted);
      });

      res.json(virtualActivities);
    } catch (error: any) {
      console.error("Error fetching portal EVS activities:", error);
      res.status(500).json({ error: error.message || "Error al obtener actividades EVS" });
    }
  });

