  app.get("/api/sst-documents/:id", requireAuth, requireAnyPermission(["documents:view", "documents:view_self"]), async (req, res) => {
    try {
      const userCompanyId = req.user!.companyId;
      const isAdmin = hasGlobalAccess(req.user!.role);
      
      let document;
      if (isAdmin) {
        document = await storage.getSstDocumentById(req.params.id);
      } else {
        if (!userCompanyId) {
          return res.status(403).send("Usuario no asociado a una empresa");
        }
        document = await storage.getSstDocument(req.params.id, userCompanyId);
      }
      
      if (!document) {
        return res.status(404).send("Documento no encontrado");
      }
      
      // Log access
      try {
        await storage.logSstDocumentAccess({
          documentId: document.id,
          userId: req.user!.id,
          accessType: 'view',
          ipAddress: req.ip || null,
          userAgent: req.get('user-agent') || null,
        });
      } catch (logError) {
        console.error('Error logging document access:', logError);
      }
      
      res.json(document);
    } catch (error: any) {
      console.error('Error fetching SST document:', error);
      res.status(500).send('Error interno al obtener documento');
    }
  });

  // POST /api/sst-documents - Create new document with auto-generated code
  app.post("/api/sst-documents", requireAuth, requirePermission("documents:create"), async (req, res) => {
    try {
      const userCompanyId = req.user!.companyId;
      const isAdmin = hasGlobalAccess(req.user!.role);
      
      let companyId: string;
      if (isAdmin) {
        companyId = req.body.companyId;
        if (!companyId) {
          return res.status(400).send("Admin debe especificar companyId");
        }
        const company = await storage.getCompany(companyId);
        if (!company) {
          return res.status(404).send("Empresa no encontrada");
        }
      } else {
        if (!userCompanyId) {
          return res.status(403).send("Usuario no asociado a una empresa");
        }
        companyId = userCompanyId;
      }
      
      // Auto-generate document code if not provided
      let code = req.body.code;
      if (!code) {
        const category = req.body.category;
        const categoryPrefixes: Record<string, string> = {
          'politica': 'POL-SST',
          'procedimiento': 'PRO-SST',
          'formato': 'FOR-SST',
          'registro': 'REG-SST',
          'manual': 'MAN-SST',
          'plan': 'PLA-SST',
          'matriz': 'MAT-SST',
          'acta': 'ACT-SST',
          'informe': 'INF-SST',
          'certificado': 'CER-SST',
          'contrato': 'CON-SST',
          'normativa': 'NOR-SST',
          'capacitacion': 'CAP-SST',
          'otro': 'DOC-SST',
        };
        const prefix = categoryPrefixes[category] || 'DOC-SST';
        
        // Get all existing documents to determine next number
        const existingDocs = await storage.getSstDocuments(companyId);
        const docsWithSamePrefix = existingDocs.filter(d => d.code?.startsWith(prefix));
        const maxNumber = docsWithSamePrefix.reduce((max, d) => {
          const match = d.code?.match(new RegExp(`${prefix}-(\\d+)`));
          if (match) {
            const num = parseInt(match[1]);
            return num > max ? num : max;
          }
          return max;
        }, 0);
        
        code = `${prefix}-${(maxNumber + 1).toString().padStart(3, '0')}`;
      }
      
      const validatedData = insertSstDocumentSchema.parse({
        ...req.body,
        code,
        createdBy: req.user!.id,
        updatedBy: req.user!.id,
        retentionYears: req.body.retentionYears || 20, // Default 20 years per Res. 0312/2019
      });
      
      const document = await storage.createSstDocument(validatedData, companyId);
      res.status(201).json(document);
    } catch (error: any) {
      console.error('Error creating SST document:', error);
      res.status(400).send(error.message);
    }
  });

  // PATCH /api/sst-documents/:id - Update document (creates version when status changes)
  app.patch("/api/sst-documents/:id", requireAuth, requirePermission("documents:edit"), async (req, res) => {
    try {
      const userCompanyId = req.user!.companyId;
      const isAdmin = hasGlobalAccess(req.user!.role);
      
      let companyId: string;
      let existingDoc;
      
      if (isAdmin) {
        existingDoc = await storage.getSstDocumentById(req.params.id);
        if (!existingDoc) {
          return res.status(404).send("Documento no encontrado");
        }
        companyId = existingDoc.companyId;
      } else {
        if (!userCompanyId) {
          return res.status(403).send("Usuario no asociado a una empresa");
        }
        companyId = userCompanyId;
        existingDoc = await storage.getSstDocument(req.params.id, companyId);
        if (!existingDoc) {
          return res.status(404).send("Documento no encontrado");
        }
      }
      
      const validatedData = insertSstDocumentSchema.partial().parse({
        ...req.body,
        updatedBy: req.user!.id,
      });
      
      // If status is changing, create a version record
      if (req.body.status && req.body.status !== existingDoc.status) {
        await storage.createSstDocumentVersion({
          documentId: existingDoc.id,
          versionNumber: existingDoc.currentVersion,
          changeDescription: req.body.changeDescription || `Estado cambiado de ${existingDoc.status} a ${req.body.status}`,
          changeType: 'minor',
          fileUrl: existingDoc.fileUrl,
          fileName: existingDoc.fileName,
          fileSize: existingDoc.fileSize,
          createdBy: req.user!.id,
          previousStatus: existingDoc.status,
          newStatus: req.body.status,
          approvedBy: null,
          approvedAt: null,
        });
      }
      
      const document = await storage.updateSstDocument(req.params.id, validatedData, companyId);
      res.json(document);
    } catch (error: any) {
      console.error('Error updating SST document:', error);
      res.status(400).send(error.message);
    }
  });

