  // ============================================================================
  // WORKER PORTAL ACCESS LOGS (SST-2025-0082)
  // ============================================================================
  // Tracks when workers/employees access the Employee Portal

  // POST /api/portal/log-access - Log portal access (called automatically when worker accesses portal)
  app.post("/api/portal/log-access", requireAuth, async (req, res) => {
    try {
      const user = req.user as schema.User;
      if (!user.companyId) {
        return res.status(400).send("Usuario sin empresa asignada");
      }

      // Check for duplicate access on the same day (server-side deduplication SST-2025-0082)
      const today = new Date();
      today.setHours(0, 0, 0, 0);
      const tomorrow = new Date(today);
      tomorrow.setDate(tomorrow.getDate() + 1);
      
      const existingLogs = await storage.getWorkerPortalAccessLogs(user.companyId, {
        from: today,
        to: tomorrow,
      });
      
      // Check if there's already a log for this user today
      const alreadyLoggedToday = existingLogs.some(log => log.userId === user.id);
      if (alreadyLoggedToday) {
        return res.status(200).json({ message: "Acceso ya registrado hoy", duplicate: true });
      }

      // Detect device type from user agent
      const userAgent = req.headers["user-agent"] || "";
      let deviceType: "mobile" | "desktop" | "tablet" | null = null;
      
      if (/mobile/i.test(userAgent) && !/tablet|ipad/i.test(userAgent)) {
        deviceType = "mobile";
      } else if (/tablet|ipad/i.test(userAgent)) {
        deviceType = "tablet";
      } else if (userAgent) {
        deviceType = "desktop";
      }

      // Get IP address
      const ipAddress = (req.headers["x-forwarded-for"] as string)?.split(",")[0]?.trim() || 
                        req.socket.remoteAddress || 
                        null;

      const logData: schema.InsertWorkerPortalAccessLog = {
        companyId: user.companyId,
        userId: user.id,
        workerId: user.workerId || null,
        ipAddress,
        userAgent: userAgent || null,
        deviceType,
      };

      const log = await storage.createWorkerPortalAccessLog(logData);
      res.status(201).json(log);
    } catch (error: any) {
      console.error("Error logging portal access:", error);
      res.status(500).send("Error al registrar acceso al portal");
    }
  });


  // POST /api/portal/me/photo - Worker uploads their own photo for carnet
  app.post("/api/portal/me/photo", requireAuth, uploadWorkerPhoto.single('photo'), async (req, res) => {
    try {
      const user = req.user as schema.User;
      
      if (!user.companyId) {
        return res.status(403).json({ error: "Usuario no asociado a una empresa" });
      }

      let workerId = user.workerId;

      // Fallback: buscar worker por email si workerId es null
      if (!workerId && user.email) {
        const worker = await storage.getWorkerByEmail(user.email, user.companyId);
        if (worker) {
          workerId = worker.id;
        }
      }

      if (!workerId) {
        return res.status(404).json({ error: "Usuario no asociado a un trabajador" });
      }

      if (!req.file) {
        return res.status(400).json({ error: "No se proporcionó ninguna imagen" });
      }

      // Get the S3 URL from the uploaded file
      const photoUrl = (req.file as Express.MulterS3.File).location;
      
      // Update worker with new photo URL
      await storage.updateWorker(workerId, user.companyId, { photoUrl });

      // Log audit event
      await storage.createAuditLog({
        action: "worker_photo_self_upload",
        tableName: "workers",
        recordId: workerId,
        userId: user.id,
        companyId: user.companyId,
        changes: { photoUrl },
        ipAddress: (req.headers["x-forwarded-for"] as string)?.split(",")[0]?.trim() || req.ip || null,
      });

      res.status(200).json({ 
        message: "Foto actualizada correctamente",
        photoUrl 
      });
    } catch (error: any) {
      console.error("Error uploading worker photo from portal:", error);
      res.status(500).json({ error: "Error al subir la foto" });
    }
  });

