  // ==================== DOCUMENT ACKNOWLEDGMENTS (Acuse de Recibo) - SST-2026-0019 ====================

  // GET /api/portal/mis-documentos-asignados - Get documents assigned to worker for acknowledgment
  app.get("/api/portal/mis-documentos-asignados", requireAuth, requirePermission("portal_empleados:access"), async (req, res) => {
    try {
      const user = req.user as schema.User;
      const companyId = user.companyId;
      
      if (!companyId) {
        return res.status(403).json({ error: "Usuario no asociado a una empresa" });
      }

      let workerId = user.workerId;

      // Fallback: buscar worker por email si workerId es null
      if (!workerId && user.email) {
        const worker = await storage.getWorkerByEmail(user.email, companyId);
        if (worker) {
          workerId = worker.id;
        }
      }

      if (!workerId) {
        return res.status(404).json({ error: "Usuario no asociado a un trabajador" });
      }

      // Get all document assignments for this worker
      const assignments = await storage.getDocumentWorkerAssignmentsByWorker(workerId, companyId);
      
      // Get all acknowledgments for this worker
      const acknowledgments = await storage.getDocumentAcknowledgmentsByWorker(workerId, companyId);
      const acknowledgedDocIds = new Set(acknowledgments.map(a => a.documentId));

      // Get document details for each assignment
      const documentsWithStatus = await Promise.all(
        assignments.map(async (assignment) => {
          const document = await storage.getSstDocument(assignment.documentId, companyId);
          if (!document || document.status !== "vigente") return null;
          
          const isAcknowledged = acknowledgedDocIds.has(assignment.documentId);
          const ack = acknowledgments.find(a => a.documentId === assignment.documentId);
          
          return {
            assignmentId: assignment.id,
            documentId: document.id,
            title: document.title,
            code: document.code,
            category: document.category,
            description: document.description,
            fileUrl: document.fileUrl,
            fileName: document.fileName,
            assignedAt: assignment.assignedAt,
            dueDate: assignment.dueDate,
            isRequired: assignment.isRequired,
            priority: assignment.priority,
            message: assignment.message,
            isAcknowledged,
            acknowledgedAt: ack?.acknowledgedAt || null,
          };
        })
      );

      // Filter out null values (documents that were deleted or not vigente)
      const validDocuments = documentsWithStatus.filter(d => d !== null);

      res.json(validDocuments);
    } catch (error: any) {
      console.error('Error fetching assigned documents:', error);
      res.status(500).json({ error: error.message || "Error al obtener documentos asignados" });
    }
  });

  // POST /api/portal/documentos/:documentId/acusar-recibo - Worker acknowledges document receipt
  app.post("/api/portal/documentos/:documentId/acusar-recibo", requireAuth, requirePermission("portal_empleados:access"), async (req, res) => {
    try {
      const user = req.user as schema.User;
      const companyId = user.companyId;
      const { documentId } = req.params;
      const { comments, signatureConfirmation } = req.body;
      
      if (!companyId) {
        return res.status(403).json({ error: "Usuario no asociado a una empresa" });
      }

      let workerId = user.workerId;

      // Fallback: buscar worker por email si workerId es null
      if (!workerId && user.email) {
        const worker = await storage.getWorkerByEmail(user.email, companyId);
        if (worker) {
          workerId = worker.id;
        }
      }

      if (!workerId) {
        return res.status(404).json({ error: "Usuario no asociado a un trabajador" });
      }

      // Check if document exists and is assigned to worker
      const document = await storage.getSstDocument(documentId, companyId);
      if (!document) {
        return res.status(404).json({ error: "Documento no encontrado" });
      }

      // Check if already acknowledged
      const existingAck = await storage.getDocumentAcknowledgment(documentId, workerId, companyId);
      if (existingAck) {
        return res.status(400).json({ error: "Ya ha acusado recibo de este documento" });
      }

      // Get assignment if exists
      const assignments = await storage.getDocumentWorkerAssignmentsByWorker(workerId, companyId);
      const assignment = assignments.find(a => a.documentId === documentId);

      // Create acknowledgment
      const acknowledgment = await storage.createDocumentAcknowledgment({
        documentId,
        workerId,
        assignmentId: assignment?.id || null,
        ipAddress: (req.headers["x-forwarded-for"] as string)?.split(",")[0]?.trim() || req.ip || null,
        userAgent: req.headers["user-agent"] || null,
        comments: comments || null,
        signatureConfirmation: signatureConfirmation || null,
      }, companyId);

      res.json({
        success: true,
        message: "Acuse de recibo registrado exitosamente",
        acknowledgment
      });
    } catch (error: any) {
      console.error('Error acknowledging document:', error);
      res.status(500).json({ error: error.message || "Error al acusar recibo" });
    }
  });

