  // POST /api/document-assignments - Admin: Assign document to workers
  app.post("/api/document-assignments", requireAuth, requirePermission("sst_management:edit"), async (req, res) => {
    try {
      const user = req.user as schema.User;
      const companyId = user.companyId;
      const { documentId, workerIds, dueDate, isRequired, priority, message } = req.body;
      
      if (!companyId) {
        return res.status(403).json({ error: "Usuario no asociado a una empresa" });
      }

      if (!documentId || !workerIds || !Array.isArray(workerIds) || workerIds.length === 0) {
        return res.status(400).json({ error: "Debe especificar el documento y al menos un trabajador" });
      }

      // Verify document exists
      const document = await storage.getSstDocument(documentId, companyId);
      if (!document) {
        return res.status(404).json({ error: "Documento no encontrado" });
      }

      // Get existing assignments to avoid duplicates
      const existingAssignments = await storage.getDocumentWorkerAssignmentsByDocument(documentId, companyId);
      const existingWorkerIds = new Set(existingAssignments.map(a => a.workerId));

      // Create new assignments
      const createdAssignments = [];
      for (const workerId of workerIds) {
        if (existingWorkerIds.has(workerId)) continue; // Skip if already assigned
        
        const assignment = await storage.createDocumentWorkerAssignment({
          documentId,
          workerId,
          assignedBy: user.id,
          dueDate: dueDate ? new Date(dueDate) : null,
          isRequired: isRequired ?? true,
          priority: priority || "normal",
          message: message || null,
        }, companyId);
        createdAssignments.push(assignment);
      }

      res.json({
        success: true,
        message: `Documento asignado a ${createdAssignments.length} trabajador(es)`,
        assignments: createdAssignments
      });
    } catch (error: any) {
      console.error('Error assigning document:', error);
      res.status(500).json({ error: error.message || "Error al asignar documento" });
    }
  });

