  // GET /api/copasst-evaluaciones/periodos/:periodoId/reporte - Get aggregated report
  app.get("/api/copasst-evaluaciones/periodos/:periodoId/reporte", requireAuth, async (req, res) => {
    try {
      const companyId = (req.user as schema.User).companyId;
      if (!companyId) {
        return res.status(400).json({ error: "No company assigned" });
      }
      const periodo = await storage.getCopasstEvaluacionPeriodo(req.params.periodoId);
      if (!periodo) {
        return res.status(404).json({ error: "Período no encontrado" });
      }
      if (periodo.companyId !== companyId) {
        return res.status(403).json({ error: "No autorizado para este período" });
      }
      
      const resultados = await storage.listCopasstEvaluacionResultados(req.params.periodoId);
      const asignaciones = await storage.listCopasstEvaluacionAsignaciones(req.params.periodoId, {});
      
      const totalEvaluados = new Set(resultados.map(r => r.evaluadoId)).size;
      const totalAsignaciones = asignaciones.length;
      const asignacionesCompletadas = asignaciones.filter(a => a.estado === 'completada').length;
      const promedioGeneral = resultados.length > 0 
        ? resultados.reduce((sum, r) => sum + parseFloat(String(r.promedioGeneral)), 0) / resultados.length 
        : 0;
      
      res.json({
        periodo,
        estadisticas: {
          totalEvaluados,
          totalAsignaciones,
          asignacionesCompletadas,
          asignacionesPendientes: totalAsignaciones - asignacionesCompletadas,
          porcentajeCompletado: totalAsignaciones > 0 ? (asignacionesCompletadas / totalAsignaciones) * 100 : 0,
          promedioGeneral: promedioGeneral.toFixed(2),
        },
        resultados,
      });
    } catch (error: any) {
      res.status(500).json({ error: error.message });
    }
  });

  // SISTEMA DE TICKETS DE SOPORTE

  // GET /api/support-tickets - Get all tickets (superadmin/soporte) or company tickets (users)
  app.get("/api/support-tickets", requireAuth, async (req, res) => {
    try {
      const userRole = req.user!.role;
      const userCompanyId = req.user!.companyId;
      
      // Superadmin and soporte can see all tickets
      if (hasSupportAccess(userRole)) {
        const tickets = await storage.getSupportTickets();
        res.json(tickets);
      } else {
        // Users without a company cannot see any tickets
        if (!userCompanyId) {
          return res.json([]);
        }
        // Filter tickets by user's company only
        const tickets = await storage.getSupportTickets(userCompanyId);
        res.json(tickets);
      }
    } catch (error: any) {
      console.error('Error fetching support tickets:', error);
      res.status(500).send('Error al obtener tickets de soporte');
    }
  });

  // GET /api/support-tickets/:id - Get single ticket with responses
  app.get("/api/support-tickets/:id", requireAuth, async (req, res) => {
    try {
      const ticket = await storage.getSupportTicket(req.params.id);
      
      if (!ticket) {
        return res.status(404).send("Ticket no encontrado");
      }

      // Check permissions: superadmin/soporte can see all, others only their company's
      const userCompanyId = req.user!.companyId;
      const userRole = req.user!.role;
      
      if (!hasSupportAccess(userRole) && userCompanyId !== ticket.companyId) {
        return res.status(403).send("No tiene permisos para ver este ticket");
      }

      // Get responses and status history
      const [responses, statusHistory] = await Promise.all([
        storage.getTicketResponses(ticket.id),
        storage.getTicketStatusHistory(ticket.id)
      ]);

      res.json({
        ...ticket,
        responses,
        statusHistory
      });
    } catch (error: any) {
      console.error('Error fetching support ticket:', error);
      res.status(500).send('Error al obtener ticket de soporte');
    }
  });

  // POST /api/support-tickets - Create new ticket
  app.post("/api/support-tickets", requireAuth, async (req, res) => {
    try {
      const user = req.user!;
      const userId = user.id;
      const userCompanyId = user.companyId;
      
      // Get company name for denormalization
      const company = userCompanyId ? await storage.getCompany(userCompanyId) : null;
      
      const ticketData = {
        ...req.body,
        userId: userId,
        userName: user.fullName || user.username,
        userEmail: user.email || null,
        companyId: userCompanyId!,
        companyName: company?.name || 'Sin empresa',
        status: 'abierto' as const,
      };

      const ticket = await storage.createSupportTicket(ticketData);
      
      // Create initial status history entry
      await storage.createTicketStatusHistory({
        ticketId: ticket.id,
        previousStatus: null,
        newStatus: 'abierto',
        changedBy: userId,
        changedByName: user.fullName || user.username,
        reason: 'Ticket creado'
      });


      // Notify support staff via internal messages
      try {
        const supportUsers = await storage.getUsersByRoleGlobal("soporte");
        const superadmins = await storage.getUsersByRoleGlobal("superadmin");
        const allSupportStaff = [...supportUsers, ...superadmins];
        
        for (const supportUser of allSupportStaff) {
          // Create internal message for each support staff member
          const message = await storage.createInternalMessage({
            companyId: supportUser.companyId || user.companyId,
            senderId: user.id,
            senderName: user.fullName || user.username,
            senderRole: user.role,
            receiverId: supportUser.id,
            receiverName: supportUser.fullName || supportUser.username,
            receiverRole: supportUser.role,
            subject: `Nuevo Ticket: ${ticket.ticketNumber} - ${ticket.subject}`,
            content: `Se ha creado un nuevo ticket de soporte.\n\nNúmero: ${ticket.ticketNumber}\nAsunto: ${ticket.subject}\nPrioridad: ${ticket.priority || 'media'}\nEmpresa: ${company?.name || 'Sin empresa'}\nUsuario: ${user.fullName || user.username}\n\nAcceda a la sección de Soporte para revisar este ticket.`,
            priority: ticket.priority === 'alta' || ticket.priority === 'critica' ? 'urgent' : 'normal',
            status: 'unread',
            relatedEntity: 'support_ticket',
            relatedEntityId: ticket.id,
          });
          
          // Send WebSocket notification
          notifyNewMessage(supportUser.id, user.id, message.id);
        }
      } catch (notifError) {
        console.error('Error sending support ticket notifications:', notifError);
        // Don't fail the request if notification fails
      }

      res.status(201).json(ticket);
    } catch (error: any) {
      console.error('Error creating support ticket:', error);
      res.status(400).send(error.message);
    }
  });

  // POST /api/support-tickets/:id/attachments - Upload attachments to a ticket
  app.post("/api/support-tickets/:id/attachments", requireAuth, upload.array('attachments', 5), async (req, res) => {
    const files = req.files as Express.Multer.File[] | undefined;
    
    // Helper function to cleanup uploaded files
    const cleanupFiles = () => {
      if (files && files.length > 0) {
        files.forEach(file => {
          try {
            fs.unlinkSync(file.path);
          } catch (e) {
            console.error('Error deleting orphaned file:', file.path, e);
          }
        });
      }
    };
    
    try {
      const ticketId = req.params.id;
      const ticket = await storage.getSupportTicket(ticketId);
      
      if (!ticket) {
        cleanupFiles();
        return res.status(404).send("Ticket no encontrado");
      }

      const user = req.user!;
      const userCompanyId = user.companyId;
      
      // Solo el dueño del ticket o staff de soporte puede subir archivos
      if (!hasSupportAccess(user.role) && userCompanyId !== ticket.companyId) {
        cleanupFiles();
        return res.status(403).send("No tiene permisos para subir archivos a este ticket");
      }

      if (!files || files.length === 0) {
        return res.status(400).send("No se proporcionaron archivos");
      }
      
      // Verificar límite de archivos por ticket (máximo 5)
      const existingAttachments = ticket.attachments || [];
      const totalFiles = existingAttachments.length + files.length;
      if (totalFiles > 5) {
        cleanupFiles();
        return res.status(400).send(`Límite de archivos excedido. Máximo 5 archivos por ticket (actual: ${existingAttachments.length}, intentando agregar: ${files.length})`);
      }
      
      // Upload files to Object Storage
      const objectStorageService = new ObjectStorageService();
      const newAttachmentUrls: string[] = [];
      
      for (const file of files) {
        const fileBuffer = fs.readFileSync(file.path);
        const ext = path.extname(file.originalname);
        const uniqueId = randomUUID();
        const objectPath = `uploads/ticket-attachments/${ticketId}/${uniqueId}${ext}`;
        await objectStorageService.uploadObject(objectPath, fileBuffer, file.mimetype);
        newAttachmentUrls.push(`/objects/${objectPath}`);
      }
      
      // Clean up local temp files after successful upload
      cleanupFiles();
      
      const allAttachments = [...existingAttachments, ...newAttachmentUrls];
      
      // Actualizar el ticket con los nuevos adjuntos
      const updatedTicket = await storage.updateSupportTicket(ticketId, {
        attachments: allAttachments
      });

      res.json({
        message: `${files.length} archivo(s) subido(s) exitosamente`,
        attachments: newAttachmentUrls,
        ticket: updatedTicket
      });
    } catch (error: any) {
      console.error('Error uploading ticket attachments:', error);
      cleanupFiles();
      res.status(500).send(error.message);
    }
  });

  // PATCH /api/support-tickets/:id - Update ticket (status, priority, assignment)
  app.patch("/api/support-tickets/:id", requireAuth, async (req, res) => {
    try {
      const ticket = await storage.getSupportTicket(req.params.id);
      
      if (!ticket) {
        return res.status(404).send("Ticket no encontrado");
      }

      const user = req.user!;
      const userRole = user.role;
      const userCompanyId = user.companyId;
      const userId = user.id;
      
      // Superadmin/soporte can update any ticket, users can only update their company's
      if (!hasSupportAccess(userRole) && userCompanyId !== ticket.companyId) {
        return res.status(403).send("No tiene permisos para actualizar este ticket");
      }

      // Only superadmin/soporte can change assignedTo and certain status transitions
      const { status, priority, assignedTo, assignedToName, ...otherUpdates } = req.body;
      
      let updateData: any = {};
      
      // Users can only close their own tickets
      if (!hasSupportAccess(userRole)) {
        if (status && status !== 'cerrado') {
          return res.status(403).send("Solo puede cerrar sus propios tickets");
        }
        if (assignedTo !== undefined) {
          return res.status(403).send("Solo administradores pueden asignar tickets");
        }
        if (status === 'cerrado') {
          updateData.status = 'cerrado';
          updateData.closedAt = new Date();
        }
      } else {
        // Superadmin/soporte can change everything
        if (status) updateData.status = status;
        if (priority) updateData.priority = priority;
        if (assignedTo !== undefined) {
          updateData.assignedTo = assignedTo;
          updateData.assignedToName = assignedToName || null;
        }
        if (status === 'cerrado' && ticket.status !== 'cerrado') {
          updateData.closedAt = new Date();
        }
        if (status === 'resuelto' && ticket.status !== 'resuelto') {
          updateData.resolvedAt = new Date();
          updateData.resolvedBy = userId;
        }
      }

      const updatedTicket = await storage.updateSupportTicket(req.params.id, updateData);
      
      // Record status change if applicable
      if (status && status !== ticket.status) {
        await storage.createTicketStatusHistory({
          ticketId: ticket.id,
          previousStatus: ticket.status,
          newStatus: status,
          changedBy: userId,
          changedByName: user.fullName || user.username,
          reason: req.body.statusNote || null
        });
        
        // Send internal notification when ticket is resolved
        if (status === 'resuelto') {
          try {
            // Get the user who created the ticket
            const ticketCreator = await storage.getUser(ticket.userId);
            if (ticketCreator && ticketCreator.companyId) {
              // Create internal notification message
              await storage.createInternalMessage({
                companyId: ticketCreator.companyId,
                senderId: ticketCreator.id,
                senderName: "SST Colombia Soporte",
                senderRole: ticketCreator.role,
                receiverId: ticketCreator.id,
                receiverName: ticketCreator.fullName || ticketCreator.username,
                receiverRole: ticketCreator.role,
                subject: `Ticket ${ticket.ticketNumber} Resuelto`,
                content: `Su ticket de soporte "${ticket.subject}" ha sido resuelto por nuestro equipo.\n\nPuede revisar la solución en la sección de Soporte. Si necesita más ayuda, puede reabrir el ticket o crear uno nuevo.\n\nGracias por usar SST Colombia.`,
                priority: "normal",
                status: "unread",
                relatedEntity: "support_ticket",
                relatedEntityId: ticket.id,
              });
              console.log(`Notification sent to user ${ticketCreator.id} for resolved ticket ${ticket.ticketNumber}`);
            }
          } catch (notifError) {
            console.error('Error sending ticket resolution notification:', notifError);
            // Don't fail the ticket update if notification fails
          }
        }
      }

      res.json(updatedTicket);
    } catch (error: any) {
      console.error('Error updating support ticket:', error);
      res.status(400).send(error.message);
    }
  });

  // POST /api/support-tickets/:id/responses - Add response to ticket
  app.post("/api/support-tickets/:id/responses", requireAuth, async (req, res) => {
    try {
      const ticket = await storage.getSupportTicket(req.params.id);
      
      if (!ticket) {
        return res.status(404).send("Ticket no encontrado");
      }

      const user = req.user!;
      const userRole = user.role;
      const userCompanyId = user.companyId;
      const userId = user.id;
      
      // Check permissions
      if (!hasSupportAccess(userRole) && userCompanyId !== ticket.companyId) {
        return res.status(403).send("No tiene permisos para responder a este ticket");
      }

      // Determine if this is a staff or customer response
      const isStaff = hasSupportAccess(userRole);
      
      const responseData = {
        ticketId: ticket.id,
        userId: userId,
        userName: user.fullName || user.username,
        userRole: userRole,
        isStaff: isStaff ? 1 : 0,
        content: req.body.content || req.body.message,
        attachments: req.body.attachments || null,
        isInternal: req.body.isInternal ? 1 : 0
      };

      const response = await storage.createTicketResponse(responseData);
      
      // Update ticket status based on response
      let newStatus = ticket.status;
      
      if (isStaff) {
        // Staff response: mark as pendiente_cliente if currently abierto or en_progreso
        if (ticket.status === 'abierto' || ticket.status === 'en_progreso') {
          newStatus = 'pendiente_cliente';
        }
        await storage.updateSupportTicket(ticket.id, { status: newStatus });
      } else {
        // Customer response: mark as en_progreso if pendiente_cliente
        if (ticket.status === 'pendiente_cliente') {
          newStatus = 'en_progreso';
          await storage.updateSupportTicket(ticket.id, { status: newStatus });
        }
      }
      
      // Record status change if applicable
      if (newStatus !== ticket.status) {
        await storage.createTicketStatusHistory({
          ticketId: ticket.id,
          previousStatus: ticket.status,
          newStatus: newStatus,
          changedBy: userId,
          changedByName: user.fullName || user.username,
          reason: isStaff ? 'Respuesta del equipo de soporte' : 'Respuesta del cliente'
        });
      }

      res.status(201).json(response);
    } catch (error: any) {
      console.error('Error creating ticket response:', error);
      res.status(400).send(error.message);
    }
  });

  // GET /api/support-tickets-stats - Get ticket statistics (superadmin/soporte only)
  app.get("/api/support-tickets-stats", requireAuth, async (req, res) => {
    try {
      if (!hasSupportAccess(req.user!.role)) {
        return res.status(403).send("Solo administradores pueden ver estadísticas");
      }

      const allTickets = await storage.getSupportTickets();
      
      const stats = {
        total: allTickets.length,
        abierto: allTickets.filter(t => t.status === 'abierto').length,
        enRevision: allTickets.filter(t => t.status === 'en_revision').length,
        enProgreso: allTickets.filter(t => t.status === 'en_progreso').length,
        pendienteCliente: allTickets.filter(t => t.status === 'pendiente_cliente').length,
        resuelto: allTickets.filter(t => t.status === 'resuelto').length,
        cerrado: allTickets.filter(t => t.status === 'cerrado').length,
        byPriority: {
          critica: allTickets.filter(t => t.priority === 'critica').length,
          alta: allTickets.filter(t => t.priority === 'alta').length,
          media: allTickets.filter(t => t.priority === 'media').length,
          baja: allTickets.filter(t => t.priority === 'baja').length,
        },
        byCategory: {
          soporte_tecnico: allTickets.filter(t => t.category === 'soporte_tecnico').length,
          facturacion: allTickets.filter(t => t.category === 'facturacion').length,
          nueva_funcionalidad: allTickets.filter(t => t.category === 'nueva_funcionalidad').length,
          error_bug: allTickets.filter(t => t.category === 'error_bug').length,
          capacitacion: allTickets.filter(t => t.category === 'capacitacion').length,
          consulta_general: allTickets.filter(t => t.category === 'consulta_general').length,
        }
      };

      res.json(stats);
    } catch (error: any) {
      console.error('Error fetching ticket stats:', error);
      res.status(500).send('Error al obtener estadísticas de tickets');
    }
  });

  // SUPPORT ACCESS AUTHORIZATION SYSTEM - Transparencia y autorización de acceso
  // Cumplimiento con Ley 1581/2012 (Protección de Datos Personales)

  // POST /api/support-access/request - Request access to a company (support staff only)
  app.post("/api/support-access/request", requireAuth, async (req, res) => {
    try {
      const user = req.user!;
      
      // Only soporte role can request access
      if (!isSupportOnlyRole(user.role)) {
        return res.status(403).send("Solo el personal de soporte puede solicitar acceso");
      }

      const { companyId, justification, scope, relatedTicketId, requestedDurationMinutes } = req.body;

      if (!companyId || !justification) {
        return res.status(400).send("Debe proporcionar empresa y justificación");
      }

      // Get company info
      const company = await storage.getCompany(companyId);
      if (!company) {
        return res.status(404).send("Empresa no encontrada");
      }

      // Check for existing pending or active session
      const existingPending = await storage.getPendingSupportAccessSessions(companyId);
      const myPending = existingPending.find(s => s.supportUserId === user.id);
      if (myPending) {
        return res.status(400).send("Ya tiene una solicitud de acceso pendiente para esta empresa");
      }

      const activeSession = await storage.getActiveSupportAccessSession(user.id, companyId);
      if (activeSession) {
        return res.status(400).send("Ya tiene una sesión de acceso activa para esta empresa");
      }

      // Get related ticket info if provided
      let relatedTicketNumber: string | undefined;
      if (relatedTicketId) {
        const ticket = await storage.getSupportTicket(relatedTicketId);
        relatedTicketNumber = ticket?.ticketNumber;
      }

      // Create the access session
      const session = await storage.createSupportAccessSession({
        supportUserId: user.id,
        supportUserName: user.fullName || user.username,
        companyId,
        companyName: company.name,
        justification,
        scope: scope || 'read_only',
        relatedTicketId: relatedTicketId || null,
        relatedTicketNumber: relatedTicketNumber || null,
        requestedDurationMinutes: requestedDurationMinutes || 120,
        approvedBy: null,
        approvedByName: null,
        denialReason: null,
        revokedReason: null,
        legalBasis: 'Prestación de servicios de soporte técnico',
        dataProcessingPurpose: 'Resolución de incidencia técnica',
      });

      // Create audit event
      await storage.createSupportAccessEvent({
        sessionId: session.id,
        eventType: 'request_created',
        actorId: user.id,
        actorName: user.fullName || user.username,
        actorRole: user.role,
        details: JSON.stringify({ justification, scope, relatedTicketId }),
        ipAddress: req.ip || null,
        userAgent: req.get('user-agent') || null,
      });

      // Send notification to company superusuario/admin (with fallback)
      let companyAdmin = await storage.getCompanySuperusuario(companyId);
      if (!companyAdmin) {
        // Fallback to admin role if no superusuario
        const adminUsers = await db.select().from(schema.users)
          .where(and(
            eq(schema.users.companyId, companyId),
            eq(schema.users.role, 'admin')
          ))
          .limit(1);
        companyAdmin = adminUsers[0];
      }
      
      if (companyAdmin) {
        try {
          // Create internal message notification
          await storage.createInternalMessage({
            companyId,
            senderId: companyAdmin.id,
            senderName: "SST Colombia Soporte",
            senderRole: 'superadmin' as any,
            receiverId: companyAdmin.id,
            receiverName: companyAdmin.fullName || companyAdmin.username,
            receiverRole: companyAdmin.role,
            subject: `Solicitud de Acceso de Soporte - ${session.sessionNumber}`,
            content: `El personal de soporte "${user.fullName || user.username}" solicita acceso a los datos de su empresa.\n\nJustificación: ${justification}\n\nAlcance: ${scope === 'read_write' ? 'Lectura y escritura' : 'Solo lectura'}\nDuración solicitada: ${requestedDurationMinutes || 120} minutos\n\nPor favor, vaya a Configuración > Accesos de Soporte para aprobar o denegar esta solicitud.`,
            priority: 'urgent',
            relatedEntity: 'support_access',
            relatedEntityId: session.id,
          });

          // Send email notification
          if (companyAdmin.email) {
            await sendSupportAccessRequestEmail(companyAdmin.email, {
              recipientName: companyAdmin.fullName || companyAdmin.username,
              companyName: company.name,
              supportUserName: user.fullName || user.username,
              justification,
              scope: scope || 'read_only',
              durationMinutes: requestedDurationMinutes || 120,
              sessionNumber: session.sessionNumber,
              relatedTicket: relatedTicketNumber || undefined,
            });
          }

          await storage.createSupportAccessEvent({
            sessionId: session.id,
            eventType: 'notification_sent',
            actorId: user.id,
            actorName: 'Sistema',
            actorRole: 'system',
            details: JSON.stringify({ recipientId: companyAdmin.id, method: 'internal_message_and_email' }),
            ipAddress: null,
            userAgent: null,
          });
        } catch (notifError) {
          console.error('Error sending access request notification:', notifError);
        }
      }

      res.status(201).json(session);
    } catch (error: any) {
      console.error('Error creating support access request:', error);
      res.status(500).send('Error al crear solicitud de acceso');
    }
  });

  // GET /api/support-access/sessions - Get access sessions
  app.get("/api/support-access/sessions", requireAuth, async (req, res) => {
    try {
      const user = req.user!;
      const { companyId } = req.query;

      // Support staff sees their own sessions, company admins see their company's sessions
      if (isSupportOnlyRole(user.role)) {
        const sessions = await storage.getSupportAccessSessions();
        const mySessions = sessions.filter(s => s.supportUserId === user.id);
        return res.json(mySessions);
      }

      if (hasGlobalAccess(user.role)) {
        // Superadmin can see all
        const sessions = await storage.getSupportAccessSessions(companyId as string | undefined);
        return res.json(sessions);
      }

      // Company users see their company's sessions
      if (!user.companyId) {
        return res.status(400).send("Usuario no tiene empresa asignada");
      }

      const sessions = await storage.getSupportAccessSessions(user.companyId);
      res.json(sessions);
    } catch (error: any) {
      console.error('Error fetching support access sessions:', error);
      res.status(500).send('Error al obtener sesiones de acceso');
    }
  });

  // GET /api/support-access/pending - Get pending access requests for current user's company
  app.get("/api/support-access/pending", requireAuth, async (req, res) => {
    try {
      const user = req.user!;
      
      if (!user.companyId) {
        return res.json([]);
      }

      // Only company admins can see pending requests
      if (!hasCompanyAdminAccess(user.role)) {
        return res.status(403).send("No tiene permisos para ver solicitudes pendientes");
      }

      const pending = await storage.getPendingSupportAccessSessions(user.companyId);
      res.json(pending);
    } catch (error: any) {
      console.error('Error fetching pending access requests:', error);
      res.status(500).send('Error al obtener solicitudes pendientes');
    }
  });

  // GET /api/support-access/sessions/:id - Get single session with events
  app.get("/api/support-access/sessions/:id", requireAuth, async (req, res) => {
    try {
      const session = await storage.getSupportAccessSession(req.params.id);
      if (!session) {
        return res.status(404).send("Sesión no encontrada");
      }

      const user = req.user!;
      
      // Check permissions
      if (!hasGlobalAccess(user.role) && 
          !isSupportOnlyRole(user.role) && 
          session.companyId !== user.companyId) {
        return res.status(403).send("No tiene permisos para ver esta sesión");
      }

      const events = await storage.getSupportAccessEvents(session.id);

      // Record that client viewed the request
      if (session.companyId === user.companyId && session.status === 'pending') {
        await storage.createSupportAccessEvent({
          sessionId: session.id,
          eventType: 'client_viewed',
          actorId: user.id,
          actorName: user.fullName || user.username,
          actorRole: user.role,
          details: null,
          ipAddress: req.ip || null,
          userAgent: req.get('user-agent') || null,
        });
      }

      res.json({ session, events });
    } catch (error: any) {
      console.error('Error fetching access session:', error);
      res.status(500).send('Error al obtener sesión de acceso');
    }
  });

  // POST /api/support-access/sessions/:id/approve - Approve access request
  app.post("/api/support-access/sessions/:id/approve", requireAuth, async (req, res) => {
    try {
      const user = req.user!;
      const session = await storage.getSupportAccessSession(req.params.id);
      
      if (!session) {
        return res.status(404).send("Sesión no encontrada");
      }

      // Only company admins of the same company can approve
      if (session.companyId !== user.companyId || !hasCompanyAdminAccess(user.role)) {
        return res.status(403).send("No tiene permisos para aprobar esta solicitud");
      }

      if (session.status !== 'pending') {
        return res.status(400).send("Esta solicitud ya fue procesada");
      }

      // Calculate expiration time
      const expiresAt = new Date();
      expiresAt.setMinutes(expiresAt.getMinutes() + (session.requestedDurationMinutes || 120));

      const updated = await storage.updateSupportAccessSession(session.id, {
        status: 'approved',
        approvedBy: user.id,
        approvedByName: user.fullName || user.username,
        approvedAt: new Date(),
        expiresAt,
      });

      // Create audit event
      await storage.createSupportAccessEvent({
        sessionId: session.id,
        eventType: 'approved',
        actorId: user.id,
        actorName: user.fullName || user.username,
        actorRole: user.role,
        details: JSON.stringify({ expiresAt }),
        ipAddress: req.ip || null,
        userAgent: req.get('user-agent') || null,
      });

      // Send notification to support staff about approval
      const supportUser = await storage.getUser(session.requestedBy);
      if (supportUser) {
        const company = await storage.getCompany(session.companyId);
        try {
          await storage.createInternalMessage({
            companyId: session.companyId,
            senderId: user.id,
            senderName: user.fullName || user.username,
            senderRole: user.role,
            receiverId: supportUser.id,
            receiverName: supportUser.fullName || supportUser.username,
            receiverRole: supportUser.role,
            subject: `Acceso Aprobado - ${company?.name || 'Empresa'}`,
            content: `Su solicitud de acceso ha sido APROBADA.\n\nEmpresa: ${company?.name || 'N/A'}\nAprobado por: ${user.fullName || user.username}\nExpira: ${expiresAt.toLocaleString('es-CO')}\n\nYa puede acceder a los datos de la empresa.`,
            priority: 'high',
            relatedEntity: 'support_access',
            relatedEntityId: session.id,
          });
        } catch (notifError) {
          console.error('Error sending approval notification:', notifError);
        }
      }

      res.json(updated);
    } catch (error: any) {
      console.error('Error approving access request:', error);
      res.status(500).send('Error al aprobar solicitud');
    }
  });

  // POST /api/support-access/sessions/:id/deny - Deny access request
  app.post("/api/support-access/sessions/:id/deny", requireAuth, async (req, res) => {
    try {
      const user = req.user!;
      const { denialReason } = req.body;
      const session = await storage.getSupportAccessSession(req.params.id);
      
      if (!session) {
        return res.status(404).send("Sesión no encontrada");
      }

      // Only company admins of the same company can deny
      if (session.companyId !== user.companyId || !hasCompanyAdminAccess(user.role)) {
        return res.status(403).send("No tiene permisos para denegar esta solicitud");
      }

      if (session.status !== 'pending') {
        return res.status(400).send("Esta solicitud ya fue procesada");
      }

      const updated = await storage.updateSupportAccessSession(session.id, {
        status: 'denied',
        denialReason: denialReason || 'Denegado por el administrador',
      });

      // Create audit event
      await storage.createSupportAccessEvent({
        sessionId: session.id,
        eventType: 'denied',
        actorId: user.id,
        actorName: user.fullName || user.username,
        actorRole: user.role,
        details: JSON.stringify({ denialReason }),
        ipAddress: req.ip || null,
        userAgent: req.get('user-agent') || null,
      });

      // Send notification to support staff about denial
      const supportUserDeny = await storage.getUser(session.requestedBy);
      if (supportUserDeny) {
        const companyDeny = await storage.getCompany(session.companyId);
        try {
          await storage.createInternalMessage({
            companyId: session.companyId,
            senderId: user.id,
            senderName: user.fullName || user.username,
            senderRole: user.role,
            receiverId: supportUserDeny.id,
            receiverName: supportUserDeny.fullName || supportUserDeny.username,
            receiverRole: supportUserDeny.role,
            subject: `Acceso Denegado - ${companyDeny?.name || 'Empresa'}`,
            content: `Su solicitud de acceso ha sido DENEGADA.\n\nEmpresa: ${companyDeny?.name || 'N/A'}\nDenegado por: ${user.fullName || user.username}\nRazón: ${denialReason || 'No especificada'}`,
            priority: 'normal',
            relatedEntity: 'support_access',
            relatedEntityId: session.id,
          });
        } catch (notifError) {
          console.error('Error sending denial notification:', notifError);
        }
      }

      res.json(updated);
    } catch (error: any) {
      console.error('Error denying access request:', error);
      res.status(500).send('Error al denegar solicitud');
    }
  });

  // POST /api/support-access/sessions/:id/revoke - Revoke approved access
  app.post("/api/support-access/sessions/:id/revoke", requireAuth, async (req, res) => {
    try {
      const user = req.user!;
      const { revokedReason } = req.body;
      const session = await storage.getSupportAccessSession(req.params.id);
      
      if (!session) {
        return res.status(404).send("Sesión no encontrada");
      }

      // Only company admins of the same company can revoke
      if (session.companyId !== user.companyId || !hasCompanyAdminAccess(user.role)) {
        return res.status(403).send("No tiene permisos para revocar este acceso");
      }

      if (session.status !== 'approved') {
        return res.status(400).send("Solo se pueden revocar accesos aprobados");
      }

      const updated = await storage.updateSupportAccessSession(session.id, {
        status: 'revoked',
        revokedAt: new Date(),
        revokedReason: revokedReason || 'Revocado por el administrador',
      });

      // Create audit event
      await storage.createSupportAccessEvent({
        sessionId: session.id,
        eventType: 'revoked',
        actorId: user.id,
        actorName: user.fullName || user.username,
        actorRole: user.role,
        details: JSON.stringify({ revokedReason }),
        ipAddress: req.ip || null,
        userAgent: req.get('user-agent') || null,
      });

      // Send notification to support staff about revocation
      const supportUserRevoke = await storage.getUser(session.requestedBy);
      if (supportUserRevoke) {
        const companyRevoke = await storage.getCompany(session.companyId);
        try {
          await storage.createInternalMessage({
            companyId: session.companyId,
            senderId: user.id,
            senderName: user.fullName || user.username,
            senderRole: user.role,
            receiverId: supportUserRevoke.id,
            receiverName: supportUserRevoke.fullName || supportUserRevoke.username,
            receiverRole: supportUserRevoke.role,
            subject: `Acceso Revocado - ${companyRevoke?.name || 'Empresa'}`,
            content: `Su acceso ha sido REVOCADO.\n\nEmpresa: ${companyRevoke?.name || 'N/A'}\nRevocado por: ${user.fullName || user.username}\nRazón: ${revokedReason || 'No especificada'}\n\nYa no tiene acceso a los datos de esta empresa.`,
            priority: 'high',
            relatedEntity: 'support_access',
            relatedEntityId: session.id,
          });
        } catch (notifError) {
          console.error('Error sending revocation notification:', notifError);
        }
      }

      res.json(updated);
    } catch (error: any) {
      console.error('Error revoking access:', error);
      res.status(500).send('Error al revocar acceso');
    }
  });

