  // POST /api/support-access/log-access - Log data access event under active session
  // This endpoint records access events for audit trail per Ley 1581/2012
  app.post("/api/support-access/log-access", requireAuth, async (req, res) => {
    try {
      const user = req.user!;
      const { sessionId, accessType, resourceType, resourceId, details } = req.body;

      if (!isSupportOnlyRole(user.role)) {
        return res.status(403).send("Solo personal de soporte puede registrar accesos");
      }

      if (!sessionId || !accessType) {
        return res.status(400).send("Se requiere sessionId y accessType");
      }

      // Verify session is active and belongs to this user
      const session = await storage.getSupportAccessSession(sessionId);
      if (!session) {
        return res.status(404).send("Sesión no encontrada");
      }
      if (session.supportUserId !== user.id) {
        return res.status(403).send("No autorizado para esta sesión");
      }
      if (session.status !== 'approved') {
        return res.status(403).send("La sesión no está aprobada");
      }
      if (session.expiresAt && new Date(session.expiresAt) < new Date()) {
        return res.status(403).send("La sesión ha expirado");
      }

      // Determine event type based on accessType
      const eventType = accessType === 'write' ? 'data_modified' : 'data_accessed';
      
      // Create audit event
      await storage.createSupportAccessEvent({
        sessionId: session.id,
        actorId: user.id,
        eventType: eventType as 'data_accessed' | 'data_modified',
        payload: {
          resourceType: resourceType || 'unknown',
          resourceId: resourceId || null,
          details: details || {},
          timestamp: new Date().toISOString(),
          ipAddress: req.ip || 'unknown',
        },
      });

      res.json({ success: true, eventType });
    } catch (error: any) {
      console.error('Error logging access:', error);
      res.status(500).send('Error al registrar acceso');
    }
  });

  // POST /api/support-access/start-session - Record when support starts accessing company data
  // This is called once when support begins viewing company data under an approved session
  app.post("/api/support-access/start-session", requireAuth, async (req, res) => {
    try {
      const user = req.user!;
      const { companyId } = req.body;

      if (!isSupportOnlyRole(user.role)) {
        return res.status(403).send("Solo personal de soporte puede iniciar sesiones de acceso");
      }

      if (!companyId) {
        return res.status(400).send("Se requiere companyId");
      }

      // Get active session for this company
      const session = await storage.getActiveSupportAccessSession(user.id, companyId);
      if (!session) {
        return res.status(403).json({ 
          error: "No tiene una sesión de acceso activa para esta empresa",
          requiresAccessRequest: true 
        });
      }

      // Record access_started event
      await storage.createSupportAccessEvent({
        sessionId: session.id,
        actorId: user.id,
        eventType: 'access_started',
        payload: {
          companyId,
          startedAt: new Date().toISOString(),
          ipAddress: req.ip || 'unknown',
          userAgent: req.headers['user-agent'] || 'unknown',
        },
      });

      // Get company name for response
      const company = await storage.getCompany(companyId);

      res.json({ 
        success: true, 
        session: {
          ...session,
          companyName: company?.name || 'Empresa desconocida',
        },
        message: `Acceso a ${company?.name || 'la empresa'} iniciado correctamente`
      });
    } catch (error: any) {
      console.error('Error starting access session:', error);
      res.status(500).send('Error al iniciar sesión de acceso');
    }
  });

