  // GET /api/internal-messages/recipients - Get available recipients for sending messages
  app.get("/api/internal-messages/recipients", requireAuth, async (req, res) => {
    try {
      const user = req.user!;
      let allRecipients: Array<{ id: string; fullName: string | null; role: string }> = [];
      
      // Handle users with companyId (normal case)
      if (user.companyId) {
        allRecipients = await storage.getMessageRecipients(user.companyId, user.role);
        
        // SST-2025-0046: Also include support users who have active sessions for this company
        const activeSupportSessions = await storage.getSupportAccessSessions(user.companyId);
        const now = new Date();
        const activeSupportUserIds = [...new Set(activeSupportSessions
          .filter(s => 
            s.status === 'approved' && 
            (!s.startedAt || new Date(s.startedAt) <= now) &&
            (!s.endedAt || new Date(s.endedAt) > now)
          )
          .map(s => s.supportUserId))];
        
        // Get support users and add to recipients (avoid duplicates)
        const existingIds = new Set(allRecipients.map(r => r.id));
        for (const supportUserId of activeSupportUserIds) {
          if (!existingIds.has(supportUserId)) {
            const supportUser = await storage.getUser(supportUserId);
            if (supportUser) {
              allRecipients.push({
                id: supportUser.id,
                fullName: supportUser.fullName || supportUser.username,
                role: supportUser.role
              });
              existingIds.add(supportUserId);
            }
          }
        }
      } 
      // Handle superadmin: get recipients from all companies or filtered by query param
      else if (user.role === 'superadmin') {
        const queryCompanyId = req.query.companyId as string | undefined;
        if (queryCompanyId) {
          // Get recipients from specific company
          allRecipients = await storage.getMessageRecipients(queryCompanyId, user.role);
        } else {
          // Get all users from all companies
          const allUsers = await storage.getAllUsers();
          allRecipients = allUsers.map(u => ({
            id: u.id,
            fullName: u.fullName,
            role: u.role
          }));
        }
      }
      // Handle soporte: get recipients only from companies with active access sessions
      else if (user.role === 'soporte') {
        const activeSessions = await storage.getSupportAccessSessionsByUser(user.id);
        const now = new Date();
        const activeCompanyIds = [...new Set(activeSessions
          .filter(s => 
            s.status === 'approved' && 
            (!s.startedAt || new Date(s.startedAt) <= now) &&
            (!s.endedAt || new Date(s.endedAt) > now)
          )
          .map(s => s.companyId))];
        
        if (activeCompanyIds.length === 0) {
          // No active sessions, no recipients
          return res.json([]);
        }
        
        // Get recipients from all companies with active sessions
        for (const companyId of activeCompanyIds) {
          const recipients = await storage.getMessageRecipients(companyId, user.role);
          allRecipients = allRecipients.concat(recipients);
        }
        
        // Remove duplicates (in case a user appears in multiple companies)
        const uniqueRecipients = new Map<string, typeof allRecipients[0]>();
        allRecipients.forEach(r => uniqueRecipients.set(r.id, r));
        allRecipients = Array.from(uniqueRecipients.values());
      }
      // Other users without companyId cannot send messages
      else {
        return res.status(400).send("Usuario no tiene empresa asignada");
      }
      
      // Filter out current user from recipients
      const filteredRecipients = allRecipients.filter(r => r.id !== user.id);
      res.json(filteredRecipients);
    } catch (error: any) {
      console.error('Error fetching recipients:', error);
      res.status(500).send('Error al obtener destinatarios');
    }
  });

