  // POST /api/internal-messages - Send a new message
  app.post("/api/internal-messages", requireAuth, async (req, res) => {
    try {
      const user = req.user!;
      if (!user.companyId) {
        return res.status(400).send("Usuario no tiene empresa asignada");
      }
      
      const { receiverId, subject, content, priority, relatedEntity, relatedEntityId } = req.body;
      
      if (!receiverId || !subject || !content) {
        return res.status(400).send("Faltan campos requeridos: receiverId, subject, content");
      }
      
      // Get receiver info
      const receiver = await storage.getUser(receiverId);
      if (!receiver) {
        return res.status(404).send("Destinatario no encontrado");
      }
      
      // Check if user is support staff (superadmin or soporte)
      const isSupportUser = user.role === 'superadmin' || user.role === 'soporte';
      
      // SST-2025-0046: Allow cross-company messaging when:
      // - Sender is support/superadmin (already handled by isSupportUser)
      // - Receiver is support/superadmin (they can receive from any company)
      const receiverIsSupportUser = receiver.role === 'soporte' || receiver.role === 'superadmin';
      if (!isSupportUser && !receiverIsSupportUser && receiver.companyId !== user.companyId) {
        return res.status(403).send("El destinatario no pertenece a su empresa");
      }
      
      // Security: Soporte role must have active access session to receiver's company
      // Superadmin has global access so no session check needed
      if (user.role === 'soporte' && receiver.companyId) {
        const activeSession = await storage.getActiveSupportAccessSession(user.id, receiver.companyId);
        const now = new Date();
        if (!activeSession || 
            activeSession.status !== 'approved' ||
            (activeSession.startedAt && new Date(activeSession.startedAt) > now) ||
            (activeSession.endedAt && new Date(activeSession.endedAt) <= now)) {
          return res.status(403).send("Debe tener una sesión de acceso activa a la empresa del destinatario para enviar mensajes");
        }
      }
      
      // Use receiver's companyId for support users, sender's companyId otherwise
      const messageCompanyId = isSupportUser ? receiver.companyId : user.companyId;
      
      const message = await storage.createInternalMessage({
        companyId: messageCompanyId,
        senderId: user.id,
        senderName: user.fullName || user.username,
        senderRole: user.role,
        receiverId,
        receiverName: receiver.fullName || receiver.username,
        receiverRole: receiver.role,
        subject,
        content,
        priority: priority || 'normal',
        status: 'unread',
        relatedEntity: relatedEntity || null,
        relatedEntityId: relatedEntityId || null,
      });
      
      res.status(201).json(message);
      // Notify receiver via WebSocket
      notifyNewMessage(receiverId, user.id, message.id);
    } catch (error: any) {
      console.error('Error creating message:', error);
      res.status(500).send('Error al enviar mensaje');
    }
  });

