  // HEALTH CHECK ENDPOINT - Infrastructure Monitoring (Bloque 2)
  
  /**
   * Health check endpoint for uptime monitoring (UptimeRobot, Pingdom, etc.)
   * Returns system status + database connectivity check
   * PUBLIC endpoint (no authentication required)
   */
  app.get('/health', async (req, res) => {
    const startTime = Date.now();
    
    try {
      // Check database connectivity with a simple query
      const dbCheck = await storage.healthCheck();
      
      const responseTime = Date.now() - startTime;
      
      // If database check failed, return 503 Service Unavailable
      if (!dbCheck) {
        return res.status(503).json({
          status: 'error',
          timestamp: new Date().toISOString(),
          uptime: process.uptime(),
          environment: process.env.NODE_ENV || 'development',
          database: {
            status: 'disconnected',
            responseTime: `${responseTime}ms`
          },
          version: '1.0.0'
        });
      }
      
      // Database is healthy, return 200 OK
      res.status(200).json({
        status: 'ok',
        timestamp: new Date().toISOString(),
        uptime: process.uptime(),
        environment: process.env.NODE_ENV || 'development',
        database: {
          status: 'connected',
          responseTime: `${responseTime}ms`
        },
        version: '1.0.0'
      });
    } catch (error: any) {
      const responseTime = Date.now() - startTime;
      
      res.status(503).json({
        status: 'error',
        timestamp: new Date().toISOString(),
        uptime: process.uptime(),
        environment: process.env.NODE_ENV || 'development',
        database: {
          status: 'error',
          error: formatZodErrorForBulkImport(error),
          responseTime: `${responseTime}ms`
        },
        version: '1.0.0'
      });
    }
  });


