  // Helper function for getting company ID from header or user
  function getConvivenciaCompanyId(req: any): string | null {
    // First try X-Company-Id header (for admin context switching)
    const headerCompanyId = req.headers['x-company-id'] as string;
    if (headerCompanyId) return headerCompanyId;
    // Fall back to user's company
    return req.user?.companyId || null;
  }

