  app.post("/api/convivencia-votacion/:eleccionId/vote", requireAuth, async (req, res) => {
    try {
      const companyId = getConvivenciaCompanyId(req);
      if (!companyId) {
        return res.status(403).send("Usuario no asociado a una empresa");
      }
      const { workerId, candidatoIds } = req.body;
      if (!workerId || !candidatoIds || !Array.isArray(candidatoIds) || candidatoIds.length === 0) {
        return res.status(400).send("workerId y candidatoIds son requeridos");
      }
      const eleccion = await storage.getConvivenciaEleccion(req.params.eleccionId);
      if (!eleccion || eleccion.companyId !== companyId) {
        return res.status(404).send("Elección no encontrada o acceso no autorizado");
      }
      if (eleccion.estado !== 'votacion') {
        return res.status(400).send("La elección no está en fase de votación");
      }
      // Verify the worker belongs to the same company as the election
      const worker = await storage.getWorker(workerId, companyId);
      if (!worker) {
        return res.status(404).send("Trabajador no encontrado o no pertenece a la empresa");
      }
      const yaVoto = await storage.hasVotedConvivencia(req.params.eleccionId, workerId);
      if (yaVoto) {
        return res.status(400).send("El trabajador ya ha votado en esta elección");
      }
      const ipAddress = req.ip || req.connection.remoteAddress || '';
      await storage.registrarVotoConvivencia(req.params.eleccionId, workerId, candidatoIds, ipAddress);
      res.json({ success: true, message: "Voto registrado exitosamente" });
    } catch (error: any) {
      res.status(400).send(error.message);
    }
  });

