  // GET /api/reportes/promocion-prevencion/pdf - Generate PDF report
  app.get("/api/reportes/promocion-prevencion/pdf", requireAuth, requirePermission("workers:view"), async (req, res) => {
    try {
      const companyId = req.user?.companyId;
      if (!companyId) return res.status(401).json({ error: "No autorizado" });

      const company = await storage.getCompany(companyId);
      if (!company) return res.status(404).json({ error: "Empresa no encontrada" });

      const activities = await storage.getPromotionPreventionActivities(companyId);

      const doc = new PDFDocument({ size: 'LETTER', margin: 35, bufferPages: true });
      
      // Add trial watermark if subscription is in trial period
      const pdf38664_subscription = await storage.getSubscriptionByCompany(companyId);
      const pdf38664_trialStatus = getTrialStatus(pdf38664_subscription?.status || 'trial', pdf38664_subscription?.trialEnd || null, true, true);
      setupTrialWatermarkOnAllPages(doc, pdf38664_trialStatus.requiresWatermark);
      res.setHeader('Content-Type', 'application/pdf');
      res.setHeader('Content-Disposition', `attachment; filename="promocion-prevencion-${Date.now()}.pdf"`);
      doc.pipe(res);

      const margin = 35;
      const pageWidth = doc.page.width;
      const contentWidth = pageWidth - 2 * margin;
      const logoBuffer = await loadCompanyLogoBuffer(company.logoUrl);
      // Worker photo not needed for muestreo PDF

      let currentY = setupPdfHeadersFooters({
        doc,
        company,
        documentTitle: 'ACTIVIDADES DE PROMOCIÓN Y PREVENCIÓN EN SALUD',
        documentCode: 'SST-FMT-312',
        version: '1.0',
        date: new Date(),
        elaboro: req.user?.fullName || 'Administrador del Sistema',
        autorizo: 'Responsable SST',
        aprobo: 'Gerencia',
        logoBuffer: logoBuffer || undefined
      });

      // ISO Banner (like sociodemografico)
      doc.fontSize(8).font('Helvetica-Bold').fillColor('#1e7e34');
      doc.text('Sistema Integrado de Gestión', margin, currentY);
      doc.font('Helvetica').fontSize(7).fillColor('#666666');
      doc.text('ISO 9001:2015 | ISO 14001:2015 | ISO 45001:2018', margin, currentY + 10);
      currentY += 25;
      
      doc.fontSize(9).font('Helvetica').fillColor('#333333');
      doc.text('Estándar 3.1.2 - Resolución 0312/2019', margin, currentY, { align: 'center', width: contentWidth });
      currentY += 20;

      // Green bar section header - CARACTERIZACIÓN DEL PROGRAMA
      doc.rect(margin, currentY, contentWidth, 18).fill('#1e7e34');
      doc.fontSize(10).font('Helvetica-Bold').fillColor('#ffffff');
      doc.text('CARACTERIZACIÓN DEL PROGRAMA', margin + 8, currentY + 4);
      currentY += 25;
      doc.fillColor('#000000');

      const activityTypeLabels: Record<string, string> = {
        medicina_trabajo: 'Medicina del Trabajo',
        promocion_prevencion: 'Promoción y Prevención',
        campana_especial: 'Campaña Especial',
        examen_ocupacional: 'Examen Ocupacional',
        capacitacion_salud: 'Capacitación en Salud'
      };

      const statusLabels: Record<string, string> = {
        programada: 'Programada',
        en_ejecucion: 'En Ejecución',
        completada: 'Completada',
        cancelada: 'Cancelada'
      };

      // Group activities by type
      const byType = activities.reduce((acc: Record<string, typeof activities>, act) => {
        const type = act.activityType || 'sin_tipo';
        if (!acc[type]) acc[type] = [];
        acc[type].push(act);
        return acc;
      }, {});

      // Calculate stats
      let totalActivities = 0;
      let totalCompleted = 0;
      Object.values(byType).forEach(acts => {
        totalActivities += acts.length;
        totalCompleted += acts.filter(a => a.status === 'completada').length;
      });
      const totalPercentage = totalActivities > 0 ? Math.round((totalCompleted / totalActivities) * 100) : 0;

      // Summary text
      doc.fontSize(10).font('Helvetica-Bold').fillColor('#333333');
      doc.text('Total de actividades programadas: ' + totalActivities, margin, currentY);
      currentY += 15;
      
      doc.fontSize(9).font('Helvetica').fillColor('#000000');
      doc.text('Distribución por Tipo de Actividad:', margin, currentY);
      currentY += 12;
      
      Object.entries(byType).forEach(([type, acts]) => {
        const completed = acts.filter(a => a.status === 'completada').length;
        const pct = acts.length > 0 ? Math.round((completed / acts.length) * 100) : 0;
        doc.text(`  • ${activityTypeLabels[type] || type}: ${acts.length} (${pct}% completadas)`, margin, currentY);
        currentY += 10;
      });
      currentY += 5;

      doc.fontSize(10).font('Helvetica-Bold').fillColor('#333333');
      doc.text('Estado General:', margin, currentY);
      currentY += 12;
      doc.fontSize(9).font('Helvetica').fillColor('#000000');
      doc.text(`  • Programadas: ${activities.filter(a => a.status === 'programada').length}`, margin, currentY);
      currentY += 10;
      doc.text(`  • En Ejecución: ${activities.filter(a => a.status === 'en_ejecucion').length}`, margin, currentY);
      currentY += 10;
      doc.text(`  • Completadas: ${totalCompleted}`, margin, currentY);
      currentY += 10;
      doc.text(`  • Canceladas: ${activities.filter(a => a.status === 'cancelada').length}`, margin, currentY);
      currentY += 15;

      doc.fontSize(10).font('Helvetica-Bold').fillColor('#333333');
      doc.text('Porcentaje de Cumplimiento:', margin, currentY);
      currentY += 12;
      doc.fontSize(9).font('Helvetica').fillColor('#000000');
      doc.text(`  • ${totalPercentage}% de las actividades han sido completadas`, margin, currentY);
      currentY += 20;

      // Green bar section header - DETALLE DE ACTIVIDADES
      if (currentY > doc.page.height - 200) {
        doc.addPage();
        currentY = 50;
      }
      doc.rect(margin, currentY, contentWidth, 18).fill('#1e7e34');
      doc.fontSize(10).font('Helvetica-Bold').fillColor('#ffffff');
      doc.text('DETALLE DE ACTIVIDADES', margin + 8, currentY + 4);
      currentY += 25;
      doc.fillColor('#000000');

      if (activities.length === 0) {
        doc.fontSize(9).font('Helvetica-Oblique').fillColor('#666666');
        doc.text('No hay actividades registradas.', margin, currentY);
        currentY += 20;
      } else {
        Object.entries(byType).forEach(([type, acts]) => {
          if (currentY > doc.page.height - 100) {
            doc.addPage();
            currentY = 50;
          }

          doc.fontSize(10).font('Helvetica-Bold').fillColor('#1e7e34');
          doc.text(activityTypeLabels[type] || type, margin, currentY);
          currentY += 14;
          doc.fillColor('#000000');

          acts.slice(0, 5).forEach(act => {
            if (currentY > doc.page.height - 80) {
              doc.addPage();
              currentY = 50;
            }

            doc.font('Helvetica-Bold').fontSize(9).text(`• ${act.title}`, margin + 10, currentY);
            currentY += 11;
            doc.font('Helvetica').fontSize(8);
            const dateStr = act.startDate ? (typeof act.startDate === 'string' ? act.startDate : new Date(act.startDate).toLocaleDateString('es-CO')) : 'N/A';
            doc.text(`  Estado: ${statusLabels[act.status] || act.status} | Fecha: ${dateStr} | Modalidad: ${act.modality || 'N/A'}`, margin + 15, currentY);
            currentY += 10;
            doc.text(`  Responsable: ${act.responsibleName || 'N/A'}`, margin + 15, currentY);
            currentY += 12;
          });
          if (acts.length > 5) {
            doc.fontSize(8).font('Helvetica-Oblique').fillColor('#666666');
            doc.text(`  ... y ${acts.length - 5} actividades más`, margin + 15, currentY);
            currentY += 12;
            doc.fillColor('#000000');
          }
          currentY += 8;
        });
      }

      // Green bar section header - CUMPLIMIENTO NORMATIVO
      if (currentY > doc.page.height - 150) {
        doc.addPage();
        currentY = 50;
      }
      currentY += 10;
      doc.rect(margin, currentY, contentWidth, 18).fill('#1e7e34');
      doc.fontSize(10).font('Helvetica-Bold').fillColor('#ffffff');
      doc.text('CUMPLIMIENTO NORMATIVO', margin + 8, currentY + 4);
      currentY += 25;

      doc.fontSize(9).font('Helvetica').fillColor('#000000');
      const checkItems = [
        'Programa de actividades de promoción y prevención documentado',
        'Actividades desarrolladas basadas en el perfil epidemiológico',
        'Registro de participación de trabajadores',
        'Seguimiento y evaluación de actividades',
        'Vinculación con programas de vigilancia epidemiológica',
        'Evidencia fotográfica y material utilizado disponible',
        'Documento disponible para verificación de autoridades'
      ];

      checkItems.forEach(item => {
        doc.text(`✓ ${item}`, margin, currentY);
        currentY += 11;
      });
      currentY += 15;

      // Legal footer text
      doc.fontSize(8).font('Helvetica-Oblique').fillColor('#666666');
      doc.text('Este documento cumple con los requisitos del Estándar 3.1.2 de la Resolución 0312/2019', margin, currentY, { 
        width: contentWidth,
        align: 'center' 
      });
      currentY += 10;
      doc.text('y el Decreto 1072 de 2015, artículo 2.2.4.6.8, numeral 8.', margin, currentY, { 
        width: contentWidth,
        align: 'center' 
      });

      doc.end();
    } catch (error: any) {
      console.error('Error generating promocion-prevencion PDF:', error);
      if (!res.headersSent) {
        res.status(500).json({ error: error.message || "Error al generar PDF" });
      }
    }
  });
