  // GET /api/accident-statistics - Listar estadísticas de la empresa
  app.get("/api/accident-statistics", requireAuth, async (req, res) => {
    try {
      const user = req.user as User;
      const companyId = req.query.companyId as string || user.companyId;
      
      if (!companyId) {
        return res.status(400).json({ error: "Company ID is required" });
      }
      
      const statistics = await storage.getAccidentStatisticsByCompanyId(companyId);
      res.json(statistics);
    } catch (error) {
      console.error("Error fetching accident statistics:", error);
      res.status(500).json({ error: "Failed to fetch accident statistics" });
    }
  });

  // GET /api/accident-statistics/:year - Obtener estadísticas por año
  app.get("/api/accident-statistics/:year", requireAuth, async (req, res) => {
    try {
      const user = req.user as User;
      const companyId = req.query.companyId as string || user.companyId;
      const year = parseInt(req.params.year);
      
      if (!companyId) {
        return res.status(400).json({ error: "Company ID is required" });
      }
      
      if (isNaN(year)) {
        return res.status(400).json({ error: "Invalid year" });
      }
      
      const statistics = await storage.getAccidentStatisticsByYear(companyId, year);
      res.json(statistics);
    } catch (error) {
      console.error("Error fetching accident statistics by year:", error);
      res.status(500).json({ error: "Failed to fetch accident statistics" });
    }
  });

