  // PDF listado general de seguimientos EVS - Formato Estandarizado
  app.get("/api/evs/followups/pdf", requireAuth, async (req, res) => {
    try {
      const companyId = req.user!.companyId;
      if (!companyId) return res.status(403).send("Usuario no asociado a una empresa");
      const company = await storage.getCompany(companyId);
      if (!company) return res.status(404).send("Empresa no encontrada");
      const followups = await storage.getEvsFollowups(companyId);
      const workers = await storage.getWorkers(companyId);
      const getWorkerName = (id: string) => workers.find(w => w.id === id)?.name || 'Desconocido';
      const getWorkerPosition = (id: string) => workers.find(w => w.id === id)?.position || '';
      const logoBuffer = await loadCompanyLogoBuffer(company.logoUrl);
      // Worker photo not needed for muestreo PDF
      const { default: PDFDocument } = await import('pdfkit');
      const doc = new PDFDocument({ margin: 50, size: 'LETTER' });
      const followups_subscription = await storage.getSubscriptionByCompany(companyId);
      const followups_trialStatus = getTrialStatus(followups_subscription?.status || 'trial', followups_subscription?.trialEnd || null, true, true);
      setupTrialWatermarkOnAllPages(doc, followups_trialStatus.requiresWatermark);
      res.setHeader('Content-Type', 'application/pdf');
      res.setHeader('Content-Disposition', 'inline; filename="Seguimientos-EVS.pdf"');
      doc.pipe(res);
      
      const margin = 50;
      const pageWidth = doc.page.width;
      const contentWidth = pageWidth - 2 * margin;
      const colorVerdeSst = '#1e7e34';
      
      let currentY = setupPdfHeadersFooters({ doc, company, documentTitle: "LISTADO DE SEGUIMIENTOS - ESTILOS DE VIDA SALUDABLE", documentCode: `SST-EVS-SEG-${new Date().getFullYear()}`, version: "1.0", date: new Date(), logoBuffer });
      currentY += 25;
      
      // Sección: RESUMEN EJECUTIVO (barra verde)
      doc.rect(margin, currentY, contentWidth, 18).fill(colorVerdeSst);
      doc.fontSize(10).font('Helvetica-Bold').fillColor('#ffffff');
      doc.text('RESUMEN EJECUTIVO', margin + 8, currentY + 4);
      currentY += 26;
      doc.fillColor('#000000');
      
      const categoryLabels: Record<string, string> = { tabaquismo: 'Tabaquismo', alcoholismo: 'Alcoholismo', farmacodependencia: 'Farmacodependencia', sedentarismo: 'Sedentarismo', alimentacion: 'Alimentación', salud_mental: 'Salud Mental', otro: 'Otro' };
      const statusLabels: Record<string, string> = { activo: 'Activo', en_seguimiento: 'En Seguimiento', cerrado: 'Cerrado', remitido: 'Remitido' };
      const riskLabels: Record<string, string> = { bajo: 'Bajo', medio: 'Medio', alto: 'Alto', critico: 'Crítico' };
      
      const totalCases = followups.length;
      const activeCases = followups.filter(f => f.status === 'activo' || f.status === 'en_seguimiento').length;
      const closedCases = followups.filter(f => f.status === 'cerrado').length;
      const remittedCases = followups.filter(f => f.status === 'remitido').length;
      
      doc.fontSize(10).font('Helvetica-Bold').text('Total de casos:', margin, currentY);
      doc.font('Helvetica').text(String(totalCases), margin + 120, currentY);
      currentY += 14;
      doc.font('Helvetica-Bold').text('Casos activos:', margin, currentY);
      doc.font('Helvetica').text(String(activeCases), margin + 120, currentY);
      currentY += 14;
      doc.font('Helvetica-Bold').text('Casos cerrados:', margin, currentY);
      doc.font('Helvetica').text(String(closedCases), margin + 120, currentY);
      currentY += 14;
      doc.font('Helvetica-Bold').text('Casos remitidos:', margin, currentY);
      doc.font('Helvetica').text(String(remittedCases), margin + 120, currentY);
      currentY += 14;
      doc.font('Helvetica-Bold').text('Fecha de generación:', margin, currentY);
      doc.font('Helvetica').text(new Date().toLocaleDateString('es-CO'), margin + 120, currentY);
      currentY += 25;
      
      // Sección: DETALLE DE CASOS (barra verde)
      doc.rect(margin, currentY, contentWidth, 18).fill(colorVerdeSst);
      doc.fontSize(10).font('Helvetica-Bold').fillColor('#ffffff');
      doc.text('DETALLE DE CASOS EN SEGUIMIENTO', margin + 8, currentY + 4);
      currentY += 26;
      doc.fillColor('#000000');
      
      if (followups.length === 0) {
        doc.fontSize(10).font('Helvetica').text('No hay seguimientos registrados.', margin, currentY);
        currentY += 20;
      } else {
        // Table header
        const colWidths = [30, 120, 80, 70, 70, 80, 60];
        const tableStartX = margin;
        let tableY = currentY;
        
        doc.rect(tableStartX, tableY, contentWidth, 20).fill(colorVerdeSst);
        doc.fontSize(8).font('Helvetica-Bold').fillColor('#ffffff');
        let xPos = tableStartX;
        doc.text('No.', xPos + 3, tableY + 6, { width: colWidths[0] });
        xPos += colWidths[0];
        doc.text('Trabajador', xPos + 3, tableY + 6, { width: colWidths[1] });
        xPos += colWidths[1];
        doc.text('Categoría', xPos + 3, tableY + 6, { width: colWidths[2] });
        xPos += colWidths[2];
        doc.text('Apertura', xPos + 3, tableY + 6, { width: colWidths[3] });
        xPos += colWidths[3];
        doc.text('Prox. Rev.', xPos + 3, tableY + 6, { width: colWidths[4] });
        xPos += colWidths[4];
        doc.text('Riesgo', xPos + 3, tableY + 6, { width: colWidths[5] });
        xPos += colWidths[5];
        doc.text('Estado', xPos + 3, tableY + 6, { width: colWidths[6] });
        tableY += 20;
        
        doc.fillColor('#000000');
        
        followups.forEach((fup, idx) => {
          if (tableY > doc.page.height - 80) {
            doc.addPage();
            tableY = 50;
          }
          
          const rowHeight = 18;
          const bgColor = idx % 2 === 0 ? '#ffffff' : '#f8f9fa';
          doc.rect(tableStartX, tableY, contentWidth, rowHeight).fill(bgColor);
          
          doc.fontSize(8).font('Helvetica').fillColor('#000000');
          xPos = tableStartX;
          doc.text(String(idx + 1), xPos + 3, tableY + 5, { width: colWidths[0] });
          xPos += colWidths[0];
          doc.text(getWorkerName(fup.workerId), xPos + 3, tableY + 5, { width: colWidths[1] - 5 });
          xPos += colWidths[1];
          doc.text(categoryLabels[fup.category] || fup.category, xPos + 3, tableY + 5, { width: colWidths[2] - 5 });
          xPos += colWidths[2];
          doc.text(fup.openDate ? new Date(fup.openDate).toLocaleDateString('es-CO') : '-', xPos + 3, tableY + 5, { width: colWidths[3] - 5 });
          xPos += colWidths[3];
          doc.text(fup.nextReviewDate ? new Date(fup.nextReviewDate).toLocaleDateString('es-CO') : '-', xPos + 3, tableY + 5, { width: colWidths[4] - 5 });
          xPos += colWidths[4];
          doc.text(riskLabels[fup.riskLevel || ''] || '-', xPos + 3, tableY + 5, { width: colWidths[5] - 5 });
          xPos += colWidths[5];
          doc.text(statusLabels[fup.status] || fup.status, xPos + 3, tableY + 5, { width: colWidths[6] - 5 });
          
          tableY += rowHeight;
        });
        
        // Draw table border
        doc.rect(tableStartX, currentY, contentWidth, tableY - currentY).stroke('#cccccc');
        currentY = tableY + 10;
      }
      
      // Sección: OBSERVACIONES (barra verde)
      if (currentY > doc.page.height - 100) { doc.addPage(); currentY = 50; }
      doc.rect(margin, currentY, contentWidth, 18).fill(colorVerdeSst);
      doc.fontSize(10).font('Helvetica-Bold').fillColor('#ffffff');
      doc.text('OBSERVACIONES', margin + 8, currentY + 4);
      currentY += 26;
      doc.fillColor('#000000');
      
      doc.fontSize(9).font('Helvetica').text('Este documento contiene el listado de casos en seguimiento del programa de Estilos de Vida Saludable (EVS) de la empresa. Los casos deben ser revisados periódicamente según las fechas establecidas.', margin, currentY, { width: contentWidth });
      
      doc.end();
    } catch (error: any) { console.error("Error generating EVS followups PDF:", error); res.status(500).send("Error al generar PDF"); }
  });


  // PDF individual de un seguimiento EVS
  // PDF individual de un seguimiento EVS - Formato Estandarizado
  app.get("/api/evs/followups/:id/pdf", requireAuth, async (req, res) => {
    try {
      const companyId = req.user!.companyId;
      if (!companyId) return res.status(403).send("Usuario no asociado a una empresa");
      const company = await storage.getCompany(companyId);
      if (!company) return res.status(404).send("Empresa no encontrada");
      const followup = await storage.getEvsFollowup(req.params.id, companyId);
      if (!followup) return res.status(404).send("Seguimiento no encontrado");
      const workers = await storage.getWorkers(companyId);
      const worker = workers.find(w => w.id === followup.workerId);
      const workerName = worker?.name || 'Desconocido';
      const logoBuffer = await loadCompanyLogoBuffer(company.logoUrl);
      // Worker photo not needed for muestreo PDF
      const { default: PDFDocument } = await import('pdfkit');
      const doc = new PDFDocument({ margin: 50, size: 'LETTER' });
      const subscription = await storage.getSubscriptionByCompany(companyId);
      const trialStatus = getTrialStatus(subscription?.status || 'trial', subscription?.trialEnd || null, true, true);
      setupTrialWatermarkOnAllPages(doc, trialStatus.requiresWatermark);
      res.setHeader('Content-Type', 'application/pdf');
      res.setHeader('Content-Disposition', `inline; filename="Seguimiento-EVS-${workerName.replace(/\s+/g, '-')}.pdf"`);
      doc.pipe(res);
      
      const margin = 50;
      const pageWidth = doc.page.width;
      const contentWidth = pageWidth - 2 * margin;
      const colorVerdeSst = '#1e7e34';
      
      let currentY = setupPdfHeadersFooters({ doc, company, documentTitle: "SEGUIMIENTO DE CASO - ESTILOS DE VIDA SALUDABLE", documentCode: `SST-EVS-SEG-${followup.id.substring(0,8).toUpperCase()}`, version: "1.0", date: new Date(), logoBuffer });
      currentY += 25;
      
      // Sección: INFORMACIÓN DEL TRABAJADOR (barra verde)
      doc.rect(margin, currentY, contentWidth, 18).fill(colorVerdeSst);
      doc.fontSize(10).font('Helvetica-Bold').fillColor('#ffffff');
      doc.text('INFORMACIÓN DEL TRABAJADOR', margin + 8, currentY + 4);
      currentY += 26;
      doc.fillColor('#000000');
      
      doc.fontSize(10).font('Helvetica-Bold').text('Nombre:', margin, currentY);
      doc.font('Helvetica').text(workerName, margin + 80, currentY);
      currentY += 14;
      if (worker?.identificationNumber) {
        doc.font('Helvetica-Bold').text('Cédula:', margin, currentY);
        doc.font('Helvetica').text(worker.identificationNumber, margin + 80, currentY);
        currentY += 14;
      }
      if (worker?.position) {
        doc.font('Helvetica-Bold').text('Cargo:', margin, currentY);
        doc.font('Helvetica').text(worker.position, margin + 80, currentY);
        currentY += 14;
      }
      if (worker?.area) {
        doc.font('Helvetica-Bold').text('Área:', margin, currentY);
        doc.font('Helvetica').text(worker.area, margin + 80, currentY);
        currentY += 14;
      }
      currentY += 10;
      
      // Sección: INFORMACIÓN DEL CASO (barra verde)
      doc.rect(margin, currentY, contentWidth, 18).fill(colorVerdeSst);
      doc.fontSize(10).font('Helvetica-Bold').fillColor('#ffffff');
      doc.text('INFORMACIÓN DEL CASO', margin + 8, currentY + 4);
      currentY += 26;
      doc.fillColor('#000000');
      
      const categoryLabels: Record<string, string> = { tabaquismo: 'Tabaquismo', alcoholismo: 'Alcoholismo', farmacodependencia: 'Farmacodependencia', sedentarismo: 'Sedentarismo', alimentacion: 'Alimentación', salud_mental: 'Salud Mental', otro: 'Otro' };
      doc.fontSize(10).font('Helvetica-Bold').text('Categoría:', margin, currentY);
      doc.font('Helvetica').text(categoryLabels[followup.category] || followup.category, margin + 100, currentY);
      currentY += 14;
      doc.font('Helvetica-Bold').text('Fecha Apertura:', margin, currentY);
      doc.font('Helvetica').text(followup.openDate ? new Date(followup.openDate).toLocaleDateString('es-CO') : 'N/A', margin + 100, currentY);
      currentY += 14;
      const riskLabels: Record<string, string> = { bajo: 'Bajo', medio: 'Medio', alto: 'Alto', critico: 'Crítico' };
      doc.font('Helvetica-Bold').text('Nivel de Riesgo:', margin, currentY);
      doc.font('Helvetica').text(riskLabels[followup.riskLevel || ''] || followup.riskLevel || 'N/A', margin + 100, currentY);
      currentY += 14;
      const statusLabels: Record<string, string> = { activo: 'Activo', en_seguimiento: 'En Seguimiento', cerrado: 'Cerrado', remitido: 'Remitido' };
      doc.font('Helvetica-Bold').text('Estado:', margin, currentY);
      doc.font('Helvetica').text(statusLabels[followup.status] || followup.status, margin + 100, currentY);
      currentY += 14;
      if (followup.nextReviewDate) {
        doc.font('Helvetica-Bold').text('Próxima Revisión:', margin, currentY);
        doc.font('Helvetica').text(new Date(followup.nextReviewDate).toLocaleDateString('es-CO'), margin + 100, currentY);
        currentY += 14;
      }
      currentY += 10;
      
      // Sección: EVALUACIÓN INICIAL (barra verde)
      if (followup.initialAssessment) {
        if (currentY > doc.page.height - 120) { doc.addPage(); currentY = 50; }
        doc.rect(margin, currentY, contentWidth, 18).fill(colorVerdeSst);
        doc.fontSize(10).font('Helvetica-Bold').fillColor('#ffffff');
        doc.text('EVALUACIÓN INICIAL', margin + 8, currentY + 4);
        currentY += 26;
        doc.fillColor('#000000');
        doc.fontSize(10).font('Helvetica').text(followup.initialAssessment, margin, currentY, { width: contentWidth });
        currentY += doc.heightOfString(followup.initialAssessment, { width: contentWidth }) + 15;
      }
      
      // Sección: PLAN DE INTERVENCIÓN (barra verde)
      if (followup.interventionPlan) {
        if (currentY > doc.page.height - 120) { doc.addPage(); currentY = 50; }
        doc.rect(margin, currentY, contentWidth, 18).fill(colorVerdeSst);
        doc.fontSize(10).font('Helvetica-Bold').fillColor('#ffffff');
        doc.text('PLAN DE INTERVENCIÓN', margin + 8, currentY + 4);
        currentY += 26;
        doc.fillColor('#000000');
        doc.fontSize(10).font('Helvetica').text(followup.interventionPlan, margin, currentY, { width: contentWidth });
        currentY += doc.heightOfString(followup.interventionPlan, { width: contentWidth }) + 15;
      }
      
      // Sección: COMPROMISOS DEL TRABAJADOR (barra verde)
      if (followup.workerCommitments) {
        if (currentY > doc.page.height - 120) { doc.addPage(); currentY = 50; }
        doc.rect(margin, currentY, contentWidth, 18).fill(colorVerdeSst);
        doc.fontSize(10).font('Helvetica-Bold').fillColor('#ffffff');
        doc.text('COMPROMISOS DEL TRABAJADOR', margin + 8, currentY + 4);
        currentY += 26;
        doc.fillColor('#000000');
        doc.fontSize(10).font('Helvetica').text(followup.workerCommitments, margin, currentY, { width: contentWidth });
        currentY += doc.heightOfString(followup.workerCommitments, { width: contentWidth }) + 15;
      }
      
      // Sección: COMPROMISOS DE LA EMPRESA (barra verde)
      if (followup.companyCommitments) {
        if (currentY > doc.page.height - 120) { doc.addPage(); currentY = 50; }
        doc.rect(margin, currentY, contentWidth, 18).fill(colorVerdeSst);
        doc.fontSize(10).font('Helvetica-Bold').fillColor('#ffffff');
        doc.text('COMPROMISOS DE LA EMPRESA', margin + 8, currentY + 4);
        currentY += 26;
        doc.fillColor('#000000');
        doc.fontSize(10).font('Helvetica').text(followup.companyCommitments, margin, currentY, { width: contentWidth });
        currentY += doc.heightOfString(followup.companyCommitments, { width: contentWidth }) + 15;
      }
      
      // Sección: PROFESIONAL RESPONSABLE (barra verde)
      if (followup.responsibleProfessional) {
        if (currentY > doc.page.height - 100) { doc.addPage(); currentY = 50; }
        doc.rect(margin, currentY, contentWidth, 18).fill(colorVerdeSst);
        doc.fontSize(10).font('Helvetica-Bold').fillColor('#ffffff');
        doc.text('PROFESIONAL RESPONSABLE', margin + 8, currentY + 4);
        currentY += 26;
        doc.fillColor('#000000');
        doc.fontSize(10).font('Helvetica').text(followup.responsibleProfessional, margin, currentY);
        currentY += 20;
      }
      
      doc.end();
    } catch (error: any) { console.error("Error generating EVS followup PDF:", error); res.status(500).send("Error al generar PDF"); }
  });
