  app.post("/api/evs/participants", requireAuth, async (req, res) => {
    const companyId = req.user!.companyId;
    if (!companyId) return res.status(400).json({ message: "No company context" });
    try {
      const data = insertEvsParticipantSchema.parse({ ...req.body, createdBy: req.user!.id });
      const participant = await storage.createEvsParticipant(data);
      
      // Send notification if activity has meetingLink (virtual activity/course)
      try {
        const activity = await storage.getEvsActivityById(data.activityId, companyId);
        if (activity && activity.meetingLink) {
          const worker = await storage.getWorkerById(data.workerId);
          if (worker) {
            const workerUser = await storage.getUserByWorkerId(worker.id);
            if (workerUser) {
              const program = activity.programId ? await storage.getEvsProgramById(activity.programId, companyId) : null;
              const fechaFormateada = activity.scheduledDate 
                ? new Date(activity.scheduledDate).toLocaleDateString('es-CO', { year: 'numeric', month: 'long', day: 'numeric' })
                : 'Por definir';
              
              const isVirtualCourse = activity.type === 'capacitacion' || activity.type === 'curso';
              const subject = isVirtualCourse ? 'Curso Virtual Asignado' : 'Actividad de Bienestar Programada';
              
              await storage.createInternalMessage({
                companyId,
                senderId: req.user!.id,
                senderName: req.user!.fullName || req.user!.username,
                senderRole: req.user!.role,
                receiverId: workerUser.id,
                receiverName: workerUser.fullName || workerUser.username,
                receiverRole: workerUser.role,
                subject,
                content: 'Se le ha asignado a una actividad virtual.' + '\n\nPrograma: ' + (program?.name || 'No especificado') + '\nActividad: ' + (activity.name || 'Sin nombre') + '\nTipo: ' + (activity.type || 'General') + '\nFecha: ' + fechaFormateada + '\n\nAcceda al portal para ver los detalles y el enlace de la reunion.',
                priority: 'normal',
                status: 'unread',
                relatedEntity: 'evs_activity',
                relatedEntityId: activity.id
              });
            }
          }
        }
      } catch (notifError) {
        console.error('Error sending portal notification for EVS participant:', notifError);
      }
      
      res.status(201).json(participant);
    } catch (error: any) {
      res.status(400).json({ message: error.message || "Invalid data" });
    }
  });

